        op.execute('CREATE POLICY studio_draft_actor_select ON knowledge.abox_mapping_rule_drafts AS RESTRICTIVE FOR SELECT TO datariver_app USING (EXISTS (SELECT 1 FROM knowledge.studio_drafts AS visible_draft WHERE visible_draft.workspace_id = abox_mapping_rule_drafts.workspace_id AND visible_draft.id = abox_mapping_rule_drafts.draft_id AND (visible_draft.author_id = NULLIF(current_setting(\'app.subject_id\', true), \'\')::uuid OR (visible_draft.state IN (\'REVIEW\', \'PUBLISHED\') AND EXISTS (SELECT 1 FROM iam.workspace_memberships AS membership JOIN iam.subjects AS reviewer_subject ON reviewer_subject.id = membership.subject_id JOIN platform.workspaces AS reviewer_workspace ON reviewer_workspace.id = membership.workspace_id WHERE membership.workspace_id = visible_draft.workspace_id AND membership.subject_id = NULLIF(current_setting(\'app.subject_id\', true), \'\')::uuid AND membership.subject_id <> visible_draft.author_id AND reviewer_workspace.status = \'ACTIVE\' AND reviewer_subject.active IS TRUE AND membership.active IS TRUE AND (membership.access_expires_at IS NULL OR membership.access_expires_at > transaction_timestamp()) AND (COALESCE(membership.job_function, \'\') <> \'SERVICE_ACCOUNT\' OR (membership.subject_id = \'00000000-0000-4000-8000-000000000111\'::uuid AND visible_draft.author_id = \'00000000-0000-4000-8000-000000000110\'::uuid AND membership.workspace_id = \'00000000-0000-4000-8000-000000000100\'::uuid AND visible_draft.workspace_id = \'00000000-0000-4000-8000-000000000100\'::uuid AND visible_draft.domain_ref_id = \'f14fa2ce-e5f2-beee-5eea-5e77be5754ff\'::uuid AND COALESCE(membership.job_function, \'\') = \'SERVICE_ACCOUNT\' AND jsonb_array_length(COALESCE(membership.attributes -> \'groups\', \'[]\'::jsonb)) = 2 AND COALESCE(membership.attributes -> \'groups\', \'[]\'::jsonb) @> \'["service-accounts", "k9-publisher-checkers"]\'::jsonb AND jsonb_array_length(COALESCE(membership.attributes -> \'allowed_actions\', \'[]\'::jsonb)) = 3 AND COALESCE(membership.attributes -> \'allowed_actions\', \'[]\'::jsonb) @> \'["kg.read", "kg.review", "kg.publish"]\'::jsonb AND COALESCE(membership.attributes -> \'denied_actions\', \'[]\'::jsonb) = \'[]\'::jsonb AND COALESCE(membership.attributes -> \'allowed_system_ids\', \'[]\'::jsonb) = \'[]\'::jsonb AND jsonb_array_length(COALESCE(membership.attributes -> \'allowed_domain_ids\', \'[]\'::jsonb)) = 1 AND COALESCE(membership.attributes -> \'allowed_domain_ids\', \'[]\'::jsonb) @> \'["f14fa2ce-e5f2-beee-5eea-5e77be5754ff"]\'::jsonb)) AND (NOT (COALESCE(membership.attributes -> \'groups\', \'[]\'::jsonb) ? \'service-accounts\') OR (membership.subject_id = \'00000000-0000-4000-8000-000000000111\'::uuid AND visible_draft.author_id = \'00000000-0000-4000-8000-000000000110\'::uuid AND membership.workspace_id = \'00000000-0000-4000-8000-000000000100\'::uuid AND visible_draft.workspace_id = \'00000000-0000-4000-8000-000000000100\'::uuid AND visible_draft.domain_ref_id = \'f14fa2ce-e5f2-beee-5eea-5e77be5754ff\'::uuid AND COALESCE(membership.job_function, \'\') = \'SERVICE_ACCOUNT\' AND jsonb_array_length(COALESCE(membership.attributes -> \'groups\', \'[]\'::jsonb)) = 2 AND COALESCE(membership.attributes -> \'groups\', \'[]\'::jsonb) @> \'["service-accounts", "k9-publisher-checkers"]\'::jsonb AND jsonb_array_length(COALESCE(membership.attributes -> \'allowed_actions\', \'[]\'::jsonb)) = 3 AND COALESCE(membership.attributes -> \'allowed_actions\', \'[]\'::jsonb) @> \'["kg.read", "kg.review", "kg.publish"]\'::jsonb AND COALESCE(membership.attributes -> \'denied_actions\', \'[]\'::jsonb) = \'[]\'::jsonb AND COALESCE(membership.attributes -> \'allowed_system_ids\', \'[]\'::jsonb) = \'[]\'::jsonb AND jsonb_array_length(COALESCE(membership.attributes -> \'allowed_domain_ids\', \'[]\'::jsonb)) = 1 AND COALESCE(membership.attributes -> \'allowed_domain_ids\', \'[]\'::jsonb) @> \'["f14fa2ce-e5f2-beee-5eea-5e77be5754ff"]\'::jsonb)) AND membership.clearance >= visible_draft.classification AND (visible_draft.classification = 0 OR COALESCE(membership.attributes -> \'allowed_domain_ids\', \'[]\'::jsonb) ? visible_draft.domain_ref_id::text) AND COALESCE(membership.attributes -> \'allowed_actions\', \'[]\'::jsonb) ? \'kg.review\' AND NOT (COALESCE(membership.attributes -> \'denied_actions\', \'[]\'::jsonb) ? \'kg.review\'))))))')
        op.execute("CREATE POLICY studio_draft_owner_insert ON knowledge.abox_mapping_rule_drafts AS RESTRICTIVE FOR INSERT TO datariver_app WITH CHECK (EXISTS (SELECT 1 FROM knowledge.studio_drafts AS owned_draft WHERE owned_draft.workspace_id = abox_mapping_rule_drafts.workspace_id AND owned_draft.id = abox_mapping_rule_drafts.draft_id AND owned_draft.author_id = NULLIF(current_setting('app.subject_id', true), '')::uuid AND owned_draft.state = 'DRAFT'))")
        op.execute("CREATE POLICY studio_draft_owner_update ON knowledge.abox_mapping_rule_drafts AS RESTRICTIVE FOR UPDATE TO datariver_app USING (EXISTS (SELECT 1 FROM knowledge.studio_drafts AS owned_draft WHERE owned_draft.workspace_id = abox_mapping_rule_drafts.workspace_id AND owned_draft.id = abox_mapping_rule_drafts.draft_id AND owned_draft.author_id = NULLIF(current_setting('app.subject_id', true), '')::uuid AND owned_draft.state = 'DRAFT')) WITH CHECK (EXISTS (SELECT 1 FROM knowledge.studio_drafts AS owned_draft WHERE owned_draft.workspace_id = abox_mapping_rule_drafts.workspace_id AND owned_draft.id = abox_mapping_rule_drafts.draft_id AND owned_draft.author_id = NULLIF(current_setting('app.subject_id', true), '')::uuid AND owned_draft.state = 'DRAFT'))")
        op.execute("CREATE POLICY studio_draft_owner_delete ON knowledge.abox_mapping_rule_drafts AS RESTRICTIVE FOR DELETE TO datariver_app USING (EXISTS (SELECT 1 FROM knowledge.studio_drafts AS owned_draft WHERE owned_draft.workspace_id = abox_mapping_rule_drafts.workspace_id AND owned_draft.id = abox_mapping_rule_drafts.draft_id AND owned_draft.author_id = NULLIF(current_setting('app.subject_id', true), '')::uuid AND owned_draft.state = 'DRAFT'))")
        op.execute("CREATE FUNCTION integration.reject_object_manifest_content_profile_change()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY INVOKER\nSET search_path = pg_catalog\nAS $function$\nBEGIN\n    IF NEW.content_profile IS DISTINCT FROM OLD.content_profile THEN\n        RAISE EXCEPTION 'object manifest content_profile is immutable'\n            USING ERRCODE = '23514';\n    END IF;\n    RETURN NEW;\nEND\n$function$")
        op.execute('CREATE TRIGGER reject_object_manifest_content_profile_change\nBEFORE UPDATE OF content_profile ON integration.object_manifests\nFOR EACH ROW\nEXECUTE FUNCTION integration.reject_object_manifest_content_profile_change()')
        op.execute("CREATE FUNCTION integration.reject_upload_registration_candidate_evidence_mutation()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY INVOKER\nSET search_path = pg_catalog\nAS $function$\nBEGIN\n    IF TG_OP = 'INSERT' AND NEW.evidence_version <> 'DATASET_DESCRIPTION_CANDIDATE_V2' THEN\n        RAISE EXCEPTION 'new upload registration candidates require V2 evidence'\n            USING ERRCODE = '23514';\n    END IF;\n    IF TG_OP IN ('UPDATE', 'DELETE') THEN\n        RAISE EXCEPTION 'upload registration candidate evidence is immutable'\n            USING ERRCODE = '23514';\n    END IF;\n    RETURN NEW;\nEND\n$function$")
        op.execute('CREATE TRIGGER reject_upload_registration_candidate_evidence_mutation\nBEFORE INSERT OR UPDATE OR DELETE ON integration.upload_registration_candidates\nFOR EACH ROW\nEXECUTE FUNCTION integration.reject_upload_registration_candidate_evidence_mutation()')
        op.execute("CREATE FUNCTION assistant.enforce_chat_session_retention_binding()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY INVOKER\nSET search_path = pg_catalog\nAS $function$\nDECLARE\n    policy_days integer;\nBEGIN\n    IF TG_OP = 'UPDATE' THEN\n        IF NEW.workspace_id IS DISTINCT FROM OLD.workspace_id\n           OR NEW.owner_id IS DISTINCT FROM OLD.owner_id\n           OR NEW.created_at IS DISTINCT FROM OLD.created_at\n           OR NEW.retention_until IS DISTINCT FROM OLD.retention_until\n           OR NEW.retention_policy_id IS DISTINCT FROM OLD.retention_policy_id\n           OR NEW.retention_policy_hash IS DISTINCT FROM OLD.retention_policy_hash\n           OR NEW.retention_basis_at IS DISTINCT FROM OLD.retention_basis_at\n           OR NEW.retention_binding_version IS DISTINCT FROM OLD.retention_binding_version THEN\n            RAISE EXCEPTION 'Chat session retention evidence is immutable'\n                USING ERRCODE = '23514';\n        END IF;\n        RETURN NEW;\n    END IF;\n\n    IF NEW.retention_binding_version <> 'ACTIVE_POLICY_V1' THEN\n        RAISE EXCEPTION 'new Chat sessions require an active-policy retention binding'\n            USING ERRCODE = '23514';\n    END IF;\n\n    SELECT policy.chat_content_days\n    INTO policy_days\n    FROM retention.policy_versions AS policy\n    WHERE policy.workspace_id = NEW.workspace_id\n      AND policy.id = NEW.retention_policy_id\n      AND policy.payload_hash = NEW.retention_policy_hash\n      AND policy.state = 'ACTIVE'\n    FOR KEY SHARE;\n\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'Chat retention policy binding is not active'\n            USING ERRCODE = '23514';\n    END IF;\n    IF NEW.retention_basis_at IS DISTINCT FROM transaction_timestamp() THEN\n        RAISE EXCEPTION 'Chat retention basis must equal the persistence transaction time'\n            USING ERRCODE = '23514';\n    END IF;\n    IF NEW.retention_until IS DISTINCT FROM\n       NEW.retention_basis_at + make_interval(days => policy_days) THEN\n        RAISE EXCEPTION 'Chat retention deadline does not match the active policy'\n            USING ERRCODE = '23514';\n    END IF;\n    RETURN NEW;\nEND\n$function$")
        op.execute('CREATE TRIGGER enforce_chat_session_retention_binding\nBEFORE INSERT OR UPDATE ON assistant.chat_sessions\nFOR EACH ROW\nEXECUTE FUNCTION assistant.enforce_chat_session_retention_binding()')
        op.execute("CREATE FUNCTION assistant.enforce_chat_message_retention_binding()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY INVOKER\nSET search_path = pg_catalog\nAS $function$\nBEGIN\n    PERFORM 1\n    FROM assistant.chat_sessions AS session\n    JOIN retention.policy_versions AS policy\n      ON policy.workspace_id = session.workspace_id\n     AND policy.id = session.retention_policy_id\n     AND policy.payload_hash = session.retention_policy_hash\n    WHERE session.workspace_id = NEW.workspace_id\n      AND session.id = NEW.session_id\n      AND session.owner_id =\n          NULLIF(current_setting('app.subject_id', true), '')::uuid\n      AND session.retention_binding_version = 'ACTIVE_POLICY_V1'\n      AND session.retention_until > transaction_timestamp()\n      AND policy.state = 'ACTIVE'\n    FOR KEY SHARE OF session, policy;\n\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'Chat session is not appendable under the active retention policy'\n            USING ERRCODE = '23514';\n    END IF;\n    RETURN NEW;\nEND\n$function$")
        op.execute('CREATE TRIGGER enforce_chat_message_retention_binding\nBEFORE INSERT ON assistant.chat_messages\nFOR EACH ROW\nEXECUTE FUNCTION assistant.enforce_chat_message_retention_binding()')
        op.execute('CREATE OR REPLACE FUNCTION iam.provision_workspace_identity(\n    p_subject_id uuid, p_workspace_id uuid, p_issuer text, p_external_subject text,\n    p_display_name text, p_email text, p_department_id uuid, p_job_function text,\n    p_role_id uuid, p_access_expires_at timestamptz, p_assurance text,\n    p_policy_decision_id uuid\n)\nRETURNS uuid\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = pg_catalog, iam, platform\nAS $datariver$\nDECLARE\n    actor_id uuid;\n    existing_subject_id uuid;\n    access_clearance integer := 2;\n    access_attributes jsonb := jsonb_build_object(\n        \'groups\', jsonb_build_array(), \'allowed_actions\', \'["attachment.download","catalog.lineage.read","catalog.read","catalog.search","change.read","chat.query","dashboard.read","governance.document.history.read","governance.document.read","governance.knowledge.read","governance.template.read","operations.read","quality.audit.read","quality.operations.read","quality.profile.read","quality.read"]\'::jsonb,\n        \'denied_actions\', jsonb_build_array(), \'allowed_system_ids\', jsonb_build_array(),\n        \'allowed_domain_ids\', jsonb_build_array(), \'default_workspace\', true,\n        \'managed_by\', \'PROFILE_ROLE_POLICY_V1\'\n    );\n    selected_role iam.access_roles%ROWTYPE;\nBEGIN\n    actor_id := NULLIF(current_setting(\'app.subject_id\', true), \'\')::uuid;\n    IF actor_id IS NULL OR NULLIF(current_setting(\'app.workspace_id\', true), \'\')::uuid\n       IS DISTINCT FROM p_workspace_id THEN\n        RAISE EXCEPTION \'A matching DataRiver security context is required\'\n            USING ERRCODE = \'42501\';\n    END IF;\n    IF p_access_expires_at <= transaction_timestamp()\n       OR p_access_expires_at > transaction_timestamp() + INTERVAL \'7 months\' THEN\n        RAISE EXCEPTION \'The initial access expiration is outside the governed bound\'\n            USING ERRCODE = \'23514\';\n    END IF;\n    PERFORM 1\n    FROM iam.workspace_memberships AS membership\n    JOIN iam.subjects AS subject ON subject.id = membership.subject_id\n    JOIN platform.workspaces AS workspace ON workspace.id = membership.workspace_id\n    WHERE membership.workspace_id = p_workspace_id\n      AND membership.subject_id = actor_id\n      AND subject.active IS TRUE AND membership.active IS TRUE\n      AND workspace.status = \'ACTIVE\'\n      AND (membership.access_expires_at IS NULL\n           OR membership.access_expires_at > transaction_timestamp())\n      AND COALESCE(membership.job_function, \'\') <> \'SERVICE_ACCOUNT\'\n      AND membership.clearance >= 3\n      AND COALESCE(membership.attributes -> \'groups\', \'[]\'::jsonb)\n          ? \'security-administrators\'\n      AND NOT (COALESCE(membership.attributes -> \'groups\', \'[]\'::jsonb)\n          ? \'service-accounts\')\n      AND COALESCE(membership.attributes -> \'allowed_actions\', \'[]\'::jsonb)\n          ? \'admin.manage\'\n      AND NOT (COALESCE(membership.attributes -> \'denied_actions\', \'[]\'::jsonb)\n          ? \'admin.manage\')\n    FOR KEY SHARE OF membership, subject, workspace;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION \'An eligible human security administrator is required\'\n            USING ERRCODE = \'42501\';\n    END IF;\n    IF p_role_id IS NOT NULL THEN\n        RAISE EXCEPTION \'New human identities always receive the Viewer profile Role\'\n            USING ERRCODE = \'23514\';\n    END IF;\n    IF p_assurance NOT IN (\'PASSWORD_REAUTH\', \'HARDWARE_WEBAUTHN\')\n       OR p_policy_decision_id IS NULL THEN\n        RAISE EXCEPTION \'The identity provisioning assurance is invalid\'\n            USING ERRCODE = \'23514\';\n    END IF;\n    SELECT id INTO existing_subject_id FROM iam.subjects\n    WHERE issuer = p_issuer AND external_subject = p_external_subject FOR KEY SHARE;\n    IF FOUND THEN\n        IF existing_subject_id IS DISTINCT FROM p_subject_id THEN\n            RAISE EXCEPTION \'The external identity is already bound to another subject\'\n                USING ERRCODE = \'23505\';\n        END IF;\n        RETURN existing_subject_id;\n    END IF;\n    INSERT INTO iam.subjects (\n        id, issuer, external_subject, display_name, email, active, created_at, updated_at\n    ) VALUES (\n        p_subject_id, p_issuer, p_external_subject, p_display_name, p_email, TRUE,\n        transaction_timestamp(), transaction_timestamp()\n    );\n    INSERT INTO iam.workspace_memberships (\n        workspace_id, subject_id, department_id, job_function, clearance, attributes,\n        active, access_expires_at, version, created_at, updated_at\n    ) VALUES (\n        p_workspace_id, p_subject_id, p_department_id, p_job_function,\n        access_clearance, access_attributes, TRUE, p_access_expires_at,\n        1, transaction_timestamp(), transaction_timestamp()\n    );\n    INSERT INTO iam.profile_role_assignments (\n        workspace_id, subject_id, tier, policy_version, materialized_actions_hash,\n        membership_version, state, assigned_by, reason, assurance, version,\n        created_at, updated_at\n    ) VALUES (\n        p_workspace_id, p_subject_id, \'VIEWER\', \'PROFILE_ROLE_POLICY_V1\',\n        \'1eeb92fb6bad810b9e17537d78983f0a5811a4059fc283d00ce87794d56018ad\', 1, \'ACTIVE\', actor_id,\n        \'New human provisioned with Viewer default.\', p_assurance, 1,\n        transaction_timestamp(), transaction_timestamp()\n    );\n    INSERT INTO iam.profile_role_assignment_events (\n        id, workspace_id, subject_id, event_type, previous_tier, next_tier,\n        policy_version, membership_version, assignment_version, actor_id,\n        policy_decision_id, reason, assurance, occurred_at\n    ) VALUES (\n        gen_random_uuid(), p_workspace_id, p_subject_id, \'ASSIGNED\', NULL, \'VIEWER\',\n        \'PROFILE_ROLE_POLICY_V1\', 1, 1, actor_id,\n        p_policy_decision_id, \'New human provisioned with Viewer default.\', p_assurance,\n        transaction_timestamp()\n    );\n    RETURN p_subject_id;\nEND\n$datariver$')
        op.execute('REVOKE ALL ON FUNCTION iam.provision_workspace_identity(uuid, uuid, text, text, text, text, uuid, text, uuid, timestamptz, text, uuid) FROM PUBLIC')
        op.execute("CREATE OR REPLACE FUNCTION iam.update_workspace_identity_profile(\n    p_workspace_id uuid,\n    p_subject_id uuid,\n    p_expected_membership_version integer,\n    p_display_name text,\n    p_email text,\n    p_department_id uuid,\n    p_job_function text\n)\nRETURNS integer\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = pg_catalog, iam, platform\nAS $datariver$\nDECLARE\n    actor_id uuid;\n    target_membership_version integer;\n    target_membership_active boolean;\n    target_subject_active boolean;\n    target_access_expires_at timestamptz;\n    target_job_function text;\n    target_attributes jsonb;\n    next_version integer;\nBEGIN\n    actor_id := NULLIF(current_setting('app.subject_id', true), '')::uuid;\n    IF actor_id IS NULL OR NULLIF(current_setting('app.workspace_id', true), '')::uuid\n       IS DISTINCT FROM p_workspace_id THEN\n        RAISE EXCEPTION 'A matching DataRiver security context is required'\n            USING ERRCODE = '42501';\n    END IF;\n    IF p_expected_membership_version < 1\n       OR char_length(COALESCE(p_display_name, '')) NOT BETWEEN 1 AND 255\n       OR char_length(COALESCE(p_email, '')) NOT BETWEEN 3 AND 320\n       OR (\n           p_job_function IS NOT NULL\n           AND char_length(p_job_function) NOT BETWEEN 1 AND 100\n       )\n       OR COALESCE(p_job_function, '') = 'SERVICE_ACCOUNT' THEN\n        RAISE EXCEPTION 'The identity profile document is outside the governed bound'\n            USING ERRCODE = '23514';\n    END IF;\n    PERFORM 1\n    FROM iam.workspace_memberships AS membership\n    JOIN iam.subjects AS subject ON subject.id = membership.subject_id\n    JOIN platform.workspaces AS workspace ON workspace.id = membership.workspace_id\n    WHERE membership.workspace_id = p_workspace_id\n      AND membership.subject_id = actor_id\n      AND subject.active IS TRUE\n      AND membership.active IS TRUE\n      AND workspace.status = 'ACTIVE'\n      AND (\n          membership.access_expires_at IS NULL\n          OR membership.access_expires_at > transaction_timestamp()\n      )\n      AND COALESCE(membership.job_function, '') <> 'SERVICE_ACCOUNT'\n      AND membership.clearance >= 3\n      AND COALESCE(membership.attributes -> 'groups', '[]'::jsonb)\n          ? 'security-administrators'\n      AND NOT (\n          COALESCE(membership.attributes -> 'groups', '[]'::jsonb)\n          ? 'service-accounts'\n      )\n      AND COALESCE(membership.attributes -> 'allowed_actions', '[]'::jsonb)\n          ? 'admin.manage'\n      AND NOT (\n          COALESCE(membership.attributes -> 'denied_actions', '[]'::jsonb)\n          ? 'admin.manage'\n      )\n    FOR KEY SHARE OF membership, subject, workspace;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'An eligible human security administrator is required'\n            USING ERRCODE = '42501';\n    END IF;\n    SELECT\n        membership.version,\n        membership.active,\n        subject.active,\n        membership.access_expires_at,\n        membership.job_function,\n        membership.attributes\n    INTO\n        target_membership_version,\n        target_membership_active,\n        target_subject_active,\n        target_access_expires_at,\n        target_job_function,\n        target_attributes\n    FROM iam.workspace_memberships AS membership\n    JOIN iam.subjects AS subject ON subject.id = membership.subject_id\n    WHERE membership.workspace_id = p_workspace_id\n      AND membership.subject_id = p_subject_id\n    FOR UPDATE OF membership, subject;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'The target workspace identity does not exist'\n            USING ERRCODE = 'P0002';\n    END IF;\n    IF target_membership_version <> p_expected_membership_version THEN\n        RAISE EXCEPTION 'The target workspace identity changed'\n            USING ERRCODE = '40001';\n    END IF;\n    IF NOT target_membership_active\n       OR NOT target_subject_active\n       OR (\n           target_access_expires_at IS NOT NULL\n           AND target_access_expires_at <= transaction_timestamp()\n       )\n       OR COALESCE(target_job_function, '') = 'SERVICE_ACCOUNT'\n       OR COALESCE(target_attributes -> 'groups', '[]'::jsonb)\n          ? 'service-accounts' THEN\n        RAISE EXCEPTION 'Only an active human identity can be updated'\n            USING ERRCODE = '23514';\n    END IF;\n    UPDATE iam.subjects\n    SET display_name = p_display_name,\n        email = p_email,\n        updated_at = transaction_timestamp()\n    WHERE id = p_subject_id;\n    UPDATE iam.workspace_memberships\n    SET department_id = p_department_id,\n        job_function = p_job_function,\n        version = version + 1,\n        updated_at = transaction_timestamp()\n    WHERE workspace_id = p_workspace_id\n      AND subject_id = p_subject_id\n    RETURNING version INTO next_version;\n    RETURN next_version;\nEND\n$datariver$")
        op.execute('REVOKE ALL ON FUNCTION iam.update_workspace_identity_profile(uuid, uuid, integer, text, text, uuid, text) FROM PUBLIC')
        op.execute('CREATE OR REPLACE FUNCTION iam.ensure_canonical_admin_definition()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = pg_catalog, iam\nAS $datariver$\nBEGIN\n    INSERT INTO iam.access_roles (\n        id, workspace_id, role_key, role_kind, management_source,\n        capability_catalog_version, name, description, clearance, groups,\n        allowed_actions, denied_actions, allowed_system_ids, allowed_domain_ids,\n        active, updated_by, version, created_at, updated_at\n    ) VALUES (\n        gen_random_uuid(), NEW.id, \'canonical-admin\', \'CANONICAL_ADMIN\',\n        \'SERVER_CANONICAL\', \'ACCESS_ROLE_CAPABILITY_CATALOG_V2\', \'Canonical Admin\',\n        \'Server-owned Canonical Admin capability definition.\', 3,\n        \'["security-administrators"]\'::jsonb, \'["admin.manage","archive.read","attachment.download","audit.read","catalog.export","catalog.lineage.read","catalog.quarantine.read","catalog.read","catalog.search","catalog.sync","change.approve","change.create","change.edit","change.raw.create","change.read","change.retry","change.review","chat.query","dashboard.read","erasure.approve","erasure.request","governance.document.archive","governance.document.create","governance.document.edit","governance.document.history.read","governance.document.publish","governance.document.read","governance.document.review","governance.knowledge.read","governance.template.activate","governance.template.archive","governance.template.propose","governance.template.read","governance.template.review","kg.create","kg.edit","kg.export","kg.publish","kg.read","kg.review","legal_hold.place","legal_hold.release","operations.read","operations.retry","quality.audit.read","quality.operations.read","quality.profile.read","quality.read","quality.rule.activate","quality.rule.archive","quality.rule.propose","quality.rule.review","quality.rule.revoke","quality.run.cancel","quality.run.request","quality.run.retry","registration.create","registration.read","registration.validate","retention.manage","retention.read","sharing.invoke","sharing.manage","sharing.publish"]\'::jsonb,\n        \'[]\'::jsonb, \'[]\'::jsonb, \'[]\'::jsonb, TRUE, NULL, 1,\n        transaction_timestamp(), transaction_timestamp()\n    )\n    ON CONFLICT (workspace_id) WHERE role_kind = \'CANONICAL_ADMIN\' DO NOTHING;\n    RETURN NEW;\nEND\n$datariver$')
        op.execute('DO $datariver$\nDECLARE\n    existing_workspace uuid;\nBEGIN\n    SELECT workspace_id INTO existing_workspace\n    FROM iam.access_roles\n    WHERE role_key = \'canonical-admin\'\n      AND role_kind <> \'CANONICAL_ADMIN\'\n    LIMIT 1;\n    IF existing_workspace IS NOT NULL THEN\n        RAISE EXCEPTION\n            \'0089 requires the reserved canonical-admin role key to be unused\';\n    END IF;\n\n    INSERT INTO iam.access_roles (\n        id, workspace_id, role_key, role_kind, management_source,\n        capability_catalog_version, name, description, clearance, groups,\n        allowed_actions, denied_actions, allowed_system_ids, allowed_domain_ids,\n        active, updated_by, version, created_at, updated_at\n    )\n    SELECT\n        gen_random_uuid(), workspace.id, \'canonical-admin\', \'CANONICAL_ADMIN\',\n        \'SERVER_CANONICAL\', \'ACCESS_ROLE_CAPABILITY_CATALOG_V2\', \'Canonical Admin\',\n        \'Server-owned Canonical Admin capability definition.\', 3,\n        \'["security-administrators"]\'::jsonb, \'["admin.manage","archive.read","attachment.download","audit.read","catalog.export","catalog.lineage.read","catalog.quarantine.read","catalog.read","catalog.search","catalog.sync","change.approve","change.create","change.edit","change.raw.create","change.read","change.retry","change.review","chat.query","dashboard.read","erasure.approve","erasure.request","governance.document.archive","governance.document.create","governance.document.edit","governance.document.history.read","governance.document.publish","governance.document.read","governance.document.review","governance.knowledge.read","governance.template.activate","governance.template.archive","governance.template.propose","governance.template.read","governance.template.review","kg.create","kg.edit","kg.export","kg.publish","kg.read","kg.review","legal_hold.place","legal_hold.release","operations.read","operations.retry","quality.audit.read","quality.operations.read","quality.profile.read","quality.read","quality.rule.activate","quality.rule.archive","quality.rule.propose","quality.rule.review","quality.rule.revoke","quality.run.cancel","quality.run.request","quality.run.retry","registration.create","registration.read","registration.validate","retention.manage","retention.read","sharing.invoke","sharing.manage","sharing.publish"]\'::jsonb,\n        \'[]\'::jsonb, \'[]\'::jsonb, \'[]\'::jsonb, TRUE, NULL, 1,\n        transaction_timestamp(), transaction_timestamp()\n    FROM platform.workspaces AS workspace\n    ON CONFLICT (workspace_id) WHERE role_kind = \'CANONICAL_ADMIN\' DO NOTHING;\nEND\n$datariver$')
        op.execute('ALTER TABLE iam.access_roles ENABLE ROW LEVEL SECURITY')
        op.execute('ALTER TABLE iam.access_roles FORCE ROW LEVEL SECURITY')
        op.execute('DROP POLICY IF EXISTS workspace_isolation ON iam.access_roles')
        op.execute('DROP POLICY IF EXISTS access_roles_workspace_select ON iam.access_roles')
        op.execute('DROP POLICY IF EXISTS access_roles_human_insert ON iam.access_roles')
        op.execute('DROP POLICY IF EXISTS access_roles_human_update ON iam.access_roles')
        op.execute('DROP POLICY IF EXISTS access_roles_bootstrap_canonical_insert ON iam.access_roles')
        op.execute('DROP POLICY IF EXISTS access_roles_bootstrap_canonical_update ON iam.access_roles')
        op.execute("CREATE POLICY access_roles_workspace_select ON iam.access_roles\n    FOR SELECT USING (\n        workspace_id = NULLIF(current_setting('app.workspace_id', true), '')::uuid\n    )")
        op.execute("CREATE POLICY access_roles_human_insert ON iam.access_roles\n    FOR INSERT WITH CHECK (\n        workspace_id = NULLIF(current_setting('app.workspace_id', true), '')::uuid\n        AND role_kind = 'HUMAN_ROLE'\n        AND management_source = 'HUMAN_ADMIN'\n        AND capability_catalog_version IS NULL\n        AND updated_by = NULLIF(current_setting('app.subject_id', true), '')::uuid\n    )")
        op.execute("CREATE POLICY access_roles_human_update ON iam.access_roles\n    FOR UPDATE USING (\n        workspace_id = NULLIF(current_setting('app.workspace_id', true), '')::uuid\n        AND role_kind = 'HUMAN_ROLE'\n        AND management_source = 'HUMAN_ADMIN'\n    ) WITH CHECK (\n        workspace_id = NULLIF(current_setting('app.workspace_id', true), '')::uuid\n        AND role_kind = 'HUMAN_ROLE'\n        AND management_source = 'HUMAN_ADMIN'\n        AND capability_catalog_version IS NULL\n        AND updated_by = NULLIF(current_setting('app.subject_id', true), '')::uuid\n    )")
        op.execute('CREATE POLICY access_roles_bootstrap_canonical_insert ON iam.access_roles\n    FOR INSERT TO datariver_bootstrap WITH CHECK (\n        workspace_id = \'00000000-0000-4000-8000-000000000100\'::uuid\n        AND role_key = \'canonical-admin\'\n        AND role_kind = \'CANONICAL_ADMIN\'\n        AND management_source = \'SERVER_CANONICAL\'\n        AND capability_catalog_version = \'ACCESS_ROLE_CAPABILITY_CATALOG_V2\'\n        AND clearance = 3\n        AND groups = \'["security-administrators"]\'::jsonb\n        AND allowed_actions = \'["admin.manage","archive.read","attachment.download","audit.read","catalog.export","catalog.lineage.read","catalog.quarantine.read","catalog.read","catalog.search","catalog.sync","change.approve","change.create","change.edit","change.raw.create","change.read","change.retry","change.review","chat.query","dashboard.read","erasure.approve","erasure.request","governance.document.archive","governance.document.create","governance.document.edit","governance.document.history.read","governance.document.publish","governance.document.read","governance.document.review","governance.knowledge.read","governance.template.activate","governance.template.archive","governance.template.propose","governance.template.read","governance.template.review","kg.create","kg.edit","kg.export","kg.publish","kg.read","kg.review","legal_hold.place","legal_hold.release","operations.read","operations.retry","quality.audit.read","quality.operations.read","quality.profile.read","quality.read","quality.rule.activate","quality.rule.archive","quality.rule.propose","quality.rule.review","quality.rule.revoke","quality.run.cancel","quality.run.request","quality.run.retry","registration.create","registration.read","registration.validate","retention.manage","retention.read","sharing.invoke","sharing.manage","sharing.publish"]\'::jsonb\n        AND denied_actions = \'[]\'::jsonb\n        AND allowed_system_ids = \'[]\'::jsonb\n        AND allowed_domain_ids = \'[]\'::jsonb\n        AND active IS TRUE\n        AND updated_by IS NULL\n    )')
        op.execute('CREATE POLICY access_roles_bootstrap_canonical_update ON iam.access_roles\n    FOR UPDATE TO datariver_bootstrap USING (\n        workspace_id = \'00000000-0000-4000-8000-000000000100\'::uuid\n        AND role_kind = \'CANONICAL_ADMIN\'\n    ) WITH CHECK (\n        workspace_id = \'00000000-0000-4000-8000-000000000100\'::uuid\n        AND role_key = \'canonical-admin\'\n        AND role_kind = \'CANONICAL_ADMIN\'\n        AND management_source = \'SERVER_CANONICAL\'\n        AND capability_catalog_version = \'ACCESS_ROLE_CAPABILITY_CATALOG_V2\'\n        AND clearance = 3\n        AND groups = \'["security-administrators"]\'::jsonb\n        AND allowed_actions = \'["admin.manage","archive.read","attachment.download","audit.read","catalog.export","catalog.lineage.read","catalog.quarantine.read","catalog.read","catalog.search","catalog.sync","change.approve","change.create","change.edit","change.raw.create","change.read","change.retry","change.review","chat.query","dashboard.read","erasure.approve","erasure.request","governance.document.archive","governance.document.create","governance.document.edit","governance.document.history.read","governance.document.publish","governance.document.read","governance.document.review","governance.knowledge.read","governance.template.activate","governance.template.archive","governance.template.propose","governance.template.read","governance.template.review","kg.create","kg.edit","kg.export","kg.publish","kg.read","kg.review","legal_hold.place","legal_hold.release","operations.read","operations.retry","quality.audit.read","quality.operations.read","quality.profile.read","quality.read","quality.rule.activate","quality.rule.archive","quality.rule.propose","quality.rule.review","quality.rule.revoke","quality.run.cancel","quality.run.request","quality.run.retry","registration.create","registration.read","registration.validate","retention.manage","retention.read","sharing.invoke","sharing.manage","sharing.publish"]\'::jsonb\n        AND denied_actions = \'[]\'::jsonb\n        AND allowed_system_ids = \'[]\'::jsonb\n        AND allowed_domain_ids = \'[]\'::jsonb\n        AND active IS TRUE\n        AND updated_by IS NULL\n    )')
        op.execute('ALTER TABLE iam.canonical_admin_bindings ENABLE ROW LEVEL SECURITY')
        op.execute('ALTER TABLE iam.canonical_admin_bindings FORCE ROW LEVEL SECURITY')
        op.execute('DROP POLICY IF EXISTS workspace_isolation ON iam.canonical_admin_bindings')
        op.execute("CREATE POLICY canonical_admin_bindings_workspace_select\n    ON iam.canonical_admin_bindings\n    FOR SELECT USING (\n        workspace_id = NULLIF(current_setting('app.workspace_id', true), '')::uuid\n    )")
        op.execute("CREATE POLICY canonical_admin_bindings_local_insert ON iam.canonical_admin_bindings\n    FOR INSERT TO datariver_bootstrap WITH CHECK (\n        workspace_id = '00000000-0000-4000-8000-000000000100'::uuid\n        AND subject_id = '00000000-0000-4000-8000-000000000101'::uuid\n        AND role_kind = 'CANONICAL_ADMIN'\n        AND capability_catalog_version = 'ACCESS_ROLE_CAPABILITY_CATALOG_V2'\n        AND capability_hash = '51cb767d682a3410c0c0ebc45160b3ed73dcdd09a8c51637e63d7d351eec74a5'\n        AND state = 'ACTIVE'\n        AND binding_source = 'LOCAL_DEVELOPMENT_BOOTSTRAP'\n    )")
        op.execute("CREATE POLICY canonical_admin_bindings_local_update ON iam.canonical_admin_bindings\n    FOR UPDATE TO datariver_bootstrap USING (\n        workspace_id = '00000000-0000-4000-8000-000000000100'::uuid\n        AND subject_id = '00000000-0000-4000-8000-000000000101'::uuid\n        AND binding_source = 'LOCAL_DEVELOPMENT_BOOTSTRAP'\n    ) WITH CHECK (\n        workspace_id = '00000000-0000-4000-8000-000000000100'::uuid\n        AND subject_id = '00000000-0000-4000-8000-000000000101'::uuid\n        AND role_kind = 'CANONICAL_ADMIN'\n        AND capability_catalog_version = 'ACCESS_ROLE_CAPABILITY_CATALOG_V2'\n        AND capability_hash = '51cb767d682a3410c0c0ebc45160b3ed73dcdd09a8c51637e63d7d351eec74a5'\n        AND state = 'ACTIVE'\n        AND binding_source = 'LOCAL_DEVELOPMENT_BOOTSTRAP'\n    )")
        op.execute('REVOKE ALL ON iam.canonical_admin_bindings FROM PUBLIC')
        op.execute("DO $datariver$\nBEGIN\n    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'datariver_app') THEN\n        GRANT SELECT ON iam.canonical_admin_bindings TO datariver_app;\n        REVOKE INSERT, UPDATE, DELETE ON iam.canonical_admin_bindings FROM datariver_app;\n    END IF;\n    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'datariver_bootstrap') THEN\n        GRANT SELECT, INSERT, UPDATE ON iam.access_roles,\n            iam.canonical_admin_bindings TO datariver_bootstrap;\n    END IF;\nEND\n$datariver$;")
        op.execute('CREATE OR REPLACE FUNCTION iam.assign_profile_role(\n    p_workspace_id uuid,\n    p_target_subject_id uuid,\n    p_tier text,\n    p_expected_membership_version integer,\n    p_reason text,\n    p_assurance text,\n    p_access_payload_hash text,\n    p_policy_decision_id uuid\n)\nRETURNS TABLE(membership_version integer, assignment_version integer)\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = pg_catalog, iam, platform\nAS $datariver$\nDECLARE\n    actor_id uuid;\n    target_membership iam.workspace_memberships%ROWTYPE;\n    previous_profile iam.profile_role_assignments%ROWTYPE;\n    previous_role iam.access_role_assignments%ROWTYPE;\n    next_actions jsonb;\n    next_actions_hash text;\n    next_attributes jsonb;\n    filtered_groups jsonb;\n    next_membership_version integer;\n    next_assignment_version integer;\nBEGIN\n    actor_id := NULLIF(current_setting(\'app.subject_id\', true), \'\')::uuid;\n    IF actor_id IS NULL OR NULLIF(current_setting(\'app.workspace_id\', true), \'\')::uuid\n       IS DISTINCT FROM p_workspace_id THEN\n        RAISE EXCEPTION \'A matching DataRiver security context is required\'\n            USING ERRCODE = \'42501\';\n    END IF;\n    IF actor_id = p_target_subject_id THEN\n        RAISE EXCEPTION \'An administrator cannot change their own profile Role\'\n            USING ERRCODE = \'23514\';\n    END IF;\n    IF p_tier NOT IN (\'VIEWER\', \'ENGINEER_STEWARD\', \'MANAGER\') THEN\n        RAISE EXCEPTION \'The profile Role tier is invalid\' USING ERRCODE = \'23514\';\n    END IF;\n    IF char_length(trim(p_reason)) NOT BETWEEN 1 AND 4000\n       OR p_assurance NOT IN (\'PASSWORD_REAUTH\', \'HARDWARE_WEBAUTHN\')\n       OR p_access_payload_hash !~ \'^[0-9a-f]{64}$\'\n       OR p_policy_decision_id IS NULL THEN\n        RAISE EXCEPTION \'The governed profile Role evidence is invalid\'\n            USING ERRCODE = \'23514\';\n    END IF;\n\n    PERFORM 1\n    FROM iam.workspace_memberships AS membership\n    JOIN iam.subjects AS subject ON subject.id = membership.subject_id\n    WHERE membership.workspace_id = p_workspace_id\n      AND membership.subject_id = actor_id\n      AND subject.active IS TRUE AND membership.active IS TRUE\n      AND (membership.access_expires_at IS NULL\n           OR membership.access_expires_at > transaction_timestamp())\n      AND COALESCE(membership.job_function, \'\') <> \'SERVICE_ACCOUNT\'\n      AND membership.clearance >= 3\n      AND COALESCE(membership.attributes -> \'groups\', \'[]\'::jsonb)\n          ? \'security-administrators\'\n      AND COALESCE(membership.attributes -> \'allowed_actions\', \'[]\'::jsonb)\n          ? \'admin.manage\'\n      AND NOT (COALESCE(membership.attributes -> \'denied_actions\', \'[]\'::jsonb)\n          ? \'admin.manage\')\n    FOR KEY SHARE OF membership, subject;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION \'An eligible human security administrator is required\'\n            USING ERRCODE = \'42501\';\n    END IF;\n\n    SELECT membership.* INTO target_membership\n    FROM iam.workspace_memberships AS membership\n    JOIN iam.subjects AS subject ON subject.id = membership.subject_id\n    WHERE membership.workspace_id = p_workspace_id\n      AND membership.subject_id = p_target_subject_id\n      AND subject.active IS TRUE AND membership.active IS TRUE\n      AND (membership.access_expires_at IS NULL\n           OR membership.access_expires_at > transaction_timestamp())\n      AND COALESCE(membership.job_function, \'\') <> \'SERVICE_ACCOUNT\'\n      AND NOT (COALESCE(membership.attributes -> \'groups\', \'[]\'::jsonb)\n          ? \'service-accounts\')\n    FOR UPDATE OF membership;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION \'Only an active human membership can receive a profile Role\'\n            USING ERRCODE = \'23514\';\n    END IF;\n    IF target_membership.version <> p_expected_membership_version THEN\n        RAISE EXCEPTION \'The target membership version changed\' USING ERRCODE = \'40001\';\n    END IF;\n    IF EXISTS (\n        SELECT 1 FROM iam.canonical_admin_bindings AS binding\n        WHERE binding.workspace_id = p_workspace_id\n          AND binding.subject_id = p_target_subject_id\n          AND binding.state = \'ACTIVE\'\n    ) THEN\n        RAISE EXCEPTION \'Canonical Admin demotion requires the protected transition\'\n            USING ERRCODE = \'23514\';\n    END IF;\n\n    next_actions := CASE p_tier\n        WHEN \'VIEWER\' THEN \'["attachment.download","catalog.lineage.read","catalog.read","catalog.search","change.read","chat.query","dashboard.read","governance.document.history.read","governance.document.read","governance.knowledge.read","governance.template.read","operations.read","quality.audit.read","quality.operations.read","quality.profile.read","quality.read"]\'::jsonb\n        WHEN \'ENGINEER_STEWARD\' THEN \'["attachment.download","catalog.lineage.read","catalog.read","catalog.search","change.create","change.edit","change.read","change.review","chat.query","dashboard.read","governance.document.history.read","governance.document.read","governance.knowledge.read","governance.template.read","operations.read","quality.audit.read","quality.operations.read","quality.profile.read","quality.read","quality.rule.archive","quality.rule.propose","quality.run.cancel","quality.run.request","quality.run.retry","registration.create","registration.read","registration.validate"]\'::jsonb\n        WHEN \'MANAGER\' THEN \'["attachment.download","catalog.lineage.read","catalog.read","catalog.search","change.create","change.edit","change.read","change.review","chat.query","dashboard.read","governance.document.archive","governance.document.create","governance.document.edit","governance.document.history.read","governance.document.read","governance.document.review","governance.knowledge.read","governance.template.archive","governance.template.propose","governance.template.read","governance.template.review","kg.create","kg.edit","kg.read","kg.review","operations.read","quality.audit.read","quality.operations.read","quality.profile.read","quality.read","quality.rule.archive","quality.rule.propose","quality.run.cancel","quality.run.request","quality.run.retry","registration.create","registration.read","registration.validate"]\'::jsonb\n    END;\n    next_actions_hash := CASE p_tier\n        WHEN \'VIEWER\' THEN \'1eeb92fb6bad810b9e17537d78983f0a5811a4059fc283d00ce87794d56018ad\'\n        WHEN \'ENGINEER_STEWARD\' THEN \'8188d86d76da94738d97f4ca0b43f3841b29fc36318f95ccd80268130aaf51da\'\n        WHEN \'MANAGER\' THEN \'acef4c78dea7a5c0179a569890f7b3d02d190d102f3534a4db243365b46c72ce\'\n    END;\n    SELECT COALESCE(jsonb_agg(value ORDER BY ordinal), \'[]\'::jsonb)\n      INTO filtered_groups\n    FROM jsonb_array_elements_text(\n        COALESCE(target_membership.attributes -> \'groups\', \'[]\'::jsonb)\n    ) WITH ORDINALITY AS item(value, ordinal)\n    WHERE value <> \'security-administrators\'\n      AND value NOT LIKE \'datariver-role-%\';\n    next_attributes := target_membership.attributes - \'role_id\' - \'managed_by\';\n    next_attributes := jsonb_set(next_attributes, \'{groups}\', filtered_groups, true);\n    next_attributes := jsonb_set(next_attributes, \'{allowed_actions}\', next_actions, true);\n    next_attributes := jsonb_set(next_attributes, \'{allowed_system_ids}\', \'[]\'::jsonb, true);\n\n    SELECT * INTO previous_role FROM iam.access_role_assignments\n    WHERE workspace_id = p_workspace_id AND subject_id = p_target_subject_id AND active IS TRUE\n    FOR UPDATE;\n    IF FOUND THEN\n        UPDATE iam.access_role_assignments\n        SET active = FALSE, version = version + 1, updated_at = transaction_timestamp()\n        WHERE workspace_id = p_workspace_id AND subject_id = p_target_subject_id;\n    END IF;\n    SELECT * INTO previous_profile FROM iam.profile_role_assignments\n    WHERE workspace_id = p_workspace_id AND subject_id = p_target_subject_id\n    FOR UPDATE;\n\n    UPDATE iam.workspace_memberships\n    SET clearance = GREATEST(clearance, 2), attributes = next_attributes,\n        version = version + 1, updated_at = transaction_timestamp()\n    WHERE workspace_id = p_workspace_id AND subject_id = p_target_subject_id\n    RETURNING version INTO next_membership_version;\n\n    IF previous_role.id IS NOT NULL THEN\n        INSERT INTO iam.access_role_assignment_events (\n            id, workspace_id, subject_id, event_type, previous_role_id,\n            previous_role_version, role_id, role_version, membership_version,\n            access_payload_hash, actor_id, occurred_at\n        ) VALUES (\n            gen_random_uuid(), p_workspace_id, p_target_subject_id, \'REMOVED\',\n            previous_role.role_id, previous_role.role_version, NULL, NULL,\n            next_membership_version, p_access_payload_hash, actor_id,\n            transaction_timestamp()\n        );\n    END IF;\n\n    IF previous_profile.workspace_id IS NULL THEN\n        next_assignment_version := 1;\n        INSERT INTO iam.profile_role_assignments (\n            workspace_id, subject_id, tier, policy_version, materialized_actions_hash,\n            membership_version, state, assigned_by, reason, assurance, version,\n            created_at, updated_at\n        ) VALUES (\n            p_workspace_id, p_target_subject_id, p_tier, \'PROFILE_ROLE_POLICY_V1\',\n            next_actions_hash, next_membership_version, \'ACTIVE\', actor_id, trim(p_reason),\n            p_assurance, next_assignment_version, transaction_timestamp(),\n            transaction_timestamp()\n        );\n    ELSE\n        next_assignment_version := previous_profile.version + 1;\n        UPDATE iam.profile_role_assignments\n        SET tier = p_tier, policy_version = \'PROFILE_ROLE_POLICY_V1\',\n            materialized_actions_hash = next_actions_hash,\n            membership_version = next_membership_version, state = \'ACTIVE\',\n            assigned_by = actor_id, reason = trim(p_reason), assurance = p_assurance,\n            version = next_assignment_version, updated_at = transaction_timestamp()\n        WHERE workspace_id = p_workspace_id AND subject_id = p_target_subject_id;\n    END IF;\n    INSERT INTO iam.profile_role_assignment_events (\n        id, workspace_id, subject_id, event_type, previous_tier, next_tier,\n        policy_version, membership_version, assignment_version, actor_id,\n        policy_decision_id,\n        reason, assurance, occurred_at\n    ) VALUES (\n        gen_random_uuid(), p_workspace_id, p_target_subject_id,\n        CASE WHEN previous_profile.workspace_id IS NULL THEN \'ASSIGNED\' ELSE \'CHANGED\' END,\n        CASE WHEN previous_profile.workspace_id IS NULL THEN NULL ELSE previous_profile.tier END,\n        p_tier, \'PROFILE_ROLE_POLICY_V1\', next_membership_version,\n        next_assignment_version, actor_id, p_policy_decision_id, trim(p_reason), p_assurance,\n        transaction_timestamp()\n    );\n    RETURN QUERY SELECT next_membership_version, next_assignment_version;\nEND\n$datariver$')
        op.execute('CREATE OR REPLACE FUNCTION iam.transition_canonical_admin_profile(\n    p_workspace_id uuid,\n    p_target_subject_id uuid,\n    p_next_tier text,\n    p_expected_membership_version integer,\n    p_expected_binding_version integer,\n    p_reason text,\n    p_assurance text,\n    p_access_payload_hash text,\n    p_policy_decision_id uuid\n)\nRETURNS TABLE(membership_version integer, assignment_version integer, binding_version integer)\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = pg_catalog, iam, platform\nAS $datariver$\nDECLARE\n    actor_id uuid;\n    target_membership iam.workspace_memberships%ROWTYPE;\n    canonical_role iam.access_roles%ROWTYPE;\n    current_binding iam.canonical_admin_bindings%ROWTYPE;\n    previous_profile iam.profile_role_assignments%ROWTYPE;\n    previous_role iam.access_role_assignments%ROWTYPE;\n    next_actions jsonb;\n    next_actions_hash text;\n    next_attributes jsonb;\n    filtered_groups jsonb;\n    next_membership_version integer;\n    next_assignment_version integer;\n    next_binding_version integer;\n    active_binding_count integer;\nBEGIN\n    actor_id := NULLIF(current_setting(\'app.subject_id\', true), \'\')::uuid;\n    IF actor_id IS NULL OR NULLIF(current_setting(\'app.workspace_id\', true), \'\')::uuid\n       IS DISTINCT FROM p_workspace_id OR actor_id = p_target_subject_id THEN\n        RAISE EXCEPTION \'A separate Canonical Admin actor is required\' USING ERRCODE = \'42501\';\n    END IF;\n    IF p_assurance <> \'HARDWARE_WEBAUTHN\' THEN\n        RAISE EXCEPTION \'Canonical Admin transitions require hardware WebAuthn\'\n            USING ERRCODE = \'42501\';\n    END IF;\n    IF p_next_tier NOT IN (\'VIEWER\', \'ENGINEER_STEWARD\', \'MANAGER\', \'ADMIN\')\n       OR char_length(trim(p_reason)) NOT BETWEEN 1 AND 4000\n       OR p_access_payload_hash !~ \'^[0-9a-f]{64}$\'\n       OR p_policy_decision_id IS NULL THEN\n        RAISE EXCEPTION \'The protected profile transition evidence is invalid\'\n            USING ERRCODE = \'23514\';\n    END IF;\n    PERFORM 1 FROM platform.workspaces\n    WHERE id = p_workspace_id AND status = \'ACTIVE\' FOR UPDATE;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION \'The workspace is not active\' USING ERRCODE = \'23514\';\n    END IF;\n    PERFORM 1\n    FROM iam.canonical_admin_bindings AS binding\n    JOIN iam.workspace_memberships AS membership\n      ON membership.workspace_id = binding.workspace_id\n     AND membership.subject_id = binding.subject_id\n    JOIN iam.subjects AS subject ON subject.id = membership.subject_id\n    JOIN iam.access_roles AS actor_role\n      ON actor_role.workspace_id = binding.workspace_id\n     AND actor_role.id = binding.canonical_role_id\n     AND actor_role.role_kind = binding.role_kind\n    WHERE binding.workspace_id = p_workspace_id AND binding.subject_id = actor_id\n      AND binding.state = \'ACTIVE\'\n      AND binding.role_kind = \'CANONICAL_ADMIN\'\n      AND binding.canonical_role_version = actor_role.version\n      AND binding.capability_catalog_version = \'ACCESS_ROLE_CAPABILITY_CATALOG_V2\'\n      AND binding.capability_hash = \'51cb767d682a3410c0c0ebc45160b3ed73dcdd09a8c51637e63d7d351eec74a5\'\n      AND binding.membership_version = membership.version\n      AND actor_role.role_key = \'canonical-admin\'\n      AND actor_role.management_source = \'SERVER_CANONICAL\'\n      AND actor_role.capability_catalog_version = \'ACCESS_ROLE_CAPABILITY_CATALOG_V2\'\n      AND actor_role.active IS TRUE AND actor_role.clearance = 3\n      AND actor_role.groups = \'["security-administrators"]\'::jsonb\n      AND actor_role.allowed_actions = \'["admin.manage","archive.read","attachment.download","audit.read","catalog.export","catalog.lineage.read","catalog.quarantine.read","catalog.read","catalog.search","catalog.sync","change.approve","change.create","change.edit","change.raw.create","change.read","change.retry","change.review","chat.query","dashboard.read","erasure.approve","erasure.request","governance.document.archive","governance.document.create","governance.document.edit","governance.document.history.read","governance.document.publish","governance.document.read","governance.document.review","governance.knowledge.read","governance.template.activate","governance.template.archive","governance.template.propose","governance.template.read","governance.template.review","kg.create","kg.edit","kg.export","kg.publish","kg.read","kg.review","legal_hold.place","legal_hold.release","operations.read","operations.retry","quality.audit.read","quality.operations.read","quality.profile.read","quality.read","quality.rule.activate","quality.rule.archive","quality.rule.propose","quality.rule.review","quality.rule.revoke","quality.run.cancel","quality.run.request","quality.run.retry","registration.create","registration.read","registration.validate","retention.manage","retention.read","sharing.invoke","sharing.manage","sharing.publish"]\'::jsonb\n      AND actor_role.denied_actions = \'[]\'::jsonb\n      AND actor_role.allowed_system_ids = \'[]\'::jsonb\n      AND actor_role.allowed_domain_ids = \'[]\'::jsonb\n      AND subject.active IS TRUE AND membership.active IS TRUE\n      AND (membership.access_expires_at IS NULL\n           OR membership.access_expires_at > transaction_timestamp())\n      AND COALESCE(membership.job_function, \'\') <> \'SERVICE_ACCOUNT\'\n      AND membership.clearance = 3\n      AND COALESCE(membership.attributes -> \'groups\', \'[]\'::jsonb)\n          ? \'security-administrators\'\n      AND NOT (COALESCE(membership.attributes -> \'groups\', \'[]\'::jsonb)\n          ? \'service-accounts\')\n      AND NOT EXISTS (\n          SELECT 1\n          FROM jsonb_array_elements_text(\n              COALESCE(membership.attributes -> \'groups\', \'[]\'::jsonb)\n          ) AS membership_group(value)\n          WHERE membership_group.value LIKE \'datariver-role-%\'\n      )\n      AND COALESCE(membership.attributes -> \'allowed_actions\', \'[]\'::jsonb)\n          = \'["admin.manage","archive.read","attachment.download","audit.read","catalog.export","catalog.lineage.read","catalog.quarantine.read","catalog.read","catalog.search","catalog.sync","change.approve","change.create","change.edit","change.raw.create","change.read","change.retry","change.review","chat.query","dashboard.read","erasure.approve","erasure.request","governance.document.archive","governance.document.create","governance.document.edit","governance.document.history.read","governance.document.publish","governance.document.read","governance.document.review","governance.knowledge.read","governance.template.activate","governance.template.archive","governance.template.propose","governance.template.read","governance.template.review","kg.create","kg.edit","kg.export","kg.publish","kg.read","kg.review","legal_hold.place","legal_hold.release","operations.read","operations.retry","quality.audit.read","quality.operations.read","quality.profile.read","quality.read","quality.rule.activate","quality.rule.archive","quality.rule.propose","quality.rule.review","quality.rule.revoke","quality.run.cancel","quality.run.request","quality.run.retry","registration.create","registration.read","registration.validate","retention.manage","retention.read","sharing.invoke","sharing.manage","sharing.publish"]\'::jsonb\n      AND COALESCE(membership.attributes -> \'denied_actions\', \'[]\'::jsonb) = \'[]\'::jsonb\n      AND COALESCE(membership.attributes -> \'allowed_system_ids\', \'[]\'::jsonb) = \'[]\'::jsonb\n    FOR KEY SHARE OF binding, membership, subject, actor_role;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION \'The actor Canonical Admin binding is not current\'\n            USING ERRCODE = \'42501\';\n    END IF;\n    SELECT * INTO canonical_role FROM iam.access_roles\n    WHERE workspace_id = p_workspace_id AND role_key = \'canonical-admin\'\n      AND role_kind = \'CANONICAL_ADMIN\'\n      AND management_source = \'SERVER_CANONICAL\' AND active IS TRUE\n      AND capability_catalog_version = \'ACCESS_ROLE_CAPABILITY_CATALOG_V2\'\n      AND clearance = 3\n      AND groups = \'["security-administrators"]\'::jsonb\n      AND allowed_actions = \'["admin.manage","archive.read","attachment.download","audit.read","catalog.export","catalog.lineage.read","catalog.quarantine.read","catalog.read","catalog.search","catalog.sync","change.approve","change.create","change.edit","change.raw.create","change.read","change.retry","change.review","chat.query","dashboard.read","erasure.approve","erasure.request","governance.document.archive","governance.document.create","governance.document.edit","governance.document.history.read","governance.document.publish","governance.document.read","governance.document.review","governance.knowledge.read","governance.template.activate","governance.template.archive","governance.template.propose","governance.template.read","governance.template.review","kg.create","kg.edit","kg.export","kg.publish","kg.read","kg.review","legal_hold.place","legal_hold.release","operations.read","operations.retry","quality.audit.read","quality.operations.read","quality.profile.read","quality.read","quality.rule.activate","quality.rule.archive","quality.rule.propose","quality.rule.review","quality.rule.revoke","quality.run.cancel","quality.run.request","quality.run.retry","registration.create","registration.read","registration.validate","retention.manage","retention.read","sharing.invoke","sharing.manage","sharing.publish"]\'::jsonb\n      AND denied_actions = \'[]\'::jsonb\n      AND allowed_system_ids = \'[]\'::jsonb\n      AND allowed_domain_ids = \'[]\'::jsonb\n    FOR KEY SHARE;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION \'The Canonical Admin definition is unavailable\'\n            USING ERRCODE = \'23514\';\n    END IF;\n    SELECT membership.* INTO target_membership\n    FROM iam.workspace_memberships AS membership\n    JOIN iam.subjects AS subject ON subject.id = membership.subject_id\n    WHERE membership.workspace_id = p_workspace_id\n      AND membership.subject_id = p_target_subject_id\n      AND subject.active IS TRUE AND membership.active IS TRUE\n      AND (membership.access_expires_at IS NULL\n           OR membership.access_expires_at > transaction_timestamp())\n      AND COALESCE(membership.job_function, \'\') <> \'SERVICE_ACCOUNT\'\n      AND NOT (COALESCE(membership.attributes -> \'groups\', \'[]\'::jsonb)\n          ? \'service-accounts\')\n    FOR UPDATE OF membership;\n    IF NOT FOUND OR target_membership.version <> p_expected_membership_version THEN\n        RAISE EXCEPTION \'The target active human membership changed\'\n            USING ERRCODE = \'40001\';\n    END IF;\n    SELECT * INTO current_binding FROM iam.canonical_admin_bindings\n    WHERE workspace_id = p_workspace_id AND subject_id = p_target_subject_id FOR UPDATE;\n    SELECT * INTO previous_profile FROM iam.profile_role_assignments\n    WHERE workspace_id = p_workspace_id AND subject_id = p_target_subject_id FOR UPDATE;\n    SELECT * INTO previous_role FROM iam.access_role_assignments\n    WHERE workspace_id = p_workspace_id AND subject_id = p_target_subject_id AND active IS TRUE\n    FOR UPDATE;\n\n    IF p_next_tier = \'ADMIN\' THEN\n        IF current_binding.workspace_id IS NOT NULL AND current_binding.state = \'ACTIVE\' THEN\n            RAISE EXCEPTION \'The target is already a Canonical Admin\' USING ERRCODE = \'23514\';\n        END IF;\n        IF current_binding.workspace_id IS NULL THEN\n            IF p_expected_binding_version <> 0 THEN\n                RAISE EXCEPTION \'A new Canonical Admin binding expects version zero\'\n                    USING ERRCODE = \'40001\';\n            END IF;\n        ELSIF current_binding.state = \'REVOKED\' THEN\n            IF p_expected_binding_version <> current_binding.version THEN\n                RAISE EXCEPTION \'The revoked Canonical Admin binding changed\'\n                    USING ERRCODE = \'40001\';\n            END IF;\n        ELSE\n            RAISE EXCEPTION \'The Canonical Admin binding state is invalid\'\n                USING ERRCODE = \'23514\';\n        END IF;\n        IF jsonb_array_length(\n            COALESCE(target_membership.attributes -> \'denied_actions\', \'[]\'::jsonb)\n        ) <> 0 THEN\n            RAISE EXCEPTION \'Explicit denies must be resolved before Admin promotion\'\n                USING ERRCODE = \'23514\';\n        END IF;\n        SELECT COALESCE(jsonb_agg(value ORDER BY ordinal), \'[]\'::jsonb)\n          INTO filtered_groups\n        FROM jsonb_array_elements_text(\n            COALESCE(target_membership.attributes -> \'groups\', \'[]\'::jsonb)\n        ) WITH ORDINALITY AS item(value, ordinal)\n        WHERE value NOT LIKE \'datariver-role-%\' AND value <> \'security-administrators\';\n        filtered_groups := filtered_groups || \'["security-administrators"]\'::jsonb;\n        next_attributes := target_membership.attributes - \'role_id\' - \'managed_by\';\n        next_attributes := jsonb_set(next_attributes, \'{groups}\', filtered_groups, true);\n        next_attributes := jsonb_set(\n            next_attributes, \'{allowed_actions}\', \'["admin.manage","archive.read","attachment.download","audit.read","catalog.export","catalog.lineage.read","catalog.quarantine.read","catalog.read","catalog.search","catalog.sync","change.approve","change.create","change.edit","change.raw.create","change.read","change.retry","change.review","chat.query","dashboard.read","erasure.approve","erasure.request","governance.document.archive","governance.document.create","governance.document.edit","governance.document.history.read","governance.document.publish","governance.document.read","governance.document.review","governance.knowledge.read","governance.template.activate","governance.template.archive","governance.template.propose","governance.template.read","governance.template.review","kg.create","kg.edit","kg.export","kg.publish","kg.read","kg.review","legal_hold.place","legal_hold.release","operations.read","operations.retry","quality.audit.read","quality.operations.read","quality.profile.read","quality.read","quality.rule.activate","quality.rule.archive","quality.rule.propose","quality.rule.review","quality.rule.revoke","quality.run.cancel","quality.run.request","quality.run.retry","registration.create","registration.read","registration.validate","retention.manage","retention.read","sharing.invoke","sharing.manage","sharing.publish"]\'::jsonb, true\n        );\n        next_attributes := jsonb_set(next_attributes, \'{allowed_system_ids}\', \'[]\'::jsonb, true);\n        UPDATE iam.workspace_memberships\n        SET clearance = 3, attributes = next_attributes, version = version + 1,\n            updated_at = transaction_timestamp()\n        WHERE workspace_id = p_workspace_id AND subject_id = p_target_subject_id\n        RETURNING version INTO next_membership_version;\n        IF previous_role.id IS NOT NULL THEN\n            UPDATE iam.access_role_assignments\n            SET active = FALSE, version = version + 1, updated_at = transaction_timestamp()\n            WHERE workspace_id = p_workspace_id AND subject_id = p_target_subject_id;\n            INSERT INTO iam.access_role_assignment_events (\n                id, workspace_id, subject_id, event_type, previous_role_id,\n                previous_role_version, role_id, role_version, membership_version,\n                access_payload_hash, actor_id, occurred_at\n            ) VALUES (\n                gen_random_uuid(), p_workspace_id, p_target_subject_id, \'REMOVED\',\n                previous_role.role_id, previous_role.role_version, NULL, NULL,\n                next_membership_version, p_access_payload_hash, actor_id,\n                transaction_timestamp()\n            );\n        END IF;\n        IF previous_profile.workspace_id IS NOT NULL THEN\n            UPDATE iam.profile_role_assignments\n            SET state = \'REVOKED\', membership_version = next_membership_version,\n                assigned_by = actor_id, reason = trim(p_reason), assurance = p_assurance,\n                version = version + 1, updated_at = transaction_timestamp()\n            WHERE workspace_id = p_workspace_id AND subject_id = p_target_subject_id\n            RETURNING version INTO next_assignment_version;\n        ELSE\n            next_assignment_version := 1;\n        END IF;\n        IF current_binding.workspace_id IS NULL THEN\n            next_binding_version := 1;\n            INSERT INTO iam.canonical_admin_bindings (\n                workspace_id, subject_id, canonical_role_id, role_kind,\n                canonical_role_version, capability_catalog_version, capability_hash,\n                membership_version, membership_access_hash, state, binding_source,\n                version, created_at, updated_at\n            ) VALUES (\n                p_workspace_id, p_target_subject_id, canonical_role.id, \'CANONICAL_ADMIN\',\n                canonical_role.version, \'ACCESS_ROLE_CAPABILITY_CATALOG_V2\',\n                \'51cb767d682a3410c0c0ebc45160b3ed73dcdd09a8c51637e63d7d351eec74a5\', next_membership_version,\n                p_access_payload_hash, \'ACTIVE\', \'GOVERNED_ADMIN_ASSIGNMENT\', 1,\n                transaction_timestamp(), transaction_timestamp()\n            );\n        ELSE\n            next_binding_version := current_binding.version + 1;\n            UPDATE iam.canonical_admin_bindings\n            SET canonical_role_id = canonical_role.id,\n                canonical_role_version = canonical_role.version,\n                capability_catalog_version = \'ACCESS_ROLE_CAPABILITY_CATALOG_V2\',\n                capability_hash = \'51cb767d682a3410c0c0ebc45160b3ed73dcdd09a8c51637e63d7d351eec74a5\',\n                membership_version = next_membership_version,\n                membership_access_hash = p_access_payload_hash, state = \'ACTIVE\',\n                binding_source = \'GOVERNED_ADMIN_ASSIGNMENT\',\n                version = next_binding_version, updated_at = transaction_timestamp()\n            WHERE workspace_id = p_workspace_id AND subject_id = p_target_subject_id;\n        END IF;\n        INSERT INTO iam.profile_role_assignment_events (\n            id, workspace_id, subject_id, event_type, previous_tier, next_tier,\n            policy_version, membership_version, assignment_version, actor_id,\n            policy_decision_id,\n            reason, assurance, occurred_at\n        ) VALUES (\n            gen_random_uuid(), p_workspace_id, p_target_subject_id, \'PROMOTED_TO_ADMIN\',\n            CASE WHEN previous_profile.workspace_id IS NULL\n                THEN NULL ELSE previous_profile.tier END,\n            \'ADMIN\', \'PROFILE_ROLE_POLICY_V1\', next_membership_version,\n            next_assignment_version, actor_id, p_policy_decision_id, trim(p_reason), p_assurance,\n            transaction_timestamp()\n        );\n    ELSE\n        IF current_binding.workspace_id IS NULL OR current_binding.state <> \'ACTIVE\'\n           OR current_binding.version <> p_expected_binding_version THEN\n            RAISE EXCEPTION \'The target Canonical Admin binding changed\'\n                USING ERRCODE = \'40001\';\n        END IF;\n        SELECT count(*) INTO active_binding_count\n        FROM iam.canonical_admin_bindings AS binding\n        JOIN iam.workspace_memberships AS membership\n          ON membership.workspace_id = binding.workspace_id\n         AND membership.subject_id = binding.subject_id\n        JOIN iam.subjects AS subject ON subject.id = membership.subject_id\n        JOIN iam.access_roles AS role\n          ON role.workspace_id = binding.workspace_id\n         AND role.id = binding.canonical_role_id\n         AND role.role_kind = binding.role_kind\n        WHERE binding.workspace_id = p_workspace_id\n          AND binding.state = \'ACTIVE\'\n          AND binding.role_kind = \'CANONICAL_ADMIN\'\n          AND binding.canonical_role_version = role.version\n          AND binding.capability_catalog_version = \'ACCESS_ROLE_CAPABILITY_CATALOG_V2\'\n          AND binding.capability_hash = \'51cb767d682a3410c0c0ebc45160b3ed73dcdd09a8c51637e63d7d351eec74a5\'\n          AND binding.membership_version = membership.version\n          AND role.role_key = \'canonical-admin\'\n          AND role.management_source = \'SERVER_CANONICAL\'\n          AND role.capability_catalog_version = \'ACCESS_ROLE_CAPABILITY_CATALOG_V2\'\n          AND role.active IS TRUE AND role.clearance = 3\n          AND role.groups = \'["security-administrators"]\'::jsonb\n          AND role.allowed_actions = \'["admin.manage","archive.read","attachment.download","audit.read","catalog.export","catalog.lineage.read","catalog.quarantine.read","catalog.read","catalog.search","catalog.sync","change.approve","change.create","change.edit","change.raw.create","change.read","change.retry","change.review","chat.query","dashboard.read","erasure.approve","erasure.request","governance.document.archive","governance.document.create","governance.document.edit","governance.document.history.read","governance.document.publish","governance.document.read","governance.document.review","governance.knowledge.read","governance.template.activate","governance.template.archive","governance.template.propose","governance.template.read","governance.template.review","kg.create","kg.edit","kg.export","kg.publish","kg.read","kg.review","legal_hold.place","legal_hold.release","operations.read","operations.retry","quality.audit.read","quality.operations.read","quality.profile.read","quality.read","quality.rule.activate","quality.rule.archive","quality.rule.propose","quality.rule.review","quality.rule.revoke","quality.run.cancel","quality.run.request","quality.run.retry","registration.create","registration.read","registration.validate","retention.manage","retention.read","sharing.invoke","sharing.manage","sharing.publish"]\'::jsonb\n          AND role.denied_actions = \'[]\'::jsonb\n          AND role.allowed_system_ids = \'[]\'::jsonb\n          AND role.allowed_domain_ids = \'[]\'::jsonb\n          AND subject.active IS TRUE AND membership.active IS TRUE\n          AND (membership.access_expires_at IS NULL\n               OR membership.access_expires_at > transaction_timestamp())\n          AND COALESCE(membership.job_function, \'\') <> \'SERVICE_ACCOUNT\'\n          AND membership.clearance = 3\n          AND COALESCE(membership.attributes -> \'groups\', \'[]\'::jsonb)\n              ? \'security-administrators\'\n          AND NOT (COALESCE(membership.attributes -> \'groups\', \'[]\'::jsonb)\n              ? \'service-accounts\')\n          AND NOT EXISTS (\n              SELECT 1\n              FROM jsonb_array_elements_text(\n                  COALESCE(membership.attributes -> \'groups\', \'[]\'::jsonb)\n              ) AS membership_group(value)\n              WHERE membership_group.value LIKE \'datariver-role-%\'\n          )\n          AND COALESCE(membership.attributes -> \'allowed_actions\', \'[]\'::jsonb)\n              = \'["admin.manage","archive.read","attachment.download","audit.read","catalog.export","catalog.lineage.read","catalog.quarantine.read","catalog.read","catalog.search","catalog.sync","change.approve","change.create","change.edit","change.raw.create","change.read","change.retry","change.review","chat.query","dashboard.read","erasure.approve","erasure.request","governance.document.archive","governance.document.create","governance.document.edit","governance.document.history.read","governance.document.publish","governance.document.read","governance.document.review","governance.knowledge.read","governance.template.activate","governance.template.archive","governance.template.propose","governance.template.read","governance.template.review","kg.create","kg.edit","kg.export","kg.publish","kg.read","kg.review","legal_hold.place","legal_hold.release","operations.read","operations.retry","quality.audit.read","quality.operations.read","quality.profile.read","quality.read","quality.rule.activate","quality.rule.archive","quality.rule.propose","quality.rule.review","quality.rule.revoke","quality.run.cancel","quality.run.request","quality.run.retry","registration.create","registration.read","registration.validate","retention.manage","retention.read","sharing.invoke","sharing.manage","sharing.publish"]\'::jsonb\n          AND COALESCE(membership.attributes -> \'denied_actions\', \'[]\'::jsonb) = \'[]\'::jsonb\n          AND COALESCE(membership.attributes -> \'allowed_system_ids\', \'[]\'::jsonb) = \'[]\'::jsonb;\n        IF active_binding_count <= 1 THEN\n            RAISE EXCEPTION \'The last Canonical Admin cannot be demoted\'\n                USING ERRCODE = \'23514\';\n        END IF;\n        next_actions := CASE p_next_tier\n        WHEN \'VIEWER\' THEN \'["attachment.download","catalog.lineage.read","catalog.read","catalog.search","change.read","chat.query","dashboard.read","governance.document.history.read","governance.document.read","governance.knowledge.read","governance.template.read","operations.read","quality.audit.read","quality.operations.read","quality.profile.read","quality.read"]\'::jsonb\n        WHEN \'ENGINEER_STEWARD\' THEN \'["attachment.download","catalog.lineage.read","catalog.read","catalog.search","change.create","change.edit","change.read","change.review","chat.query","dashboard.read","governance.document.history.read","governance.document.read","governance.knowledge.read","governance.template.read","operations.read","quality.audit.read","quality.operations.read","quality.profile.read","quality.read","quality.rule.archive","quality.rule.propose","quality.run.cancel","quality.run.request","quality.run.retry","registration.create","registration.read","registration.validate"]\'::jsonb\n        WHEN \'MANAGER\' THEN \'["attachment.download","catalog.lineage.read","catalog.read","catalog.search","change.create","change.edit","change.read","change.review","chat.query","dashboard.read","governance.document.archive","governance.document.create","governance.document.edit","governance.document.history.read","governance.document.read","governance.document.review","governance.knowledge.read","governance.template.archive","governance.template.propose","governance.template.read","governance.template.review","kg.create","kg.edit","kg.read","kg.review","operations.read","quality.audit.read","quality.operations.read","quality.profile.read","quality.read","quality.rule.archive","quality.rule.propose","quality.run.cancel","quality.run.request","quality.run.retry","registration.create","registration.read","registration.validate"]\'::jsonb\n    END;\n        next_actions_hash := CASE p_next_tier\n        WHEN \'VIEWER\' THEN \'1eeb92fb6bad810b9e17537d78983f0a5811a4059fc283d00ce87794d56018ad\'\n        WHEN \'ENGINEER_STEWARD\' THEN \'8188d86d76da94738d97f4ca0b43f3841b29fc36318f95ccd80268130aaf51da\'\n        WHEN \'MANAGER\' THEN \'acef4c78dea7a5c0179a569890f7b3d02d190d102f3534a4db243365b46c72ce\'\n    END;\n        SELECT COALESCE(jsonb_agg(value ORDER BY ordinal), \'[]\'::jsonb)\n          INTO filtered_groups\n        FROM jsonb_array_elements_text(\n            COALESCE(target_membership.attributes -> \'groups\', \'[]\'::jsonb)\n        ) WITH ORDINALITY AS item(value, ordinal)\n        WHERE value <> \'security-administrators\' AND value NOT LIKE \'datariver-role-%\';\n        next_attributes := target_membership.attributes - \'role_id\' - \'managed_by\';\n        next_attributes := jsonb_set(next_attributes, \'{groups}\', filtered_groups, true);\n        next_attributes := jsonb_set(next_attributes, \'{allowed_actions}\', next_actions, true);\n        next_attributes := jsonb_set(next_attributes, \'{allowed_system_ids}\', \'[]\'::jsonb, true);\n        UPDATE iam.workspace_memberships\n        SET clearance = GREATEST(clearance, 2), attributes = next_attributes,\n            version = version + 1, updated_at = transaction_timestamp()\n        WHERE workspace_id = p_workspace_id AND subject_id = p_target_subject_id\n        RETURNING version INTO next_membership_version;\n        next_binding_version := current_binding.version + 1;\n        UPDATE iam.canonical_admin_bindings\n        SET state = \'REVOKED\', membership_version = next_membership_version,\n            membership_access_hash = p_access_payload_hash,\n            version = next_binding_version, updated_at = transaction_timestamp()\n        WHERE workspace_id = p_workspace_id AND subject_id = p_target_subject_id;\n        IF previous_profile.workspace_id IS NULL THEN\n            next_assignment_version := 1;\n            INSERT INTO iam.profile_role_assignments (\n                workspace_id, subject_id, tier, policy_version,\n                materialized_actions_hash, membership_version, state, assigned_by,\n                reason, assurance, version, created_at, updated_at\n            ) VALUES (\n                p_workspace_id, p_target_subject_id, p_next_tier,\n                \'PROFILE_ROLE_POLICY_V1\', next_actions_hash,\n                next_membership_version, \'ACTIVE\', actor_id, trim(p_reason), p_assurance,\n                1, transaction_timestamp(), transaction_timestamp()\n            );\n        ELSE\n            next_assignment_version := previous_profile.version + 1;\n            UPDATE iam.profile_role_assignments\n            SET tier = p_next_tier, policy_version = \'PROFILE_ROLE_POLICY_V1\',\n                materialized_actions_hash = next_actions_hash,\n                membership_version = next_membership_version, state = \'ACTIVE\',\n                assigned_by = actor_id, reason = trim(p_reason), assurance = p_assurance,\n                version = next_assignment_version, updated_at = transaction_timestamp()\n            WHERE workspace_id = p_workspace_id AND subject_id = p_target_subject_id;\n        END IF;\n        INSERT INTO iam.profile_role_assignment_events (\n            id, workspace_id, subject_id, event_type, previous_tier, next_tier,\n            policy_version, membership_version, assignment_version, actor_id,\n            policy_decision_id,\n            reason, assurance, occurred_at\n        ) VALUES (\n            gen_random_uuid(), p_workspace_id, p_target_subject_id,\n            \'DEMOTED_FROM_ADMIN\', \'ADMIN\', p_next_tier,\n            \'PROFILE_ROLE_POLICY_V1\', next_membership_version,\n            next_assignment_version, actor_id, p_policy_decision_id, trim(p_reason), p_assurance,\n            transaction_timestamp()\n        );\n    END IF;\n    RETURN QUERY SELECT next_membership_version, next_assignment_version, next_binding_version;\nEND\n$datariver$')
        op.execute('ALTER TABLE iam.profile_role_assignments ENABLE ROW LEVEL SECURITY')
        op.execute('ALTER TABLE iam.profile_role_assignments FORCE ROW LEVEL SECURITY')
        op.execute('ALTER TABLE iam.profile_role_assignment_events ENABLE ROW LEVEL SECURITY')
        op.execute('ALTER TABLE iam.profile_role_assignment_events FORCE ROW LEVEL SECURITY')
        op.execute('DROP POLICY IF EXISTS profile_role_assignments_workspace ON iam.profile_role_assignments')
        op.execute('DROP POLICY IF EXISTS profile_role_assignment_events_workspace ON iam.profile_role_assignment_events')
        op.execute("CREATE POLICY profile_role_assignments_workspace ON iam.profile_role_assignments\n    USING (workspace_id = NULLIF(current_setting('app.workspace_id', true), '')::uuid)\n    WITH CHECK (workspace_id = NULLIF(current_setting('app.workspace_id', true), '')::uuid)")
        op.execute("CREATE POLICY profile_role_assignment_events_workspace\n    ON iam.profile_role_assignment_events\n    USING (workspace_id = NULLIF(current_setting('app.workspace_id', true), '')::uuid)\n    WITH CHECK (workspace_id = NULLIF(current_setting('app.workspace_id', true), '')::uuid)")
        op.execute('DROP POLICY IF EXISTS canonical_admin_bindings_governed_insert ON iam.canonical_admin_bindings')
        op.execute('DROP POLICY IF EXISTS canonical_admin_bindings_governed_update ON iam.canonical_admin_bindings')
        op.execute("CREATE POLICY canonical_admin_bindings_governed_insert\n    ON iam.canonical_admin_bindings FOR INSERT WITH CHECK (\n        workspace_id = NULLIF(current_setting('app.workspace_id', true), '')::uuid\n        AND subject_id <> NULLIF(current_setting('app.subject_id', true), '')::uuid\n        AND binding_source = 'GOVERNED_ADMIN_ASSIGNMENT'\n    )")
        op.execute("CREATE POLICY canonical_admin_bindings_governed_update\n    ON iam.canonical_admin_bindings FOR UPDATE USING (\n        workspace_id = NULLIF(current_setting('app.workspace_id', true), '')::uuid\n        AND subject_id <> NULLIF(current_setting('app.subject_id', true), '')::uuid\n    ) WITH CHECK (\n        workspace_id = NULLIF(current_setting('app.workspace_id', true), '')::uuid\n        AND subject_id <> NULLIF(current_setting('app.subject_id', true), '')::uuid\n        AND binding_source IN ('LOCAL_DEVELOPMENT_BOOTSTRAP', 'GOVERNED_ADMIN_ASSIGNMENT')\n    )")
        op.execute('REVOKE ALL ON iam.profile_role_assignments FROM PUBLIC')
        op.execute('REVOKE ALL ON iam.profile_role_assignment_events FROM PUBLIC')
        op.execute('REVOKE ALL ON FUNCTION iam.assign_profile_role(uuid, uuid, text, integer, text, text, text, uuid) FROM PUBLIC')
        op.execute('REVOKE ALL ON FUNCTION iam.transition_canonical_admin_profile(uuid, uuid, text, integer, integer, text, text, text, uuid) FROM PUBLIC')
        op.execute("DO $datariver$\nBEGIN\n    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'datariver_app') THEN\n        GRANT SELECT ON iam.profile_role_assignments,\n            iam.profile_role_assignment_events TO datariver_app;\n        REVOKE INSERT, UPDATE, DELETE ON iam.profile_role_assignments,\n            iam.profile_role_assignment_events FROM datariver_app;\n        GRANT EXECUTE ON FUNCTION iam.assign_profile_role(uuid, uuid, text, integer, text, text, text, uuid) TO datariver_app;\n        GRANT EXECUTE ON FUNCTION iam.transition_canonical_admin_profile(uuid, uuid, text, integer, integer, text, text, text, uuid)\n            TO datariver_app;\n    END IF;\nEND\n$datariver$;")
        op.execute('CREATE TRIGGER ensure_canonical_admin_definition AFTER INSERT ON platform.workspaces FOR EACH ROW EXECUTE FUNCTION iam.ensure_canonical_admin_definition()')
        op.execute("\n        CREATE FUNCTION iam.resolve_default_workspace(\n            p_issuer text,\n            p_external_subject text\n        )\n        RETURNS uuid\n        LANGUAGE sql\n        STABLE\n        SECURITY DEFINER\n        SET search_path = pg_catalog, iam, platform\n        AS $datariver$\n            SELECT membership.workspace_id\n            FROM iam.subjects AS subject\n            JOIN iam.workspace_memberships AS membership\n              ON membership.subject_id = subject.id\n            JOIN platform.workspaces AS workspace\n              ON workspace.id = membership.workspace_id\n            WHERE subject.issuer = p_issuer\n              AND subject.external_subject = p_external_subject\n              AND subject.active IS TRUE\n              AND membership.active IS TRUE\n              AND (\n                  membership.access_expires_at IS NULL\n                  OR membership.access_expires_at > CURRENT_TIMESTAMP\n              )\n              AND workspace.status = 'ACTIVE'\n            ORDER BY\n              CASE WHEN membership.attributes ->> 'default_workspace' = 'true'\n                THEN 0 ELSE 1 END,\n              workspace.slug ASC,\n              membership.workspace_id ASC\n            LIMIT 1\n        $datariver$\n        ")
        op.execute('REVOKE ALL ON FUNCTION iam.resolve_default_workspace(text, text) FROM PUBLIC')
