        op.execute('GRANT EXECUTE ON FUNCTION knowledge.lock_source_analysis_finalization()\nTO datariver_knowledge;')
        op.execute('GRANT EXECUTE ON FUNCTION knowledge.current_source_claim_scope()\nTO datariver_knowledge;')
        op.execute("CREATE OR REPLACE FUNCTION sharing.prepare_api_invocation_v2(\n    p_workspace_id uuid,\n    p_subject_id uuid,\n    p_grant_id uuid,\n    p_invocation_key_hash text,\n    p_legacy_invocation_key text,\n    p_consumer_issuer text,\n    p_consumer_client_id text,\n    p_product_id uuid,\n    p_product_version_id uuid,\n    p_graph_id uuid,\n    p_release_id uuid,\n    p_release_content_hash text,\n    p_surface text,\n    p_requested_scope text,\n    p_effective_classification integer,\n    p_security_scope_hash text,\n    p_request_hash text,\n    p_result_type text\n)\nRETURNS TABLE (\n    status text,\n    invocation_id uuid,\n    stored_result_hash text,\n    stored_result_size_bytes integer,\n    stored_retention_policy_id uuid,\n    stored_retention_policy_hash text,\n    stored_retention_data_class text,\n    stored_retention_until timestamptz,\n    result_document text,\n    minute_units bigint,\n    month_units bigint\n)\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = pg_catalog, sharing\nSET TimeZone = 'UTC'\nAS $$\nDECLARE\n    stored sharing.api_invocations%ROWTYPE;\n    stored_result sharing.api_invocation_results%ROWTYPE;\n    product sharing.api_products%ROWTYPE;\n    version sharing.api_product_versions%ROWTYPE;\n    grant_value sharing.consumer_grants%ROWTYPE;\n    consumer iam.workspace_memberships%ROWTYPE;\n    consumer_subject iam.subjects%ROWTYPE;\n    current_retention_policy_id uuid;\n    current_retention_policy_hash text;\n    current_retention_data_class text;\n    release_valid boolean;\n    lineage_count bigint;\n    observed_at timestamptz := clock_timestamp();\n    observed_month timestamptz :=\n        date_trunc('month', observed_at AT TIME ZONE 'UTC') AT TIME ZONE 'UTC';\nBEGIN\n    IF p_workspace_id IS DISTINCT FROM\n            NULLIF(current_setting('app.workspace_id', true), '')::uuid\n       OR p_subject_id IS DISTINCT FROM\n            NULLIF(current_setting('app.subject_id', true), '')::uuid THEN\n        RAISE EXCEPTION 'Sharing invocation context is absent or mismatched'\n            USING ERRCODE = '42501';\n    END IF;\n    IF COALESCE(char_length(p_invocation_key_hash), 0) <> 64\n       OR COALESCE(char_length(p_release_content_hash), 0) <> 64\n       OR COALESCE(char_length(p_security_scope_hash), 0) <> 64\n       OR COALESCE(char_length(p_request_hash), 0) <> 64\n       OR COALESCE(char_length(p_legacy_invocation_key), 0) NOT BETWEEN 16 AND 200\n       OR COALESCE(char_length(p_consumer_issuer), 0) NOT BETWEEN 1 AND 500\n       OR COALESCE(char_length(p_consumer_client_id), 0) NOT BETWEEN 3 AND 255\n       OR COALESCE(char_length(p_surface), 0) NOT BETWEEN 1 AND 32\n       OR COALESCE(char_length(p_requested_scope), 0) NOT BETWEEN 1 AND 100\n       OR COALESCE(char_length(p_result_type), 0) NOT BETWEEN 1 AND 32\n       OR p_invocation_key_hash !~ '^[0-9a-f]{64}$'\n       OR p_security_scope_hash !~ '^[0-9a-f]{64}$'\n       OR p_request_hash !~ '^[0-9a-f]{64}$'\n       OR p_release_content_hash !~ '^[0-9a-f]{64}$' THEN\n        RAISE EXCEPTION 'Sharing invocation hashes are invalid'\n            USING ERRCODE = '22023';\n    END IF;\n\n    SELECT * INTO product\n    FROM sharing.api_products AS selected_product\n    WHERE selected_product.workspace_id = p_workspace_id\n      AND selected_product.id = p_product_id\n      AND selected_product.graph_id = p_graph_id\n      AND selected_product.state = 'PUBLISHED'\n      AND selected_product.current_version_id = p_product_version_id\n    FOR SHARE;\n    SELECT * INTO version\n    FROM sharing.api_product_versions AS selected_version\n    WHERE selected_version.workspace_id = p_workspace_id\n      AND selected_version.product_id = p_product_id\n      AND selected_version.id = p_product_version_id\n      AND selected_version.graph_id = p_graph_id\n      AND selected_version.release_id = p_release_id\n      AND selected_version.surface = p_surface\n      AND selected_version.state = 'PUBLISHED'\n    FOR SHARE;\n    SELECT * INTO grant_value\n    FROM sharing.consumer_grants AS selected_grant\n    WHERE selected_grant.workspace_id = p_workspace_id\n      AND selected_grant.id = p_grant_id\n      AND selected_grant.product_id = p_product_id\n      AND selected_grant.product_version_id = p_product_version_id\n      AND selected_grant.contract_version = 'SUBJECT_CLIENT_V2'\n      AND selected_grant.consumer_subject_id = p_subject_id\n      AND selected_grant.consumer_issuer = p_consumer_issuer\n      AND selected_grant.consumer_client_id = p_consumer_client_id\n    FOR UPDATE;\n    SELECT * INTO consumer\n    FROM iam.workspace_memberships AS membership\n    WHERE membership.workspace_id = p_workspace_id\n      AND membership.subject_id = p_subject_id\n      AND membership.active\n      AND membership.job_function = 'SERVICE_ACCOUNT'\n      AND membership.access_expires_at IS NULL\n    FOR SHARE;\n    SELECT * INTO consumer_subject\n    FROM iam.subjects AS subject_value\n    WHERE subject_value.id = p_subject_id\n      AND subject_value.active\n      AND subject_value.issuer = p_consumer_issuer\n    FOR SHARE;\n    SELECT true INTO release_valid\n    FROM knowledge.releases AS release\n    WHERE release.workspace_id = p_workspace_id\n      AND release.graph_id = p_graph_id\n      AND release.id = p_release_id\n      AND release.content_hash = p_release_content_hash\n    FOR SHARE;\n    SELECT count(*) INTO lineage_count\n    FROM (\n        SELECT changeset.id\n        FROM knowledge.changesets AS changeset\n        WHERE changeset.workspace_id = p_workspace_id\n          AND changeset.graph_id = p_graph_id\n          AND changeset.published_release_id = p_release_id\n          AND changeset.state = 'PUBLISHED'\n          AND changeset.reviewed_by IS NOT NULL\n          AND changeset.reviewed_by <> changeset.author_id\n          AND changeset.reviewed_at IS NOT NULL\n          AND length(btrim(changeset.review_reason)) > 0\n        FOR SHARE\n    ) AS governed_lineage;\n    IF product.id IS NULL\n       OR version.id IS NULL\n       OR grant_value.id IS NULL\n       OR grant_value.state <> 'ACTIVE'\n       OR observed_at < grant_value.valid_from\n       OR observed_at >= grant_value.expires_at\n       OR NOT (grant_value.scopes ? p_requested_scope)\n       OR product.classification > grant_value.maximum_classification\n       OR p_effective_classification < product.classification\n       OR p_effective_classification > grant_value.maximum_classification\n       OR p_surface NOT IN ('SNAPSHOT', 'NEIGHBORS', 'CHAT')\n       OR (\n           p_surface = 'SNAPSHOT'\n           AND (\n               p_requested_scope <> 'snapshot.read'\n               OR p_result_type <> 'SNAPSHOT_V1'\n               OR version.contract_document->>'query_template' <> 'snapshot-v1'\n           )\n       )\n       OR (\n           p_surface = 'NEIGHBORS'\n           AND (\n               p_requested_scope <> 'neighbors.query'\n               OR p_result_type <> 'NEIGHBORS_V1'\n               OR version.contract_document->>'query_template' <> 'neighbors-v1'\n           )\n       )\n       OR (\n           p_surface = 'CHAT'\n           AND (\n               p_requested_scope <> 'chat.query'\n               OR p_result_type <> 'CHAT_LOCAL_V1'\n               OR version.contract_document->>'query_template' <> 'chat-v1'\n           )\n       )\n       OR NOT (version.contract_document->'scopes' ? p_requested_scope)\n       OR version.contract_document->'response_schema'->>'type' <> 'object'\n       OR COALESCE(\n           (version.contract_document->'response_schema'\n               ->>'additionalProperties')::boolean,\n           TRUE\n       )\n       OR consumer.subject_id IS NULL\n       OR consumer_subject.id IS NULL\n       OR release_valid IS DISTINCT FROM true\n       OR lineage_count <> 1 THEN\n        RETURN QUERY SELECT\n            'DENIED'::text, NULL::uuid, NULL::text, NULL::integer,\n            NULL::uuid, NULL::text, NULL::text, NULL::timestamptz,\n            NULL::text, 0::bigint, 0::bigint;\n        RETURN;\n    END IF;\n\n    current_retention_data_class := CASE p_surface\n        WHEN 'CHAT' THEN 'CHAT_CONTENT'\n        ELSE 'OBJECT_DATA'\n    END;\n    PERFORM pg_advisory_xact_lock(\n        hashtextextended('datariver:retention:workspace:' || p_workspace_id::text, 0)\n    );\n    SELECT selected_policy.id, selected_policy.payload_hash\n    INTO current_retention_policy_id, current_retention_policy_hash\n    FROM retention.policy_versions AS selected_policy\n    JOIN retention.policy_class_rules AS selected_rule\n      ON selected_rule.workspace_id = selected_policy.workspace_id\n     AND selected_rule.policy_id = selected_policy.id\n     AND selected_rule.policy_hash = selected_policy.payload_hash\n    WHERE selected_policy.workspace_id = p_workspace_id\n      AND selected_policy.contract_version = 'POLICY_BOOK_V2'\n      AND selected_policy.state = 'ACTIVE'\n      AND selected_policy.effective_from <= observed_at\n      AND (\n          selected_policy.effective_until IS NULL\n          OR selected_policy.effective_until > observed_at\n      )\n      AND selected_rule.data_class = current_retention_data_class\n      AND selected_rule.minimum_value >= 1\n      AND EXISTS (\n          SELECT 1\n          FROM retention.policy_class_rules AS audit_rule\n          WHERE audit_rule.workspace_id = selected_policy.workspace_id\n            AND audit_rule.policy_id = selected_policy.id\n            AND audit_rule.policy_hash = selected_policy.payload_hash\n            AND audit_rule.data_class = 'AUDIT_EVIDENCE'\n            AND audit_rule.minimum_value >= 1\n      )\n    FOR SHARE OF selected_policy, selected_rule;\n    IF current_retention_policy_id IS NULL THEN\n        RETURN QUERY SELECT\n            'DENIED'::text, NULL::uuid, NULL::text, NULL::integer,\n            NULL::uuid, NULL::text, current_retention_data_class, NULL::timestamptz,\n            NULL::text, 0::bigint, 0::bigint;\n        RETURN;\n    END IF;\n\n    SELECT *\n    INTO stored\n    FROM sharing.api_invocations AS invocation\n    WHERE invocation.workspace_id = p_workspace_id\n      AND invocation.grant_id = p_grant_id\n      AND invocation.invocation_key IN (\n          p_invocation_key_hash,\n          p_legacy_invocation_key\n      )\n    LIMIT 1;\n\n    IF FOUND THEN\n        IF stored.evidence_kind <> 'ATOMIC_RESULT_V2' THEN\n            RETURN QUERY SELECT\n                'LEGACY'::text, stored.id, NULL::text, NULL::integer,\n                NULL::uuid, NULL::text, NULL::text, NULL::timestamptz,\n                NULL::text, 0::bigint, 0::bigint;\n            RETURN;\n        END IF;\n        IF stored.actor_id IS DISTINCT FROM p_subject_id\n           OR stored.consumer_issuer IS DISTINCT FROM p_consumer_issuer\n           OR stored.consumer_client_id IS DISTINCT FROM p_consumer_client_id\n           OR stored.product_id IS DISTINCT FROM p_product_id\n           OR stored.product_version_id IS DISTINCT FROM p_product_version_id\n           OR stored.graph_id IS DISTINCT FROM p_graph_id\n           OR stored.release_id IS DISTINCT FROM p_release_id\n           OR stored.release_content_hash IS DISTINCT FROM p_release_content_hash\n           OR stored.surface IS DISTINCT FROM p_surface\n           OR stored.requested_scope IS DISTINCT FROM p_requested_scope\n           OR stored.effective_classification IS DISTINCT FROM p_effective_classification\n           OR stored.security_scope_hash IS DISTINCT FROM p_security_scope_hash\n           OR stored.request_hash IS DISTINCT FROM p_request_hash\n           OR stored.result_type IS DISTINCT FROM p_result_type THEN\n            RETURN QUERY SELECT\n                'CONFLICT'::text, stored.id, NULL::text, NULL::integer,\n                NULL::uuid, NULL::text, NULL::text, NULL::timestamptz,\n                NULL::text, 0::bigint, 0::bigint;\n            RETURN;\n        END IF;\n        IF stored.audit_retention_policy_id IS DISTINCT FROM current_retention_policy_id\n           OR stored.audit_retention_policy_hash IS DISTINCT FROM current_retention_policy_hash\n           OR stored.audit_retention_until IS NULL THEN\n            RETURN QUERY SELECT\n                'DENIED'::text, stored.id, NULL::text, NULL::integer,\n                stored.retention_policy_id, stored.retention_policy_hash::text,\n                stored.retention_data_class::text, stored.retention_until,\n                NULL::text, 0::bigint, 0::bigint;\n            RETURN;\n        END IF;\n        IF stored.retention_until IS NULL OR observed_at >= stored.retention_until THEN\n            RETURN QUERY SELECT\n                'EXPIRED'::text, stored.id, NULL::text, NULL::integer,\n                stored.retention_policy_id, stored.retention_policy_hash::text,\n                stored.retention_data_class::text, stored.retention_until,\n                NULL::text, 0::bigint, 0::bigint;\n            RETURN;\n        END IF;\n        SELECT *\n        INTO stored_result\n        FROM sharing.api_invocation_results AS result\n        WHERE result.workspace_id = p_workspace_id\n          AND result.invocation_id = stored.id\n          AND result.actor_id = p_subject_id\n          AND result.consumer_client_id = p_consumer_client_id;\n        IF NOT FOUND\n           OR stored_result.result_type IS DISTINCT FROM stored.result_type\n           OR stored_result.result_hash IS DISTINCT FROM stored.result_hash\n           OR stored_result.result_size_bytes IS DISTINCT FROM stored.result_size_bytes\n           OR stored_result.retention_policy_id IS DISTINCT FROM stored.retention_policy_id\n           OR stored_result.retention_policy_hash IS DISTINCT FROM stored.retention_policy_hash\n           OR stored_result.retention_data_class IS DISTINCT FROM stored.retention_data_class\n           OR stored_result.retention_until IS DISTINCT FROM stored.retention_until THEN\n            RETURN QUERY SELECT\n                'CORRUPT'::text, stored.id, NULL::text, NULL::integer,\n                stored.retention_policy_id, stored.retention_policy_hash::text,\n                stored.retention_data_class::text, stored.retention_until,\n                NULL::text, 0::bigint, 0::bigint;\n            RETURN;\n        END IF;\n        IF stored.retention_policy_id IS DISTINCT FROM current_retention_policy_id\n           OR stored.retention_policy_hash IS DISTINCT FROM current_retention_policy_hash\n           OR stored.retention_data_class IS DISTINCT FROM current_retention_data_class THEN\n            RETURN QUERY SELECT\n                'DENIED'::text, stored.id, NULL::text, NULL::integer,\n                stored.retention_policy_id, stored.retention_policy_hash::text,\n                stored.retention_data_class::text, stored.retention_until,\n                NULL::text, 0::bigint, 0::bigint;\n            RETURN;\n        END IF;\n        RETURN QUERY SELECT\n            'REPLAY'::text,\n            stored.id,\n            stored_result.result_hash::text,\n            stored_result.result_size_bytes,\n            stored_result.retention_policy_id,\n            stored_result.retention_policy_hash::text,\n            stored_result.retention_data_class::text,\n            stored_result.retention_until,\n            stored_result.result_document,\n            0::bigint,\n            0::bigint;\n        RETURN;\n    END IF;\n\n    RETURN QUERY\n    SELECT\n        'NEW'::text,\n        NULL::uuid,\n        NULL::text,\n        NULL::integer,\n        current_retention_policy_id,\n        current_retention_policy_hash,\n        current_retention_data_class,\n        NULL::timestamptz,\n        NULL::text,\n        (\n            SELECT count(*)::bigint\n            FROM sharing.api_invocations AS recent\n            WHERE recent.workspace_id = p_workspace_id\n              AND recent.grant_id = p_grant_id\n              AND recent.occurred_at >= observed_at - interval '1 minute'\n        ),\n        COALESCE(\n            (\n                SELECT monthly.units::bigint\n                FROM sharing.api_invocation_monthly_usage AS monthly\n                WHERE monthly.workspace_id = p_workspace_id\n                  AND monthly.grant_id = p_grant_id\n                  AND monthly.month_start = observed_month\n            ),\n            0::bigint\n        );\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION sharing.complete_api_invocation_v2(\n    p_workspace_id uuid,\n    p_subject_id uuid,\n    p_grant_id uuid,\n    p_invocation_id uuid,\n    p_invocation_key_hash text,\n    p_legacy_invocation_key text,\n    p_consumer_issuer text,\n    p_consumer_client_id text,\n    p_product_id uuid,\n    p_product_version_id uuid,\n    p_graph_id uuid,\n    p_release_id uuid,\n    p_release_content_hash text,\n    p_surface text,\n    p_requested_scope text,\n    p_request_id text,\n    p_effective_classification integer,\n    p_security_scope_hash text,\n    p_request_hash text,\n    p_result_type text,\n    p_result_document text,\n    p_retention_data_class text,\n    p_retention_policy_id uuid,\n    p_retention_policy_hash text\n)\nRETURNS TABLE (\n    status text,\n    occurred_at timestamptz,\n    completed_at timestamptz,\n    result_hash text,\n    result_size_bytes integer\n)\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = pg_catalog, sharing, iam, knowledge, retention\nSET TimeZone = 'UTC'\nAS $$\nDECLARE\n    product sharing.api_products%ROWTYPE;\n    version sharing.api_product_versions%ROWTYPE;\n    grant_value sharing.consumer_grants%ROWTYPE;\n    consumer iam.workspace_memberships%ROWTYPE;\n    consumer_subject iam.subjects%ROWTYPE;\n    policy retention.policy_versions%ROWTYPE;\n    class_rule retention.policy_class_rules%ROWTYPE;\n    audit_rule retention.policy_class_rules%ROWTYPE;\n    observed_at timestamptz := clock_timestamp();\n    observed_month timestamptz :=\n        date_trunc('month', observed_at AT TIME ZONE 'UTC') AT TIME ZONE 'UTC';\n    minute_count bigint;\n    month_count bigint;\n    canonical_size integer;\n    canonical_hash text;\n    calculated_retention_until timestamptz;\n    calculated_audit_retention_until timestamptz;\n    release_valid boolean;\n    lineage_count bigint;\nBEGIN\n    IF p_workspace_id IS DISTINCT FROM\n            NULLIF(current_setting('app.workspace_id', true), '')::uuid\n       OR p_subject_id IS DISTINCT FROM\n            NULLIF(current_setting('app.subject_id', true), '')::uuid THEN\n        RAISE EXCEPTION 'Sharing invocation context is absent or mismatched'\n            USING ERRCODE = '42501';\n    END IF;\n    IF COALESCE(char_length(p_invocation_key_hash), 0) <> 64\n       OR COALESCE(char_length(p_release_content_hash), 0) <> 64\n       OR COALESCE(char_length(p_security_scope_hash), 0) <> 64\n       OR COALESCE(char_length(p_request_hash), 0) <> 64\n       OR COALESCE(char_length(p_retention_policy_hash), 0) <> 64\n       OR COALESCE(char_length(p_legacy_invocation_key), 0) NOT BETWEEN 16 AND 200\n       OR COALESCE(char_length(p_consumer_issuer), 0) NOT BETWEEN 1 AND 500\n       OR COALESCE(char_length(p_consumer_client_id), 0) NOT BETWEEN 3 AND 255\n       OR COALESCE(char_length(p_surface), 0) NOT BETWEEN 1 AND 32\n       OR COALESCE(char_length(p_requested_scope), 0) NOT BETWEEN 1 AND 100\n       OR COALESCE(char_length(p_request_id), 0) NOT BETWEEN 1 AND 100\n       OR COALESCE(char_length(p_result_type), 0) NOT BETWEEN 1 AND 32\n       OR COALESCE(char_length(p_retention_data_class), 0) NOT BETWEEN 1 AND 32\n       OR p_invocation_key_hash !~ '^[0-9a-f]{64}$'\n       OR p_security_scope_hash !~ '^[0-9a-f]{64}$'\n       OR p_request_hash !~ '^[0-9a-f]{64}$'\n       OR p_release_content_hash !~ '^[0-9a-f]{64}$'\n       OR p_retention_policy_hash !~ '^[0-9a-f]{64}$' THEN\n        RAISE EXCEPTION 'Sharing invocation hashes are invalid'\n            USING ERRCODE = '22023';\n    END IF;\n    canonical_size := octet_length(convert_to(COALESCE(p_result_document, ''), 'UTF8'));\n    IF canonical_size < 2 OR canonical_size > 1048576 THEN\n        RETURN QUERY SELECT\n            'OVERSIZE'::text, NULL::timestamptz, NULL::timestamptz,\n            NULL::text, NULL::integer;\n        RETURN;\n    END IF;\n    IF jsonb_typeof(p_result_document::jsonb) <> 'object' THEN\n        RAISE EXCEPTION 'Sharing result must be a JSON object'\n            USING ERRCODE = '22023';\n    END IF;\n    canonical_hash := encode(sha256(convert_to(p_result_document, 'UTF8')), 'hex');\n\n    SELECT * INTO product\n    FROM sharing.api_products AS selected_product\n    WHERE selected_product.workspace_id = p_workspace_id\n      AND selected_product.id = p_product_id\n      AND selected_product.graph_id = p_graph_id\n      AND selected_product.state = 'PUBLISHED'\n      AND selected_product.current_version_id = p_product_version_id\n    FOR SHARE;\n    IF NOT FOUND THEN\n        RETURN QUERY SELECT\n            'DENIED'::text, NULL::timestamptz, NULL::timestamptz,\n            NULL::text, NULL::integer;\n        RETURN;\n    END IF;\n\n    SELECT * INTO version\n    FROM sharing.api_product_versions AS selected_version\n    WHERE selected_version.workspace_id = p_workspace_id\n      AND selected_version.product_id = p_product_id\n      AND selected_version.id = p_product_version_id\n      AND selected_version.graph_id = p_graph_id\n      AND selected_version.release_id = p_release_id\n      AND selected_version.surface = p_surface\n      AND selected_version.state = 'PUBLISHED'\n    FOR SHARE;\n    IF NOT FOUND THEN\n        RETURN QUERY SELECT\n            'DENIED'::text, NULL::timestamptz, NULL::timestamptz,\n            NULL::text, NULL::integer;\n        RETURN;\n    END IF;\n\n    SELECT * INTO grant_value\n    FROM sharing.consumer_grants AS selected_grant\n    WHERE selected_grant.workspace_id = p_workspace_id\n      AND selected_grant.id = p_grant_id\n      AND selected_grant.product_id = p_product_id\n      AND selected_grant.product_version_id = p_product_version_id\n      AND selected_grant.contract_version = 'SUBJECT_CLIENT_V2'\n      AND selected_grant.consumer_subject_id = p_subject_id\n      AND selected_grant.consumer_issuer = p_consumer_issuer\n      AND selected_grant.consumer_client_id = p_consumer_client_id\n    FOR UPDATE;\n    IF NOT FOUND\n       OR grant_value.state <> 'ACTIVE'\n       OR observed_at < grant_value.valid_from\n       OR observed_at >= grant_value.expires_at\n       OR NOT (grant_value.scopes ? p_requested_scope)\n       OR product.classification > grant_value.maximum_classification\n       OR p_effective_classification < product.classification\n       OR p_effective_classification > grant_value.maximum_classification\n       OR p_surface NOT IN ('SNAPSHOT', 'NEIGHBORS', 'CHAT')\n       OR (\n           p_surface = 'SNAPSHOT'\n           AND (\n               p_requested_scope <> 'snapshot.read'\n               OR p_result_type <> 'SNAPSHOT_V1'\n               OR version.contract_document->>'query_template' <> 'snapshot-v1'\n           )\n       )\n       OR (\n           p_surface = 'NEIGHBORS'\n           AND (\n               p_requested_scope <> 'neighbors.query'\n               OR p_result_type <> 'NEIGHBORS_V1'\n               OR version.contract_document->>'query_template' <> 'neighbors-v1'\n           )\n       )\n       OR (\n           p_surface = 'CHAT'\n           AND (\n               p_requested_scope <> 'chat.query'\n               OR p_result_type <> 'CHAT_LOCAL_V1'\n               OR version.contract_document->>'query_template' <> 'chat-v1'\n           )\n       )\n       OR NOT (version.contract_document->'scopes' ? p_requested_scope)\n       OR version.contract_document->'response_schema'->>'type' <> 'object'\n       OR COALESCE(\n           (version.contract_document->'response_schema'\n               ->>'additionalProperties')::boolean,\n           TRUE\n       ) THEN\n        RETURN QUERY SELECT\n            'DENIED'::text, NULL::timestamptz, NULL::timestamptz,\n            NULL::text, NULL::integer;\n        RETURN;\n    END IF;\n\n    SELECT * INTO consumer\n    FROM iam.workspace_memberships AS membership\n    WHERE membership.workspace_id = p_workspace_id\n      AND membership.subject_id = p_subject_id\n      AND membership.active\n      AND membership.job_function = 'SERVICE_ACCOUNT'\n      AND membership.access_expires_at IS NULL\n    FOR SHARE;\n    SELECT * INTO consumer_subject\n    FROM iam.subjects AS subject_value\n    WHERE subject_value.id = p_subject_id\n      AND subject_value.active\n      AND subject_value.issuer = p_consumer_issuer\n    FOR SHARE;\n    IF consumer.subject_id IS NULL OR consumer_subject.id IS NULL THEN\n        RETURN QUERY SELECT\n            'DENIED'::text, NULL::timestamptz, NULL::timestamptz,\n            NULL::text, NULL::integer;\n        RETURN;\n    END IF;\n\n    SELECT true INTO release_valid\n    FROM knowledge.releases AS release\n    WHERE release.workspace_id = p_workspace_id\n      AND release.graph_id = p_graph_id\n      AND release.id = p_release_id\n      AND release.content_hash = p_release_content_hash\n    FOR SHARE;\n    SELECT count(*) INTO lineage_count\n    FROM (\n        SELECT changeset.id\n        FROM knowledge.changesets AS changeset\n        WHERE changeset.workspace_id = p_workspace_id\n          AND changeset.graph_id = p_graph_id\n          AND changeset.published_release_id = p_release_id\n          AND changeset.state = 'PUBLISHED'\n          AND changeset.reviewed_by IS NOT NULL\n          AND changeset.reviewed_by <> changeset.author_id\n          AND changeset.reviewed_at IS NOT NULL\n          AND length(btrim(changeset.review_reason)) > 0\n        FOR SHARE\n    ) AS governed_lineage;\n    IF release_valid IS DISTINCT FROM true OR lineage_count <> 1 THEN\n        RETURN QUERY SELECT\n            'DENIED'::text, NULL::timestamptz, NULL::timestamptz,\n            NULL::text, NULL::integer;\n        RETURN;\n    END IF;\n\n    PERFORM pg_advisory_xact_lock(\n        hashtextextended('datariver:retention:workspace:' || p_workspace_id::text, 0)\n    );\n    SELECT * INTO policy\n    FROM retention.policy_versions AS selected_policy\n    WHERE selected_policy.workspace_id = p_workspace_id\n      AND selected_policy.id = p_retention_policy_id\n      AND selected_policy.payload_hash = p_retention_policy_hash\n      AND selected_policy.contract_version = 'POLICY_BOOK_V2'\n      AND selected_policy.state = 'ACTIVE'\n      AND selected_policy.effective_from <= observed_at\n      AND (\n          selected_policy.effective_until IS NULL\n          OR selected_policy.effective_until > observed_at\n      )\n    FOR SHARE;\n    SELECT * INTO class_rule\n    FROM retention.policy_class_rules AS selected_rule\n    WHERE selected_rule.workspace_id = p_workspace_id\n      AND selected_rule.policy_id = p_retention_policy_id\n      AND selected_rule.policy_hash = p_retention_policy_hash\n      AND selected_rule.data_class = p_retention_data_class\n    FOR SHARE;\n    SELECT * INTO audit_rule\n    FROM retention.policy_class_rules AS selected_rule\n    WHERE selected_rule.workspace_id = p_workspace_id\n      AND selected_rule.policy_id = p_retention_policy_id\n      AND selected_rule.policy_hash = p_retention_policy_hash\n      AND selected_rule.data_class = 'AUDIT_EVIDENCE'\n    FOR SHARE;\n    IF policy.id IS NULL\n       OR class_rule.id IS NULL\n       OR class_rule.minimum_value < 1\n       OR audit_rule.id IS NULL\n       OR audit_rule.minimum_value < 1 THEN\n        RETURN QUERY SELECT\n            'RETENTION_DENIED'::text, NULL::timestamptz, NULL::timestamptz,\n            NULL::text, NULL::integer;\n        RETURN;\n    END IF;\n    calculated_retention_until := CASE class_rule.unit\n        WHEN 'DAYS' THEN\n            observed_at + make_interval(days => class_rule.minimum_value)\n        WHEN 'MONTHS' THEN\n            observed_at + make_interval(months => class_rule.minimum_value)\n        WHEN 'YEARS' THEN\n            observed_at + make_interval(years => class_rule.minimum_value)\n        ELSE NULL\n    END;\n    calculated_audit_retention_until := CASE audit_rule.unit\n        WHEN 'DAYS' THEN\n            observed_at + make_interval(days => audit_rule.minimum_value)\n        WHEN 'MONTHS' THEN\n            observed_at + make_interval(months => audit_rule.minimum_value)\n        WHEN 'YEARS' THEN\n            observed_at + make_interval(years => audit_rule.minimum_value)\n        ELSE NULL\n    END;\n    IF calculated_retention_until IS NULL\n       OR calculated_retention_until <= observed_at\n       OR calculated_audit_retention_until IS NULL\n       OR calculated_audit_retention_until <= observed_at THEN\n        RETURN QUERY SELECT\n            'RETENTION_DENIED'::text, NULL::timestamptz, NULL::timestamptz,\n            NULL::text, NULL::integer;\n        RETURN;\n    END IF;\n\n    IF EXISTS (\n        SELECT 1\n        FROM sharing.api_invocations AS existing\n        WHERE existing.workspace_id = p_workspace_id\n          AND existing.grant_id = p_grant_id\n          AND existing.invocation_key IN (\n              p_invocation_key_hash,\n              p_legacy_invocation_key\n          )\n    ) THEN\n        RETURN QUERY SELECT\n            'CONFLICT'::text, NULL::timestamptz, NULL::timestamptz,\n            NULL::text, NULL::integer;\n        RETURN;\n    END IF;\n\n    SELECT count(*)::bigint INTO minute_count\n    FROM sharing.api_invocations AS recent\n    WHERE recent.workspace_id = p_workspace_id\n      AND recent.grant_id = p_grant_id\n      AND recent.occurred_at >= observed_at - interval '1 minute';\n    SELECT COALESCE(monthly.units, 0)::bigint INTO month_count\n    FROM sharing.api_invocation_monthly_usage AS monthly\n    WHERE monthly.workspace_id = p_workspace_id\n      AND monthly.grant_id = p_grant_id\n      AND monthly.month_start = observed_month;\n    month_count := COALESCE(month_count, 0);\n    IF minute_count >= grant_value.requests_per_minute THEN\n        RETURN QUERY SELECT\n            'RATE_MINUTE'::text, NULL::timestamptz, NULL::timestamptz,\n            NULL::text, NULL::integer;\n        RETURN;\n    END IF;\n    IF month_count >= grant_value.monthly_quota THEN\n        RETURN QUERY SELECT\n            'RATE_MONTH'::text, NULL::timestamptz, NULL::timestamptz,\n            NULL::text, NULL::integer;\n        RETURN;\n    END IF;\n\n    INSERT INTO sharing.api_invocations (\n        id, workspace_id, grant_id, invocation_key, evidence_kind, actor_id,\n        consumer_issuer, consumer_client_id, product_id, product_version_id,\n        graph_id, release_id, release_content_hash, surface, requested_scope,\n        request_id, effective_classification, security_scope_hash, request_hash,\n        result_type, result_hash, result_size_bytes, retention_data_class,\n        retention_policy_id, retention_policy_hash, retention_until,\n        audit_retention_policy_id, audit_retention_policy_hash,\n        audit_retention_until,\n        occurred_at, completed_at, units\n    ) VALUES (\n        p_invocation_id, p_workspace_id, p_grant_id, p_invocation_key_hash,\n        'ATOMIC_RESULT_V2', p_subject_id, p_consumer_issuer,\n        p_consumer_client_id, p_product_id, p_product_version_id, p_graph_id,\n        p_release_id, p_release_content_hash, p_surface, p_requested_scope,\n        p_request_id, p_effective_classification, p_security_scope_hash,\n        p_request_hash, p_result_type, canonical_hash, canonical_size,\n        p_retention_data_class, p_retention_policy_id, p_retention_policy_hash,\n        calculated_retention_until, p_retention_policy_id,\n        p_retention_policy_hash, calculated_audit_retention_until,\n        observed_at, observed_at, 1\n    );\n    INSERT INTO sharing.api_invocation_results (\n        workspace_id, invocation_id, actor_id, consumer_client_id, result_type,\n        result_document, result_size_bytes, result_hash, classification,\n        retention_data_class, retention_policy_id, retention_policy_hash,\n        retention_until, created_at\n    ) VALUES (\n        p_workspace_id, p_invocation_id, p_subject_id, p_consumer_client_id,\n        p_result_type, p_result_document, canonical_size, canonical_hash,\n        product.classification, p_retention_data_class, p_retention_policy_id,\n        p_retention_policy_hash, calculated_retention_until, observed_at\n    );\n    INSERT INTO sharing.api_invocation_monthly_usage (\n        workspace_id, grant_id, month_start, units, updated_at\n    ) VALUES (\n        p_workspace_id, p_grant_id, observed_month, 1, observed_at\n    )\n    ON CONFLICT (workspace_id, grant_id, month_start)\n    DO UPDATE SET\n        units = sharing.api_invocation_monthly_usage.units + 1,\n        updated_at = EXCLUDED.updated_at;\n\n    RETURN QUERY SELECT\n        'RECORDED'::text, observed_at, observed_at, canonical_hash, canonical_size;\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION sharing.reject_invocation_evidence_mutation()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = pg_catalog, sharing\nAS $$\nBEGIN\n    RAISE EXCEPTION 'Sharing invocation evidence is immutable'\n        USING ERRCODE = '42501';\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION sharing.require_atomic_invocation_result()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = pg_catalog, sharing\nAS $$\nBEGIN\n    IF NEW.evidence_kind = 'ATOMIC_RESULT_V2'\n       AND NOT EXISTS (\n           SELECT 1\n           FROM sharing.api_invocation_results AS result\n           WHERE result.workspace_id = NEW.workspace_id\n             AND result.invocation_id = NEW.id\n             AND result.actor_id = NEW.actor_id\n             AND result.consumer_client_id = NEW.consumer_client_id\n             AND result.result_type = NEW.result_type\n             AND result.result_hash = NEW.result_hash\n             AND result.result_size_bytes = NEW.result_size_bytes\n             AND result.retention_data_class = NEW.retention_data_class\n             AND result.retention_policy_id = NEW.retention_policy_id\n             AND result.retention_policy_hash = NEW.retention_policy_hash\n             AND result.retention_until = NEW.retention_until\n       ) THEN\n        RAISE EXCEPTION 'Atomic Sharing invocation has no exact result';\n    END IF;\n    RETURN NEW;\nEND\n$$;")
        op.execute('CREATE TRIGGER api_invocations_immutable\nBEFORE UPDATE OR DELETE ON sharing.api_invocations\nFOR EACH ROW EXECUTE FUNCTION sharing.reject_invocation_evidence_mutation();')
        op.execute('CREATE TRIGGER api_invocation_results_immutable\nBEFORE UPDATE OR DELETE ON sharing.api_invocation_results\nFOR EACH ROW EXECUTE FUNCTION sharing.reject_invocation_evidence_mutation();')
        op.execute('CREATE CONSTRAINT TRIGGER api_invocation_exact_result\nAFTER INSERT ON sharing.api_invocations\nDEFERRABLE INITIALLY DEFERRED\nFOR EACH ROW EXECUTE FUNCTION sharing.require_atomic_invocation_result();')
        op.execute("DO $$\nDECLARE\n    role_is_safe boolean;\n    migration_owner oid := to_regrole(current_user)::oid;\nBEGIN\n    SELECT\n        rolcanlogin\n        AND NOT rolsuper\n        AND NOT rolcreatedb\n        AND NOT rolcreaterole\n        AND NOT rolreplication\n        AND NOT rolbypassrls\n    INTO role_is_safe\n    FROM pg_roles\n    WHERE rolname = 'datariver_app';\n    IF role_is_safe IS DISTINCT FROM true THEN\n        RAISE EXCEPTION\n            'datariver_app must be an unprivileged direct LOGIN principal';\n    END IF;\n    IF EXISTS (\n        SELECT 1\n        FROM pg_roles AS candidate\n        WHERE candidate.rolname <> 'datariver_app'\n          AND pg_has_role('datariver_app', candidate.oid, 'MEMBER')\n    ) THEN\n        RAISE EXCEPTION\n            'datariver_app must not inherit or SET ROLE to another principal';\n    END IF;\n    IF EXISTS (\n        SELECT 1\n        FROM pg_roles AS candidate\n        WHERE candidate.rolname <> 'datariver_app'\n          AND NOT candidate.rolsuper\n          AND candidate.rolname NOT LIKE 'pg\\_%' ESCAPE '\\'\n          AND pg_has_role(candidate.oid, 'datariver_app', 'MEMBER')\n    ) THEN\n        RAISE EXCEPTION\n            'datariver_app must not be assumable by another non-superuser principal';\n    END IF;\n    IF EXISTS (\n        SELECT 1\n        FROM pg_class AS class\n        JOIN pg_namespace AS namespace ON namespace.oid = class.relnamespace\n        WHERE namespace.nspname = 'sharing'\n          AND class.relname IN (\n              'api_invocations',\n              'api_invocation_results',\n              'api_invocation_monthly_usage'\n          )\n          AND class.relowner <> migration_owner\n    ) OR EXISTS (\n        SELECT 1\n        FROM pg_proc AS procedure\n        WHERE procedure.oid IN (\n            to_regprocedure(\n                'sharing.prepare_api_invocation_v2('\n                'uuid,uuid,uuid,text,text,text,text,uuid,uuid,uuid,uuid,text,'\n                'text,text,integer,text,text,text)'\n            ),\n            to_regprocedure(\n                'sharing.complete_api_invocation_v2('\n                'uuid,uuid,uuid,uuid,text,text,text,text,uuid,uuid,uuid,uuid,'\n                'text,text,text,text,integer,text,text,text,text,text,uuid,text)'\n            ),\n            to_regprocedure('sharing.reject_invocation_evidence_mutation()'),\n            to_regprocedure('sharing.require_atomic_invocation_result()')\n        )\n          AND procedure.proowner <> migration_owner\n    ) THEN\n        RAISE EXCEPTION\n            'Atomic Sharing protected objects must remain migration-owner controlled';\n    END IF;\nEND\n$$;")
        op.execute("DO $$\nDECLARE\n    role_value record;\nBEGIN\n    FOR role_value IN\n        SELECT role_state.rolname\n        FROM pg_roles AS role_state\n        WHERE role_state.oid <> (\n            SELECT class.relowner\n            FROM pg_class AS class\n            JOIN pg_namespace AS namespace ON namespace.oid = class.relnamespace\n            WHERE namespace.nspname = 'sharing'\n              AND class.relname = 'api_invocations'\n        )\n    LOOP\n        EXECUTE format(\n            'REVOKE ALL ON sharing.api_invocations, '\n            'sharing.api_invocation_results, '\n            'sharing.api_invocation_monthly_usage FROM %I',\n            role_value.rolname\n        );\n    END LOOP;\nEND\n$$;")
        op.execute('REVOKE ALL ON FUNCTION sharing.reject_invocation_evidence_mutation()\nFROM PUBLIC;')
        op.execute('REVOKE ALL ON FUNCTION sharing.require_atomic_invocation_result()\nFROM PUBLIC;')
        op.execute('REVOKE ALL ON FUNCTION sharing.prepare_api_invocation_v2(\n    uuid, uuid, uuid, text, text, text, text, uuid, uuid, uuid, uuid, text,\n    text, text, integer, text, text, text\n) FROM PUBLIC;')
        op.execute('REVOKE ALL ON FUNCTION sharing.complete_api_invocation_v2(\n    uuid, uuid, uuid, uuid, text, text, text, text, uuid, uuid, uuid, uuid,\n    text, text, text, text, integer, text, text, text, text, text, uuid,\n    text\n) FROM PUBLIC;')
        op.execute("DO $$\nDECLARE\n    role_value record;\nBEGIN\n    FOR role_value IN\n        SELECT role_state.rolname\n        FROM pg_roles AS role_state\n        WHERE role_state.rolname <> 'datariver_app'\n          AND role_state.oid <> (\n              SELECT procedure.proowner\n              FROM pg_proc AS procedure\n              WHERE procedure.oid = to_regprocedure(\n                  'sharing.prepare_api_invocation_v2('\n                  'uuid,uuid,uuid,text,text,text,text,uuid,uuid,uuid,uuid,text,'\n                  'text,text,integer,text,text,text)'\n              )\n          )\n    LOOP\n        EXECUTE format(\n            'REVOKE ALL ON FUNCTION '\n            'sharing.prepare_api_invocation_v2('\n            'uuid,uuid,uuid,text,text,text,text,uuid,uuid,uuid,uuid,text,'\n            'text,text,integer,text,text,text) FROM %I',\n            role_value.rolname\n        );\n        EXECUTE format(\n            'REVOKE ALL ON FUNCTION '\n            'sharing.complete_api_invocation_v2('\n            'uuid,uuid,uuid,uuid,text,text,text,text,uuid,uuid,uuid,uuid,'\n            'text,text,text,text,integer,text,text,text,text,text,uuid,text) FROM %I',\n            role_value.rolname\n        );\n        EXECUTE format(\n            'REVOKE ALL ON FUNCTION '\n            'sharing.reject_invocation_evidence_mutation() FROM %I',\n            role_value.rolname\n        );\n        EXECUTE format(\n            'REVOKE ALL ON FUNCTION '\n            'sharing.require_atomic_invocation_result() FROM %I',\n            role_value.rolname\n        );\n    END LOOP;\nEND\n$$;")
        op.execute('REVOKE ALL ON sharing.api_invocations,\n    sharing.api_invocation_results,\n    sharing.api_invocation_monthly_usage\nFROM datariver_app;')
        op.execute('GRANT EXECUTE ON FUNCTION sharing.prepare_api_invocation_v2(\n    uuid, uuid, uuid, text, text, text, text, uuid, uuid, uuid, uuid, text,\n    text, text, integer, text, text, text\n) TO datariver_app;')
        op.execute('GRANT EXECUTE ON FUNCTION sharing.complete_api_invocation_v2(\n    uuid, uuid, uuid, uuid, text, text, text, text, uuid, uuid, uuid, uuid,\n    text, text, text, text, integer, text, text, text, text, text, uuid,\n    text\n) TO datariver_app;')
        op.execute("DO $$\nBEGIN\n    IF NOT EXISTS (\n        SELECT 1 FROM pg_roles\n        WHERE rolname = 'datariver_quality'\n          AND rolcanlogin IS TRUE\n          AND rolsuper IS FALSE\n          AND rolcreatedb IS FALSE\n          AND rolcreaterole IS FALSE\n          AND rolreplication IS FALSE\n          AND rolbypassrls IS FALSE\n    ) THEN\n        RAISE EXCEPTION 'datariver_quality must be a safe NOBYPASSRLS login role';\n    END IF;\n    IF EXISTS (\n        SELECT 1\n        FROM pg_auth_members AS membership\n        JOIN pg_roles AS member_role ON member_role.oid = membership.member\n        JOIN pg_roles AS granted_role ON granted_role.oid = membership.roleid\n        WHERE member_role.rolname = 'datariver_quality'\n           OR (\n               granted_role.rolname = 'datariver_quality'\n               AND member_role.rolname NOT IN (\n                   current_user,\n                   session_user,\n                   'datariver_migrator'\n               )\n           )\n    ) THEN\n        RAISE EXCEPTION 'datariver_quality role membership is unsafe';\n    END IF;\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION retention.advance_legal_hold_generation(\n    p_workspace_id uuid,\n    p_data_class text,\n    p_event_kind text,\n    p_hold_id uuid,\n    p_hold_version integer,\n    p_payload_hash text,\n    p_scope text,\n    p_resource_type text,\n    p_scope_id uuid,\n    p_state text\n)\nRETURNS void\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, retention\nAS $$\nDECLARE\n    event_hash text;\nBEGIN\n    event_hash := encode(\n        sha256(convert_to(jsonb_build_object(\n            'contract', 'LEGAL_HOLD_GENERATION_EVENT_V1',\n            'event_kind', p_event_kind,\n            'hold_id', p_hold_id::text,\n            'hold_version', p_hold_version,\n            'payload_hash', p_payload_hash,\n            'scope', p_scope,\n            'resource_type', p_resource_type,\n            'scope_id', p_scope_id::text,\n            'state', p_state\n        )::text, 'UTF8')),\n        'hex'\n    );\n\n    INSERT INTO retention.legal_hold_generations (\n        id, workspace_id, data_class, generation, resolution_hash,\n        version, created_at, updated_at\n    )\n    VALUES (\n        gen_random_uuid(), p_workspace_id, p_data_class, 1,\n        encode(sha256(convert_to(\n            'LEGAL_HOLD_GENERATION_V1:1:' || event_hash, 'UTF8'\n        )), 'hex'),\n        1, transaction_timestamp(), transaction_timestamp()\n    )\n    ON CONFLICT (workspace_id, data_class) DO UPDATE\n    SET generation = retention.legal_hold_generations.generation + 1,\n        resolution_hash = encode(sha256(convert_to(\n            retention.legal_hold_generations.resolution_hash || ':' ||\n            (retention.legal_hold_generations.generation + 1)::text || ':' ||\n            event_hash,\n            'UTF8'\n        )), 'hex'),\n        version = retention.legal_hold_generations.version + 1,\n        updated_at = transaction_timestamp();\nEND\n$$;")
        op.execute('REVOKE ALL ON FUNCTION retention.advance_legal_hold_generation(\n    uuid, text, text, uuid, integer, text, text, text, uuid, text\n) FROM PUBLIC;')
        op.execute("CREATE OR REPLACE FUNCTION retention.refresh_legal_hold_generation()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = pg_catalog, retention\nAS $$\nBEGIN\n    IF TG_OP = 'DELETE' THEN\n        PERFORM retention.advance_legal_hold_generation(\n            OLD.workspace_id, OLD.data_class, 'DELETE', OLD.id, OLD.version,\n            OLD.payload_hash, OLD.scope, OLD.resource_type, OLD.scope_id, OLD.state\n        );\n        RETURN OLD;\n    END IF;\n    PERFORM retention.advance_legal_hold_generation(\n        NEW.workspace_id, NEW.data_class, TG_OP, NEW.id, NEW.version,\n        NEW.payload_hash, NEW.scope, NEW.resource_type, NEW.scope_id, NEW.state\n    );\n    IF TG_OP = 'UPDATE'\n       AND (OLD.workspace_id, OLD.data_class) IS DISTINCT FROM\n           (NEW.workspace_id, NEW.data_class) THEN\n        PERFORM retention.advance_legal_hold_generation(\n            OLD.workspace_id, OLD.data_class, 'UPDATE_OLD', OLD.id, OLD.version,\n            OLD.payload_hash, OLD.scope, OLD.resource_type, OLD.scope_id, OLD.state\n        );\n    END IF;\n    RETURN NEW;\nEND\n$$;")
        op.execute('REVOKE ALL ON FUNCTION retention.refresh_legal_hold_generation() FROM PUBLIC;')
        op.execute('CREATE TRIGGER refresh_legal_hold_generation\nAFTER INSERT OR UPDATE OR DELETE ON retention.legal_holds\nFOR EACH ROW EXECUTE FUNCTION retention.refresh_legal_hold_generation();')
        op.execute("INSERT INTO retention.legal_hold_generations (\n    id, workspace_id, data_class, generation, resolution_hash,\n    version, created_at, updated_at\n)\nSELECT\n    gen_random_uuid(),\n    workspace.id,\n    kind.data_class,\n    1,\n    encode(sha256(convert_to(COALESCE(active_holds.hold_set, ''), 'UTF8')), 'hex'),\n    1,\n    transaction_timestamp(),\n    transaction_timestamp()\nFROM platform.workspaces AS workspace\nCROSS JOIN (\n    VALUES\n        ('QUALITY_RULE'::text),\n        ('QUALITY_RESULT'::text),\n        ('QUALITY_AUDIT'::text)\n) AS kind(data_class)\nLEFT JOIN LATERAL (\n    SELECT string_agg(\n        hold.id::text || ':' || hold.version::text || ':' ||\n        hold.payload_hash || ':' || hold.scope || ':' ||\n        COALESCE(hold.resource_type, '-') || ':' ||\n        COALESCE(hold.scope_id::text, '-'),\n        '|' ORDER BY hold.id\n    ) AS hold_set\n    FROM retention.legal_holds AS hold\n    WHERE hold.workspace_id = workspace.id\n      AND hold.data_class = kind.data_class\n      AND hold.state <> 'RELEASED'\n) AS active_holds ON true\nON CONFLICT (workspace_id, data_class) DO NOTHING;")
        op.execute("CREATE OR REPLACE FUNCTION retention.resolve_quality_binding_v1(\n    p_workspace_id uuid,\n    p_data_class text,\n    p_resource_type text,\n    p_resource_id uuid,\n    p_basis_at timestamptz\n)\nRETURNS TABLE (\n    policy_id uuid,\n    policy_number integer,\n    policy_hash text,\n    retain_until timestamptz,\n    hold_generation bigint,\n    hold_hash text\n)\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, retention\nAS $$\nDECLARE\n    selected_policy retention.policy_versions%ROWTYPE;\n    selected_rule retention.policy_class_rules%ROWTYPE;\n    selected_generation retention.legal_hold_generations%ROWTYPE;\nBEGIN\n    IF p_data_class NOT IN ('QUALITY_RULE', 'QUALITY_RESULT', 'QUALITY_AUDIT')\n       OR p_resource_type NOT IN ('QUALITY_RULE_SET', 'QUALITY_VALIDATION_RUN')\n       OR p_resource_id IS NULL\n       OR p_basis_at IS DISTINCT FROM transaction_timestamp() THEN\n        RAISE EXCEPTION 'invalid Quality retention binding request'\n            USING ERRCODE = '23514';\n    END IF;\n\n    SELECT policy.* INTO selected_policy\n    FROM retention.policy_versions AS policy\n    WHERE policy.workspace_id = p_workspace_id\n      AND policy.state = 'ACTIVE'\n      AND policy.contract_version = 'POLICY_BOOK_V3'\n      AND policy.effective_from <= p_basis_at\n      AND (policy.effective_until IS NULL OR policy.effective_until > p_basis_at)\n    FOR KEY SHARE;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'Quality retention requires an effective POLICY_BOOK_V3'\n            USING ERRCODE = '23514';\n    END IF;\n\n    SELECT class_rule.* INTO selected_rule\n    FROM retention.policy_class_rules AS class_rule\n    WHERE class_rule.workspace_id = p_workspace_id\n      AND class_rule.policy_id = selected_policy.id\n      AND class_rule.policy_hash = selected_policy.payload_hash\n      AND class_rule.policy_number = selected_policy.policy_number\n      AND class_rule.data_class = p_data_class\n    FOR KEY SHARE;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'Quality retention class rule is unavailable'\n            USING ERRCODE = '23514';\n    END IF;\n\n    SELECT generation.* INTO selected_generation\n    FROM retention.legal_hold_generations AS generation\n    WHERE generation.workspace_id = p_workspace_id\n      AND generation.data_class = p_data_class\n    FOR UPDATE;\n    IF NOT FOUND THEN\n        INSERT INTO retention.legal_hold_generations (\n            id, workspace_id, data_class, generation, resolution_hash,\n            version, created_at, updated_at\n        )\n        VALUES (\n            gen_random_uuid(), p_workspace_id, p_data_class, 1,\n            encode(sha256(convert_to('', 'UTF8')), 'hex'),\n            1, transaction_timestamp(), transaction_timestamp()\n        )\n        ON CONFLICT (workspace_id, data_class) DO NOTHING;\n        SELECT generation.* INTO selected_generation\n        FROM retention.legal_hold_generations AS generation\n        WHERE generation.workspace_id = p_workspace_id\n          AND generation.data_class = p_data_class\n        FOR UPDATE;\n    END IF;\n\n    IF EXISTS (\n        SELECT 1\n        FROM retention.legal_holds AS hold\n        WHERE hold.workspace_id = p_workspace_id\n          AND hold.data_class = p_data_class\n          AND hold.state <> 'RELEASED'\n          AND hold.scope = 'RESOURCE'\n          AND hold.scope_id = p_resource_id\n          AND hold.resource_type IS DISTINCT FROM p_resource_type\n          AND hold.resource_type <> 'LEGACY_UNTYPED'\n    ) THEN\n        RAISE EXCEPTION 'ambiguous typed Quality Legal Hold resolution'\n            USING ERRCODE = '23514';\n    END IF;\n\n    policy_id := selected_policy.id;\n    policy_number := selected_policy.policy_number;\n    policy_hash := selected_policy.payload_hash;\n    retain_until := CASE selected_rule.unit\n        WHEN 'DAYS' THEN p_basis_at + make_interval(days => selected_rule.minimum_value)\n        WHEN 'MONTHS' THEN p_basis_at + make_interval(months => selected_rule.minimum_value)\n        WHEN 'YEARS' THEN p_basis_at + make_interval(years => selected_rule.minimum_value)\n        ELSE NULL\n    END;\n    hold_generation := selected_generation.generation;\n    hold_hash := selected_generation.resolution_hash;\n    IF retain_until IS NULL OR retain_until <= p_basis_at THEN\n        RAISE EXCEPTION 'invalid Quality retention deadline'\n            USING ERRCODE = '23514';\n    END IF;\n    RETURN NEXT;\nEND\n$$;")
        op.execute('REVOKE ALL ON FUNCTION retention.resolve_quality_binding_v1(\n    uuid, text, text, uuid, timestamptz\n) FROM PUBLIC;')
        op.execute("CREATE OR REPLACE FUNCTION quality.current_human_can(\n    p_workspace_id uuid,\n    p_action text,\n    p_classification integer,\n    p_system_id uuid,\n    p_domain_id uuid\n)\nRETURNS boolean\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = pg_catalog, platform, iam\nAS $$\n    SELECT EXISTS (\n        SELECT 1\n        FROM platform.workspaces AS workspace\n        JOIN iam.workspace_memberships AS membership\n          ON membership.workspace_id = workspace.id\n        JOIN iam.subjects AS subject\n          ON subject.id = membership.subject_id\n        WHERE workspace.id = p_workspace_id\n          AND workspace.status = 'ACTIVE'\n          AND membership.subject_id =\n              NULLIF(current_setting('app.subject_id', true), '')::uuid\n          AND subject.active IS TRUE\n          AND membership.active IS TRUE\n          AND (\n              membership.access_expires_at IS NULL\n              OR membership.access_expires_at > transaction_timestamp()\n          )\n          AND COALESCE(membership.job_function, '') <> 'SERVICE_ACCOUNT'\n          AND NOT (\n              COALESCE(membership.attributes -> 'groups', '[]'::jsonb)\n              ? 'service-accounts'\n          )\n          AND membership.clearance >= p_classification\n          AND (\n              p_system_id IS NULL\n              OR p_classification = 0\n              OR COALESCE(\n                  membership.attributes -> 'allowed_system_ids',\n                  '[]'::jsonb\n              ) ? p_system_id::text\n          )\n          AND (\n              p_domain_id IS NULL\n              OR p_classification = 0\n              OR COALESCE(\n                  membership.attributes -> 'allowed_domain_ids',\n                  '[]'::jsonb\n              ) ? p_domain_id::text\n          )\n          AND COALESCE(\n              membership.attributes -> 'allowed_actions',\n              '[]'::jsonb\n          ) ? p_action\n          AND NOT (\n              COALESCE(\n                  membership.attributes -> 'denied_actions',\n                  '[]'::jsonb\n              ) ? p_action\n          )\n    )\n$$;")
        op.execute('REVOKE ALL ON FUNCTION quality.current_human_can(\n    uuid, text, integer, uuid, uuid\n) FROM PUBLIC;')
        op.execute("CREATE OR REPLACE FUNCTION quality.can_read_asset(\n    p_workspace_id uuid,\n    p_asset_id uuid,\n    p_pinned_classification integer DEFAULT NULL,\n    p_pinned_system_id uuid DEFAULT NULL,\n    p_pinned_domain_id uuid DEFAULT NULL\n)\nRETURNS boolean\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = pg_catalog, catalog, quality\nAS $$\n    SELECT quality.current_human_can(\n        asset.workspace_id,\n        'quality.read',\n        GREATEST(asset.classification, COALESCE(p_pinned_classification, 0)),\n        CASE\n            WHEN p_pinned_system_id IS NOT NULL\n                 AND asset.system_id IS DISTINCT FROM p_pinned_system_id\n            THEN NULL\n            ELSE COALESCE(p_pinned_system_id, asset.system_id)\n        END,\n        CASE\n            WHEN p_pinned_domain_id IS NOT NULL\n                 AND asset.domain_id IS DISTINCT FROM p_pinned_domain_id\n            THEN NULL\n            ELSE COALESCE(p_pinned_domain_id, asset.domain_id)\n        END\n    )\n    AND (\n        p_pinned_system_id IS NULL\n        OR asset.system_id IS NOT DISTINCT FROM p_pinned_system_id\n        OR (\n            quality.current_human_can(\n                asset.workspace_id,\n                'quality.read',\n                GREATEST(asset.classification, COALESCE(p_pinned_classification, 0)),\n                asset.system_id,\n                asset.domain_id\n            )\n            AND quality.current_human_can(\n                asset.workspace_id,\n                'quality.read',\n                GREATEST(asset.classification, COALESCE(p_pinned_classification, 0)),\n                p_pinned_system_id,\n                p_pinned_domain_id\n            )\n        )\n    )\n    AND (\n        p_pinned_domain_id IS NULL\n        OR asset.domain_id IS NOT DISTINCT FROM p_pinned_domain_id\n        OR (\n            quality.current_human_can(\n                asset.workspace_id,\n                'quality.read',\n                GREATEST(asset.classification, COALESCE(p_pinned_classification, 0)),\n                asset.system_id,\n                asset.domain_id\n            )\n            AND quality.current_human_can(\n                asset.workspace_id,\n                'quality.read',\n                GREATEST(asset.classification, COALESCE(p_pinned_classification, 0)),\n                p_pinned_system_id,\n                p_pinned_domain_id\n            )\n        )\n    )\n    FROM catalog.assets_projection AS asset\n    WHERE asset.workspace_id = p_workspace_id\n      AND asset.id = p_asset_id\n$$;")
        op.execute('REVOKE ALL ON FUNCTION quality.can_read_asset(uuid, uuid, integer, uuid, uuid) FROM PUBLIC;')
        op.execute("CREATE OR REPLACE FUNCTION quality.current_target_matches_v1(\n    p_workspace_id uuid,\n    p_asset_id uuid,\n    p_classification integer,\n    p_system_id uuid,\n    p_domain_id uuid,\n    p_lifecycle text,\n    p_source_version text,\n    p_action text\n)\nRETURNS boolean\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = pg_catalog, catalog, quality\nAS $$\n    SELECT EXISTS (\n        SELECT 1\n        FROM catalog.assets_projection AS asset\n        WHERE asset.workspace_id = p_workspace_id\n          AND asset.id = p_asset_id\n          AND asset.deleted_at IS NULL\n          AND asset.lifecycle = 'ACTIVE'\n          AND asset.lifecycle = p_lifecycle\n          AND asset.source_version = p_source_version\n          AND asset.classification = p_classification\n          AND asset.system_id IS NOT DISTINCT FROM p_system_id\n          AND asset.domain_id IS NOT DISTINCT FROM p_domain_id\n          AND quality.current_human_can(\n              asset.workspace_id, p_action, asset.classification,\n              asset.system_id, asset.domain_id\n          )\n    )\n$$;")
        op.execute('REVOKE ALL ON FUNCTION quality.current_target_matches_v1(\n    uuid, uuid, integer, uuid, uuid, text, text, text\n) FROM PUBLIC;')
        op.execute("CREATE OR REPLACE FUNCTION quality.enforce_rule_set_binding_v1()\nRETURNS trigger\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, quality, retention\nAS $$\nDECLARE\n    resolved_rule record;\n    actor_id uuid := NULLIF(current_setting('app.subject_id', true), '')::uuid;\n    workspace_id uuid := NULLIF(current_setting('app.workspace_id', true), '')::uuid;\nBEGIN\n    IF NEW.workspace_id IS DISTINCT FROM workspace_id\n       OR NEW.created_by IS DISTINCT FROM actor_id\n       OR NEW.updated_by IS DISTINCT FROM actor_id\n       OR NEW.state <> 'ACTIVE'\n       OR NEW.archived_at IS NOT NULL\n       OR NEW.version <> 1 THEN\n        RAISE EXCEPTION 'invalid initial Quality rule-set actor or state'\n            USING ERRCODE = '42501';\n    END IF;\n    SELECT * INTO resolved_rule\n    FROM retention.resolve_quality_binding_v1(\n        NEW.workspace_id, 'QUALITY_RULE', 'QUALITY_RULE_SET',\n        NEW.id, NEW.rule_retention_basis_at\n    );\n    IF ROW(\n        NEW.rule_retention_policy_id,\n        NEW.rule_retention_policy_number,\n        NEW.rule_retention_policy_hash,\n        NEW.rule_retain_until,\n        NEW.rule_hold_generation,\n        NEW.rule_hold_hash\n    ) IS DISTINCT FROM ROW(\n        resolved_rule.policy_id,\n        resolved_rule.policy_number,\n        resolved_rule.policy_hash,\n        resolved_rule.retain_until,\n        resolved_rule.hold_generation,\n        resolved_rule.hold_hash\n    ) THEN\n        RAISE EXCEPTION 'Quality rule-set retention binding drift'\n            USING ERRCODE = '23514';\n    END IF;\n    RETURN NEW;\nEND\n$$;")
        op.execute('REVOKE ALL ON FUNCTION quality.enforce_rule_set_binding_v1() FROM PUBLIC;')
        op.execute('CREATE TRIGGER enforce_rule_set_binding\nBEFORE INSERT ON quality.rule_sets\nFOR EACH ROW EXECUTE FUNCTION quality.enforce_rule_set_binding_v1();')
        op.execute("CREATE OR REPLACE FUNCTION quality.reject_evidence_mutation()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY INVOKER\nSET search_path = pg_catalog\nAS $$\nBEGIN\n    IF TG_OP IN ('UPDATE', 'DELETE') THEN\n        RAISE EXCEPTION 'Quality evidence is append-only'\n            USING ERRCODE = '23514';\n    END IF;\n    RETURN NEW;\nEND\n$$;")
        op.execute('REVOKE ALL ON FUNCTION quality.reject_evidence_mutation() FROM PUBLIC;')
        op.execute("CREATE OR REPLACE FUNCTION quality.assert_run_attempt_shape_v1()\nRETURNS trigger\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, quality\nAS $$\nDECLARE\n    selected_run quality.validation_runs%ROWTYPE;\n    selected_attempt quality.validation_attempts%ROWTYPE;\nBEGIN\n    IF TG_TABLE_NAME = 'validation_runs' THEN\n        selected_run := NEW;\n    ELSE\n        SELECT * INTO selected_run\n        FROM quality.validation_runs AS run\n        WHERE run.workspace_id = NEW.workspace_id\n          AND run.current_attempt_id = NEW.id;\n        IF NOT FOUND THEN\n            RETURN NEW;\n        END IF;\n    END IF;\n    IF selected_run.current_attempt_id IS NULL THEN\n        IF selected_run.state NOT IN ('QUEUED', 'CANCELLED')\n           OR selected_run.attempt_count <> 0\n           OR selected_run.lease_epoch <> 0 THEN\n            RAISE EXCEPTION 'Quality run requires a current attempt'\n                USING ERRCODE = '23514';\n        END IF;\n        RETURN NEW;\n    END IF;\n    SELECT * INTO selected_attempt\n    FROM quality.validation_attempts AS attempt\n    WHERE attempt.workspace_id = selected_run.workspace_id\n      AND attempt.run_id = selected_run.id\n      AND attempt.id = selected_run.current_attempt_id;\n    IF NOT FOUND\n       OR selected_attempt.attempt_no <> selected_run.attempt_count\n       OR selected_attempt.lease_epoch <> selected_run.lease_epoch\n       OR (\n           selected_run.state IN ('RUNNING', 'CANCEL_REQUESTED')\n           AND selected_attempt.lease_token_hash\n               IS DISTINCT FROM selected_run.lease_token_hash\n       )\n       OR NOT (\n        (selected_run.state IN ('RUNNING', 'CANCEL_REQUESTED')\n            AND selected_attempt.state = 'RUNNING')\n        OR (selected_run.state = 'RETRY_WAIT'\n            AND selected_attempt.state = 'RETRYABLE_FAILED')\n        OR (selected_run.state = 'SUCCEEDED'\n            AND selected_attempt.state = 'SUCCEEDED')\n        OR (selected_run.state = 'FAILED'\n            AND selected_attempt.state = 'FAILED')\n        OR (selected_run.state = 'STALE'\n            AND selected_attempt.state = 'STALE')\n        OR (selected_run.state = 'CANCELLED'\n            AND selected_attempt.state IN ('CANCELLED', 'RETRYABLE_FAILED'))\n    ) THEN\n        RAISE EXCEPTION 'Quality run/current-attempt state mismatch'\n            USING ERRCODE = '23514';\n    END IF;\n    RETURN NEW;\nEND\n$$;")
        op.execute('REVOKE ALL ON FUNCTION quality.assert_run_attempt_shape_v1() FROM PUBLIC;')
        op.execute('CREATE CONSTRAINT TRIGGER enforce_run_attempt_shape\nAFTER INSERT OR UPDATE ON quality.validation_runs\nDEFERRABLE INITIALLY DEFERRED\nFOR EACH ROW EXECUTE FUNCTION quality.assert_run_attempt_shape_v1();')
        op.execute('CREATE CONSTRAINT TRIGGER enforce_run_attempt_shape\nAFTER INSERT OR UPDATE ON quality.validation_attempts\nDEFERRABLE INITIALLY DEFERRED\nFOR EACH ROW EXECUTE FUNCTION quality.assert_run_attempt_shape_v1();')
        op.execute("CREATE OR REPLACE FUNCTION quality.assert_run_results_shape_v1()\nRETURNS trigger\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, quality\nAS $$\nDECLARE\n    selected_run quality.validation_runs%ROWTYPE;\n    target_workspace_id uuid;\n    target_run_id uuid;\n    expected_count bigint;\n    actual_count bigint;\n    actual_passed bigint;\n    actual_advisory bigint;\n    actual_blocking bigint;\n    expected_outcome text;\nBEGIN\n    IF TG_TABLE_NAME = 'validation_runs' THEN\n        selected_run := NEW;\n    ELSE\n        IF TG_OP = 'DELETE' THEN\n            target_workspace_id := OLD.workspace_id;\n            target_run_id := OLD.run_id;\n        ELSE\n            target_workspace_id := NEW.workspace_id;\n            target_run_id := NEW.run_id;\n        END IF;\n        SELECT * INTO selected_run\n        FROM quality.validation_runs AS run\n        WHERE run.workspace_id = target_workspace_id\n          AND run.id = target_run_id;\n        IF NOT FOUND THEN\n            IF TG_OP = 'DELETE' THEN\n                RETURN OLD;\n            END IF;\n            RETURN NEW;\n        END IF;\n    END IF;\n\n    SELECT count(*) INTO actual_count\n    FROM quality.expectation_results AS result\n    WHERE result.workspace_id = selected_run.workspace_id\n      AND result.run_id = selected_run.id;\n    IF selected_run.state <> 'SUCCEEDED' THEN\n        IF actual_count <> 0 THEN\n            RAISE EXCEPTION 'Only a successful Quality run may own results'\n                USING ERRCODE = '23514';\n        END IF;\n    ELSE\n        SELECT count(*) INTO expected_count\n        FROM quality.rule_definitions AS definition\n        WHERE definition.workspace_id = selected_run.workspace_id\n          AND definition.rule_set_version_id = selected_run.rule_set_version_id;\n        SELECT\n            count(*) FILTER (WHERE result.outcome = 'PASS'),\n            count(*) FILTER (WHERE result.outcome = 'ADVISORY_FAIL'),\n            count(*) FILTER (WHERE result.outcome = 'BLOCKING_FAIL')\n        INTO actual_passed, actual_advisory, actual_blocking\n        FROM quality.expectation_results AS result\n        WHERE result.workspace_id = selected_run.workspace_id\n          AND result.run_id = selected_run.id;\n        expected_outcome := CASE\n            WHEN actual_blocking > 0 THEN 'FAIL'\n            WHEN actual_advisory > 0 THEN 'WARN'\n            ELSE 'PASS'\n        END;\n        IF expected_count = 0\n           OR actual_count <> expected_count\n           OR selected_run.passed_count IS DISTINCT FROM actual_passed\n           OR selected_run.advisory_failed_count IS DISTINCT FROM actual_advisory\n           OR selected_run.blocking_failed_count IS DISTINCT FROM actual_blocking\n           OR selected_run.quality_outcome IS DISTINCT FROM expected_outcome THEN\n            RAISE EXCEPTION 'Quality successful-run result coverage is incomplete'\n                USING ERRCODE = '23514';\n        END IF;\n    END IF;\n    IF TG_OP = 'DELETE' THEN\n        RETURN OLD;\n    END IF;\n    RETURN NEW;\nEND\n$$;")
        op.execute('REVOKE ALL ON FUNCTION quality.assert_run_results_shape_v1() FROM PUBLIC;')
        op.execute('CREATE CONSTRAINT TRIGGER enforce_run_results_shape\nAFTER INSERT OR UPDATE ON quality.validation_runs\nDEFERRABLE INITIALLY DEFERRED\nFOR EACH ROW EXECUTE FUNCTION quality.assert_run_results_shape_v1();')
        op.execute('CREATE CONSTRAINT TRIGGER enforce_run_results_shape\nAFTER INSERT OR UPDATE OR DELETE ON quality.expectation_results\nDEFERRABLE INITIALLY DEFERRED\nFOR EACH ROW EXECUTE FUNCTION quality.assert_run_results_shape_v1();')
        op.execute("CREATE OR REPLACE FUNCTION quality.require_human_decision_v1(\n    p_workspace_id uuid,\n    p_subject_id uuid,\n    p_resource_id uuid,\n    p_action text,\n    p_policy_decision_id uuid,\n    p_require_hardware boolean\n)\nRETURNS TABLE(\n    authentication_time timestamptz,\n    authorization_hash text,\n    assurance_hash text\n)\nLANGUAGE plpgsql\nSTABLE\nSECURITY DEFINER\nSET search_path = pg_catalog, authz\nAS $$\nDECLARE\n    selected_decision authz.policy_decisions%ROWTYPE;\nBEGIN\n    IF p_subject_id IS DISTINCT FROM\n       NULLIF(current_setting('app.subject_id', true), '')::uuid\n       OR p_workspace_id IS DISTINCT FROM\n          NULLIF(current_setting('app.workspace_id', true), '')::uuid THEN\n        RAISE EXCEPTION 'Quality command security context mismatch'\n            USING ERRCODE = '42501';\n    END IF;\n    SELECT * INTO selected_decision\n    FROM authz.policy_decisions\n    WHERE workspace_id = p_workspace_id\n      AND id = p_policy_decision_id\n      AND subject_id = p_subject_id\n      AND resource_id = p_resource_id\n      AND action = p_action\n      AND effect = 'ALLOW'\n      AND decided_at <= transaction_timestamp()\n      AND decided_at >= transaction_timestamp() - interval '15 minutes';\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'Quality command authorization decision is invalid'\n            USING ERRCODE = '42501';\n    END IF;\n    IF selected_decision.evaluation_context ->> 'authentication_time' IS NOT NULL THEN\n        authentication_time :=\n            (selected_decision.evaluation_context ->> 'authentication_time')::timestamptz;\n        IF authentication_time > selected_decision.decided_at\n           OR authentication_time > transaction_timestamp() THEN\n            RAISE EXCEPTION 'authentication evidence is invalid'\n                USING ERRCODE = '42501';\n        END IF;\n    END IF;\n    IF p_require_hardware THEN\n        IF selected_decision.evaluation_context ->> 'authentication_assurance'\n           <> 'HARDWARE_WEBAUTHN'\n           OR authentication_time IS NULL THEN\n            RAISE EXCEPTION 'recent hardware WebAuthn is required'\n                USING ERRCODE = '42501';\n        END IF;\n        IF authentication_time < transaction_timestamp() - interval '15 minutes' THEN\n            RAISE EXCEPTION 'hardware WebAuthn evidence is stale or invalid'\n                USING ERRCODE = '42501';\n        END IF;\n    END IF;\n    authorization_hash := encode(sha256(convert_to(jsonb_build_object(\n        'contract', 'QUALITY_AUTHORIZATION_EVIDENCE_V1',\n        'decision_id', selected_decision.id::text,\n        'workspace_id', selected_decision.workspace_id::text,\n        'subject_id', selected_decision.subject_id::text,\n        'resource_id', selected_decision.resource_id::text,\n        'action', selected_decision.action,\n        'effect', selected_decision.effect,\n        'reason_codes', selected_decision.reason_codes,\n        'policy_versions', selected_decision.policy_versions,\n        'evaluation_context', selected_decision.evaluation_context,\n        'request_id', selected_decision.request_id,\n        'decided_at', selected_decision.decided_at\n    )::text, 'UTF8')), 'hex');\n    assurance_hash := encode(sha256(convert_to(jsonb_build_object(\n        'contract', 'QUALITY_ASSURANCE_EVIDENCE_V1',\n        'decision_id', selected_decision.id::text,\n        'assurance',\n            selected_decision.evaluation_context ->> 'authentication_assurance',\n        'authentication_time', authentication_time\n    )::text, 'UTF8')), 'hex');\n    RETURN NEXT;\nEND\n$$;")
        op.execute('REVOKE ALL ON FUNCTION quality.require_human_decision_v1(\n    uuid, uuid, uuid, text, uuid, boolean\n) FROM PUBLIC;')
        op.execute("CREATE OR REPLACE FUNCTION quality.review_rule_set_version_v1(\n    p_workspace_id uuid,\n    p_version_id uuid,\n    p_decision text,\n    p_reason text,\n    p_policy_decision_id uuid,\n    p_assurance_hash text,\n    p_expected_version integer,\n    p_audit_policy_id uuid,\n    p_audit_policy_number integer,\n    p_audit_policy_hash text,\n    p_audit_retain_until timestamptz,\n    p_audit_hold_generation bigint,\n    p_audit_hold_hash text\n)\nRETURNS uuid\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, quality, retention\nAS $$\nDECLARE\n    actor_id uuid := NULLIF(current_setting('app.subject_id', true), '')::uuid;\n    candidate quality.rule_set_versions%ROWTYPE;\n    resolved record;\n    decision_evidence record;\n    review_id uuid := gen_random_uuid();\nBEGIN\n    IF p_workspace_id IS DISTINCT FROM\n       NULLIF(current_setting('app.workspace_id', true), '')::uuid THEN\n        RAISE EXCEPTION 'invalid Quality review command'\n            USING ERRCODE = '42501';\n    END IF;\n    SELECT * INTO candidate\n    FROM quality.rule_set_versions\n    WHERE workspace_id = p_workspace_id AND id = p_version_id\n    FOR UPDATE;\n    IF NOT FOUND OR candidate.state <> 'PROPOSED'\n       OR candidate.version <> p_expected_version\n       OR p_decision NOT IN ('APPROVE','REJECT')\n       OR char_length(btrim(p_reason)) NOT BETWEEN 1 AND 4000\n       OR actor_id = candidate.author_id\n       OR NOT quality.current_target_matches_v1(\n           p_workspace_id, candidate.asset_id, candidate.classification,\n           candidate.system_id, candidate.domain_id, candidate.lifecycle,\n           candidate.source_version, 'quality.rule.review'\n       ) THEN\n        RAISE EXCEPTION 'invalid Quality review command'\n            USING ERRCODE = '42501';\n    END IF;\n    SELECT * INTO decision_evidence\n    FROM quality.require_human_decision_v1(\n        p_workspace_id, actor_id, p_version_id, 'quality.rule.review',\n        p_policy_decision_id, false\n    );\n    IF p_assurance_hash IS DISTINCT FROM decision_evidence.assurance_hash THEN\n        RAISE EXCEPTION 'Quality review assurance evidence drift'\n            USING ERRCODE = '23514';\n    END IF;\n    SELECT * INTO resolved\n    FROM retention.resolve_quality_binding_v1(\n        p_workspace_id, 'QUALITY_AUDIT', 'QUALITY_RULE_SET',\n        candidate.rule_set_id, transaction_timestamp()\n    );\n    IF ROW(\n        p_audit_policy_id, p_audit_policy_number, p_audit_policy_hash,\n        p_audit_retain_until, p_audit_hold_generation, p_audit_hold_hash\n    ) IS DISTINCT FROM ROW(\n        resolved.policy_id, resolved.policy_number, resolved.policy_hash,\n        resolved.retain_until, resolved.hold_generation, resolved.hold_hash\n    ) THEN\n        RAISE EXCEPTION 'Quality review retention binding drift'\n            USING ERRCODE = '23514';\n    END IF;\n\n    INSERT INTO quality.rule_reviews (\n        id, workspace_id, rule_set_version_id, decision, actor_id, reason,\n        policy_decision_id, assurance_hash, target_binding_hash,\n        audit_retention_kind, audit_retention_policy_id,\n        audit_retention_policy_number, audit_retention_policy_hash,\n        audit_retention_basis_at, audit_retain_until,\n        audit_hold_generation, audit_hold_hash, occurred_at\n    )\n    VALUES (\n        review_id, p_workspace_id, p_version_id, p_decision, actor_id, btrim(p_reason),\n        p_policy_decision_id, p_assurance_hash, candidate.target_binding_hash,\n        'QUALITY_AUDIT', p_audit_policy_id, p_audit_policy_number,\n        p_audit_policy_hash, transaction_timestamp(), p_audit_retain_until,\n        p_audit_hold_generation, p_audit_hold_hash, transaction_timestamp()\n    );\n    UPDATE quality.rule_set_versions\n    SET state = CASE p_decision WHEN 'APPROVE' THEN 'APPROVED' ELSE 'REJECTED' END,\n        reviewed_by = actor_id,\n        reviewed_at = transaction_timestamp(),\n        version = version + 1,\n        updated_at = transaction_timestamp()\n    WHERE workspace_id = p_workspace_id AND id = p_version_id;\n    RETURN review_id;\nEND\n$$;")
        op.execute('REVOKE ALL ON FUNCTION quality.review_rule_set_version_v1(\n    uuid, uuid, text, text, uuid, text, integer,\n    uuid, integer, text, timestamptz, bigint, text\n) FROM PUBLIC;')
        op.execute("CREATE OR REPLACE FUNCTION quality.activate_rule_set_version_v1(\n    p_workspace_id uuid,\n    p_version_id uuid,\n    p_policy_decision_id uuid,\n    p_webauthn_evidence_hash text,\n    p_authorization_hash text,\n    p_schedule_binding_hash text,\n    p_retention_binding_hash text,\n    p_idempotency_key_hash text,\n    p_expected_version integer,\n    p_audit_policy_id uuid,\n    p_audit_policy_number integer,\n    p_audit_policy_hash text,\n    p_audit_retain_until timestamptz,\n    p_audit_hold_generation bigint,\n    p_audit_hold_hash text\n)\nRETURNS uuid\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, quality, retention\nAS $$\nDECLARE\n    actor_id uuid := NULLIF(current_setting('app.subject_id', true), '')::uuid;\n    candidate quality.rule_set_versions%ROWTYPE;\n    prior_active quality.rule_set_versions%ROWTYPE;\n    parent quality.rule_sets%ROWTYPE;\n    resolved_rule record;\n    resolved_audit record;\n    decision_evidence record;\n    existing_command quality.rule_command_events%ROWTYPE;\n    calculated_schedule_hash text;\n    calculated_retention_hash text;\n    calculated_request_hash text;\n    superseded_schedule_hash text;\n    superseded_retention_hash text;\n    supersede_request_hash text;\n    supersede_idempotency_hash text;\n    supersede_command_id uuid := gen_random_uuid();\n    command_id uuid := gen_random_uuid();\n    next_sequence bigint;\nBEGIN\n    IF p_workspace_id IS DISTINCT FROM\n       NULLIF(current_setting('app.workspace_id', true), '')::uuid THEN\n        RAISE EXCEPTION 'invalid Quality activation command'\n            USING ERRCODE = '42501';\n    END IF;\n    SELECT * INTO candidate\n    FROM quality.rule_set_versions\n    WHERE workspace_id = p_workspace_id AND id = p_version_id\n    FOR UPDATE;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'Quality Rule Set Version is unavailable'\n            USING ERRCODE = '42501';\n    END IF;\n    SELECT * INTO parent\n    FROM quality.rule_sets\n    WHERE workspace_id = p_workspace_id AND id = candidate.rule_set_id\n    FOR UPDATE;\n    SELECT * INTO prior_active\n    FROM quality.rule_set_versions\n    WHERE workspace_id = p_workspace_id\n      AND rule_set_id = candidate.rule_set_id\n      AND state = 'ACTIVE'\n      AND id <> p_version_id\n    FOR UPDATE;\n    calculated_request_hash := encode(sha256(convert_to(jsonb_build_object(\n        'contract', 'QUALITY_ACTIVATE_REQUEST_V1',\n        'workspace_id', p_workspace_id::text,\n        'version_id', p_version_id::text,\n        'actor_id', actor_id::text,\n        'policy_decision_id', p_policy_decision_id::text,\n        'webauthn_evidence_hash', p_webauthn_evidence_hash,\n        'authorization_hash', p_authorization_hash,\n        'schedule_binding_hash', p_schedule_binding_hash,\n        'retention_binding_hash', p_retention_binding_hash,\n        'expected_version', p_expected_version,\n        'audit_policy_id', p_audit_policy_id::text,\n        'audit_policy_number', p_audit_policy_number,\n        'audit_policy_hash', p_audit_policy_hash,\n        'audit_retain_until', p_audit_retain_until,\n        'audit_hold_generation', p_audit_hold_generation,\n        'audit_hold_hash', p_audit_hold_hash\n    )::text, 'UTF8')), 'hex');\n    SELECT * INTO existing_command\n    FROM quality.rule_command_events\n    WHERE workspace_id = p_workspace_id\n      AND rule_set_id = candidate.rule_set_id\n      AND idempotency_key_hash = p_idempotency_key_hash;\n    IF FOUND THEN\n        IF existing_command.command = 'ACTIVATE'\n           AND existing_command.rule_set_version_id = p_version_id\n           AND existing_command.request_hash = calculated_request_hash THEN\n            RETURN existing_command.id;\n        END IF;\n        RAISE EXCEPTION 'Quality activation idempotency conflict'\n            USING ERRCODE = '23505';\n    END IF;\n    IF candidate.state <> 'APPROVED'\n       OR candidate.version <> p_expected_version\n       OR parent.state <> 'ACTIVE'\n       OR actor_id = candidate.author_id\n       OR candidate.schedule_mode <> 'MANUAL_ONLY'\n       OR NOT EXISTS (\n           SELECT 1 FROM quality.rule_definitions AS definition\n           WHERE definition.workspace_id = p_workspace_id\n             AND definition.rule_set_version_id = p_version_id\n       )\n       OR NOT quality.current_target_matches_v1(\n           p_workspace_id, candidate.asset_id, candidate.classification,\n           candidate.system_id, candidate.domain_id, candidate.lifecycle,\n           candidate.source_version, 'quality.rule.activate'\n       ) THEN\n        RAISE EXCEPTION 'invalid Quality activation command'\n            USING ERRCODE = '42501';\n    END IF;\n    SELECT * INTO decision_evidence\n    FROM quality.require_human_decision_v1(\n        p_workspace_id, actor_id, p_version_id, 'quality.rule.activate',\n        p_policy_decision_id, true\n    );\n    IF p_authorization_hash IS DISTINCT FROM decision_evidence.authorization_hash\n       OR p_webauthn_evidence_hash IS DISTINCT FROM decision_evidence.assurance_hash THEN\n        RAISE EXCEPTION 'Quality activation authorization evidence drift'\n            USING ERRCODE = '23514';\n    END IF;\n    calculated_schedule_hash := encode(sha256(convert_to(jsonb_build_object(\n        'contract', 'QUALITY_SCHEDULE_BINDING_V1',\n        'mode', candidate.schedule_mode,\n        'profile_id', candidate.schedule_profile_id,\n        'profile_version', candidate.schedule_profile_version,\n        'profile_hash', candidate.schedule_profile_hash\n    )::text, 'UTF8')), 'hex');\n    IF p_schedule_binding_hash IS DISTINCT FROM calculated_schedule_hash THEN\n        RAISE EXCEPTION 'Quality activation schedule evidence drift'\n            USING ERRCODE = '23514';\n    END IF;\n    SELECT * INTO resolved_rule\n    FROM retention.resolve_quality_binding_v1(\n        p_workspace_id, 'QUALITY_RULE', 'QUALITY_RULE_SET',\n        candidate.rule_set_id, transaction_timestamp()\n    );\n    IF ROW(\n        candidate.rule_retention_policy_id,\n        candidate.rule_retention_policy_number,\n        candidate.rule_retention_policy_hash,\n        candidate.rule_hold_generation,\n        candidate.rule_hold_hash\n    ) IS DISTINCT FROM ROW(\n        resolved_rule.policy_id, resolved_rule.policy_number,\n        resolved_rule.policy_hash, resolved_rule.hold_generation,\n        resolved_rule.hold_hash\n    ) OR candidate.rule_retain_until <= transaction_timestamp() THEN\n        RAISE EXCEPTION 'Quality Rule retention binding drift'\n            USING ERRCODE = '23514';\n    END IF;\n    SELECT * INTO resolved_audit\n    FROM retention.resolve_quality_binding_v1(\n        p_workspace_id, 'QUALITY_AUDIT', 'QUALITY_RULE_SET',\n        candidate.rule_set_id, transaction_timestamp()\n    );\n    IF ROW(\n        p_audit_policy_id, p_audit_policy_number, p_audit_policy_hash,\n        p_audit_retain_until, p_audit_hold_generation, p_audit_hold_hash\n    ) IS DISTINCT FROM ROW(\n        resolved_audit.policy_id, resolved_audit.policy_number,\n        resolved_audit.policy_hash, resolved_audit.retain_until,\n        resolved_audit.hold_generation, resolved_audit.hold_hash\n    ) THEN\n        RAISE EXCEPTION 'Quality activation audit binding drift'\n            USING ERRCODE = '23514';\n    END IF;\n    calculated_retention_hash := encode(sha256(convert_to(jsonb_build_object(\n        'contract', 'QUALITY_COMMAND_RETENTION_BINDING_V1',\n        'rule_policy_id', resolved_rule.policy_id::text,\n        'rule_policy_number', resolved_rule.policy_number,\n        'rule_policy_hash', resolved_rule.policy_hash,\n        'rule_retain_until', resolved_rule.retain_until,\n        'rule_hold_generation', resolved_rule.hold_generation,\n        'rule_hold_hash', resolved_rule.hold_hash,\n        'audit_policy_id', resolved_audit.policy_id::text,\n        'audit_policy_number', resolved_audit.policy_number,\n        'audit_policy_hash', resolved_audit.policy_hash,\n        'audit_retain_until', resolved_audit.retain_until,\n        'audit_hold_generation', resolved_audit.hold_generation,\n        'audit_hold_hash', resolved_audit.hold_hash\n    )::text, 'UTF8')), 'hex');\n    IF p_retention_binding_hash IS DISTINCT FROM calculated_retention_hash THEN\n        RAISE EXCEPTION 'Quality activation retention evidence drift'\n            USING ERRCODE = '23514';\n    END IF;\n    IF prior_active.id IS NOT NULL THEN\n        superseded_schedule_hash := encode(sha256(convert_to(jsonb_build_object(\n            'contract', 'QUALITY_SCHEDULE_BINDING_V1',\n            'mode', prior_active.schedule_mode,\n            'profile_id', prior_active.schedule_profile_id,\n            'profile_version', prior_active.schedule_profile_version,\n            'profile_hash', prior_active.schedule_profile_hash\n        )::text, 'UTF8')), 'hex');\n        superseded_retention_hash := encode(sha256(convert_to(jsonb_build_object(\n            'contract', 'QUALITY_COMMAND_RETENTION_BINDING_V1',\n            'rule_policy_id', prior_active.rule_retention_policy_id::text,\n            'rule_policy_number', prior_active.rule_retention_policy_number,\n            'rule_policy_hash', prior_active.rule_retention_policy_hash,\n            'rule_retain_until', prior_active.rule_retain_until,\n            'rule_hold_generation', prior_active.rule_hold_generation,\n            'rule_hold_hash', prior_active.rule_hold_hash,\n            'audit_policy_id', resolved_audit.policy_id::text,\n            'audit_policy_number', resolved_audit.policy_number,\n            'audit_policy_hash', resolved_audit.policy_hash,\n            'audit_retain_until', resolved_audit.retain_until,\n            'audit_hold_generation', resolved_audit.hold_generation,\n            'audit_hold_hash', resolved_audit.hold_hash\n        )::text, 'UTF8')), 'hex');\n        supersede_request_hash := encode(sha256(convert_to(jsonb_build_object(\n            'contract', 'QUALITY_SUPERSEDE_REQUEST_V1',\n            'activation_request_hash', calculated_request_hash,\n            'superseded_version_id', prior_active.id::text\n        )::text, 'UTF8')), 'hex');\n        supersede_idempotency_hash := encode(sha256(convert_to(\n            'QUALITY_SUPERSEDE_V1:' || p_idempotency_key_hash || ':' ||\n            prior_active.id::text,\n            'UTF8'\n        )), 'hex');\n    END IF;\n\n    UPDATE quality.rule_set_versions\n    SET state = 'SUPERSEDED',\n        version = version + 1,\n        updated_at = transaction_timestamp()\n    WHERE workspace_id = p_workspace_id\n      AND rule_set_id = candidate.rule_set_id\n      AND state = 'ACTIVE';\n    UPDATE quality.rule_schedules\n    SET state = 'INACTIVE',\n        version = version + 1,\n        updated_at = transaction_timestamp()\n    WHERE workspace_id = p_workspace_id\n      AND rule_set_id = candidate.rule_set_id\n      AND state = 'ACTIVE';\n    UPDATE quality.rule_set_versions\n    SET state = 'ACTIVE',\n        activated_by = actor_id,\n        activated_at = transaction_timestamp(),\n        version = version + 1,\n        updated_at = transaction_timestamp()\n    WHERE workspace_id = p_workspace_id AND id = p_version_id;\n\n    SELECT COALESCE(max(sequence), 0) + 1 INTO next_sequence\n    FROM quality.rule_command_events\n    WHERE workspace_id = p_workspace_id\n      AND rule_set_id = candidate.rule_set_id;\n    IF prior_active.id IS NOT NULL THEN\n        INSERT INTO quality.rule_command_events (\n            id, workspace_id, rule_set_id, rule_set_version_id, sequence,\n            command, actor_id, actor_kind, webauthn_evidence_hash,\n            authentication_time, authorization_hash, target_binding_hash,\n            schedule_binding_hash, retention_binding_hash, request_hash,\n            idempotency_key_hash,\n            audit_retention_kind, audit_retention_policy_id,\n            audit_retention_policy_number, audit_retention_policy_hash,\n            audit_retention_basis_at, audit_retain_until,\n            audit_hold_generation, audit_hold_hash, occurred_at\n        )\n        VALUES (\n            supersede_command_id, p_workspace_id, candidate.rule_set_id,\n            prior_active.id, next_sequence, 'SUPERSEDE', actor_id, 'HUMAN',\n            decision_evidence.assurance_hash, decision_evidence.authentication_time,\n            decision_evidence.authorization_hash, prior_active.target_binding_hash,\n            superseded_schedule_hash, superseded_retention_hash,\n            supersede_request_hash, supersede_idempotency_hash,\n            'QUALITY_AUDIT', p_audit_policy_id, p_audit_policy_number,\n            p_audit_policy_hash, transaction_timestamp(), p_audit_retain_until,\n            p_audit_hold_generation, p_audit_hold_hash, transaction_timestamp()\n        );\n        next_sequence := next_sequence + 1;\n    END IF;\n    INSERT INTO quality.rule_command_events (\n        id, workspace_id, rule_set_id, rule_set_version_id, sequence,\n        command, actor_id, actor_kind, webauthn_evidence_hash,\n        authentication_time, authorization_hash, target_binding_hash,\n        schedule_binding_hash, retention_binding_hash, request_hash,\n        idempotency_key_hash,\n        audit_retention_kind, audit_retention_policy_id,\n        audit_retention_policy_number, audit_retention_policy_hash,\n        audit_retention_basis_at, audit_retain_until,\n        audit_hold_generation, audit_hold_hash, occurred_at\n    )\n    VALUES (\n        command_id, p_workspace_id, candidate.rule_set_id, p_version_id,\n        next_sequence, 'ACTIVATE', actor_id, 'HUMAN',\n        decision_evidence.assurance_hash, decision_evidence.authentication_time,\n        decision_evidence.authorization_hash,\n        candidate.target_binding_hash, calculated_schedule_hash,\n        calculated_retention_hash, calculated_request_hash, p_idempotency_key_hash,\n        'QUALITY_AUDIT', p_audit_policy_id, p_audit_policy_number,\n        p_audit_policy_hash, transaction_timestamp(), p_audit_retain_until,\n        p_audit_hold_generation, p_audit_hold_hash, transaction_timestamp()\n    );\n    RETURN command_id;\nEND\n$$;")
        op.execute('REVOKE ALL ON FUNCTION quality.activate_rule_set_version_v1(\n    uuid, uuid, uuid, text, text, text, text, text, integer,\n    uuid, integer, text, timestamptz, bigint, text\n) FROM PUBLIC;')
        op.execute("CREATE OR REPLACE FUNCTION quality.revoke_rule_set_version_v1(\n    p_workspace_id uuid,\n    p_version_id uuid,\n    p_policy_decision_id uuid,\n    p_webauthn_evidence_hash text,\n    p_authorization_hash text,\n    p_retention_binding_hash text,\n    p_idempotency_key_hash text,\n    p_expected_version integer,\n    p_audit_policy_id uuid,\n    p_audit_policy_number integer,\n    p_audit_policy_hash text,\n    p_audit_retain_until timestamptz,\n    p_audit_hold_generation bigint,\n    p_audit_hold_hash text\n)\nRETURNS uuid\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, quality, retention\nAS $$\nDECLARE\n    actor_id uuid := NULLIF(current_setting('app.subject_id', true), '')::uuid;\n    candidate quality.rule_set_versions%ROWTYPE;\n    resolved_audit record;\n    decision_evidence record;\n    existing_command quality.rule_command_events%ROWTYPE;\n    calculated_schedule_hash text;\n    calculated_retention_hash text;\n    calculated_request_hash text;\n    command_id uuid := gen_random_uuid();\n    next_sequence bigint;\nBEGIN\n    IF p_workspace_id IS DISTINCT FROM\n       NULLIF(current_setting('app.workspace_id', true), '')::uuid THEN\n        RAISE EXCEPTION 'invalid Quality revoke command'\n            USING ERRCODE = '42501';\n    END IF;\n    SELECT * INTO candidate\n    FROM quality.rule_set_versions\n    WHERE workspace_id = p_workspace_id AND id = p_version_id\n    FOR UPDATE;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'invalid Quality revoke command'\n            USING ERRCODE = '42501';\n    END IF;\n    calculated_request_hash := encode(sha256(convert_to(jsonb_build_object(\n        'contract', 'QUALITY_REVOKE_REQUEST_V1',\n        'workspace_id', p_workspace_id::text,\n        'version_id', p_version_id::text,\n        'actor_id', actor_id::text,\n        'policy_decision_id', p_policy_decision_id::text,\n        'webauthn_evidence_hash', p_webauthn_evidence_hash,\n        'authorization_hash', p_authorization_hash,\n        'retention_binding_hash', p_retention_binding_hash,\n        'expected_version', p_expected_version,\n        'audit_policy_id', p_audit_policy_id::text,\n        'audit_policy_number', p_audit_policy_number,\n        'audit_policy_hash', p_audit_policy_hash,\n        'audit_retain_until', p_audit_retain_until,\n        'audit_hold_generation', p_audit_hold_generation,\n        'audit_hold_hash', p_audit_hold_hash\n    )::text, 'UTF8')), 'hex');\n    SELECT * INTO existing_command\n    FROM quality.rule_command_events\n    WHERE workspace_id = p_workspace_id\n      AND rule_set_id = candidate.rule_set_id\n      AND idempotency_key_hash = p_idempotency_key_hash;\n    IF FOUND THEN\n        IF existing_command.command = 'REVOKE'\n           AND existing_command.rule_set_version_id = p_version_id\n           AND existing_command.request_hash = calculated_request_hash THEN\n            RETURN existing_command.id;\n        END IF;\n        RAISE EXCEPTION 'Quality revoke idempotency conflict'\n            USING ERRCODE = '23505';\n    END IF;\n    IF candidate.state <> 'ACTIVE'\n       OR candidate.version <> p_expected_version\n       OR NOT quality.current_human_can(\n           p_workspace_id, 'quality.rule.revoke', candidate.classification,\n           candidate.system_id, candidate.domain_id\n       ) THEN\n        RAISE EXCEPTION 'invalid Quality revoke command'\n            USING ERRCODE = '42501';\n    END IF;\n    SELECT * INTO decision_evidence\n    FROM quality.require_human_decision_v1(\n        p_workspace_id, actor_id, p_version_id, 'quality.rule.revoke',\n        p_policy_decision_id, true\n    );\n    IF p_authorization_hash IS DISTINCT FROM decision_evidence.authorization_hash\n       OR p_webauthn_evidence_hash IS DISTINCT FROM decision_evidence.assurance_hash THEN\n        RAISE EXCEPTION 'Quality revoke authorization evidence drift'\n            USING ERRCODE = '23514';\n    END IF;\n    SELECT * INTO resolved_audit\n    FROM retention.resolve_quality_binding_v1(\n        p_workspace_id, 'QUALITY_AUDIT', 'QUALITY_RULE_SET',\n        candidate.rule_set_id, transaction_timestamp()\n    );\n    IF ROW(\n        p_audit_policy_id, p_audit_policy_number, p_audit_policy_hash,\n        p_audit_retain_until, p_audit_hold_generation, p_audit_hold_hash\n    ) IS DISTINCT FROM ROW(\n        resolved_audit.policy_id, resolved_audit.policy_number,\n        resolved_audit.policy_hash, resolved_audit.retain_until,\n        resolved_audit.hold_generation, resolved_audit.hold_hash\n    ) THEN\n        RAISE EXCEPTION 'Quality revoke audit binding drift'\n            USING ERRCODE = '23514';\n    END IF;\n    calculated_schedule_hash := encode(sha256(convert_to(jsonb_build_object(\n        'contract', 'QUALITY_SCHEDULE_BINDING_V1',\n        'mode', candidate.schedule_mode,\n        'profile_id', candidate.schedule_profile_id,\n        'profile_version', candidate.schedule_profile_version,\n        'profile_hash', candidate.schedule_profile_hash\n    )::text, 'UTF8')), 'hex');\n    calculated_retention_hash := encode(sha256(convert_to(jsonb_build_object(\n        'contract', 'QUALITY_COMMAND_RETENTION_BINDING_V1',\n        'rule_policy_id', candidate.rule_retention_policy_id::text,\n        'rule_policy_number', candidate.rule_retention_policy_number,\n        'rule_policy_hash', candidate.rule_retention_policy_hash,\n        'rule_retain_until', candidate.rule_retain_until,\n        'rule_hold_generation', candidate.rule_hold_generation,\n        'rule_hold_hash', candidate.rule_hold_hash,\n        'audit_policy_id', resolved_audit.policy_id::text,\n        'audit_policy_number', resolved_audit.policy_number,\n        'audit_policy_hash', resolved_audit.policy_hash,\n        'audit_retain_until', resolved_audit.retain_until,\n        'audit_hold_generation', resolved_audit.hold_generation,\n        'audit_hold_hash', resolved_audit.hold_hash\n    )::text, 'UTF8')), 'hex');\n    IF p_retention_binding_hash IS DISTINCT FROM calculated_retention_hash THEN\n        RAISE EXCEPTION 'Quality revoke retention evidence drift'\n            USING ERRCODE = '23514';\n    END IF;\n    UPDATE quality.rule_set_versions\n    SET state = 'REVOKED',\n        revoked_by = actor_id,\n        revoked_at = transaction_timestamp(),\n        version = version + 1,\n        updated_at = transaction_timestamp()\n    WHERE workspace_id = p_workspace_id AND id = p_version_id;\n    UPDATE quality.rule_schedules\n    SET state = 'INACTIVE',\n        version = version + 1,\n        updated_at = transaction_timestamp()\n    WHERE workspace_id = p_workspace_id\n      AND rule_set_version_id = p_version_id\n      AND state = 'ACTIVE';\n    SELECT COALESCE(max(sequence), 0) + 1 INTO next_sequence\n    FROM quality.rule_command_events\n    WHERE workspace_id = p_workspace_id\n      AND rule_set_id = candidate.rule_set_id;\n    INSERT INTO quality.rule_command_events (\n        id, workspace_id, rule_set_id, rule_set_version_id, sequence,\n        command, actor_id, actor_kind, webauthn_evidence_hash,\n        authentication_time, authorization_hash, target_binding_hash,\n        schedule_binding_hash, retention_binding_hash, request_hash,\n        idempotency_key_hash,\n        audit_retention_kind, audit_retention_policy_id,\n        audit_retention_policy_number, audit_retention_policy_hash,\n        audit_retention_basis_at, audit_retain_until,\n        audit_hold_generation, audit_hold_hash, occurred_at\n    )\n    VALUES (\n        command_id, p_workspace_id, candidate.rule_set_id, p_version_id,\n        next_sequence, 'REVOKE', actor_id, 'HUMAN',\n        decision_evidence.assurance_hash, decision_evidence.authentication_time,\n        decision_evidence.authorization_hash, candidate.target_binding_hash,\n        calculated_schedule_hash, calculated_retention_hash,\n        calculated_request_hash, p_idempotency_key_hash,\n        'QUALITY_AUDIT', p_audit_policy_id, p_audit_policy_number,\n        p_audit_policy_hash, transaction_timestamp(), p_audit_retain_until,\n        p_audit_hold_generation, p_audit_hold_hash, transaction_timestamp()\n    );\n    RETURN command_id;\nEND\n$$;")
        op.execute('REVOKE ALL ON FUNCTION quality.revoke_rule_set_version_v1(\n    uuid, uuid, uuid, text, text, text, text, integer,\n    uuid, integer, text, timestamptz, bigint, text\n) FROM PUBLIC;')
        op.execute("CREATE OR REPLACE FUNCTION quality.archive_rule_set_v1(\n    p_workspace_id uuid,\n    p_rule_set_id uuid,\n    p_policy_decision_id uuid,\n    p_authorization_hash text,\n    p_retention_binding_hash text,\n    p_idempotency_key_hash text,\n    p_expected_version integer,\n    p_audit_policy_id uuid,\n    p_audit_policy_number integer,\n    p_audit_policy_hash text,\n    p_audit_retain_until timestamptz,\n    p_audit_hold_generation bigint,\n    p_audit_hold_hash text\n)\nRETURNS uuid\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, quality, retention, iam\nAS $$\nDECLARE\n    actor_id uuid := NULLIF(current_setting('app.subject_id', true), '')::uuid;\n    parent quality.rule_sets%ROWTYPE;\n    asset record;\n    resolved_audit record;\n    decision_evidence record;\n    existing_command quality.rule_command_events%ROWTYPE;\n    calculated_target_hash text;\n    calculated_schedule_hash text;\n    calculated_retention_hash text;\n    calculated_request_hash text;\n    command_id uuid := gen_random_uuid();\n    next_sequence bigint;\n    is_security_admin boolean;\nBEGIN\n    IF p_workspace_id IS DISTINCT FROM\n       NULLIF(current_setting('app.workspace_id', true), '')::uuid THEN\n        RAISE EXCEPTION 'invalid Quality archive command'\n            USING ERRCODE = '42501';\n    END IF;\n    SELECT * INTO parent\n    FROM quality.rule_sets\n    WHERE workspace_id = p_workspace_id AND id = p_rule_set_id\n    FOR UPDATE;\n    IF parent.id IS NULL THEN\n        RAISE EXCEPTION 'invalid Quality archive command'\n            USING ERRCODE = '42501';\n    END IF;\n    calculated_request_hash := encode(sha256(convert_to(jsonb_build_object(\n        'contract', 'QUALITY_ARCHIVE_REQUEST_V1',\n        'workspace_id', p_workspace_id::text,\n        'rule_set_id', p_rule_set_id::text,\n        'actor_id', actor_id::text,\n        'policy_decision_id', p_policy_decision_id::text,\n        'authorization_hash', p_authorization_hash,\n        'retention_binding_hash', p_retention_binding_hash,\n        'expected_version', p_expected_version,\n        'audit_policy_id', p_audit_policy_id::text,\n        'audit_policy_number', p_audit_policy_number,\n        'audit_policy_hash', p_audit_policy_hash,\n        'audit_retain_until', p_audit_retain_until,\n        'audit_hold_generation', p_audit_hold_generation,\n        'audit_hold_hash', p_audit_hold_hash\n    )::text, 'UTF8')), 'hex');\n    SELECT * INTO existing_command\n    FROM quality.rule_command_events\n    WHERE workspace_id = p_workspace_id\n      AND rule_set_id = p_rule_set_id\n      AND idempotency_key_hash = p_idempotency_key_hash;\n    IF FOUND THEN\n        IF existing_command.command = 'ARCHIVE'\n           AND existing_command.rule_set_version_id IS NULL\n           AND existing_command.request_hash = calculated_request_hash THEN\n            RETURN existing_command.id;\n        END IF;\n        RAISE EXCEPTION 'Quality archive idempotency conflict'\n            USING ERRCODE = '23505';\n    END IF;\n    SELECT classification, system_id, domain_id INTO asset\n    FROM catalog.assets_projection\n    WHERE workspace_id = p_workspace_id AND id = parent.asset_id;\n    IF asset.classification IS NULL THEN\n        RAISE EXCEPTION 'invalid Quality archive target'\n            USING ERRCODE = '42501';\n    END IF;\n    SELECT COALESCE(membership.attributes -> 'groups', '[]'::jsonb)\n           ? 'security-administrators'\n    INTO is_security_admin\n    FROM iam.workspace_memberships AS membership\n    WHERE membership.workspace_id = p_workspace_id\n      AND membership.subject_id = actor_id;\n    IF parent.state <> 'ACTIVE'\n       OR parent.version <> p_expected_version\n       OR (actor_id <> parent.created_by AND NOT COALESCE(is_security_admin, false))\n       OR EXISTS (\n           SELECT 1 FROM quality.rule_set_versions AS version\n           WHERE version.workspace_id = p_workspace_id\n             AND version.rule_set_id = p_rule_set_id\n             AND version.state = 'ACTIVE'\n       )\n       OR NOT quality.current_human_can(\n           p_workspace_id, 'quality.rule.archive',\n           asset.classification, asset.system_id, asset.domain_id\n       ) THEN\n        RAISE EXCEPTION 'invalid Quality archive command'\n            USING ERRCODE = '42501';\n    END IF;\n    SELECT * INTO decision_evidence\n    FROM quality.require_human_decision_v1(\n        p_workspace_id, actor_id, p_rule_set_id, 'quality.rule.archive',\n        p_policy_decision_id, false\n    );\n    IF p_authorization_hash IS DISTINCT FROM decision_evidence.authorization_hash THEN\n        RAISE EXCEPTION 'Quality archive authorization evidence drift'\n            USING ERRCODE = '23514';\n    END IF;\n    SELECT * INTO resolved_audit\n    FROM retention.resolve_quality_binding_v1(\n        p_workspace_id, 'QUALITY_AUDIT', 'QUALITY_RULE_SET',\n        p_rule_set_id, transaction_timestamp()\n    );\n    IF ROW(\n        p_audit_policy_id, p_audit_policy_number, p_audit_policy_hash,\n        p_audit_retain_until, p_audit_hold_generation, p_audit_hold_hash\n    ) IS DISTINCT FROM ROW(\n        resolved_audit.policy_id, resolved_audit.policy_number,\n        resolved_audit.policy_hash, resolved_audit.retain_until,\n        resolved_audit.hold_generation, resolved_audit.hold_hash\n    ) THEN\n        RAISE EXCEPTION 'Quality archive audit binding drift'\n            USING ERRCODE = '23514';\n    END IF;\n    calculated_target_hash := encode(sha256(convert_to(jsonb_build_object(\n        'contract', 'QUALITY_ARCHIVE_TARGET_V1',\n        'asset_id', parent.asset_id::text,\n        'classification', asset.classification,\n        'system_id', asset.system_id::text,\n        'domain_id', asset.domain_id::text\n    )::text, 'UTF8')), 'hex');\n    calculated_schedule_hash := encode(sha256(convert_to(jsonb_build_object(\n        'contract', 'QUALITY_ARCHIVE_SCHEDULE_V1',\n        'state', 'INACTIVE'\n    )::text, 'UTF8')), 'hex');\n    calculated_retention_hash := encode(sha256(convert_to(jsonb_build_object(\n        'contract', 'QUALITY_COMMAND_RETENTION_BINDING_V1',\n        'rule_policy_id', parent.rule_retention_policy_id::text,\n        'rule_policy_number', parent.rule_retention_policy_number,\n        'rule_policy_hash', parent.rule_retention_policy_hash,\n        'rule_retain_until', parent.rule_retain_until,\n        'rule_hold_generation', parent.rule_hold_generation,\n        'rule_hold_hash', parent.rule_hold_hash,\n        'audit_policy_id', resolved_audit.policy_id::text,\n        'audit_policy_number', resolved_audit.policy_number,\n        'audit_policy_hash', resolved_audit.policy_hash,\n        'audit_retain_until', resolved_audit.retain_until,\n        'audit_hold_generation', resolved_audit.hold_generation,\n        'audit_hold_hash', resolved_audit.hold_hash\n    )::text, 'UTF8')), 'hex');\n    IF p_retention_binding_hash IS DISTINCT FROM calculated_retention_hash THEN\n        RAISE EXCEPTION 'Quality archive retention evidence drift'\n            USING ERRCODE = '23514';\n    END IF;\n    UPDATE quality.rule_sets\n    SET state = 'ARCHIVED',\n        archived_at = transaction_timestamp(),\n        updated_by = actor_id,\n        version = version + 1,\n        updated_at = transaction_timestamp()\n    WHERE workspace_id = p_workspace_id AND id = p_rule_set_id;\n    SELECT COALESCE(max(sequence), 0) + 1 INTO next_sequence\n    FROM quality.rule_command_events\n    WHERE workspace_id = p_workspace_id AND rule_set_id = p_rule_set_id;\n    INSERT INTO quality.rule_command_events (\n        id, workspace_id, rule_set_id, rule_set_version_id, sequence,\n        command, actor_id, actor_kind, webauthn_evidence_hash,\n        authentication_time, authorization_hash, target_binding_hash,\n        schedule_binding_hash, retention_binding_hash, request_hash,\n        idempotency_key_hash,\n        audit_retention_kind, audit_retention_policy_id,\n        audit_retention_policy_number, audit_retention_policy_hash,\n        audit_retention_basis_at, audit_retain_until,\n        audit_hold_generation, audit_hold_hash, occurred_at\n    )\n    VALUES (\n        command_id, p_workspace_id, p_rule_set_id, NULL, next_sequence,\n        'ARCHIVE', actor_id, 'HUMAN', NULL, NULL,\n        decision_evidence.authorization_hash, calculated_target_hash,\n        calculated_schedule_hash, calculated_retention_hash,\n        calculated_request_hash, p_idempotency_key_hash,\n        'QUALITY_AUDIT', p_audit_policy_id, p_audit_policy_number,\n        p_audit_policy_hash, transaction_timestamp(), p_audit_retain_until,\n        p_audit_hold_generation, p_audit_hold_hash, transaction_timestamp()\n    );\n    RETURN command_id;\nEND\n$$;")
        op.execute('REVOKE ALL ON FUNCTION quality.archive_rule_set_v1(\n    uuid, uuid, uuid, text, text, text, integer,\n    uuid, integer, text, timestamptz, bigint, text\n) FROM PUBLIC;')
        op.execute('CREATE TRIGGER reject_evidence_mutation BEFORE UPDATE OR DELETE ON quality.rule_definitions FOR EACH ROW EXECUTE FUNCTION quality.reject_evidence_mutation()')
        op.execute('CREATE TRIGGER reject_evidence_mutation BEFORE UPDATE OR DELETE ON quality.rule_reviews FOR EACH ROW EXECUTE FUNCTION quality.reject_evidence_mutation()')
        op.execute('CREATE TRIGGER reject_evidence_mutation BEFORE UPDATE OR DELETE ON quality.rule_command_events FOR EACH ROW EXECUTE FUNCTION quality.reject_evidence_mutation()')
        op.execute('CREATE TRIGGER reject_evidence_mutation BEFORE UPDATE OR DELETE ON quality.expectation_results FOR EACH ROW EXECUTE FUNCTION quality.reject_evidence_mutation()')
        op.execute('CREATE TRIGGER reject_evidence_mutation BEFORE UPDATE OR DELETE ON quality.run_events FOR EACH ROW EXECUTE FUNCTION quality.reject_evidence_mutation()')
        op.execute('CREATE TRIGGER reject_evidence_mutation BEFORE UPDATE OR DELETE ON quality.dispatch_call_receipts FOR EACH ROW EXECUTE FUNCTION quality.reject_evidence_mutation()')
        op.execute('CREATE TRIGGER reject_evidence_mutation BEFORE UPDATE OR DELETE ON quality.dispatch_run_links FOR EACH ROW EXECUTE FUNCTION quality.reject_evidence_mutation()')
        op.execute('CREATE TRIGGER reject_evidence_mutation BEFORE UPDATE OR DELETE ON quality.execution_call_receipts FOR EACH ROW EXECUTE FUNCTION quality.reject_evidence_mutation()')
        op.execute('CREATE POLICY quality_rule_sets_read ON quality.rule_sets\nAS RESTRICTIVE FOR SELECT TO datariver_app\nUSING (quality.can_read_asset(workspace_id, asset_id, NULL, NULL, NULL));')
        op.execute("CREATE POLICY quality_rule_sets_insert ON quality.rule_sets\nAS RESTRICTIVE FOR INSERT TO datariver_app\nWITH CHECK (\n    created_by = NULLIF(current_setting('app.subject_id', true), '')::uuid\n    AND updated_by = created_by\n    AND EXISTS (\n        SELECT 1 FROM catalog.assets_projection AS asset\n        WHERE asset.workspace_id = rule_sets.workspace_id\n          AND asset.id = rule_sets.asset_id\n          AND asset.deleted_at IS NULL\n          AND asset.lifecycle = 'ACTIVE'\n          AND quality.current_human_can(\n              asset.workspace_id, 'quality.rule.propose',\n              asset.classification, asset.system_id, asset.domain_id\n          )\n    )\n);")
        op.execute('CREATE POLICY quality_rule_versions_read ON quality.rule_set_versions\nAS RESTRICTIVE FOR SELECT TO datariver_app\nUSING (\n    quality.can_read_asset(\n        workspace_id, asset_id, classification, system_id, domain_id\n    )\n);')
        op.execute("CREATE POLICY quality_rule_versions_insert ON quality.rule_set_versions\nAS RESTRICTIVE FOR INSERT TO datariver_app\nWITH CHECK (\n    author_id = NULLIF(current_setting('app.subject_id', true), '')::uuid\n    AND state = 'PROPOSED'\n    AND EXISTS (\n        SELECT 1 FROM catalog.assets_projection AS asset\n        WHERE asset.workspace_id = rule_set_versions.workspace_id\n          AND asset.id = rule_set_versions.asset_id\n          AND asset.id = (\n              SELECT rule_set.asset_id\n              FROM quality.rule_sets AS rule_set\n              WHERE rule_set.workspace_id = rule_set_versions.workspace_id\n                AND rule_set.id = rule_set_versions.rule_set_id\n                AND rule_set.state = 'ACTIVE'\n          )\n          AND asset.deleted_at IS NULL\n          AND asset.lifecycle = rule_set_versions.lifecycle\n          AND asset.source_version = rule_set_versions.source_version\n          AND asset.classification = rule_set_versions.classification\n          AND asset.system_id IS NOT DISTINCT FROM rule_set_versions.system_id\n          AND asset.domain_id IS NOT DISTINCT FROM rule_set_versions.domain_id\n          AND quality.current_human_can(\n              asset.workspace_id, 'quality.rule.propose',\n              asset.classification, asset.system_id, asset.domain_id\n          )\n    )\n);")
        op.execute('CREATE POLICY quality_runs_read ON quality.validation_runs\nAS RESTRICTIVE FOR SELECT TO datariver_app\nUSING (\n    EXISTS (\n        SELECT 1\n        FROM quality.rule_set_versions AS version\n        WHERE version.workspace_id = validation_runs.workspace_id\n          AND version.id = validation_runs.rule_set_version_id\n          AND quality.can_read_asset(\n              version.workspace_id,\n              version.asset_id,\n              version.classification,\n              version.system_id,\n              version.domain_id\n          )\n    )\n);')
        op.execute('CREATE POLICY quality_rule_definitions_read ON quality.rule_definitions\nAS RESTRICTIVE FOR SELECT TO datariver_app\nUSING (\n    EXISTS (\n        SELECT 1 FROM quality.rule_set_versions AS version\n        WHERE version.workspace_id = rule_definitions.workspace_id\n          AND version.id = rule_definitions.rule_set_version_id\n          AND quality.can_read_asset(\n              version.workspace_id, version.asset_id, version.classification,\n              version.system_id, version.domain_id\n          )\n    )\n);')
        op.execute("CREATE POLICY quality_rule_definitions_insert ON quality.rule_definitions\nAS RESTRICTIVE FOR INSERT TO datariver_app\nWITH CHECK (\n    EXISTS (\n        SELECT 1 FROM quality.rule_set_versions AS version\n        WHERE version.workspace_id = rule_definitions.workspace_id\n          AND version.id = rule_definitions.rule_set_version_id\n          AND version.state = 'PROPOSED'\n          AND version.author_id =\n              NULLIF(current_setting('app.subject_id', true), '')::uuid\n          AND quality.current_human_can(\n              version.workspace_id, 'quality.rule.propose',\n              version.classification, version.system_id, version.domain_id\n          )\n    )\n);")
        op.execute('CREATE POLICY quality_rule_reviews_read ON quality.rule_reviews\nAS RESTRICTIVE FOR SELECT TO datariver_app\nUSING (\n    EXISTS (\n        SELECT 1 FROM quality.rule_set_versions AS version\n        WHERE version.workspace_id = rule_reviews.workspace_id\n          AND version.id = rule_reviews.rule_set_version_id\n          AND quality.can_read_asset(\n              version.workspace_id, version.asset_id, version.classification,\n              version.system_id, version.domain_id\n          )\n    )\n);')
        op.execute('CREATE POLICY quality_rule_commands_read ON quality.rule_command_events\nAS RESTRICTIVE FOR SELECT TO datariver_app\nUSING (\n    EXISTS (\n        SELECT 1 FROM quality.rule_sets AS rule_set\n        WHERE rule_set.workspace_id = rule_command_events.workspace_id\n          AND rule_set.id = rule_command_events.rule_set_id\n          AND quality.can_read_asset(\n              rule_set.workspace_id, rule_set.asset_id, NULL, NULL, NULL\n          )\n    )\n);')
        op.execute('CREATE POLICY quality_rule_schedules_read ON quality.rule_schedules\nAS RESTRICTIVE FOR SELECT TO datariver_app\nUSING (\n    EXISTS (\n        SELECT 1 FROM quality.rule_set_versions AS version\n        WHERE version.workspace_id = rule_schedules.workspace_id\n          AND version.id = rule_schedules.rule_set_version_id\n          AND quality.can_read_asset(\n              version.workspace_id, version.asset_id, version.classification,\n              version.system_id, version.domain_id\n          )\n    )\n);')
        op.execute('CREATE POLICY quality_attempts_read ON quality.validation_attempts\nAS RESTRICTIVE FOR SELECT TO datariver_app\nUSING (\n    EXISTS (\n        SELECT 1 FROM quality.validation_runs AS run\n        WHERE run.workspace_id = validation_attempts.workspace_id\n          AND run.id = validation_attempts.run_id\n    )\n);')
        op.execute('CREATE POLICY quality_results_read ON quality.expectation_results\nAS RESTRICTIVE FOR SELECT TO datariver_app\nUSING (\n    EXISTS (\n        SELECT 1 FROM quality.validation_runs AS run\n        WHERE run.workspace_id = expectation_results.workspace_id\n          AND run.id = expectation_results.run_id\n    )\n);')
        op.execute('CREATE POLICY quality_run_events_read ON quality.run_events\nAS RESTRICTIVE FOR SELECT TO datariver_app\nUSING (\n    EXISTS (\n        SELECT 1 FROM quality.validation_runs AS run\n        WHERE run.workspace_id = run_events.workspace_id\n          AND run.id = run_events.run_id\n    )\n);')
        op.execute("CREATE POLICY quality_dispatch_receipts_read ON quality.dispatch_call_receipts\nAS RESTRICTIVE FOR SELECT TO datariver_app\nUSING (\n    quality.current_human_can(\n        workspace_id, 'quality.operations.read', 0, NULL, NULL\n    )\n);")
        op.execute('CREATE POLICY quality_dispatch_links_read ON quality.dispatch_run_links\nAS RESTRICTIVE FOR SELECT TO datariver_app\nUSING (\n    EXISTS (\n        SELECT 1 FROM quality.validation_runs AS run\n        WHERE run.workspace_id = dispatch_run_links.workspace_id\n          AND run.id = dispatch_run_links.run_id\n    )\n);')
        op.execute("CREATE POLICY quality_execution_receipts_read ON quality.execution_call_receipts\nAS RESTRICTIVE FOR SELECT TO datariver_app\nUSING (\n    quality.current_human_can(\n        workspace_id, 'quality.operations.read', 0, NULL, NULL\n    )\n    AND EXISTS (\n        SELECT 1 FROM quality.validation_runs AS run\n        WHERE run.workspace_id = execution_call_receipts.workspace_id\n          AND run.id = execution_call_receipts.run_id\n    )\n);")
        op.execute("DO $$\nBEGIN\n    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'datariver_app') THEN\n        GRANT USAGE ON SCHEMA quality TO datariver_app;\n        GRANT SELECT ON quality.dispatch_call_receipts, quality.rule_sets, quality.rule_set_versions, quality.rule_command_events, quality.rule_definitions, quality.rule_reviews, quality.rule_schedules, quality.validation_runs, quality.dispatch_run_links, quality.expectation_results, quality.run_events, quality.validation_attempts, quality.execution_call_receipts TO datariver_app;\n        GRANT INSERT ON quality.rule_sets, quality.rule_set_versions, quality.rule_definitions TO datariver_app;\n        GRANT SELECT ON retention.legal_hold_generations TO datariver_app;\n        GRANT EXECUTE ON FUNCTION quality.current_human_can(\n            uuid, text, integer, uuid, uuid\n        ) TO datariver_app;\n        GRANT EXECUTE ON FUNCTION quality.can_read_asset(\n            uuid, uuid, integer, uuid, uuid\n        ) TO datariver_app;\n        GRANT EXECUTE ON FUNCTION retention.resolve_quality_binding_v1(\n            uuid, text, text, uuid, timestamptz\n        ) TO datariver_app;\n        GRANT EXECUTE ON FUNCTION quality.review_rule_set_version_v1(\n            uuid, uuid, text, text, uuid, text, integer,\n            uuid, integer, text, timestamptz, bigint, text\n        ) TO datariver_app;\n        GRANT EXECUTE ON FUNCTION quality.activate_rule_set_version_v1(\n            uuid, uuid, uuid, text, text, text, text, text, integer,\n            uuid, integer, text, timestamptz, bigint, text\n        ) TO datariver_app;\n        GRANT EXECUTE ON FUNCTION quality.revoke_rule_set_version_v1(\n            uuid, uuid, uuid, text, text, text, text, integer,\n            uuid, integer, text, timestamptz, bigint, text\n        ) TO datariver_app;\n        GRANT EXECUTE ON FUNCTION quality.archive_rule_set_v1(\n            uuid, uuid, uuid, text, text, text, integer,\n            uuid, integer, text, timestamptz, bigint, text\n        ) TO datariver_app;\n    END IF;\nEND\n$$;")
        op.execute("DO $$\nBEGIN\n    IF NOT EXISTS (\n        SELECT 1 FROM pg_roles\n        WHERE rolname = 'datariver_catalog_profile'\n          AND rolcanlogin IS TRUE\n          AND rolsuper IS FALSE\n          AND rolcreatedb IS FALSE\n          AND rolcreaterole IS FALSE\n          AND rolreplication IS FALSE\n          AND rolbypassrls IS FALSE\n    ) THEN\n        RAISE EXCEPTION\n            'datariver_catalog_profile must be a safe NOBYPASSRLS login role';\n    END IF;\n    IF EXISTS (\n        SELECT 1\n        FROM pg_auth_members AS membership\n        JOIN pg_roles AS member_role ON member_role.oid = membership.member\n        JOIN pg_roles AS granted_role ON granted_role.oid = membership.roleid\n        WHERE member_role.rolname = 'datariver_catalog_profile'\n           OR (\n               granted_role.rolname = 'datariver_catalog_profile'\n               AND member_role.rolname NOT IN (\n                   current_user, session_user, 'datariver_migrator'\n               )\n           )\n    ) THEN\n        RAISE EXCEPTION 'datariver_catalog_profile role membership is unsafe';\n    END IF;\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION retention.resolve_quality_binding_v1(\n    p_workspace_id uuid,\n    p_data_class text,\n    p_resource_type text,\n    p_resource_id uuid,\n    p_basis_at timestamptz\n)\nRETURNS TABLE (\n    policy_id uuid,\n    policy_number integer,\n    policy_hash text,\n    retain_until timestamptz,\n    hold_generation bigint,\n    hold_hash text\n)\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, retention\nAS $$\nDECLARE\n    selected_policy retention.policy_versions%ROWTYPE;\n    selected_rule retention.policy_class_rules%ROWTYPE;\n    selected_generation retention.legal_hold_generations%ROWTYPE;\n    expected_class_count integer;\nBEGIN\n    IF p_resource_id IS NULL\n       OR p_basis_at IS DISTINCT FROM transaction_timestamp()\n       OR NOT (\n           (\n               p_data_class IN ('QUALITY_RULE', 'QUALITY_AUDIT')\n               AND p_resource_type = 'QUALITY_RULE_SET'\n           )\n           OR (\n               p_data_class IN ('QUALITY_RESULT', 'QUALITY_AUDIT')\n               AND p_resource_type = 'QUALITY_VALIDATION_RUN'\n           )\n           OR (\n               p_data_class = 'QUALITY_PROFILE'\n               AND p_resource_type = 'PROFILE_SNAPSHOT'\n           )\n       ) THEN\n        RAISE EXCEPTION 'invalid Quality retention binding request'\n            USING ERRCODE = '23514';\n    END IF;\n\n    SELECT policy.* INTO selected_policy\n    FROM retention.policy_versions AS policy\n    WHERE policy.workspace_id = p_workspace_id\n      AND policy.state = 'ACTIVE'\n      AND (\n          (\n              p_data_class = 'QUALITY_PROFILE'\n              AND policy.contract_version = 'POLICY_BOOK_V4'\n          )\n          OR (\n              p_data_class <> 'QUALITY_PROFILE'\n              AND policy.contract_version IN ('POLICY_BOOK_V3', 'POLICY_BOOK_V4')\n          )\n      )\n      AND policy.effective_from <= p_basis_at\n      AND (policy.effective_until IS NULL OR policy.effective_until > p_basis_at)\n    FOR KEY SHARE;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'Quality retention requires an effective policy book'\n            USING ERRCODE = '23514';\n    END IF;\n\n    expected_class_count := CASE selected_policy.contract_version\n        WHEN 'POLICY_BOOK_V3' THEN 7\n        WHEN 'POLICY_BOOK_V4' THEN 8\n        ELSE 0\n    END;\n    IF (\n        SELECT count(*) <> expected_class_count\n            OR bool_or(class_rule.data_class NOT IN (\n                'COMPLETED_OPERATIONS', 'CHAT_CONTENT', 'AUDIT_EVIDENCE', 'OBJECT_DATA',\n                'QUALITY_RULE', 'QUALITY_RESULT', 'QUALITY_AUDIT', 'QUALITY_PROFILE'\n            ))\n            OR (\n                selected_policy.contract_version = 'POLICY_BOOK_V3'\n                AND bool_or(class_rule.data_class = 'QUALITY_PROFILE')\n            )\n            OR (\n                selected_policy.contract_version = 'POLICY_BOOK_V4'\n                AND count(*) FILTER (\n                    WHERE class_rule.data_class = 'QUALITY_PROFILE'\n                ) <> 1\n            )\n        FROM retention.policy_class_rules AS class_rule\n        WHERE class_rule.workspace_id = p_workspace_id\n          AND class_rule.policy_id = selected_policy.id\n          AND class_rule.policy_hash = selected_policy.payload_hash\n          AND class_rule.policy_number = selected_policy.policy_number\n    ) THEN\n        RAISE EXCEPTION 'Quality retention policy class set is incomplete'\n            USING ERRCODE = '23514';\n    END IF;\n\n    SELECT class_rule.* INTO selected_rule\n    FROM retention.policy_class_rules AS class_rule\n    WHERE class_rule.workspace_id = p_workspace_id\n      AND class_rule.policy_id = selected_policy.id\n      AND class_rule.policy_hash = selected_policy.payload_hash\n      AND class_rule.policy_number = selected_policy.policy_number\n      AND class_rule.data_class = p_data_class\n    FOR KEY SHARE;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'Quality retention class rule is unavailable'\n            USING ERRCODE = '23514';\n    END IF;\n\n    SELECT generation.* INTO selected_generation\n    FROM retention.legal_hold_generations AS generation\n    WHERE generation.workspace_id = p_workspace_id\n      AND generation.data_class = p_data_class\n    FOR UPDATE;\n    IF NOT FOUND THEN\n        INSERT INTO retention.legal_hold_generations (\n            id, workspace_id, data_class, generation, resolution_hash,\n            version, created_at, updated_at\n        )\n        VALUES (\n            gen_random_uuid(), p_workspace_id, p_data_class, 1,\n            encode(sha256(convert_to('', 'UTF8')), 'hex'),\n            1, transaction_timestamp(), transaction_timestamp()\n        )\n        ON CONFLICT (workspace_id, data_class) DO NOTHING;\n        SELECT generation.* INTO selected_generation\n        FROM retention.legal_hold_generations AS generation\n        WHERE generation.workspace_id = p_workspace_id\n          AND generation.data_class = p_data_class\n        FOR UPDATE;\n    END IF;\n\n    IF EXISTS (\n        SELECT 1\n        FROM retention.legal_holds AS hold\n        WHERE hold.workspace_id = p_workspace_id\n          AND hold.data_class = p_data_class\n          AND hold.state <> 'RELEASED'\n          AND hold.scope = 'RESOURCE'\n          AND hold.scope_id = p_resource_id\n          AND hold.resource_type IS DISTINCT FROM p_resource_type\n          AND hold.resource_type <> 'LEGACY_UNTYPED'\n    ) THEN\n        RAISE EXCEPTION 'ambiguous typed Quality Legal Hold resolution'\n            USING ERRCODE = '23514';\n    END IF;\n\n    policy_id := selected_policy.id;\n    policy_number := selected_policy.policy_number;\n    policy_hash := selected_policy.payload_hash;\n    retain_until := CASE selected_rule.unit\n        WHEN 'DAYS' THEN p_basis_at + make_interval(days => selected_rule.minimum_value)\n        WHEN 'MONTHS' THEN p_basis_at + make_interval(months => selected_rule.minimum_value)\n        WHEN 'YEARS' THEN p_basis_at + make_interval(years => selected_rule.minimum_value)\n        ELSE NULL\n    END;\n    hold_generation := selected_generation.generation;\n    hold_hash := selected_generation.resolution_hash;\n    IF retain_until IS NULL OR retain_until <= p_basis_at THEN\n        RAISE EXCEPTION 'invalid Quality retention deadline'\n            USING ERRCODE = '23514';\n    END IF;\n    RETURN NEXT;\nEND\n$$;")
        op.execute('REVOKE ALL ON FUNCTION retention.resolve_quality_binding_v1(\n    uuid, text, text, uuid, timestamptz\n) FROM PUBLIC;')
        op.execute('CREATE OR REPLACE FUNCTION catalog.current_profile_collector_can_v1(\n    p_workspace_id uuid,\n    p_classification integer,\n    p_system_id uuid,\n    p_domain_id uuid\n)\nRETURNS boolean\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = pg_catalog, platform, iam\nAS $$\n    SELECT session_user = \'datariver_catalog_profile\'\n       AND p_workspace_id IS NOT DISTINCT FROM\n           NULLIF(current_setting(\'app.workspace_id\', true), \'\')::uuid\n       AND EXISTS (\n           SELECT 1\n           FROM platform.workspaces AS workspace\n           JOIN iam.workspace_memberships AS membership\n             ON membership.workspace_id = workspace.id\n           JOIN iam.subjects AS subject\n             ON subject.id = membership.subject_id\n           WHERE workspace.id = p_workspace_id\n             AND workspace.status = \'ACTIVE\'\n             AND membership.subject_id =\n                 NULLIF(current_setting(\'app.subject_id\', true), \'\')::uuid\n             AND subject.active IS TRUE\n             AND membership.active IS TRUE\n             AND (\n                 membership.access_expires_at IS NULL\n                 OR membership.access_expires_at > transaction_timestamp()\n             )\n             AND membership.job_function = \'SERVICE_ACCOUNT\'\n             AND jsonb_typeof(\n                 COALESCE(membership.attributes -> \'groups\', \'[]\'::jsonb)\n             ) = \'array\'\n             AND jsonb_array_length(\n                 COALESCE(membership.attributes -> \'groups\', \'[]\'::jsonb)\n             ) = 2\n             AND COALESCE(membership.attributes -> \'groups\', \'[]\'::jsonb)\n                 @> \'["service-accounts","catalog-profile-collectors"]\'::jsonb\n             AND COALESCE(\n                 membership.attributes -> \'allowed_actions\', \'[]\'::jsonb\n             ) = \'["catalog.profile.collect"]\'::jsonb\n             AND NOT (\n                 COALESCE(\n                     membership.attributes -> \'denied_actions\', \'[]\'::jsonb\n                 ) ? \'catalog.profile.collect\'\n             )\n             AND membership.clearance >= p_classification\n             AND (\n                 p_classification = 0\n                 OR p_system_id IS NULL\n                 OR COALESCE(\n                     membership.attributes -> \'allowed_system_ids\', \'[]\'::jsonb\n                 ) ? p_system_id::text\n             )\n             AND (\n                 p_classification = 0\n                 OR p_domain_id IS NULL\n                 OR COALESCE(\n                     membership.attributes -> \'allowed_domain_ids\', \'[]\'::jsonb\n                 ) ? p_domain_id::text\n             )\n       )\n$$;')
        op.execute('REVOKE ALL ON FUNCTION catalog.current_profile_collector_can_v1(\n    uuid, integer, uuid, uuid\n) FROM PUBLIC;')
        op.execute("CREATE OR REPLACE FUNCTION catalog.read_profile_target_v1(\n    p_workspace_id uuid,\n    p_asset_id uuid\n)\nRETURNS TABLE (\n    external_urn text,\n    source_version varchar,\n    classification integer,\n    system_id uuid,\n    domain_id uuid\n)\nLANGUAGE plpgsql\nSTABLE\nSECURITY DEFINER\nSET search_path = pg_catalog, catalog\nAS $$\nDECLARE\n    selected_asset catalog.assets_projection%ROWTYPE;\nBEGIN\n    IF p_workspace_id IS DISTINCT FROM\n       NULLIF(current_setting('app.workspace_id', true), '')::uuid THEN\n        RAISE EXCEPTION 'Profile target security context mismatch'\n            USING ERRCODE = '42501';\n    END IF;\n    SELECT asset.* INTO selected_asset\n    FROM catalog.assets_projection AS asset\n    WHERE asset.workspace_id = p_workspace_id\n      AND asset.id = p_asset_id\n      AND asset.deleted_at IS NULL\n      AND asset.lifecycle = 'ACTIVE';\n    IF NOT FOUND OR NOT catalog.current_profile_collector_can_v1(\n        selected_asset.workspace_id,\n        selected_asset.classification,\n        selected_asset.system_id,\n        selected_asset.domain_id\n    ) THEN\n        RAISE EXCEPTION 'Profile target is unavailable'\n            USING ERRCODE = '42501';\n    END IF;\n    external_urn := selected_asset.external_urn;\n    source_version := selected_asset.source_version;\n    classification := selected_asset.classification;\n    system_id := selected_asset.system_id;\n    domain_id := selected_asset.domain_id;\n    RETURN NEXT;\nEND\n$$;")
        op.execute('REVOKE ALL ON FUNCTION catalog.read_profile_target_v1(uuid, uuid) FROM PUBLIC;')
        op.execute('CREATE OR REPLACE FUNCTION catalog.project_asset_profile_v1(\n    p_workspace_id uuid,\n    p_asset_id uuid,\n    p_payload jsonb\n)\nRETURNS TABLE (\n    snapshot_id uuid,\n    snapshot_identity_hash text,\n    created boolean,\n    last_observed_at timestamptz\n)\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, catalog, retention\nAS $$\nDECLARE\n    selected_asset catalog.assets_projection%ROWTYPE;\n    resolved record;\n    current_field jsonb;\n    target_scope_hash text;\n    calculated_identity_hash text;\n    inserted_snapshot_id uuid;\n    existing_snapshot catalog.asset_profile_snapshots%ROWTYPE;\n    basis_at timestamptz := transaction_timestamp();\n    observed_at timestamptz;\n    profiled_at timestamptz;\n    stale_at timestamptz;\n    profile_kind text;\n    profile_completeness text;\nBEGIN\n    IF p_workspace_id IS DISTINCT FROM\n       NULLIF(current_setting(\'app.workspace_id\', true), \'\')::uuid\n       OR jsonb_typeof(p_payload) <> \'object\'\n       OR ARRAY(\n           SELECT key\n           FROM jsonb_object_keys(p_payload) AS key\n           ORDER BY key COLLATE "C"\n       ) IS DISTINCT FROM ARRAY[\n           \'asset_source_version\', \'classification\', \'column_count\', \'columns\',\n           \'completeness\', \'domain_id\', \'normalized_payload_hash\', \'observed_at\',\n           \'profile_kind\', \'profiled_at\', \'provenance_fingerprint\',\n           \'provenance_key_id\', \'provider_config_hash\', \'provider_contract_hash\',\n           \'provider_query_hash\', \'provider_version\', \'row_count\', \'size_bytes\',\n           \'source_watermark_hash\', \'stale_at\', \'system_id\'\n       ]::text[] THEN\n        RAISE EXCEPTION \'invalid Profile projection payload\'\n            USING ERRCODE = \'23514\';\n    END IF;\n\n    SELECT asset.* INTO selected_asset\n    FROM catalog.assets_projection AS asset\n    WHERE asset.workspace_id = p_workspace_id\n      AND asset.id = p_asset_id\n      AND asset.deleted_at IS NULL\n      AND asset.lifecycle = \'ACTIVE\'\n    FOR KEY SHARE;\n    IF NOT FOUND OR NOT catalog.current_profile_collector_can_v1(\n        selected_asset.workspace_id,\n        selected_asset.classification,\n        selected_asset.system_id,\n        selected_asset.domain_id\n    ) THEN\n        RAISE EXCEPTION \'Profile target is unavailable\'\n            USING ERRCODE = \'42501\';\n    END IF;\n\n    IF p_payload ->> \'asset_source_version\' IS DISTINCT FROM selected_asset.source_version\n       OR (p_payload ->> \'classification\')::integer\n            IS DISTINCT FROM selected_asset.classification\n       OR NULLIF(p_payload ->> \'system_id\', \'\')::uuid\n            IS DISTINCT FROM selected_asset.system_id\n       OR NULLIF(p_payload ->> \'domain_id\', \'\')::uuid\n            IS DISTINCT FROM selected_asset.domain_id\n       OR jsonb_typeof(p_payload -> \'columns\') <> \'array\'\n       OR jsonb_array_length(p_payload -> \'columns\') > 1000\n       OR (p_payload ->> \'provider_version\') IS NULL\n       OR char_length(p_payload ->> \'provider_version\') NOT BETWEEN 1 AND 64\n       OR (p_payload ->> \'asset_source_version\') IS NULL\n       OR char_length(p_payload ->> \'asset_source_version\') NOT BETWEEN 1 AND 255 THEN\n        RAISE EXCEPTION \'Profile target or collection contract drift\'\n            USING ERRCODE = \'23514\';\n    END IF;\n\n    profile_kind := p_payload ->> \'profile_kind\';\n    profile_completeness := p_payload ->> \'completeness\';\n    observed_at := (p_payload ->> \'observed_at\')::timestamptz;\n    profiled_at := (p_payload ->> \'profiled_at\')::timestamptz;\n    stale_at := (p_payload ->> \'stale_at\')::timestamptz;\n    IF profile_kind NOT IN (\'FULL\', \'SAMPLE\', \'PARTITION\', \'QUERY\', \'UNKNOWN\')\n       OR profile_completeness NOT IN (\'COMPLETE\', \'PARTIAL\')\n       OR observed_at IS NULL\n       OR profiled_at IS NULL\n       OR stale_at IS NULL\n       OR observed_at > basis_at + interval \'5 minutes\'\n       OR profiled_at > observed_at + interval \'5 minutes\'\n       OR stale_at <= profiled_at\n       OR jsonb_typeof(p_payload -> \'row_count\') NOT IN (\'number\', \'null\')\n       OR jsonb_typeof(p_payload -> \'column_count\') NOT IN (\'number\', \'null\')\n       OR jsonb_typeof(p_payload -> \'size_bytes\') NOT IN (\'number\', \'null\')\n       OR (\n           p_payload ->> \'row_count\' IS NOT NULL\n           AND (\n               (p_payload ->> \'row_count\')::numeric < 0\n               OR (p_payload ->> \'row_count\')::numeric > 9223372036854775807\n               OR trunc((p_payload ->> \'row_count\')::numeric)\n                    <> (p_payload ->> \'row_count\')::numeric\n           )\n       )\n       OR (\n           p_payload ->> \'column_count\' IS NOT NULL\n           AND (\n               (p_payload ->> \'column_count\')::numeric < 0\n               OR (p_payload ->> \'column_count\')::numeric > 9223372036854775807\n               OR trunc((p_payload ->> \'column_count\')::numeric)\n                    <> (p_payload ->> \'column_count\')::numeric\n           )\n       )\n       OR (\n           p_payload ->> \'size_bytes\' IS NOT NULL\n           AND (\n               (p_payload ->> \'size_bytes\')::numeric < 0\n               OR (p_payload ->> \'size_bytes\')::numeric > 9223372036854775807\n               OR trunc((p_payload ->> \'size_bytes\')::numeric)\n                    <> (p_payload ->> \'size_bytes\')::numeric\n           )\n       )\n       OR (\n           profile_kind IN (\'PARTITION\', \'QUERY\')\n           AND (\n               char_length(COALESCE(p_payload ->> \'provenance_key_id\', \'\'))\n                   NOT BETWEEN 1 AND 128\n               OR COALESCE(p_payload ->> \'provenance_fingerprint\', \'\')\n                   !~ \'^[0-9a-f]{64}$\'\n           )\n       )\n       OR (\n           profile_kind NOT IN (\'PARTITION\', \'QUERY\')\n           AND (\n               p_payload ->> \'provenance_key_id\' IS NOT NULL\n               OR p_payload ->> \'provenance_fingerprint\' IS NOT NULL\n           )\n       )\n       OR EXISTS (\n           SELECT 1\n           FROM unnest(ARRAY[\n               p_payload ->> \'normalized_payload_hash\',\n               p_payload ->> \'provider_config_hash\',\n               p_payload ->> \'provider_contract_hash\',\n               p_payload ->> \'provider_query_hash\',\n               p_payload ->> \'source_watermark_hash\'\n           ]) AS hash_value\n           WHERE hash_value IS NULL OR hash_value !~ \'^[0-9a-f]{64}$\'\n       ) THEN\n        RAISE EXCEPTION \'invalid Profile metric or provenance shape\'\n            USING ERRCODE = \'23514\';\n    END IF;\n\n    FOR current_field IN\n        SELECT value FROM jsonb_array_elements(p_payload -> \'columns\')\n    LOOP\n        IF jsonb_typeof(current_field) <> \'object\'\n           OR ARRAY(\n               SELECT key\n               FROM jsonb_object_keys(current_field) AS key\n               ORDER BY key COLLATE "C"\n           ) IS DISTINCT FROM ARRAY[\n               \'field_path\', \'null_count\', \'null_proportion\',\n               \'unique_count\', \'unique_proportion\'\n           ]::text[]\n           OR char_length(COALESCE(current_field ->> \'field_path\', \'\'))\n                NOT BETWEEN 1 AND 4096\n           OR current_field ->> \'field_path\'\n                IS DISTINCT FROM btrim(current_field ->> \'field_path\')\n           OR jsonb_typeof(current_field -> \'null_count\') NOT IN (\'number\', \'null\')\n           OR jsonb_typeof(current_field -> \'unique_count\') NOT IN (\'number\', \'null\')\n           OR jsonb_typeof(current_field -> \'null_proportion\') NOT IN (\'number\', \'null\')\n           OR jsonb_typeof(current_field -> \'unique_proportion\') NOT IN (\'number\', \'null\')\n           OR (\n               current_field ->> \'null_count\' IS NOT NULL\n               AND (\n                   (current_field ->> \'null_count\')::numeric < 0\n                   OR (current_field ->> \'null_count\')::numeric > 9223372036854775807\n                   OR trunc((current_field ->> \'null_count\')::numeric)\n                        <> (current_field ->> \'null_count\')::numeric\n               )\n           )\n           OR (\n               current_field ->> \'unique_count\' IS NOT NULL\n               AND (\n                   (current_field ->> \'unique_count\')::numeric < 0\n                   OR (current_field ->> \'unique_count\')::numeric > 9223372036854775807\n                   OR trunc((current_field ->> \'unique_count\')::numeric)\n                        <> (current_field ->> \'unique_count\')::numeric\n               )\n           )\n           OR (\n               current_field ->> \'null_proportion\' IS NOT NULL\n               AND (current_field ->> \'null_proportion\')::numeric NOT BETWEEN 0 AND 1\n           )\n           OR (\n               current_field ->> \'unique_proportion\' IS NOT NULL\n               AND (current_field ->> \'unique_proportion\')::numeric NOT BETWEEN 0 AND 1\n           )\n           OR (\n               p_payload ->> \'row_count\' IS NOT NULL\n               AND current_field ->> \'null_count\' IS NOT NULL\n               AND (current_field ->> \'null_count\')::numeric\n                    > (p_payload ->> \'row_count\')::numeric\n           )\n           OR (\n               p_payload ->> \'row_count\' IS NOT NULL\n               AND current_field ->> \'unique_count\' IS NOT NULL\n               AND (current_field ->> \'unique_count\')::numeric\n                    > (p_payload ->> \'row_count\')::numeric\n           ) THEN\n            RAISE EXCEPTION \'invalid Profile column metric\'\n                USING ERRCODE = \'23514\';\n        END IF;\n    END LOOP;\n    IF EXISTS (\n        SELECT 1\n        FROM jsonb_array_elements(p_payload -> \'columns\') AS field_value\n        GROUP BY field_value ->> \'field_path\'\n        HAVING count(*) <> 1\n    ) OR (\n        profile_completeness = \'COMPLETE\'\n        AND (\n            p_payload ->> \'row_count\' IS NULL\n            OR p_payload ->> \'column_count\' IS NULL\n            OR p_payload ->> \'size_bytes\' IS NULL\n            OR (p_payload ->> \'column_count\')::bigint\n                <> jsonb_array_length(p_payload -> \'columns\')\n            OR EXISTS (\n                SELECT 1\n                FROM jsonb_array_elements(p_payload -> \'columns\') AS field_value\n                WHERE field_value ->> \'null_count\' IS NULL\n                   OR field_value ->> \'null_proportion\' IS NULL\n                   OR field_value ->> \'unique_count\' IS NULL\n                   OR field_value ->> \'unique_proportion\' IS NULL\n            )\n        )\n    ) THEN\n        RAISE EXCEPTION \'ambiguous or incomplete Profile column set\'\n            USING ERRCODE = \'23514\';\n    END IF;\n\n    target_scope_hash := encode(sha256(convert_to(jsonb_build_object(\n        \'contract\', \'CATALOG_PROFILE_TARGET_SCOPE_V1\',\n        \'workspace_id\', selected_asset.workspace_id::text,\n        \'asset_id\', selected_asset.id::text,\n        \'classification\', selected_asset.classification,\n        \'system_id\', selected_asset.system_id::text,\n        \'domain_id\', selected_asset.domain_id::text,\n        \'source_version\', selected_asset.source_version\n    )::text, \'UTF8\')), \'hex\');\n    calculated_identity_hash := encode(sha256(convert_to(jsonb_build_object(\n        \'contract\', \'CATALOG_PROFILE_SNAPSHOT_IDENTITY_V1\',\n        \'workspace_id\', p_workspace_id::text,\n        \'asset_id\', p_asset_id::text,\n        \'profiled_at\', profiled_at,\n        \'profile_kind\', profile_kind,\n        \'target_scope_hash\', target_scope_hash,\n        \'provider_version\', p_payload ->> \'provider_version\',\n        \'provider_contract_hash\', p_payload ->> \'provider_contract_hash\',\n        \'provider_query_hash\', p_payload ->> \'provider_query_hash\',\n        \'provider_config_hash\', p_payload ->> \'provider_config_hash\',\n        \'source_watermark_hash\', p_payload ->> \'source_watermark_hash\',\n        \'normalized_payload_hash\', p_payload ->> \'normalized_payload_hash\',\n        \'provenance_key_id\', p_payload ->> \'provenance_key_id\',\n        \'provenance_fingerprint\', p_payload ->> \'provenance_fingerprint\'\n    )::text, \'UTF8\')), \'hex\');\n\n    PERFORM pg_advisory_xact_lock(hashtextextended(\n        p_workspace_id::text || \':\' || p_asset_id::text || \':\' ||\n        calculated_identity_hash,\n        0\n    ));\n    SELECT snapshot.* INTO existing_snapshot\n    FROM catalog.asset_profile_snapshots AS snapshot\n    WHERE snapshot.workspace_id = p_workspace_id\n      AND snapshot.asset_id = p_asset_id\n      AND snapshot.snapshot_identity_hash = calculated_identity_hash\n    FOR UPDATE;\n    IF FOUND THEN\n        UPDATE catalog.asset_profile_snapshots AS snapshot\n        SET last_observed_at = GREATEST(snapshot.last_observed_at, observed_at)\n        WHERE snapshot.workspace_id = p_workspace_id\n          AND snapshot.id = existing_snapshot.id\n        RETURNING snapshot.last_observed_at\n        INTO last_observed_at;\n        snapshot_id := existing_snapshot.id;\n        snapshot_identity_hash := calculated_identity_hash;\n        created := false;\n        RETURN NEXT;\n        RETURN;\n    END IF;\n\n    inserted_snapshot_id := gen_random_uuid();\n    SELECT * INTO resolved\n    FROM retention.resolve_quality_binding_v1(\n        p_workspace_id,\n        \'QUALITY_PROFILE\',\n        \'PROFILE_SNAPSHOT\',\n        inserted_snapshot_id,\n        basis_at\n    );\n    INSERT INTO catalog.asset_profile_snapshots (\n        id, workspace_id, asset_id, asset_source_version,\n        snapshot_identity_hash, profile_kind, completeness,\n        profiled_at, first_observed_at, last_observed_at, stale_at,\n        row_count, column_count, size_bytes,\n        provenance_key_id, provenance_fingerprint,\n        provider_version, provider_contract_hash, provider_query_hash,\n        provider_config_hash, source_watermark_hash, normalized_payload_hash,\n        classification, system_id, domain_id, target_scope_hash,\n        profile_retention_kind, profile_retention_policy_id,\n        profile_retention_policy_number, profile_retention_policy_hash,\n        profile_retention_basis_at, profile_retain_until,\n        profile_hold_generation, profile_hold_hash\n    )\n    VALUES (\n        inserted_snapshot_id, p_workspace_id, p_asset_id, selected_asset.source_version,\n        calculated_identity_hash, profile_kind, profile_completeness,\n        profiled_at, observed_at, observed_at, stale_at,\n        NULLIF(p_payload ->> \'row_count\', \'\')::bigint,\n        NULLIF(p_payload ->> \'column_count\', \'\')::bigint,\n        NULLIF(p_payload ->> \'size_bytes\', \'\')::bigint,\n        p_payload ->> \'provenance_key_id\',\n        p_payload ->> \'provenance_fingerprint\',\n        p_payload ->> \'provider_version\',\n        p_payload ->> \'provider_contract_hash\',\n        p_payload ->> \'provider_query_hash\',\n        p_payload ->> \'provider_config_hash\',\n        p_payload ->> \'source_watermark_hash\',\n        p_payload ->> \'normalized_payload_hash\',\n        selected_asset.classification, selected_asset.system_id,\n        selected_asset.domain_id, target_scope_hash,\n        \'QUALITY_PROFILE\', resolved.policy_id, resolved.policy_number,\n        resolved.policy_hash, basis_at, resolved.retain_until,\n        resolved.hold_generation, resolved.hold_hash\n    );\n    INSERT INTO catalog.column_profile_metrics (\n        id, workspace_id, snapshot_id, field_path,\n        null_count_available, null_count,\n        null_proportion_available, null_proportion,\n        unique_count_available, unique_count,\n        unique_proportion_available, unique_proportion,\n        classification, target_scope_hash,\n        profile_retention_policy_id, profile_retention_policy_number,\n        profile_retention_policy_hash, profile_retain_until,\n        profile_hold_generation, profile_hold_hash\n    )\n    SELECT\n        gen_random_uuid(), p_workspace_id, inserted_snapshot_id,\n        field_value ->> \'field_path\',\n        field_value ->> \'null_count\' IS NOT NULL,\n        NULLIF(field_value ->> \'null_count\', \'\')::bigint,\n        field_value ->> \'null_proportion\' IS NOT NULL,\n        NULLIF(field_value ->> \'null_proportion\', \'\')::numeric,\n        field_value ->> \'unique_count\' IS NOT NULL,\n        NULLIF(field_value ->> \'unique_count\', \'\')::bigint,\n        field_value ->> \'unique_proportion\' IS NOT NULL,\n        NULLIF(field_value ->> \'unique_proportion\', \'\')::numeric,\n        selected_asset.classification, target_scope_hash,\n        resolved.policy_id, resolved.policy_number, resolved.policy_hash,\n        resolved.retain_until, resolved.hold_generation, resolved.hold_hash\n    FROM jsonb_array_elements(p_payload -> \'columns\') AS field_value;\n\n    snapshot_id := inserted_snapshot_id;\n    snapshot_identity_hash := calculated_identity_hash;\n    created := true;\n    last_observed_at := observed_at;\n    RETURN NEXT;\nEND\n$$;')
        op.execute('REVOKE ALL ON FUNCTION catalog.project_asset_profile_v1(uuid, uuid, jsonb) FROM PUBLIC;')
        op.execute('REVOKE ALL ON catalog.asset_profile_snapshots FROM PUBLIC, datariver_catalog_profile;')
        op.execute('REVOKE ALL ON catalog.column_profile_metrics FROM PUBLIC, datariver_catalog_profile;')
        op.execute('REVOKE ALL ON ALL SEQUENCES IN SCHEMA catalog FROM datariver_catalog_profile;')
        op.execute('GRANT USAGE ON SCHEMA catalog TO datariver_catalog_profile;')
        op.execute('GRANT EXECUTE ON FUNCTION catalog.read_profile_target_v1(uuid, uuid)\nTO datariver_catalog_profile;')
        op.execute('GRANT EXECUTE ON FUNCTION catalog.project_asset_profile_v1(uuid, uuid, jsonb)\nTO datariver_catalog_profile;')
        op.execute('CREATE OR REPLACE FUNCTION quality.current_quality_service_can_v1(\n    p_workspace_id uuid,\n    p_action text,\n    p_classification integer DEFAULT 0,\n    p_system_id uuid DEFAULT NULL,\n    p_domain_id uuid DEFAULT NULL\n)\nRETURNS boolean\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = pg_catalog, platform, iam\nAS $$\n    SELECT p_workspace_id IS NOT DISTINCT FROM\n               NULLIF(current_setting(\'app.workspace_id\', true), \'\')::uuid\n       AND (\n           (p_action = \'quality.dispatch\' AND session_user = \'datariver_app\')\n           OR (p_action = \'quality.execute\' AND session_user = \'datariver_quality\')\n       )\n       AND EXISTS (\n           SELECT 1\n           FROM platform.workspaces AS workspace\n           JOIN iam.workspace_memberships AS membership\n             ON membership.workspace_id = workspace.id\n           JOIN iam.subjects AS subject\n             ON subject.id = membership.subject_id\n           WHERE workspace.id = p_workspace_id\n             AND workspace.status = \'ACTIVE\'\n             AND membership.subject_id =\n                 NULLIF(current_setting(\'app.subject_id\', true), \'\')::uuid\n             AND subject.active IS TRUE\n             AND membership.active IS TRUE\n             AND (\n                 membership.access_expires_at IS NULL\n                 OR membership.access_expires_at > transaction_timestamp()\n             )\n             AND membership.job_function = \'SERVICE_ACCOUNT\'\n             AND COALESCE(membership.attributes -> \'groups\', \'[]\'::jsonb) =\n                 CASE p_action\n                     WHEN \'quality.dispatch\'\n                     THEN \'["service-accounts","quality-dispatchers"]\'::jsonb\n                     WHEN \'quality.execute\'\n                     THEN \'["service-accounts","quality-workers"]\'::jsonb\n                 END\n             AND COALESCE(\n                 membership.attributes -> \'allowed_actions\', \'[]\'::jsonb\n             ) = jsonb_build_array(p_action)\n             AND COALESCE(\n                 membership.attributes -> \'denied_actions\', \'[]\'::jsonb\n             ) = \'[]\'::jsonb\n             AND membership.clearance >= p_classification\n             AND (\n                 p_classification = 0\n                 OR p_system_id IS NULL\n                 OR COALESCE(\n                     membership.attributes -> \'allowed_system_ids\', \'[]\'::jsonb\n                 ) ? p_system_id::text\n             )\n             AND (\n                 p_classification = 0\n                 OR p_domain_id IS NULL\n                 OR COALESCE(\n                     membership.attributes -> \'allowed_domain_ids\', \'[]\'::jsonb\n                 ) ? p_domain_id::text\n             )\n       )\n$$;')
        op.execute('REVOKE ALL ON FUNCTION quality.current_quality_service_can_v1(\n    uuid, text, integer, uuid, uuid\n) FROM PUBLIC;')
        op.execute("CREATE OR REPLACE FUNCTION quality.current_quality_target_matches_v1(\n    p_workspace_id uuid,\n    p_asset_id uuid,\n    p_classification integer,\n    p_system_id uuid,\n    p_domain_id uuid,\n    p_lifecycle text,\n    p_source_version text\n)\nRETURNS boolean\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = pg_catalog, catalog, quality\nAS $$\n    SELECT EXISTS (\n        SELECT 1\n        FROM catalog.assets_projection AS asset\n        WHERE asset.workspace_id = p_workspace_id\n          AND asset.id = p_asset_id\n          AND asset.deleted_at IS NULL\n          AND asset.lifecycle = 'ACTIVE'\n          AND asset.lifecycle = p_lifecycle\n          AND asset.source_version = p_source_version\n          AND asset.classification = p_classification\n          AND asset.system_id IS NOT DISTINCT FROM p_system_id\n          AND asset.domain_id IS NOT DISTINCT FROM p_domain_id\n          AND quality.current_quality_service_can_v1(\n              asset.workspace_id, 'quality.execute', asset.classification,\n              asset.system_id, asset.domain_id\n          )\n    )\n$$;")
        op.execute('REVOKE ALL ON FUNCTION quality.current_quality_target_matches_v1(\n    uuid, uuid, integer, uuid, uuid, text, text\n) FROM PUBLIC;')
        op.execute('CREATE OR REPLACE FUNCTION quality.dispatch_due_validation_runs_v1(\n    p_workspace_id uuid,\n    p_call_id text,\n    p_max_due_schedules integer,\n    p_max_created_runs integer\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, quality, catalog, retention, integration\nAS $$\nDECLARE\n    actor_id uuid := NULLIF(current_setting(\'app.subject_id\', true), \'\')::uuid;\n    call_hash text;\n    request_hash text;\n    result_hash text;\n    receipt_id uuid := gen_random_uuid();\n    cutoff_at timestamptz := transaction_timestamp();\n    selected_schedule quality.rule_schedules%ROWTYPE;\n    selected_version quality.rule_set_versions%ROWTYPE;\n    result_binding record;\n    audit_binding record;\n    receipt_binding record;\n    run_id uuid;\n    created_ids jsonb := \'[]\'::jsonb;\n    created_count integer := 0;\n    skipped_count integer := 0;\n    interval_seconds integer;\n    profile_context_hash text;\n    security_context_hash text;\n    existing_receipt quality.dispatch_call_receipts%ROWTYPE;\nBEGIN\n    IF p_workspace_id IS DISTINCT FROM\n           NULLIF(current_setting(\'app.workspace_id\', true), \'\')::uuid\n       OR char_length(COALESCE(p_call_id, \'\')) NOT BETWEEN 1 AND 200\n       OR p_call_id IS DISTINCT FROM btrim(p_call_id)\n       OR p_max_due_schedules NOT BETWEEN 1 AND 100\n       OR p_max_created_runs NOT BETWEEN 1 AND 100\n       OR NOT quality.current_quality_service_can_v1(\n           p_workspace_id, \'quality.dispatch\', 0, NULL, NULL\n       ) THEN\n        RAISE EXCEPTION \'invalid Quality dispatch request\'\n            USING ERRCODE = \'42501\';\n    END IF;\n    call_hash := encode(sha256(convert_to(p_call_id, \'UTF8\')), \'hex\');\n    request_hash := encode(sha256(convert_to(jsonb_build_object(\n        \'contract\', \'QUALITY_DISPATCH_REQUEST_V1\',\n        \'workspace_id\', p_workspace_id::text,\n        \'service_subject_id\', actor_id::text,\n        \'call_id_hash\', call_hash,\n        \'max_due_schedules\', p_max_due_schedules,\n        \'max_created_runs\', p_max_created_runs\n    )::text, \'UTF8\')), \'hex\');\n    PERFORM pg_advisory_xact_lock(hashtextextended(\n        p_workspace_id::text || \':\' || actor_id::text || \':\' || call_hash, 0\n    ));\n    SELECT * INTO existing_receipt\n    FROM quality.dispatch_call_receipts AS receipt\n    WHERE receipt.workspace_id = p_workspace_id\n      AND receipt.service_subject_id = actor_id\n      AND receipt.call_id_hash = call_hash;\n    IF FOUND THEN\n        IF existing_receipt.request_hash <> request_hash THEN\n            RAISE EXCEPTION \'Quality dispatch idempotency conflict\'\n                USING ERRCODE = \'23505\';\n        END IF;\n        SELECT COALESCE(jsonb_agg(link.run_id::text ORDER BY link.ordinal), \'[]\'::jsonb)\n        INTO created_ids\n        FROM quality.dispatch_run_links AS link\n        WHERE link.workspace_id = p_workspace_id\n          AND link.dispatch_receipt_id = existing_receipt.id;\n        RETURN jsonb_build_object(\n            \'created_run_ids\', created_ids,\n            \'created_run_count\', existing_receipt.created_run_count,\n            \'skipped_window_count\', existing_receipt.skipped_window_count,\n            \'replayed\', true\n        );\n    END IF;\n\n    FOR selected_schedule IN\n        SELECT schedule.*\n        FROM quality.rule_schedules AS schedule\n        JOIN quality.rule_set_versions AS version\n          ON version.workspace_id = schedule.workspace_id\n         AND version.id = schedule.rule_set_version_id\n        WHERE schedule.workspace_id = p_workspace_id\n          AND schedule.state = \'ACTIVE\'\n          AND schedule.next_due_at <= cutoff_at\n          AND version.state = \'ACTIVE\'\n          AND version.schedule_mode = \'SCHEDULED\'\n        ORDER BY schedule.next_due_at, schedule.id\n        FOR UPDATE OF schedule SKIP LOCKED\n        LIMIT p_max_due_schedules\n    LOOP\n        EXIT WHEN created_count >= p_max_created_runs;\n        SELECT * INTO selected_version\n        FROM quality.rule_set_versions AS version\n        WHERE version.workspace_id = p_workspace_id\n          AND version.id = selected_schedule.rule_set_version_id\n        FOR KEY SHARE;\n        interval_seconds := NULL;\n        IF jsonb_typeof(selected_schedule.cadence) = \'object\'\n           AND ARRAY(\n               SELECT key FROM jsonb_object_keys(selected_schedule.cadence) AS key\n               ORDER BY key COLLATE "C"\n           ) = ARRAY[\'contract\',\'interval_seconds\']::text[]\n           AND selected_schedule.cadence ->> \'contract\' = \'FIXED_INTERVAL_V1\'\n           AND jsonb_typeof(selected_schedule.cadence -> \'interval_seconds\') = \'number\'\n           AND (selected_schedule.cadence ->> \'interval_seconds\')::numeric\n               = trunc((selected_schedule.cadence ->> \'interval_seconds\')::numeric)\n           AND (selected_schedule.cadence ->> \'interval_seconds\')::numeric\n               BETWEEN 60 AND 2678400 THEN\n            interval_seconds :=\n                (selected_schedule.cadence ->> \'interval_seconds\')::integer;\n        END IF;\n        IF interval_seconds IS NULL\n           OR selected_schedule.current_window_key IS NULL\n           OR char_length(selected_schedule.current_window_key) NOT BETWEEN 1 AND 255\n           OR selected_version.id IS NULL\n           OR NOT EXISTS (\n               SELECT 1\n               FROM catalog.assets_projection AS asset\n               WHERE asset.workspace_id = p_workspace_id\n                 AND asset.id = selected_version.asset_id\n                 AND asset.deleted_at IS NULL\n                 AND asset.lifecycle = selected_version.lifecycle\n                 AND asset.source_version = selected_version.source_version\n                 AND asset.classification = selected_version.classification\n                 AND asset.system_id IS NOT DISTINCT FROM selected_version.system_id\n                 AND asset.domain_id IS NOT DISTINCT FROM selected_version.domain_id\n           )\n           OR NOT EXISTS (\n               SELECT 1 FROM quality.rule_definitions AS definition\n               WHERE definition.workspace_id = p_workspace_id\n                 AND definition.rule_set_version_id = selected_version.id\n           ) THEN\n            skipped_count := skipped_count + 1;\n            CONTINUE;\n        END IF;\n        run_id := gen_random_uuid();\n        SELECT * INTO result_binding\n        FROM retention.resolve_quality_binding_v1(\n            p_workspace_id, \'QUALITY_RESULT\', \'QUALITY_VALIDATION_RUN\',\n            run_id, cutoff_at\n        );\n        SELECT * INTO audit_binding\n        FROM retention.resolve_quality_binding_v1(\n            p_workspace_id, \'QUALITY_AUDIT\', \'QUALITY_VALIDATION_RUN\',\n            run_id, cutoff_at\n        );\n        SELECT COALESCE(\n            (\n                SELECT snapshot.snapshot_identity_hash\n                FROM catalog.asset_profile_snapshots AS snapshot\n                WHERE snapshot.workspace_id = p_workspace_id\n                  AND snapshot.asset_id = selected_version.asset_id\n                  AND snapshot.asset_source_version = selected_version.source_version\n                  AND snapshot.profile_kind IN (\'FULL\', \'PARTITION\')\n                  AND snapshot.completeness = \'COMPLETE\'\n                  AND snapshot.stale_at > cutoff_at\n                  AND snapshot.profile_retain_until > cutoff_at\n                ORDER BY snapshot.profiled_at DESC, snapshot.id DESC\n                LIMIT 1\n            ),\n            encode(sha256(convert_to(\n                \'QUALITY_PROFILE_CONTEXT_UNAVAILABLE_V1\', \'UTF8\'\n            )), \'hex\')\n        ) INTO profile_context_hash;\n        security_context_hash := encode(sha256(convert_to(jsonb_build_object(\n            \'contract\', \'QUALITY_SECURITY_CONTEXT_V1\',\n            \'asset_id\', selected_version.asset_id::text,\n            \'classification\', selected_version.classification,\n            \'system_id\', selected_version.system_id::text,\n            \'domain_id\', selected_version.domain_id::text,\n            \'lifecycle\', selected_version.lifecycle,\n            \'source_version\', selected_version.source_version\n        )::text, \'UTF8\')), \'hex\');\n        INSERT INTO quality.validation_runs (\n            id, workspace_id, rule_set_id, rule_set_version_id, asset_id,\n            target_binding_hash, schema_hash,\n            source_connection_profile_id, source_connection_profile_version,\n            source_connection_profile_hash,\n            workload_profile_id, workload_profile_version, workload_profile_hash,\n            security_context_hash, datahub_profile_context_hash,\n            score_policy_id, score_policy_version, score_policy_hash,\n            retry_of_run_id, trigger_kind, requested_by,\n            schedule_id, schedule_version, canonical_window_key, due_at, is_late,\n            state, quality_outcome, score, passed_count,\n            advisory_failed_count, blocking_failed_count,\n            current_attempt_id, attempt_count, maximum_attempts, next_attempt_at,\n            lease_epoch, lease_token_hash, lease_owner_fingerprint, lease_until,\n            heartbeat_at, source_started_at, source_access_deadline,\n            hard_timeout_contract_hash, completed_at, failure_code,\n            result_retention_kind, result_retention_policy_id,\n            result_retention_policy_number, result_retention_policy_hash,\n            result_retention_basis_at, result_retain_until,\n            result_hold_generation, result_hold_hash,\n            audit_retention_kind, audit_retention_policy_id,\n            audit_retention_policy_number, audit_retention_policy_hash,\n            audit_retention_basis_at, audit_retain_until,\n            audit_hold_generation, audit_hold_hash,\n            created_at, updated_at, version\n        )\n        VALUES (\n            run_id, p_workspace_id, selected_version.rule_set_id,\n            selected_version.id, selected_version.asset_id,\n            selected_version.target_binding_hash, selected_version.schema_hash,\n            selected_version.source_connection_profile_id,\n            selected_version.source_connection_profile_version,\n            selected_version.source_connection_profile_hash,\n            selected_version.workload_profile_id,\n            selected_version.workload_profile_version,\n            selected_version.workload_profile_hash,\n            security_context_hash, profile_context_hash,\n            selected_version.score_policy_id,\n            selected_version.score_policy_version,\n            selected_version.score_policy_hash,\n            NULL, \'SCHEDULED\', NULL,\n            selected_schedule.id, selected_schedule.version,\n            selected_schedule.current_window_key, selected_schedule.next_due_at,\n            cutoff_at > selected_schedule.next_due_at\n                + make_interval(secs => selected_schedule.late_grace_seconds),\n            \'QUEUED\', \'UNKNOWN\', NULL, NULL, NULL, NULL,\n            NULL, 0, 3, cutoff_at, 0, NULL, NULL, NULL,\n            NULL, NULL, NULL, selected_version.workload_profile_hash, NULL, NULL,\n            \'QUALITY_RESULT\', result_binding.policy_id, result_binding.policy_number,\n            result_binding.policy_hash, cutoff_at, result_binding.retain_until,\n            result_binding.hold_generation, result_binding.hold_hash,\n            \'QUALITY_AUDIT\', audit_binding.policy_id, audit_binding.policy_number,\n            audit_binding.policy_hash, cutoff_at, audit_binding.retain_until,\n            audit_binding.hold_generation, audit_binding.hold_hash,\n            cutoff_at, cutoff_at, 1\n        )\n        ON CONFLICT (workspace_id, schedule_id, canonical_window_key) DO NOTHING;\n        IF FOUND THEN\n            created_count := created_count + 1;\n            created_ids := created_ids || jsonb_build_array(run_id::text);\n            INSERT INTO quality.run_events (\n                id, workspace_id, run_id, sequence, state, reason_code,\n                actor_id, actor_kind, evidence_hash,\n                audit_retention_policy_id, audit_retention_policy_number,\n                audit_retention_policy_hash, audit_retain_until,\n                audit_hold_generation, audit_hold_hash, occurred_at\n            )\n            VALUES (\n                gen_random_uuid(), p_workspace_id, run_id, 1, \'QUEUED\',\n                \'SCHEDULE_WINDOW_DUE\', actor_id, \'SERVICE\',\n                encode(sha256(convert_to(jsonb_build_object(\n                    \'contract\', \'QUALITY_RUN_QUEUED_EVENT_V1\',\n                    \'schedule_id\', selected_schedule.id::text,\n                    \'window_key\', selected_schedule.current_window_key,\n                    \'due_at\', selected_schedule.next_due_at\n                )::text, \'UTF8\')), \'hex\'),\n                audit_binding.policy_id, audit_binding.policy_number,\n                audit_binding.policy_hash, audit_binding.retain_until,\n                audit_binding.hold_generation, audit_binding.hold_hash, cutoff_at\n            );\n            INSERT INTO integration.outbox_events (\n                id, workspace_id, aggregate_type, aggregate_id, event_type,\n                schema_version, payload, created_at, published_at,\n                dead_lettered_at, lease_until, attempts, last_error_code\n            )\n            VALUES (\n                gen_random_uuid(), p_workspace_id, \'quality_validation_run\', run_id,\n                \'quality.validation_run.queued.v1\', 1,\n                jsonb_build_object(\'run_id\', run_id::text, \'state\', \'QUEUED\'),\n                cutoff_at, NULL, NULL, NULL, 0, NULL\n            );\n        ELSE\n            skipped_count := skipped_count + 1;\n        END IF;\n        UPDATE quality.rule_schedules\n        SET next_due_at = selected_schedule.next_due_at\n                + make_interval(secs => interval_seconds),\n            current_window_key = encode(sha256(convert_to(jsonb_build_object(\n                \'contract\', \'QUALITY_FIXED_WINDOW_V1\',\n                \'schedule_id\', selected_schedule.id::text,\n                \'due_at\', selected_schedule.next_due_at\n                    + make_interval(secs => interval_seconds)\n            )::text, \'UTF8\')), \'hex\'),\n            updated_at = cutoff_at\n        WHERE workspace_id = p_workspace_id\n          AND id = selected_schedule.id\n          AND version = selected_schedule.version;\n    END LOOP;\n\n    SELECT * INTO receipt_binding\n    FROM retention.resolve_quality_binding_v1(\n        p_workspace_id, \'QUALITY_AUDIT\', \'QUALITY_VALIDATION_RUN\',\n        receipt_id, cutoff_at\n    );\n    result_hash := encode(sha256(convert_to(jsonb_build_object(\n        \'contract\', \'QUALITY_DISPATCH_RESULT_V1\',\n        \'created_run_ids\', created_ids,\n        \'created_run_count\', created_count,\n        \'skipped_window_count\', skipped_count\n    )::text, \'UTF8\')), \'hex\');\n    INSERT INTO quality.dispatch_call_receipts (\n        id, workspace_id, service_subject_id, call_id_hash, request_hash,\n        result_hash, idempotency_hash, cutoff_at,\n        evaluator_contract_version, tzdb_version, contract_hash,\n        max_due_schedules, max_created_runs, created_run_count,\n        skipped_window_count, created_run_list_hash, skipped_range_hash,\n        audit_retention_kind, audit_retention_policy_id,\n        audit_retention_policy_number, audit_retention_policy_hash,\n        audit_retention_basis_at, audit_retain_until,\n        audit_hold_generation, audit_hold_hash, created_at, updated_at\n    )\n    VALUES (\n        receipt_id, p_workspace_id, actor_id, call_hash, request_hash,\n        result_hash,\n        encode(sha256(convert_to(\n            \'QUALITY_DISPATCH_IDEMPOTENCY_V1:\' || actor_id::text || \':\' || call_hash,\n            \'UTF8\'\n        )), \'hex\'),\n        cutoff_at, \'FIXED_INTERVAL_EVALUATOR_V1\', \'UTC\',\n        encode(sha256(convert_to(\'QUALITY_DISPATCH_CONTRACT_V1\', \'UTF8\')), \'hex\'),\n        p_max_due_schedules, p_max_created_runs, created_count, skipped_count,\n        encode(sha256(convert_to(created_ids::text, \'UTF8\')), \'hex\'),\n        encode(sha256(convert_to(skipped_count::text, \'UTF8\')), \'hex\'),\n        \'QUALITY_AUDIT\', receipt_binding.policy_id, receipt_binding.policy_number,\n        receipt_binding.policy_hash, cutoff_at, receipt_binding.retain_until,\n        receipt_binding.hold_generation, receipt_binding.hold_hash,\n        cutoff_at, cutoff_at\n    );\n    INSERT INTO quality.dispatch_run_links (\n        id, workspace_id, dispatch_receipt_id, run_id, ordinal,\n        receipt_audit_policy_id, receipt_audit_policy_number,\n        receipt_audit_policy_hash, receipt_audit_retain_until,\n        receipt_audit_hold_generation, receipt_audit_hold_hash,\n        run_result_policy_id, run_result_policy_number, run_result_policy_hash,\n        run_result_retain_until, run_result_hold_generation, run_result_hold_hash,\n        run_audit_policy_id, run_audit_policy_number, run_audit_policy_hash,\n        run_audit_retain_until, run_audit_hold_generation, run_audit_hold_hash,\n        created_at\n    )\n    SELECT\n        gen_random_uuid(), p_workspace_id, receipt_id, run.id, item.ordinality::integer,\n        receipt_binding.policy_id, receipt_binding.policy_number,\n        receipt_binding.policy_hash, receipt_binding.retain_until,\n        receipt_binding.hold_generation, receipt_binding.hold_hash,\n        run.result_retention_policy_id, run.result_retention_policy_number,\n        run.result_retention_policy_hash, run.result_retain_until,\n        run.result_hold_generation, run.result_hold_hash,\n        run.audit_retention_policy_id, run.audit_retention_policy_number,\n        run.audit_retention_policy_hash, run.audit_retain_until,\n        run.audit_hold_generation, run.audit_hold_hash, cutoff_at\n    FROM jsonb_array_elements_text(created_ids) WITH ORDINALITY AS item(run_id, ordinality)\n    JOIN quality.validation_runs AS run\n      ON run.workspace_id = p_workspace_id\n     AND run.id = item.run_id::uuid;\n    RETURN jsonb_build_object(\n        \'created_run_ids\', created_ids,\n        \'created_run_count\', created_count,\n        \'skipped_window_count\', skipped_count,\n        \'replayed\', false\n    );\nEND\n$$;')
        op.execute('REVOKE ALL ON FUNCTION quality.dispatch_due_validation_runs_v1(\n    uuid, text, integer, integer\n) FROM PUBLIC;')
        op.execute("CREATE OR REPLACE FUNCTION quality.claim_validation_run_v1(\n    p_workspace_id uuid,\n    p_worker_fingerprint text,\n    p_lease_token text,\n    p_lease_seconds integer\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, quality\nAS $$\nDECLARE\n    candidate quality.validation_runs%ROWTYPE;\n    selected_version quality.rule_set_versions%ROWTYPE;\n    previous_attempt quality.validation_attempts%ROWTYPE;\n    attempt_id uuid := gen_random_uuid();\n    token_hash text;\n    now_at timestamptz := transaction_timestamp();\n    new_epoch bigint;\n    new_attempt integer;\n    claim_document jsonb;\nBEGIN\n    IF p_workspace_id IS DISTINCT FROM\n           NULLIF(current_setting('app.workspace_id', true), '')::uuid\n       OR char_length(COALESCE(p_worker_fingerprint, '')) NOT BETWEEN 1 AND 255\n       OR p_worker_fingerprint IS DISTINCT FROM btrim(p_worker_fingerprint)\n       OR char_length(COALESCE(p_lease_token, '')) NOT BETWEEN 32 AND 200\n       OR p_lease_seconds NOT BETWEEN 60 AND 90000\n       OR NOT quality.current_quality_service_can_v1(\n           p_workspace_id, 'quality.execute', 0, NULL, NULL\n       ) THEN\n        RAISE EXCEPTION 'invalid Quality claim request'\n            USING ERRCODE = '42501';\n    END IF;\n    SELECT * INTO candidate\n    FROM quality.validation_runs AS run\n    WHERE run.workspace_id = p_workspace_id\n      AND (\n          (run.state IN ('QUEUED','RETRY_WAIT') AND run.next_attempt_at <= now_at)\n          OR (\n              run.state = 'RUNNING'\n              AND run.lease_until <= now_at\n          )\n      )\n    ORDER BY\n        CASE WHEN run.state = 'RUNNING' THEN 0 ELSE 1 END,\n        run.next_attempt_at, run.id\n    FOR UPDATE SKIP LOCKED\n    LIMIT 1;\n    IF NOT FOUND THEN\n        RETURN NULL;\n    END IF;\n    SELECT * INTO selected_version\n    FROM quality.rule_set_versions AS version\n    WHERE version.workspace_id = p_workspace_id\n      AND version.id = candidate.rule_set_version_id\n    FOR KEY SHARE;\n    IF selected_version.state <> 'ACTIVE'\n       OR candidate.result_retain_until <= now_at\n       OR candidate.audit_retain_until <= now_at\n       OR NOT quality.current_quality_target_matches_v1(\n           p_workspace_id, candidate.asset_id, selected_version.classification,\n           selected_version.system_id, selected_version.domain_id,\n           selected_version.lifecycle, selected_version.source_version\n       ) THEN\n        RETURN NULL;\n    END IF;\n    IF candidate.state = 'RUNNING' THEN\n        SELECT * INTO previous_attempt\n        FROM quality.validation_attempts AS attempt\n        WHERE attempt.workspace_id = p_workspace_id\n          AND attempt.id = candidate.current_attempt_id\n        FOR UPDATE;\n        IF candidate.attempt_count >= candidate.maximum_attempts THEN\n            UPDATE quality.validation_attempts\n            SET state = 'STALE', failure_code = 'LEASE_EXHAUSTED',\n                finished_at = now_at\n            WHERE workspace_id = p_workspace_id AND id = previous_attempt.id;\n            UPDATE quality.validation_runs\n            SET state = 'STALE', completed_at = now_at,\n                failure_code = 'LEASE_EXHAUSTED',\n                lease_token_hash = NULL, lease_owner_fingerprint = NULL,\n                lease_until = NULL, heartbeat_at = NULL,\n                version = version + 1, updated_at = now_at\n            WHERE workspace_id = p_workspace_id AND id = candidate.id;\n            INSERT INTO integration.outbox_events (\n                id, workspace_id, aggregate_type, aggregate_id, event_type,\n                schema_version, payload, created_at, published_at,\n                dead_lettered_at, lease_until, attempts, last_error_code\n            )\n            VALUES (\n                gen_random_uuid(), p_workspace_id, 'quality_validation_run',\n                candidate.id, 'quality.validation_run.stale.v1', 1,\n                jsonb_build_object('run_id', candidate.id::text, 'state', 'STALE'),\n                now_at, NULL, NULL, NULL, 0, NULL\n            );\n            RETURN NULL;\n        END IF;\n        UPDATE quality.validation_attempts\n        SET state = 'SUPERSEDED', failure_code = 'LEASE_EXPIRED',\n            finished_at = now_at\n        WHERE workspace_id = p_workspace_id AND id = previous_attempt.id;\n    END IF;\n    token_hash := encode(sha256(convert_to(p_lease_token, 'UTF8')), 'hex');\n    new_epoch := candidate.lease_epoch + 1;\n    new_attempt := candidate.attempt_count + 1;\n    INSERT INTO quality.validation_attempts (\n        id, workspace_id, run_id, attempt_no, lease_epoch, lease_token_hash,\n        worker_fingerprint, state, claimed_at, lease_until,\n        source_started_at, source_access_deadline,\n        compiler_result_hash, gx_result_hash, normalized_result_hash,\n        failure_code, finished_at,\n        result_retention_policy_id, result_retention_policy_number,\n        result_retention_policy_hash, result_retain_until,\n        result_hold_generation, result_hold_hash,\n        audit_retention_policy_id, audit_retention_policy_number,\n        audit_retention_policy_hash, audit_retain_until,\n        audit_hold_generation, audit_hold_hash\n    )\n    VALUES (\n        attempt_id, p_workspace_id, candidate.id, new_attempt, new_epoch, token_hash,\n        p_worker_fingerprint, 'RUNNING', now_at,\n        now_at + make_interval(secs => p_lease_seconds),\n        NULL, NULL, NULL, NULL, NULL, NULL, NULL,\n        candidate.result_retention_policy_id,\n        candidate.result_retention_policy_number,\n        candidate.result_retention_policy_hash, candidate.result_retain_until,\n        candidate.result_hold_generation, candidate.result_hold_hash,\n        candidate.audit_retention_policy_id,\n        candidate.audit_retention_policy_number,\n        candidate.audit_retention_policy_hash, candidate.audit_retain_until,\n        candidate.audit_hold_generation, candidate.audit_hold_hash\n    );\n    UPDATE quality.validation_runs\n    SET state = 'RUNNING', current_attempt_id = attempt_id,\n        attempt_count = new_attempt, lease_epoch = new_epoch,\n        lease_token_hash = token_hash,\n        lease_owner_fingerprint = p_worker_fingerprint,\n        lease_until = now_at + make_interval(secs => p_lease_seconds),\n        heartbeat_at = now_at, source_started_at = NULL,\n        source_access_deadline = NULL, failure_code = NULL,\n        version = version + 1, updated_at = now_at\n    WHERE workspace_id = p_workspace_id AND id = candidate.id;\n    INSERT INTO quality.run_events (\n        id, workspace_id, run_id, sequence, state, reason_code,\n        actor_id, actor_kind, evidence_hash,\n        audit_retention_policy_id, audit_retention_policy_number,\n        audit_retention_policy_hash, audit_retain_until,\n        audit_hold_generation, audit_hold_hash, occurred_at\n    )\n    SELECT\n        gen_random_uuid(), p_workspace_id, candidate.id,\n        COALESCE(max(event.sequence), 0) + 1, 'RUNNING', 'WORKER_CLAIMED',\n        NULLIF(current_setting('app.subject_id', true), '')::uuid, 'SERVICE',\n        encode(sha256(convert_to(jsonb_build_object(\n            'contract', 'QUALITY_RUN_CLAIM_EVENT_V1',\n            'attempt_id', attempt_id::text,\n            'lease_epoch', new_epoch,\n            'worker_fingerprint', p_worker_fingerprint\n        )::text, 'UTF8')), 'hex'),\n        candidate.audit_retention_policy_id,\n        candidate.audit_retention_policy_number,\n        candidate.audit_retention_policy_hash, candidate.audit_retain_until,\n        candidate.audit_hold_generation, candidate.audit_hold_hash, now_at\n    FROM quality.run_events AS event\n    WHERE event.workspace_id = p_workspace_id AND event.run_id = candidate.id;\n    SELECT jsonb_build_object(\n        'workspace_id', p_workspace_id::text,\n        'run_id', candidate.id::text,\n        'attempt_id', attempt_id::text,\n        'lease_epoch', new_epoch,\n        'asset_id', candidate.asset_id::text,\n        'source_connection_profile_id', candidate.source_connection_profile_id,\n        'source_connection_profile_version', candidate.source_connection_profile_version,\n        'source_connection_profile_hash', candidate.source_connection_profile_hash,\n        'workload_profile_id', candidate.workload_profile_id,\n        'workload_profile_version', candidate.workload_profile_version,\n        'workload_profile_hash', candidate.workload_profile_hash,\n        'compiler_hash', selected_version.compiler_hash,\n        'rules', (\n            SELECT jsonb_agg(jsonb_build_object(\n                'rule_definition_id', definition.id::text,\n                'ordinal', definition.ordinal,\n                'field_identifier', definition.field_identifier,\n                'kind', definition.kind,\n                'severity', definition.severity,\n                'parameters', definition.parameters,\n                'definition_hash', definition.definition_hash\n            ) ORDER BY definition.ordinal)\n            FROM quality.rule_definitions AS definition\n            WHERE definition.workspace_id = p_workspace_id\n              AND definition.rule_set_version_id = candidate.rule_set_version_id\n        )\n    ) INTO claim_document;\n    RETURN claim_document;\nEND\n$$;")
        op.execute('REVOKE ALL ON FUNCTION quality.claim_validation_run_v1(\n    uuid, text, text, integer\n) FROM PUBLIC;')
        op.execute("CREATE OR REPLACE FUNCTION quality.freeze_source_access_v1(\n    p_workspace_id uuid,\n    p_run_id uuid,\n    p_attempt_id uuid,\n    p_lease_epoch bigint,\n    p_lease_token text,\n    p_hard_timeout_seconds integer,\n    p_cancel_timeout_seconds integer,\n    p_close_timeout_seconds integer,\n    p_completion_timeout_seconds integer\n)\nRETURNS timestamptz\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, quality\nAS $$\nDECLARE\n    selected_run quality.validation_runs%ROWTYPE;\n    selected_version quality.rule_set_versions%ROWTYPE;\n    token_hash text;\n    deadline timestamptz;\n    now_at timestamptz := transaction_timestamp();\nBEGIN\n    token_hash := encode(sha256(convert_to(COALESCE(p_lease_token, ''), 'UTF8')), 'hex');\n    SELECT * INTO selected_run\n    FROM quality.validation_runs AS run\n    WHERE run.workspace_id = p_workspace_id AND run.id = p_run_id\n    FOR UPDATE;\n    SELECT * INTO selected_version\n    FROM quality.rule_set_versions AS version\n    WHERE version.workspace_id = p_workspace_id\n      AND version.id = selected_run.rule_set_version_id\n    FOR KEY SHARE;\n    IF p_workspace_id IS DISTINCT FROM\n           NULLIF(current_setting('app.workspace_id', true), '')::uuid\n       OR NOT quality.current_quality_service_can_v1(\n           p_workspace_id, 'quality.execute', selected_version.classification,\n           selected_version.system_id, selected_version.domain_id\n       )\n       OR selected_run.state <> 'RUNNING'\n       OR selected_run.current_attempt_id <> p_attempt_id\n       OR selected_run.lease_epoch <> p_lease_epoch\n       OR selected_run.lease_token_hash <> token_hash\n       OR selected_run.lease_until <= now_at\n       OR selected_run.source_started_at IS NOT NULL\n       OR selected_version.state <> 'ACTIVE'\n       OR p_hard_timeout_seconds NOT BETWEEN 1 AND 86400\n       OR p_cancel_timeout_seconds NOT BETWEEN 1 AND 300\n       OR p_close_timeout_seconds NOT BETWEEN 1 AND 300\n       OR p_completion_timeout_seconds NOT BETWEEN 1 AND 300\n       OR p_hard_timeout_seconds + p_cancel_timeout_seconds\n            + p_close_timeout_seconds + p_completion_timeout_seconds\n            >= extract(epoch FROM selected_run.lease_until - now_at)\n       OR selected_run.hard_timeout_contract_hash\n            <> selected_run.workload_profile_hash\n       OR NOT quality.current_quality_target_matches_v1(\n           p_workspace_id, selected_run.asset_id, selected_version.classification,\n           selected_version.system_id, selected_version.domain_id,\n           selected_version.lifecycle, selected_version.source_version\n       ) THEN\n        RAISE EXCEPTION 'Quality source access fence denied'\n            USING ERRCODE = '42501';\n    END IF;\n    deadline := now_at + make_interval(secs => p_hard_timeout_seconds);\n    UPDATE quality.validation_runs\n    SET source_started_at = now_at, source_access_deadline = deadline,\n        heartbeat_at = now_at, version = version + 1, updated_at = now_at\n    WHERE workspace_id = p_workspace_id AND id = p_run_id;\n    UPDATE quality.validation_attempts\n    SET source_started_at = now_at, source_access_deadline = deadline\n    WHERE workspace_id = p_workspace_id AND id = p_attempt_id\n      AND run_id = p_run_id AND lease_epoch = p_lease_epoch\n      AND lease_token_hash = token_hash AND state = 'RUNNING';\n    RETURN deadline;\nEND\n$$;")
        op.execute('REVOKE ALL ON FUNCTION quality.freeze_source_access_v1(\n    uuid, uuid, uuid, bigint, text, integer, integer, integer, integer\n) FROM PUBLIC;')
        op.execute("CREATE OR REPLACE FUNCTION quality.assert_source_statement_fence_v1(\n    p_workspace_id uuid,\n    p_run_id uuid,\n    p_attempt_id uuid,\n    p_lease_epoch bigint,\n    p_lease_token text\n)\nRETURNS integer\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, quality\nAS $$\nDECLARE\n    selected_run quality.validation_runs%ROWTYPE;\n    selected_version quality.rule_set_versions%ROWTYPE;\n    now_at timestamptz := transaction_timestamp();\n    remaining_ms numeric;\nBEGIN\n    SELECT * INTO selected_run\n    FROM quality.validation_runs AS run\n    WHERE run.workspace_id = p_workspace_id AND run.id = p_run_id;\n    SELECT * INTO selected_version\n    FROM quality.rule_set_versions AS version\n    WHERE version.workspace_id = p_workspace_id\n      AND version.id = selected_run.rule_set_version_id;\n    IF p_workspace_id IS DISTINCT FROM\n           NULLIF(current_setting('app.workspace_id', true), '')::uuid\n       OR NOT quality.current_quality_service_can_v1(\n           p_workspace_id, 'quality.execute', selected_version.classification,\n           selected_version.system_id, selected_version.domain_id\n       )\n       OR selected_run.state <> 'RUNNING'\n       OR selected_run.current_attempt_id <> p_attempt_id\n       OR selected_run.lease_epoch <> p_lease_epoch\n       OR selected_run.lease_token_hash <>\n            encode(sha256(convert_to(COALESCE(p_lease_token, ''), 'UTF8')), 'hex')\n       OR selected_run.lease_until <= now_at\n       OR selected_run.source_started_at IS NULL\n       OR selected_run.source_access_deadline <= now_at\n       OR selected_version.state <> 'ACTIVE'\n       OR NOT quality.current_quality_target_matches_v1(\n           p_workspace_id, selected_run.asset_id, selected_version.classification,\n           selected_version.system_id, selected_version.domain_id,\n           selected_version.lifecycle, selected_version.source_version\n       ) THEN\n        RAISE EXCEPTION 'Quality source statement fence denied'\n            USING ERRCODE = '42501';\n    END IF;\n    remaining_ms := floor(extract(epoch FROM\n        LEAST(selected_run.lease_until, selected_run.source_access_deadline) - now_at\n    ) * 1000);\n    RETURN LEAST(remaining_ms, 86400000)::integer;\nEND\n$$;")
        op.execute('REVOKE ALL ON FUNCTION quality.assert_source_statement_fence_v1(\n    uuid, uuid, uuid, bigint, text\n) FROM PUBLIC;')
        op.execute('CREATE OR REPLACE FUNCTION quality.complete_validation_run_v1(\n    p_workspace_id uuid,\n    p_run_id uuid,\n    p_attempt_id uuid,\n    p_lease_epoch bigint,\n    p_lease_token text,\n    p_call_id text,\n    p_compiler_result_hash text,\n    p_gx_result_hash text,\n    p_normalized_result_hash text,\n    p_results jsonb\n)\nRETURNS boolean\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, quality, integration\nAS $$\nDECLARE\n    selected_run quality.validation_runs%ROWTYPE;\n    selected_version quality.rule_set_versions%ROWTYPE;\n    actor_id uuid := NULLIF(current_setting(\'app.subject_id\', true), \'\')::uuid;\n    token_hash text;\n    call_hash text;\n    request_hash text;\n    result_document jsonb;\n    receipt quality.execution_call_receipts%ROWTYPE;\n    calculated_passed_count integer;\n    calculated_advisory_count integer;\n    calculated_blocking_count integer;\n    calculated_total_count integer;\n    calculated_outcome text;\n    calculated_score integer;\n    now_at timestamptz := transaction_timestamp();\nBEGIN\n    token_hash := encode(sha256(convert_to(COALESCE(p_lease_token, \'\'), \'UTF8\')), \'hex\');\n    call_hash := encode(sha256(convert_to(COALESCE(p_call_id, \'\'), \'UTF8\')), \'hex\');\n    request_hash := encode(sha256(convert_to(jsonb_build_object(\n        \'contract\', \'QUALITY_EXECUTION_COMPLETE_REQUEST_V1\',\n        \'run_id\', p_run_id::text, \'attempt_id\', p_attempt_id::text,\n        \'lease_epoch\', p_lease_epoch, \'lease_token_hash\', token_hash,\n        \'compiler_result_hash\', p_compiler_result_hash,\n        \'gx_result_hash\', p_gx_result_hash,\n        \'normalized_result_hash\', p_normalized_result_hash,\n        \'results\', p_results\n    )::text, \'UTF8\')), \'hex\');\n    SELECT * INTO receipt\n    FROM quality.execution_call_receipts AS value\n    WHERE value.workspace_id = p_workspace_id\n      AND value.service_subject_id = actor_id\n      AND value.run_id = p_run_id\n      AND value.call_id_hash = call_hash;\n    IF FOUND THEN\n        IF receipt.request_hash <> request_hash THEN\n            RAISE EXCEPTION \'Quality execution idempotency conflict\'\n                USING ERRCODE = \'23505\';\n        END IF;\n        RETURN true;\n    END IF;\n    SELECT * INTO selected_run\n    FROM quality.validation_runs AS run\n    WHERE run.workspace_id = p_workspace_id AND run.id = p_run_id\n    FOR UPDATE;\n    SELECT * INTO selected_version\n    FROM quality.rule_set_versions AS version\n    WHERE version.workspace_id = p_workspace_id\n      AND version.id = selected_run.rule_set_version_id\n    FOR KEY SHARE;\n    IF p_workspace_id IS DISTINCT FROM\n           NULLIF(current_setting(\'app.workspace_id\', true), \'\')::uuid\n       OR char_length(COALESCE(p_call_id, \'\')) NOT BETWEEN 1 AND 200\n       OR p_results IS NULL OR jsonb_typeof(p_results) <> \'array\'\n       OR jsonb_array_length(p_results) NOT BETWEEN 1 AND 1000\n       OR p_compiler_result_hash !~ \'^[0-9a-f]{64}$\'\n       OR p_gx_result_hash !~ \'^[0-9a-f]{64}$\'\n       OR p_normalized_result_hash !~ \'^[0-9a-f]{64}$\'\n       OR NOT quality.current_quality_service_can_v1(\n           p_workspace_id, \'quality.execute\', selected_version.classification,\n           selected_version.system_id, selected_version.domain_id\n       )\n       OR selected_run.state <> \'RUNNING\'\n       OR selected_run.current_attempt_id <> p_attempt_id\n       OR selected_run.lease_epoch <> p_lease_epoch\n       OR selected_run.lease_token_hash <> token_hash\n       OR selected_run.lease_until <= now_at\n       OR selected_run.source_started_at IS NULL\n       OR selected_run.source_access_deadline <= now_at\n       OR selected_version.state <> \'ACTIVE\'\n       OR NOT quality.current_quality_target_matches_v1(\n           p_workspace_id, selected_run.asset_id, selected_version.classification,\n           selected_version.system_id, selected_version.domain_id,\n           selected_version.lifecycle, selected_version.source_version\n       )\n       OR EXISTS (\n           SELECT 1\n           FROM jsonb_array_elements(p_results) AS item\n           WHERE jsonb_typeof(item) <> \'object\'\n              OR ARRAY(\n                  SELECT key FROM jsonb_object_keys(item) AS key\n                  ORDER BY key COLLATE "C"\n              ) IS DISTINCT FROM ARRAY[\n                  \'duration_ms\',\'evaluated_count\',\'missing_count\',\'missing_ratio\',\n                  \'outcome\',\'result_hash\',\'rule_definition_id\',\n                  \'unexpected_count\',\'unexpected_ratio\'\n              ]::text[]\n              OR COALESCE(item ->> \'result_hash\', \'\') !~ \'^[0-9a-f]{64}$\'\n              OR COALESCE(item ->> \'outcome\', \'\')\n                    NOT IN (\'PASS\',\'ADVISORY_FAIL\',\'BLOCKING_FAIL\')\n              OR jsonb_typeof(item -> \'evaluated_count\') <> \'number\'\n              OR jsonb_typeof(item -> \'missing_count\') <> \'number\'\n              OR jsonb_typeof(item -> \'unexpected_count\') <> \'number\'\n              OR jsonb_typeof(item -> \'duration_ms\') <> \'number\'\n              OR jsonb_typeof(item -> \'missing_ratio\') <> \'number\'\n              OR jsonb_typeof(item -> \'unexpected_ratio\') <> \'number\'\n              OR (item ->> \'evaluated_count\')::numeric < 0\n              OR (item ->> \'missing_count\')::numeric < 0\n              OR (item ->> \'unexpected_count\')::numeric < 0\n              OR (item ->> \'duration_ms\')::numeric < 0\n              OR (item ->> \'missing_ratio\')::numeric NOT BETWEEN 0 AND 1\n              OR (item ->> \'unexpected_ratio\')::numeric NOT BETWEEN 0 AND 1\n       )\n       OR (\n           SELECT count(DISTINCT item ->> \'rule_definition_id\')\n           FROM jsonb_array_elements(p_results) AS item\n       ) <> jsonb_array_length(p_results)\n       OR (\n           SELECT count(*) FROM quality.rule_definitions AS definition\n           WHERE definition.workspace_id = p_workspace_id\n             AND definition.rule_set_version_id = selected_run.rule_set_version_id\n       ) <> jsonb_array_length(p_results)\n       OR EXISTS (\n           SELECT 1\n           FROM jsonb_array_elements(p_results) AS item\n           LEFT JOIN quality.rule_definitions AS definition\n             ON definition.workspace_id = p_workspace_id\n            AND definition.rule_set_version_id = selected_run.rule_set_version_id\n            AND definition.id = (item ->> \'rule_definition_id\')::uuid\n           WHERE definition.id IS NULL\n              OR item ->> \'outcome\' IS DISTINCT FROM CASE\n                  WHEN (item ->> \'unexpected_count\')::bigint = 0 THEN \'PASS\'\n                  WHEN definition.severity = \'BLOCKING\' THEN \'BLOCKING_FAIL\'\n                  ELSE \'ADVISORY_FAIL\'\n              END\n              OR (item ->> \'unexpected_count\')::bigint\n                    > (item ->> \'evaluated_count\')::bigint\n       ) THEN\n        RAISE EXCEPTION \'Quality completion fence or result contract denied\'\n            USING ERRCODE = \'42501\';\n    END IF;\n    SELECT\n        count(*) FILTER (WHERE item ->> \'outcome\' = \'PASS\'),\n        count(*) FILTER (WHERE item ->> \'outcome\' = \'ADVISORY_FAIL\'),\n        count(*) FILTER (WHERE item ->> \'outcome\' = \'BLOCKING_FAIL\'),\n        count(*)\n    INTO calculated_passed_count, calculated_advisory_count,\n         calculated_blocking_count, calculated_total_count\n    FROM jsonb_array_elements(p_results) AS item;\n    calculated_outcome := CASE\n        WHEN calculated_blocking_count > 0 THEN \'FAIL\'\n        WHEN calculated_advisory_count > 0 THEN \'WARN\'\n        ELSE \'PASS\'\n    END;\n    calculated_score := round(\n        (calculated_passed_count::numeric * 100) / calculated_total_count\n    )::integer;\n    UPDATE quality.validation_attempts\n    SET state = \'SUCCEEDED\', compiler_result_hash = p_compiler_result_hash,\n        gx_result_hash = p_gx_result_hash,\n        normalized_result_hash = p_normalized_result_hash,\n        failure_code = NULL, finished_at = now_at\n    WHERE workspace_id = p_workspace_id AND id = p_attempt_id\n      AND run_id = p_run_id AND state = \'RUNNING\'\n      AND lease_epoch = p_lease_epoch AND lease_token_hash = token_hash;\n    INSERT INTO quality.expectation_results (\n        id, workspace_id, run_id, attempt_id, run_state,\n        rule_set_version_id, rule_definition_id, outcome,\n        evaluated_count, missing_count, unexpected_count,\n        missing_ratio, unexpected_ratio, duration_ms, result_hash,\n        result_retention_policy_id, result_retention_policy_number,\n        result_retention_policy_hash, result_retain_until,\n        result_hold_generation, result_hold_hash, occurred_at\n    )\n    SELECT\n        gen_random_uuid(), p_workspace_id, p_run_id, p_attempt_id, \'SUCCEEDED\',\n        selected_run.rule_set_version_id, (item ->> \'rule_definition_id\')::uuid,\n        item ->> \'outcome\', (item ->> \'evaluated_count\')::bigint,\n        (item ->> \'missing_count\')::bigint,\n        (item ->> \'unexpected_count\')::bigint,\n        (item ->> \'missing_ratio\')::numeric,\n        (item ->> \'unexpected_ratio\')::numeric,\n        (item ->> \'duration_ms\')::bigint, item ->> \'result_hash\',\n        selected_run.result_retention_policy_id,\n        selected_run.result_retention_policy_number,\n        selected_run.result_retention_policy_hash,\n        selected_run.result_retain_until,\n        selected_run.result_hold_generation, selected_run.result_hold_hash, now_at\n    FROM jsonb_array_elements(p_results) AS item;\n    UPDATE quality.validation_runs\n    SET state = \'SUCCEEDED\', quality_outcome = calculated_outcome,\n        score = calculated_score, passed_count = calculated_passed_count,\n        advisory_failed_count = calculated_advisory_count,\n        blocking_failed_count = calculated_blocking_count, completed_at = now_at,\n        failure_code = NULL, lease_token_hash = NULL,\n        lease_owner_fingerprint = NULL, lease_until = NULL, heartbeat_at = NULL,\n        version = version + 1, updated_at = now_at\n    WHERE workspace_id = p_workspace_id AND id = p_run_id;\n    INSERT INTO quality.run_events (\n        id, workspace_id, run_id, sequence, state, reason_code,\n        actor_id, actor_kind, evidence_hash,\n        audit_retention_policy_id, audit_retention_policy_number,\n        audit_retention_policy_hash, audit_retain_until,\n        audit_hold_generation, audit_hold_hash, occurred_at\n    )\n    SELECT\n        gen_random_uuid(), p_workspace_id, p_run_id,\n        COALESCE(max(event.sequence), 0) + 1, \'SUCCEEDED\', \'WORKER_COMPLETED\',\n        actor_id, \'SERVICE\',\n        encode(sha256(convert_to(jsonb_build_object(\n            \'contract\', \'QUALITY_RUN_COMPLETION_EVENT_V1\',\n            \'attempt_id\', p_attempt_id::text,\n            \'lease_epoch\', p_lease_epoch,\n            \'normalized_result_hash\', p_normalized_result_hash\n        )::text, \'UTF8\')), \'hex\'),\n        selected_run.audit_retention_policy_id,\n        selected_run.audit_retention_policy_number,\n        selected_run.audit_retention_policy_hash,\n        selected_run.audit_retain_until,\n        selected_run.audit_hold_generation, selected_run.audit_hold_hash, now_at\n    FROM quality.run_events AS event\n    WHERE event.workspace_id = p_workspace_id AND event.run_id = p_run_id;\n    result_document := jsonb_build_object(\n        \'state\', \'SUCCEEDED\', \'quality_outcome\', calculated_outcome,\n        \'score\', calculated_score, \'passed_count\', calculated_passed_count,\n        \'advisory_failed_count\', calculated_advisory_count,\n        \'blocking_failed_count\', calculated_blocking_count\n    );\n    INSERT INTO quality.execution_call_receipts (\n        id, workspace_id, service_subject_id, run_id, attempt_id, lease_epoch,\n        lease_token_hash, call_id_hash, request_hash, result_hash,\n        idempotency_hash, audit_retention_policy_id,\n        audit_retention_policy_number, audit_retention_policy_hash,\n        audit_retain_until, audit_hold_generation, audit_hold_hash,\n        created_at, updated_at\n    )\n    VALUES (\n        gen_random_uuid(), p_workspace_id, actor_id, p_run_id, p_attempt_id,\n        p_lease_epoch, token_hash, call_hash, request_hash,\n        encode(sha256(convert_to(result_document::text, \'UTF8\')), \'hex\'),\n        encode(sha256(convert_to(\n            \'QUALITY_EXECUTION_IDEMPOTENCY_V1:\' || actor_id::text || \':\' ||\n            p_run_id::text || \':\' || call_hash, \'UTF8\'\n        )), \'hex\'),\n        selected_run.audit_retention_policy_id,\n        selected_run.audit_retention_policy_number,\n        selected_run.audit_retention_policy_hash,\n        selected_run.audit_retain_until,\n        selected_run.audit_hold_generation, selected_run.audit_hold_hash,\n        now_at, now_at\n    );\n    INSERT INTO integration.outbox_events (\n        id, workspace_id, aggregate_type, aggregate_id, event_type,\n        schema_version, payload, created_at, published_at,\n        dead_lettered_at, lease_until, attempts, last_error_code\n    )\n    VALUES (\n        gen_random_uuid(), p_workspace_id, \'quality_validation_run\', p_run_id,\n        \'quality.validation_run.succeeded.v1\', 1,\n        jsonb_build_object(\n            \'run_id\', p_run_id::text, \'state\', \'SUCCEEDED\',\n            \'quality_outcome\', calculated_outcome, \'score\', calculated_score\n        ),\n        now_at, NULL, NULL, NULL, 0, NULL\n    );\n    RETURN true;\nEND\n$$;')
        op.execute('REVOKE ALL ON FUNCTION quality.complete_validation_run_v1(\n    uuid, uuid, uuid, bigint, text, text, text, text, text, jsonb\n) FROM PUBLIC;')
        op.execute("CREATE OR REPLACE FUNCTION quality.fail_validation_run_v1(\n    p_workspace_id uuid,\n    p_run_id uuid,\n    p_attempt_id uuid,\n    p_lease_epoch bigint,\n    p_lease_token text,\n    p_call_id text,\n    p_failure_code text,\n    p_retryable boolean\n)\nRETURNS boolean\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, quality, integration\nAS $$\nDECLARE\n    selected_run quality.validation_runs%ROWTYPE;\n    selected_version quality.rule_set_versions%ROWTYPE;\n    actor_id uuid := NULLIF(current_setting('app.subject_id', true), '')::uuid;\n    token_hash text;\n    call_hash text;\n    request_hash text;\n    target_state text;\n    attempt_state text;\n    event_type text;\n    now_at timestamptz := transaction_timestamp();\n    existing_receipt quality.execution_call_receipts%ROWTYPE;\nBEGIN\n    token_hash := encode(sha256(convert_to(COALESCE(p_lease_token, ''), 'UTF8')), 'hex');\n    call_hash := encode(sha256(convert_to(COALESCE(p_call_id, ''), 'UTF8')), 'hex');\n    request_hash := encode(sha256(convert_to(jsonb_build_object(\n        'contract', 'QUALITY_EXECUTION_FAILURE_REQUEST_V1',\n        'run_id', p_run_id::text, 'attempt_id', p_attempt_id::text,\n        'lease_epoch', p_lease_epoch, 'lease_token_hash', token_hash,\n        'failure_code', p_failure_code, 'retryable', p_retryable\n    )::text, 'UTF8')), 'hex');\n    SELECT * INTO existing_receipt\n    FROM quality.execution_call_receipts AS receipt\n    WHERE receipt.workspace_id = p_workspace_id\n      AND receipt.service_subject_id = actor_id\n      AND receipt.run_id = p_run_id\n      AND receipt.call_id_hash = call_hash;\n    IF FOUND THEN\n        IF existing_receipt.request_hash <> request_hash THEN\n            RAISE EXCEPTION 'Quality execution idempotency conflict'\n                USING ERRCODE = '23505';\n        END IF;\n        RETURN true;\n    END IF;\n    SELECT * INTO selected_run\n    FROM quality.validation_runs AS run\n    WHERE run.workspace_id = p_workspace_id AND run.id = p_run_id\n    FOR UPDATE;\n    SELECT * INTO selected_version\n    FROM quality.rule_set_versions AS version\n    WHERE version.workspace_id = p_workspace_id\n      AND version.id = selected_run.rule_set_version_id;\n    IF p_workspace_id IS DISTINCT FROM\n           NULLIF(current_setting('app.workspace_id', true), '')::uuid\n       OR char_length(COALESCE(p_call_id, '')) NOT BETWEEN 1 AND 200\n       OR COALESCE(p_failure_code, '') !~ '^[A-Z][A-Z0-9_]{0,99}$'\n       OR NOT quality.current_quality_service_can_v1(\n           p_workspace_id, 'quality.execute', selected_version.classification,\n           selected_version.system_id, selected_version.domain_id\n       )\n       OR selected_run.state NOT IN ('RUNNING','CANCEL_REQUESTED')\n       OR selected_run.current_attempt_id <> p_attempt_id\n       OR selected_run.lease_epoch <> p_lease_epoch\n       OR selected_run.lease_token_hash <> token_hash\n       OR selected_run.lease_until <= now_at THEN\n        RAISE EXCEPTION 'Quality failure fence denied'\n            USING ERRCODE = '42501';\n    END IF;\n    IF selected_run.state = 'CANCEL_REQUESTED' THEN\n        target_state := 'CANCELLED';\n        attempt_state := 'CANCELLED';\n    ELSIF p_retryable AND selected_run.attempt_count < selected_run.maximum_attempts THEN\n        target_state := 'RETRY_WAIT';\n        attempt_state := 'RETRYABLE_FAILED';\n    ELSE\n        target_state := 'FAILED';\n        attempt_state := 'FAILED';\n    END IF;\n    event_type := CASE target_state\n        WHEN 'RETRY_WAIT' THEN 'quality.validation_run.retry_wait.v1'\n        WHEN 'CANCELLED' THEN 'quality.validation_run.cancelled.v1'\n        ELSE 'quality.validation_run.failed.v1'\n    END;\n    UPDATE quality.validation_attempts\n    SET state = attempt_state, failure_code = p_failure_code, finished_at = now_at\n    WHERE workspace_id = p_workspace_id AND id = p_attempt_id\n      AND run_id = p_run_id AND state = 'RUNNING'\n      AND lease_epoch = p_lease_epoch AND lease_token_hash = token_hash;\n    UPDATE quality.validation_runs\n    SET state = target_state, quality_outcome = 'UNKNOWN', score = NULL,\n        completed_at = CASE\n            WHEN target_state IN ('FAILED','CANCELLED') THEN now_at ELSE NULL\n        END,\n        next_attempt_at = CASE\n            WHEN target_state = 'RETRY_WAIT' THEN now_at + interval '30 seconds'\n            ELSE next_attempt_at\n        END,\n        failure_code = p_failure_code, lease_token_hash = NULL,\n        lease_owner_fingerprint = NULL, lease_until = NULL, heartbeat_at = NULL,\n        version = version + 1, updated_at = now_at\n    WHERE workspace_id = p_workspace_id AND id = p_run_id;\n    INSERT INTO quality.run_events (\n        id, workspace_id, run_id, sequence, state, reason_code,\n        actor_id, actor_kind, evidence_hash,\n        audit_retention_policy_id, audit_retention_policy_number,\n        audit_retention_policy_hash, audit_retain_until,\n        audit_hold_generation, audit_hold_hash, occurred_at\n    )\n    SELECT\n        gen_random_uuid(), p_workspace_id, p_run_id,\n        COALESCE(max(event.sequence), 0) + 1, target_state,\n        CASE target_state\n            WHEN 'RETRY_WAIT' THEN 'WORKER_RETRYABLE_FAILURE'\n            WHEN 'CANCELLED' THEN 'WORKER_CANCELLED'\n            ELSE 'WORKER_FAILURE'\n        END,\n        actor_id, 'SERVICE',\n        encode(sha256(convert_to(jsonb_build_object(\n            'contract', 'QUALITY_RUN_FAILURE_EVENT_V1',\n            'attempt_id', p_attempt_id::text,\n            'lease_epoch', p_lease_epoch,\n            'failure_code', p_failure_code,\n            'state', target_state\n        )::text, 'UTF8')), 'hex'),\n        selected_run.audit_retention_policy_id,\n        selected_run.audit_retention_policy_number,\n        selected_run.audit_retention_policy_hash,\n        selected_run.audit_retain_until,\n        selected_run.audit_hold_generation, selected_run.audit_hold_hash, now_at\n    FROM quality.run_events AS event\n    WHERE event.workspace_id = p_workspace_id AND event.run_id = p_run_id;\n    INSERT INTO quality.execution_call_receipts (\n        id, workspace_id, service_subject_id, run_id, attempt_id, lease_epoch,\n        lease_token_hash, call_id_hash, request_hash, result_hash,\n        idempotency_hash, audit_retention_policy_id,\n        audit_retention_policy_number, audit_retention_policy_hash,\n        audit_retain_until, audit_hold_generation, audit_hold_hash,\n        created_at, updated_at\n    )\n    VALUES (\n        gen_random_uuid(), p_workspace_id, actor_id, p_run_id, p_attempt_id,\n        p_lease_epoch, token_hash, call_hash, request_hash,\n        encode(sha256(convert_to(jsonb_build_object(\n            'state', target_state, 'failure_code', p_failure_code\n        )::text, 'UTF8')), 'hex'),\n        encode(sha256(convert_to(\n            'QUALITY_EXECUTION_IDEMPOTENCY_V1:' || actor_id::text || ':' ||\n            p_run_id::text || ':' || call_hash, 'UTF8'\n        )), 'hex'),\n        selected_run.audit_retention_policy_id,\n        selected_run.audit_retention_policy_number,\n        selected_run.audit_retention_policy_hash,\n        selected_run.audit_retain_until,\n        selected_run.audit_hold_generation, selected_run.audit_hold_hash,\n        now_at, now_at\n    );\n    INSERT INTO integration.outbox_events (\n        id, workspace_id, aggregate_type, aggregate_id, event_type,\n        schema_version, payload, created_at, published_at,\n        dead_lettered_at, lease_until, attempts, last_error_code\n    )\n    VALUES (\n        gen_random_uuid(), p_workspace_id, 'quality_validation_run', p_run_id,\n        event_type, 1,\n        jsonb_build_object(\n            'run_id', p_run_id::text, 'state', target_state,\n            'failure_code', p_failure_code\n        ),\n        now_at, NULL, NULL, NULL, 0, NULL\n    );\n    RETURN true;\nEND\n$$;")
        op.execute('REVOKE ALL ON FUNCTION quality.fail_validation_run_v1(\n    uuid, uuid, uuid, bigint, text, text, text, boolean\n) FROM PUBLIC;')
        op.execute("DO $$\nBEGIN\n    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'datariver_app') THEN\n        GRANT EXECUTE ON FUNCTION quality.dispatch_due_validation_runs_v1(\n            uuid, text, integer, integer\n        ) TO datariver_app;\n    END IF;\n    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'datariver_quality') THEN\n        REVOKE ALL PRIVILEGES ON ALL TABLES IN SCHEMA quality, catalog, integration\n            FROM datariver_quality;\n        REVOKE ALL PRIVILEGES ON ALL SEQUENCES IN SCHEMA quality, catalog, integration\n            FROM datariver_quality;\n        REVOKE ALL PRIVILEGES ON ALL FUNCTIONS IN SCHEMA quality\n            FROM datariver_quality;\n        GRANT USAGE ON SCHEMA quality TO datariver_quality;\n        GRANT EXECUTE ON FUNCTION quality.claim_validation_run_v1(\n            uuid, text, text, integer\n        ) TO datariver_quality;\n        GRANT EXECUTE ON FUNCTION quality.freeze_source_access_v1(\n            uuid, uuid, uuid, bigint, text, integer, integer, integer, integer\n        ) TO datariver_quality;\n        GRANT EXECUTE ON FUNCTION quality.assert_source_statement_fence_v1(\n            uuid, uuid, uuid, bigint, text\n        ) TO datariver_quality;\n        GRANT EXECUTE ON FUNCTION quality.complete_validation_run_v1(\n            uuid, uuid, uuid, bigint, text, text, text, text, text, jsonb\n        ) TO datariver_quality;\n        GRANT EXECUTE ON FUNCTION quality.fail_validation_run_v1(\n            uuid, uuid, uuid, bigint, text, text, text, boolean\n        ) TO datariver_quality;\n    END IF;\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION quality.review_rule_set_version_command_v2(\n    p_workspace_id uuid,\n    p_version_id uuid,\n    p_decision text,\n    p_reason text,\n    p_policy_decision_id uuid,\n    p_expected_version integer\n)\nRETURNS uuid\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, quality, retention\nAS $$\nDECLARE\n    candidate quality.rule_set_versions%ROWTYPE;\n    evidence record;\n    audit_binding record;\nBEGIN\n    SELECT * INTO candidate\n    FROM quality.rule_set_versions\n    WHERE workspace_id = p_workspace_id AND id = p_version_id;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'Quality Rule Set Version is unavailable'\n            USING ERRCODE = '42501';\n    END IF;\n    SELECT * INTO evidence\n    FROM quality.require_human_decision_v1(\n        p_workspace_id,\n        NULLIF(current_setting('app.subject_id', true), '')::uuid,\n        p_version_id,\n        'quality.rule.review',\n        p_policy_decision_id,\n        false\n    );\n    SELECT * INTO audit_binding\n    FROM retention.resolve_quality_binding_v1(\n        p_workspace_id,\n        'QUALITY_AUDIT',\n        'QUALITY_RULE_SET',\n        candidate.rule_set_id,\n        transaction_timestamp()\n    );\n    RETURN quality.review_rule_set_version_v1(\n        p_workspace_id,\n        p_version_id,\n        p_decision,\n        p_reason,\n        p_policy_decision_id,\n        evidence.assurance_hash,\n        p_expected_version,\n        audit_binding.policy_id,\n        audit_binding.policy_number,\n        audit_binding.policy_hash,\n        audit_binding.retain_until,\n        audit_binding.hold_generation,\n        audit_binding.hold_hash\n    );\nEND\n$$;")
        op.execute('REVOKE ALL ON FUNCTION quality.review_rule_set_version_command_v2(\n    uuid, uuid, text, text, uuid, integer\n) FROM PUBLIC;')
        op.execute("CREATE OR REPLACE FUNCTION quality.activate_rule_set_version_command_v2(\n    p_workspace_id uuid,\n    p_version_id uuid,\n    p_policy_decision_id uuid,\n    p_idempotency_key_hash text,\n    p_expected_version integer\n)\nRETURNS uuid\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, quality, retention\nAS $$\nDECLARE\n    candidate quality.rule_set_versions%ROWTYPE;\n    evidence record;\n    rule_binding record;\n    audit_binding record;\n    schedule_binding_hash text;\n    retention_binding_hash text;\nBEGIN\n    SELECT * INTO candidate\n    FROM quality.rule_set_versions\n    WHERE workspace_id = p_workspace_id AND id = p_version_id;\n    IF NOT FOUND OR candidate.schedule_mode <> 'MANUAL_ONLY'\n       OR p_idempotency_key_hash !~ '^[0-9a-f]{64}$' THEN\n        RAISE EXCEPTION 'Quality Rule Set Version is unavailable'\n            USING ERRCODE = '42501';\n    END IF;\n    SELECT * INTO evidence\n    FROM quality.require_human_decision_v1(\n        p_workspace_id,\n        NULLIF(current_setting('app.subject_id', true), '')::uuid,\n        p_version_id,\n        'quality.rule.activate',\n        p_policy_decision_id,\n        true\n    );\n    SELECT * INTO rule_binding\n    FROM retention.resolve_quality_binding_v1(\n        p_workspace_id,\n        'QUALITY_RULE',\n        'QUALITY_RULE_SET',\n        candidate.rule_set_id,\n        transaction_timestamp()\n    );\n    SELECT * INTO audit_binding\n    FROM retention.resolve_quality_binding_v1(\n        p_workspace_id,\n        'QUALITY_AUDIT',\n        'QUALITY_RULE_SET',\n        candidate.rule_set_id,\n        transaction_timestamp()\n    );\n    schedule_binding_hash := encode(sha256(convert_to(jsonb_build_object(\n        'contract', 'QUALITY_SCHEDULE_BINDING_V1',\n        'mode', candidate.schedule_mode,\n        'profile_id', candidate.schedule_profile_id,\n        'profile_version', candidate.schedule_profile_version,\n        'profile_hash', candidate.schedule_profile_hash\n    )::text, 'UTF8')), 'hex');\n    retention_binding_hash := encode(sha256(convert_to(jsonb_build_object(\n        'contract', 'QUALITY_COMMAND_RETENTION_BINDING_V1',\n        'rule_policy_id', rule_binding.policy_id::text,\n        'rule_policy_number', rule_binding.policy_number,\n        'rule_policy_hash', rule_binding.policy_hash,\n        'rule_retain_until', rule_binding.retain_until,\n        'rule_hold_generation', rule_binding.hold_generation,\n        'rule_hold_hash', rule_binding.hold_hash,\n        'audit_policy_id', audit_binding.policy_id::text,\n        'audit_policy_number', audit_binding.policy_number,\n        'audit_policy_hash', audit_binding.policy_hash,\n        'audit_retain_until', audit_binding.retain_until,\n        'audit_hold_generation', audit_binding.hold_generation,\n        'audit_hold_hash', audit_binding.hold_hash\n    )::text, 'UTF8')), 'hex');\n    RETURN quality.activate_rule_set_version_v1(\n        p_workspace_id,\n        p_version_id,\n        p_policy_decision_id,\n        evidence.assurance_hash,\n        evidence.authorization_hash,\n        schedule_binding_hash,\n        retention_binding_hash,\n        p_idempotency_key_hash,\n        p_expected_version,\n        audit_binding.policy_id,\n        audit_binding.policy_number,\n        audit_binding.policy_hash,\n        audit_binding.retain_until,\n        audit_binding.hold_generation,\n        audit_binding.hold_hash\n    );\nEND\n$$;")
        op.execute('REVOKE ALL ON FUNCTION quality.activate_rule_set_version_command_v2(\n    uuid, uuid, uuid, text, integer\n) FROM PUBLIC;')
        op.execute("CREATE OR REPLACE FUNCTION quality.request_manual_validation_run_v1(\n    p_workspace_id uuid,\n    p_rule_set_id uuid,\n    p_policy_decision_id uuid\n)\nRETURNS uuid\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, quality, catalog, retention, integration\nAS $$\nDECLARE\n    actor_id uuid := NULLIF(current_setting('app.subject_id', true), '')::uuid;\n    parent quality.rule_sets%ROWTYPE;\n    candidate quality.rule_set_versions%ROWTYPE;\n    result_binding record;\n    audit_binding record;\n    decision_evidence record;\n    run_id uuid := gen_random_uuid();\n    cutoff_at timestamptz := transaction_timestamp();\n    profile_context_hash text;\n    security_context_hash text;\nBEGIN\n    IF p_workspace_id IS DISTINCT FROM\n       NULLIF(current_setting('app.workspace_id', true), '')::uuid THEN\n        RAISE EXCEPTION 'invalid Quality manual Run request'\n            USING ERRCODE = '42501';\n    END IF;\n    SELECT * INTO parent\n    FROM quality.rule_sets\n    WHERE workspace_id = p_workspace_id\n      AND id = p_rule_set_id\n      AND state = 'ACTIVE'\n    FOR KEY SHARE;\n    SELECT * INTO candidate\n    FROM quality.rule_set_versions\n    WHERE workspace_id = p_workspace_id\n      AND rule_set_id = p_rule_set_id\n      AND state = 'ACTIVE'\n    FOR KEY SHARE;\n    IF parent.id IS NULL\n       OR candidate.id IS NULL\n       OR candidate.schedule_mode <> 'MANUAL_ONLY'\n       OR NOT EXISTS (\n           SELECT 1\n           FROM quality.rule_definitions AS definition\n           WHERE definition.workspace_id = p_workspace_id\n             AND definition.rule_set_version_id = candidate.id\n       )\n       OR NOT quality.current_target_matches_v1(\n           p_workspace_id,\n           candidate.asset_id,\n           candidate.classification,\n           candidate.system_id,\n           candidate.domain_id,\n           candidate.lifecycle,\n           candidate.source_version,\n           'quality.run.request'\n       ) THEN\n        RAISE EXCEPTION 'invalid Quality manual Run request'\n            USING ERRCODE = '42501';\n    END IF;\n    SELECT * INTO decision_evidence\n    FROM quality.require_human_decision_v1(\n        p_workspace_id,\n        actor_id,\n        candidate.id,\n        'quality.run.request',\n        p_policy_decision_id,\n        false\n    );\n    SELECT * INTO result_binding\n    FROM retention.resolve_quality_binding_v1(\n        p_workspace_id,\n        'QUALITY_RESULT',\n        'QUALITY_VALIDATION_RUN',\n        run_id,\n        cutoff_at\n    );\n    SELECT * INTO audit_binding\n    FROM retention.resolve_quality_binding_v1(\n        p_workspace_id,\n        'QUALITY_AUDIT',\n        'QUALITY_VALIDATION_RUN',\n        run_id,\n        cutoff_at\n    );\n    SELECT COALESCE(\n        (\n            SELECT snapshot.snapshot_identity_hash\n            FROM catalog.asset_profile_snapshots AS snapshot\n            WHERE snapshot.workspace_id = p_workspace_id\n              AND snapshot.asset_id = candidate.asset_id\n              AND snapshot.asset_source_version = candidate.source_version\n              AND snapshot.profile_kind IN ('FULL', 'PARTITION')\n              AND snapshot.completeness = 'COMPLETE'\n              AND snapshot.stale_at > cutoff_at\n              AND snapshot.profile_retain_until > cutoff_at\n            ORDER BY snapshot.profiled_at DESC, snapshot.id DESC\n            LIMIT 1\n        ),\n        encode(sha256(convert_to(\n            'QUALITY_PROFILE_CONTEXT_UNAVAILABLE_V1', 'UTF8'\n        )), 'hex')\n    ) INTO profile_context_hash;\n    security_context_hash := encode(sha256(convert_to(jsonb_build_object(\n        'contract', 'QUALITY_SECURITY_CONTEXT_V1',\n        'asset_id', candidate.asset_id::text,\n        'classification', candidate.classification,\n        'system_id', candidate.system_id::text,\n        'domain_id', candidate.domain_id::text,\n        'lifecycle', candidate.lifecycle,\n        'source_version', candidate.source_version\n    )::text, 'UTF8')), 'hex');\n\n    INSERT INTO quality.validation_runs (\n        id, workspace_id, rule_set_id, rule_set_version_id, asset_id,\n        target_binding_hash, schema_hash,\n        source_connection_profile_id, source_connection_profile_version,\n        source_connection_profile_hash,\n        workload_profile_id, workload_profile_version, workload_profile_hash,\n        security_context_hash, datahub_profile_context_hash,\n        score_policy_id, score_policy_version, score_policy_hash,\n        retry_of_run_id, trigger_kind, requested_by,\n        schedule_id, schedule_version, canonical_window_key, due_at, is_late,\n        state, quality_outcome, score, passed_count,\n        advisory_failed_count, blocking_failed_count,\n        current_attempt_id, attempt_count, maximum_attempts, next_attempt_at,\n        lease_epoch, lease_token_hash, lease_owner_fingerprint, lease_until,\n        heartbeat_at, source_started_at, source_access_deadline,\n        hard_timeout_contract_hash, completed_at, failure_code,\n        result_retention_kind, result_retention_policy_id,\n        result_retention_policy_number, result_retention_policy_hash,\n        result_retention_basis_at, result_retain_until,\n        result_hold_generation, result_hold_hash,\n        audit_retention_kind, audit_retention_policy_id,\n        audit_retention_policy_number, audit_retention_policy_hash,\n        audit_retention_basis_at, audit_retain_until,\n        audit_hold_generation, audit_hold_hash,\n        created_at, updated_at, version\n    )\n    VALUES (\n        run_id, p_workspace_id, candidate.rule_set_id,\n        candidate.id, candidate.asset_id,\n        candidate.target_binding_hash, candidate.schema_hash,\n        candidate.source_connection_profile_id,\n        candidate.source_connection_profile_version,\n        candidate.source_connection_profile_hash,\n        candidate.workload_profile_id,\n        candidate.workload_profile_version,\n        candidate.workload_profile_hash,\n        security_context_hash, profile_context_hash,\n        candidate.score_policy_id,\n        candidate.score_policy_version,\n        candidate.score_policy_hash,\n        NULL, 'MANUAL', actor_id,\n        NULL, NULL, NULL, NULL, false,\n        'QUEUED', 'UNKNOWN', NULL, NULL, NULL, NULL,\n        NULL, 0, 3, cutoff_at, 0, NULL, NULL, NULL,\n        NULL, NULL, NULL, candidate.workload_profile_hash, NULL, NULL,\n        'QUALITY_RESULT', result_binding.policy_id, result_binding.policy_number,\n        result_binding.policy_hash, cutoff_at, result_binding.retain_until,\n        result_binding.hold_generation, result_binding.hold_hash,\n        'QUALITY_AUDIT', audit_binding.policy_id, audit_binding.policy_number,\n        audit_binding.policy_hash, cutoff_at, audit_binding.retain_until,\n        audit_binding.hold_generation, audit_binding.hold_hash,\n        cutoff_at, cutoff_at, 1\n    );\n    INSERT INTO quality.run_events (\n        id, workspace_id, run_id, sequence, state, reason_code,\n        actor_id, actor_kind, evidence_hash,\n        audit_retention_policy_id, audit_retention_policy_number,\n        audit_retention_policy_hash, audit_retain_until,\n        audit_hold_generation, audit_hold_hash, occurred_at\n    )\n    VALUES (\n        gen_random_uuid(), p_workspace_id, run_id, 1, 'QUEUED',\n        'MANUAL_REQUEST_ACCEPTED', actor_id, 'HUMAN',\n        decision_evidence.authorization_hash,\n        audit_binding.policy_id, audit_binding.policy_number,\n        audit_binding.policy_hash, audit_binding.retain_until,\n        audit_binding.hold_generation, audit_binding.hold_hash, cutoff_at\n    );\n    INSERT INTO integration.outbox_events (\n        id, workspace_id, aggregate_type, aggregate_id, event_type,\n        schema_version, payload, created_at, published_at,\n        dead_lettered_at, lease_until, attempts, last_error_code\n    )\n    VALUES (\n        gen_random_uuid(), p_workspace_id, 'quality_validation_run', run_id,\n        'quality.validation_run.queued.v1', 1,\n        jsonb_build_object('run_id', run_id::text, 'state', 'QUEUED'),\n        cutoff_at, NULL, NULL, NULL, 0, NULL\n    );\n    RETURN run_id;\nEND\n$$;")
        op.execute('REVOKE ALL ON FUNCTION quality.request_manual_validation_run_v1(\n    uuid, uuid, uuid\n) FROM PUBLIC;')
        op.execute("DO $$\nBEGIN\n    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'datariver_app') THEN\n        GRANT EXECUTE ON FUNCTION quality.review_rule_set_version_command_v2(\n            uuid, uuid, text, text, uuid, integer\n        ) TO datariver_app;\n        GRANT EXECUTE ON FUNCTION quality.activate_rule_set_version_command_v2(\n            uuid, uuid, uuid, text, integer\n        ) TO datariver_app;\n        GRANT EXECUTE ON FUNCTION quality.request_manual_validation_run_v1(\n            uuid, uuid, uuid\n        ) TO datariver_app;\n    END IF;\nEND\n$$;")
        op.execute("DO $$\nBEGIN\n    IF NOT EXISTS (\n        SELECT 1 FROM pg_roles\n        WHERE rolname = 'datariver_app'\n          AND rolcanlogin IS TRUE\n          AND rolsuper IS FALSE\n          AND rolcreatedb IS FALSE\n          AND rolcreaterole IS FALSE\n          AND rolreplication IS FALSE\n          AND rolbypassrls IS FALSE\n    ) THEN\n        RAISE EXCEPTION 'required role datariver_app is missing';\n    END IF;\n    IF NOT EXISTS (\n        SELECT 1 FROM pg_roles\n        WHERE rolname = 'datariver_governance_document'\n          AND rolcanlogin IS TRUE\n          AND rolsuper IS FALSE\n          AND rolcreatedb IS FALSE\n          AND rolcreaterole IS FALSE\n          AND rolreplication IS FALSE\n          AND rolbypassrls IS FALSE\n    ) THEN\n        RAISE EXCEPTION\n            'datariver_governance_document must be a safe NOBYPASSRLS login role';\n    END IF;\n    IF EXISTS (\n        SELECT 1\n        FROM pg_auth_members AS membership\n        JOIN pg_roles AS member_role ON member_role.oid = membership.member\n        JOIN pg_roles AS granted_role ON granted_role.oid = membership.roleid\n        WHERE member_role.rolname = 'datariver_governance_document'\n           OR (\n               granted_role.rolname = 'datariver_governance_document'\n               AND member_role.rolname NOT IN (\n                   current_user, session_user, 'datariver_migrator'\n               )\n           )\n    ) THEN\n        RAISE EXCEPTION 'datariver_governance_document role membership is unsafe';\n    END IF;\nEND\n$$")
        op.execute("CREATE OR REPLACE FUNCTION governance.current_human_can_document_v1(\n    p_workspace_id uuid,\n    p_action text,\n    p_classification integer,\n    p_system_id uuid,\n    p_domain_id uuid\n)\nRETURNS boolean\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = pg_catalog, platform, iam\nAS $$\n    SELECT EXISTS (\n        SELECT 1\n        FROM platform.workspaces AS workspace\n        JOIN iam.workspace_memberships AS membership\n          ON membership.workspace_id = workspace.id\n        JOIN iam.subjects AS subject\n          ON subject.id = membership.subject_id\n        WHERE workspace.id = p_workspace_id\n          AND workspace.status = 'ACTIVE'\n          AND membership.subject_id =\n              NULLIF(current_setting('app.subject_id', true), '')::uuid\n          AND subject.active IS TRUE\n          AND membership.active IS TRUE\n          AND (\n              membership.access_expires_at IS NULL\n              OR membership.access_expires_at > transaction_timestamp()\n          )\n          AND COALESCE(membership.job_function, '') <> 'SERVICE_ACCOUNT'\n          AND NOT (\n              COALESCE(membership.attributes -> 'groups', '[]'::jsonb)\n              ? 'service-accounts'\n          )\n          AND membership.clearance >= p_classification\n          AND (\n              p_system_id IS NULL\n              OR p_classification = 0\n              OR COALESCE(\n                  membership.attributes -> 'allowed_system_ids',\n                  '[]'::jsonb\n              ) ? p_system_id::text\n          )\n          AND (\n              p_domain_id IS NULL\n              OR p_classification = 0\n              OR COALESCE(\n                  membership.attributes -> 'allowed_domain_ids',\n                  '[]'::jsonb\n              ) ? p_domain_id::text\n          )\n          AND COALESCE(\n              membership.attributes -> 'allowed_actions',\n              '[]'::jsonb\n          ) ? p_action\n          AND NOT (\n              COALESCE(\n                  membership.attributes -> 'denied_actions',\n                  '[]'::jsonb\n              ) ? p_action\n          )\n    )\n$$;")
        op.execute('REVOKE ALL ON FUNCTION governance.current_human_can_document_v1(\n    uuid, text, integer, uuid, uuid\n) FROM PUBLIC;')
        op.execute('GRANT EXECUTE ON FUNCTION governance.current_human_can_document_v1(\n    uuid, text, integer, uuid, uuid\n) TO datariver_app;')
        op.execute("CREATE OR REPLACE FUNCTION governance.can_read_document_v1(p_document_id uuid)\nRETURNS boolean\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = pg_catalog, governance\nAS $$\n    SELECT governance.current_human_can_document_v1(\n        document.workspace_id,\n        CASE\n            WHEN document.kind = 'TEMPLATE' THEN 'governance.template.read'\n            WHEN document.state = 'ARCHIVED' THEN 'governance.document.history.read'\n            ELSE 'governance.document.read'\n        END,\n        document.classification,\n        document.system_id,\n        document.domain_id\n    )\n    FROM governance.documents AS document\n    WHERE document.id = p_document_id\n      AND document.workspace_id =\n          NULLIF(current_setting('app.workspace_id', true), '')::uuid\n$$;")
        op.execute('REVOKE ALL ON FUNCTION governance.can_read_document_v1(uuid) FROM PUBLIC;')
        op.execute('GRANT EXECUTE ON FUNCTION governance.can_read_document_v1(uuid) TO datariver_app;')
        op.execute("CREATE OR REPLACE FUNCTION governance.can_act_on_document_v1(\n    p_document_id uuid,\n    p_document_action text,\n    p_template_action text\n)\nRETURNS boolean\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = pg_catalog, governance\nAS $$\n    SELECT governance.current_human_can_document_v1(\n        document.workspace_id,\n        CASE WHEN document.kind = 'TEMPLATE'\n             THEN p_template_action ELSE p_document_action END,\n        document.classification,\n        document.system_id,\n        document.domain_id\n    )\n    FROM governance.documents AS document\n    WHERE document.id = p_document_id\n      AND document.workspace_id =\n          NULLIF(current_setting('app.workspace_id', true), '')::uuid\n$$;")
        op.execute('REVOKE ALL ON FUNCTION governance.can_act_on_document_v1(\n    uuid, text, text\n) FROM PUBLIC;')
        op.execute('GRANT EXECUTE ON FUNCTION governance.can_act_on_document_v1(\n    uuid, text, text\n) TO datariver_app;')
        op.execute("CREATE OR REPLACE FUNCTION governance.reject_document_evidence_mutation_v1()\nRETURNS trigger\nLANGUAGE plpgsql\nAS $$\nBEGIN\n    RAISE EXCEPTION 'Governance Document evidence is immutable'\n        USING ERRCODE = '55000';\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION governance.enforce_document_mutation_v1()\nRETURNS trigger\nLANGUAGE plpgsql\nAS $$\nDECLARE\n    required_action text;\nBEGIN\n    IF TG_OP = 'DELETE' THEN\n        RAISE EXCEPTION 'Governance Documents are logically archived, never deleted'\n            USING ERRCODE = '55000';\n    END IF;\n    IF NEW.id IS DISTINCT FROM OLD.id\n       OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id\n       OR NEW.kind IS DISTINCT FROM OLD.kind\n       OR NEW.category IS DISTINCT FROM OLD.category\n       OR NEW.classification IS DISTINCT FROM OLD.classification\n       OR NEW.owner_subject_id IS DISTINCT FROM OLD.owner_subject_id\n       OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN\n        RAISE EXCEPTION 'Governance Document identity is immutable'\n            USING ERRCODE = '55000';\n    END IF;\n    IF NEW.state = 'ARCHIVED' AND OLD.state <> 'ARCHIVED' THEN\n        required_action := CASE WHEN NEW.kind = 'TEMPLATE'\n            THEN 'governance.template.archive'\n            ELSE 'governance.document.archive' END;\n    ELSIF NEW.current_published_version_id IS DISTINCT FROM\n          OLD.current_published_version_id THEN\n        required_action := CASE WHEN NEW.kind = 'TEMPLATE'\n            THEN 'governance.template.activate'\n            ELSE 'governance.document.publish' END;\n    ELSE\n        required_action := CASE WHEN NEW.kind = 'TEMPLATE'\n            THEN 'governance.template.propose'\n            ELSE 'governance.document.edit' END;\n    END IF;\n    IF NOT governance.current_human_can_document_v1(\n        NEW.workspace_id,\n        required_action,\n        NEW.classification,\n        NEW.system_id,\n        NEW.domain_id\n    ) AND NOT (\n        required_action = 'governance.document.edit'\n        AND governance.current_human_can_document_v1(\n            NEW.workspace_id,\n            'governance.document.review',\n            NEW.classification,\n            NEW.system_id,\n            NEW.domain_id\n        )\n    ) AND NOT (\n        required_action = 'governance.template.propose'\n        AND governance.current_human_can_document_v1(\n            NEW.workspace_id,\n            'governance.template.review',\n            NEW.classification,\n            NEW.system_id,\n            NEW.domain_id\n        )\n    ) THEN\n        RAISE EXCEPTION 'Governance Document transition is not authorized'\n            USING ERRCODE = '42501';\n    END IF;\n    IF NEW.state = 'ARCHIVED' AND (\n        NEW.archived_at IS NULL OR NEW.archived_by IS DISTINCT FROM\n        NULLIF(current_setting('app.subject_id', true), '')::uuid\n    ) THEN\n        RAISE EXCEPTION 'Governance Document archive evidence is invalid'\n            USING ERRCODE = '55000';\n    END IF;\n    RETURN NEW;\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION governance.enforce_document_version_mutation_v1()\nRETURNS trigger\nLANGUAGE plpgsql\nAS $$\nDECLARE\n    parent governance.documents%ROWTYPE;\n    required_action text;\nBEGIN\n    IF TG_OP = 'DELETE' THEN\n        RAISE EXCEPTION 'Governance Document versions are immutable'\n            USING ERRCODE = '55000';\n    END IF;\n    IF NEW.id IS DISTINCT FROM OLD.id\n       OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id\n       OR NEW.document_id IS DISTINCT FROM OLD.document_id\n       OR NEW.version_number IS DISTINCT FROM OLD.version_number\n       OR NEW.version_tag IS DISTINCT FROM OLD.version_tag\n       OR NEW.title IS DISTINCT FROM OLD.title\n       OR NEW.summary IS DISTINCT FROM OLD.summary\n       OR NEW.applicability_scope IS DISTINCT FROM OLD.applicability_scope\n       OR NEW.sanitized_html IS DISTINCT FROM OLD.sanitized_html\n       OR NEW.plain_text IS DISTINCT FROM OLD.plain_text\n       OR NEW.content_sha256 IS DISTINCT FROM OLD.content_sha256\n       OR NEW.size_bytes IS DISTINCT FROM OLD.size_bytes\n       OR NEW.sanitizer_policy_version IS DISTINCT FROM OLD.sanitizer_policy_version\n       OR NEW.sanitizer_policy_sha256 IS DISTINCT FROM OLD.sanitizer_policy_sha256\n       OR NEW.source_format IS DISTINCT FROM OLD.source_format\n       OR NEW.source_template_version_id IS DISTINCT FROM OLD.source_template_version_id\n       OR NEW.author_id IS DISTINCT FROM OLD.author_id\n       OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN\n        RAISE EXCEPTION 'Governance Document version content is immutable'\n            USING ERRCODE = '55000';\n    END IF;\n    SELECT * INTO parent\n    FROM governance.documents\n    WHERE workspace_id = NEW.workspace_id AND id = NEW.document_id;\n    IF current_user = 'datariver_governance_document' THEN\n        IF NEW.state IS DISTINCT FROM OLD.state\n           OR NEW.submitted_at IS DISTINCT FROM OLD.submitted_at\n           OR NEW.reviewed_by IS DISTINCT FROM OLD.reviewed_by\n           OR NEW.reviewed_at IS DISTINCT FROM OLD.reviewed_at\n           OR NEW.published_at IS DISTINCT FROM OLD.published_at THEN\n            RAISE EXCEPTION 'Projection worker cannot change publication state'\n                USING ERRCODE = '42501';\n        END IF;\n        RETURN NEW;\n    END IF;\n    IF NEW.artifact_state IS DISTINCT FROM OLD.artifact_state\n       OR NEW.knowledge_state IS DISTINCT FROM OLD.knowledge_state\n       OR NEW.projection_attempts IS DISTINCT FROM OLD.projection_attempts\n       OR NEW.next_attempt_at IS DISTINCT FROM OLD.next_attempt_at\n       OR NEW.lease_owner IS DISTINCT FROM OLD.lease_owner\n       OR NEW.lease_until IS DISTINCT FROM OLD.lease_until\n       OR NEW.failure_code IS DISTINCT FROM OLD.failure_code THEN\n        RAISE EXCEPTION 'Human commands cannot mutate projection evidence'\n            USING ERRCODE = '42501';\n    END IF;\n    IF OLD.state = 'DRAFT' AND NEW.state = 'IN_REVIEW'\n       AND NEW.author_id =\n           NULLIF(current_setting('app.subject_id', true), '')::uuid THEN\n        required_action := CASE WHEN parent.kind = 'TEMPLATE'\n            THEN 'governance.template.propose'\n            ELSE 'governance.document.edit' END;\n    ELSIF OLD.state = 'IN_REVIEW' AND NEW.state = 'REJECTED'\n       AND NEW.reviewed_by =\n           NULLIF(current_setting('app.subject_id', true), '')::uuid\n       AND NEW.reviewed_by <> NEW.author_id THEN\n        required_action := CASE WHEN parent.kind = 'TEMPLATE'\n            THEN 'governance.template.review'\n            ELSE 'governance.document.review' END;\n    ELSIF OLD.state = 'IN_REVIEW' AND NEW.state = 'PUBLISHED'\n       AND NEW.reviewed_by =\n           NULLIF(current_setting('app.subject_id', true), '')::uuid\n       AND NEW.reviewed_by <> NEW.author_id THEN\n        required_action := CASE WHEN parent.kind = 'TEMPLATE'\n            THEN 'governance.template.activate'\n            ELSE 'governance.document.publish' END;\n    ELSIF OLD.state = 'PUBLISHED' AND NEW.state = 'SUPERSEDED' THEN\n        required_action := CASE WHEN parent.kind = 'TEMPLATE'\n            THEN 'governance.template.activate'\n            ELSE 'governance.document.publish' END;\n    ELSIF NEW.state IS NOT DISTINCT FROM OLD.state THEN\n        required_action := CASE WHEN parent.kind = 'TEMPLATE'\n            THEN 'governance.template.propose'\n            ELSE 'governance.document.edit' END;\n    ELSE\n        RAISE EXCEPTION 'Governance Document version transition is invalid'\n            USING ERRCODE = '55000';\n    END IF;\n    IF NOT governance.current_human_can_document_v1(\n        NEW.workspace_id,\n        required_action,\n        parent.classification,\n        parent.system_id,\n        parent.domain_id\n    ) THEN\n        RAISE EXCEPTION 'Governance Document version transition is not authorized'\n            USING ERRCODE = '42501';\n    END IF;\n    RETURN NEW;\nEND\n$$;")
        op.execute('CREATE TRIGGER enforce_document_mutation\nBEFORE UPDATE OR DELETE ON governance.documents\nFOR EACH ROW EXECUTE FUNCTION governance.enforce_document_mutation_v1();')
        op.execute('CREATE TRIGGER enforce_document_version_mutation\nBEFORE UPDATE OR DELETE ON governance.document_versions\nFOR EACH ROW EXECUTE FUNCTION governance.enforce_document_version_mutation_v1();')
        op.execute('CREATE TRIGGER reject_document_review_mutation\nBEFORE UPDATE OR DELETE ON governance.document_reviews\nFOR EACH ROW EXECUTE FUNCTION governance.reject_document_evidence_mutation_v1();')
        op.execute('CREATE TRIGGER reject_document_event_mutation\nBEFORE UPDATE OR DELETE ON governance.document_events\nFOR EACH ROW EXECUTE FUNCTION governance.reject_document_evidence_mutation_v1();')
        op.execute('CREATE TRIGGER reject_document_artifact_receipt_mutation\nBEFORE UPDATE OR DELETE ON governance.document_artifact_receipts\nFOR EACH ROW EXECUTE FUNCTION governance.reject_document_evidence_mutation_v1();')
        op.execute('CREATE TRIGGER reject_document_attachment_mutation\nBEFORE UPDATE OR DELETE ON governance.document_attachments\nFOR EACH ROW EXECUTE FUNCTION governance.reject_document_evidence_mutation_v1();')
        op.execute('CREATE TRIGGER reject_document_chunk_mutation\nBEFORE UPDATE OR DELETE ON governance.document_knowledge_chunks\nFOR EACH ROW EXECUTE FUNCTION governance.reject_document_evidence_mutation_v1();')
        op.execute('CREATE TRIGGER reject_document_projection_receipt_mutation\nBEFORE UPDATE OR DELETE ON governance.document_projection_receipts\nFOR EACH ROW EXECUTE FUNCTION governance.reject_document_evidence_mutation_v1();')
        op.execute('ALTER TABLE governance.documents ENABLE ROW LEVEL SECURITY;')
        op.execute('ALTER TABLE governance.documents FORCE ROW LEVEL SECURITY;')
        op.execute('ALTER TABLE governance.document_versions ENABLE ROW LEVEL SECURITY;')
        op.execute('ALTER TABLE governance.document_versions FORCE ROW LEVEL SECURITY;')
        op.execute('ALTER TABLE governance.document_reviews ENABLE ROW LEVEL SECURITY;')
        op.execute('ALTER TABLE governance.document_reviews FORCE ROW LEVEL SECURITY;')
        op.execute('ALTER TABLE governance.document_events ENABLE ROW LEVEL SECURITY;')
        op.execute('ALTER TABLE governance.document_events FORCE ROW LEVEL SECURITY;')
        op.execute('ALTER TABLE governance.document_artifact_receipts ENABLE ROW LEVEL SECURITY;')
        op.execute('ALTER TABLE governance.document_artifact_receipts FORCE ROW LEVEL SECURITY;')
        op.execute('ALTER TABLE governance.document_attachments ENABLE ROW LEVEL SECURITY;')
        op.execute('ALTER TABLE governance.document_attachments FORCE ROW LEVEL SECURITY;')
        op.execute('ALTER TABLE governance.document_knowledge_chunks ENABLE ROW LEVEL SECURITY;')
        op.execute('ALTER TABLE governance.document_knowledge_chunks FORCE ROW LEVEL SECURITY;')
        op.execute('ALTER TABLE governance.document_projection_receipts ENABLE ROW LEVEL SECURITY;')
        op.execute('ALTER TABLE governance.document_projection_receipts FORCE ROW LEVEL SECURITY;')
        op.execute('CREATE POLICY governance_documents_app_select ON governance.documents\nFOR SELECT TO datariver_app\nUSING (governance.can_read_document_v1(id));')
        op.execute("CREATE POLICY governance_documents_app_insert ON governance.documents\nFOR INSERT TO datariver_app\nWITH CHECK (\n    workspace_id = NULLIF(current_setting('app.workspace_id', true), '')::uuid\n    AND owner_subject_id = NULLIF(current_setting('app.subject_id', true), '')::uuid\n    AND governance.current_human_can_document_v1(\n        workspace_id,\n        CASE WHEN kind = 'TEMPLATE' THEN 'governance.template.propose'\n             ELSE 'governance.document.create' END,\n        classification, system_id, domain_id\n    )\n);")
        op.execute("CREATE POLICY governance_documents_app_update ON governance.documents\nFOR UPDATE TO datariver_app\nUSING (governance.can_read_document_v1(id))\nWITH CHECK (\n    workspace_id = NULLIF(current_setting('app.workspace_id', true), '')::uuid\n);")
        op.execute('CREATE POLICY governance_document_versions_app_select ON governance.document_versions\nFOR SELECT TO datariver_app\nUSING (governance.can_read_document_v1(document_id));')
        op.execute("CREATE POLICY governance_document_versions_app_insert ON governance.document_versions\nFOR INSERT TO datariver_app\nWITH CHECK (\n    workspace_id = NULLIF(current_setting('app.workspace_id', true), '')::uuid\n    AND author_id = NULLIF(current_setting('app.subject_id', true), '')::uuid\n    AND governance.can_act_on_document_v1(\n        document_id, 'governance.document.edit', 'governance.template.propose'\n    )\n);")
        op.execute('CREATE POLICY governance_document_versions_app_update ON governance.document_versions\nFOR UPDATE TO datariver_app\nUSING (governance.can_read_document_v1(document_id))\nWITH CHECK (governance.can_read_document_v1(document_id));')
        op.execute('CREATE POLICY governance_document_reviews_app_select ON governance.document_reviews\nFOR SELECT TO datariver_app\nUSING (governance.can_read_document_v1(document_id));')
        op.execute("CREATE POLICY governance_document_reviews_app_insert ON governance.document_reviews\nFOR INSERT TO datariver_app\nWITH CHECK (\n    workspace_id = NULLIF(current_setting('app.workspace_id', true), '')::uuid\n    AND reviewer_id = NULLIF(current_setting('app.subject_id', true), '')::uuid\n    AND governance.can_act_on_document_v1(\n        document_id, 'governance.document.review', 'governance.template.review'\n    )\n);")
        op.execute('CREATE POLICY governance_document_events_app_select ON governance.document_events\nFOR SELECT TO datariver_app\nUSING (governance.can_read_document_v1(document_id));')
        op.execute("CREATE POLICY governance_document_events_app_insert ON governance.document_events\nFOR INSERT TO datariver_app\nWITH CHECK (\n    workspace_id = NULLIF(current_setting('app.workspace_id', true), '')::uuid\n    AND actor_id = NULLIF(current_setting('app.subject_id', true), '')::uuid\n    AND governance.can_act_on_document_v1(\n        document_id,\n        CASE event_type\n            WHEN 'CREATED' THEN 'governance.document.create'\n            WHEN 'VERSION_CREATED' THEN 'governance.document.edit'\n            WHEN 'SUBMITTED' THEN 'governance.document.edit'\n            WHEN 'REJECTED' THEN 'governance.document.review'\n            WHEN 'PUBLISHED' THEN 'governance.document.publish'\n            WHEN 'ARCHIVED' THEN 'governance.document.archive'\n            WHEN 'ATTACHMENT_ADDED' THEN 'governance.document.edit'\n            ELSE 'governance.document.__denied__'\n        END,\n        CASE event_type\n            WHEN 'CREATED' THEN 'governance.template.propose'\n            WHEN 'VERSION_CREATED' THEN 'governance.template.propose'\n            WHEN 'SUBMITTED' THEN 'governance.template.propose'\n            WHEN 'REJECTED' THEN 'governance.template.review'\n            WHEN 'PUBLISHED' THEN 'governance.template.activate'\n            WHEN 'ARCHIVED' THEN 'governance.template.archive'\n            WHEN 'ATTACHMENT_ADDED' THEN 'governance.template.propose'\n            ELSE 'governance.template.__denied__'\n        END\n    )\n);")
        op.execute('CREATE POLICY governance_document_attachments_app_select ON governance.document_attachments\nFOR SELECT TO datariver_app\nUSING (governance.can_read_document_v1(document_id));')
        op.execute("CREATE POLICY governance_document_attachments_app_insert ON governance.document_attachments\nFOR INSERT TO datariver_app\nWITH CHECK (\n    workspace_id = NULLIF(current_setting('app.workspace_id', true), '')::uuid\n    AND uploaded_by = NULLIF(current_setting('app.subject_id', true), '')::uuid\n    AND governance.can_act_on_document_v1(\n        document_id, 'governance.document.edit', 'governance.template.propose'\n    )\n);")
        op.execute('CREATE POLICY governance_document_chunks_app_select ON governance.document_knowledge_chunks\nFOR SELECT TO datariver_app\nUSING (governance.can_read_document_v1(document_id));')
        op.execute('CREATE POLICY governance_documents_worker_select ON governance.documents\nFOR SELECT TO datariver_governance_document USING (true);')
        op.execute('CREATE POLICY governance_versions_worker_select ON governance.document_versions\nFOR SELECT TO datariver_governance_document USING (true);')
        op.execute('CREATE POLICY governance_versions_worker_update ON governance.document_versions\nFOR UPDATE TO datariver_governance_document USING (true) WITH CHECK (true);')
        op.execute('CREATE POLICY governance_artifacts_worker_all ON governance.document_artifact_receipts\nFOR ALL TO datariver_governance_document USING (true) WITH CHECK (true);')
        op.execute('CREATE POLICY governance_chunks_worker_all ON governance.document_knowledge_chunks\nFOR ALL TO datariver_governance_document USING (true) WITH CHECK (true);')
        op.execute('CREATE POLICY governance_projection_receipts_worker_all\nON governance.document_projection_receipts\nFOR ALL TO datariver_governance_document USING (true) WITH CHECK (true);')
        op.execute('REVOKE ALL ON ALL TABLES IN SCHEMA governance\nFROM datariver_governance_document;')
        op.execute('GRANT USAGE ON SCHEMA governance TO datariver_app, datariver_governance_document;')
        op.execute('GRANT SELECT, INSERT, UPDATE ON governance.documents TO datariver_app;')
        op.execute('GRANT SELECT, INSERT, UPDATE ON governance.document_versions TO datariver_app;')
        op.execute('GRANT SELECT, INSERT ON governance.document_reviews TO datariver_app;')
        op.execute('GRANT SELECT, INSERT ON governance.document_events TO datariver_app;')
        op.execute('GRANT SELECT ON governance.document_artifact_receipts TO datariver_app;')
        op.execute('GRANT SELECT, INSERT ON governance.document_attachments TO datariver_app;')
        op.execute('GRANT SELECT ON governance.document_knowledge_chunks TO datariver_app;')
        op.execute('GRANT SELECT ON governance.document_projection_receipts TO datariver_app;')
        op.execute('GRANT SELECT ON governance.documents TO datariver_governance_document;')
        op.execute('GRANT SELECT ON governance.document_versions TO datariver_governance_document;')
        op.execute('GRANT UPDATE (\n    artifact_state,\n    knowledge_state,\n    projection_attempts,\n    next_attempt_at,\n    lease_owner,\n    lease_until,\n    failure_code,\n    version\n) ON governance.document_versions TO datariver_governance_document;')
        op.execute('GRANT SELECT, INSERT ON governance.document_artifact_receipts\nTO datariver_governance_document;')
        op.execute('GRANT SELECT, INSERT ON governance.document_knowledge_chunks\nTO datariver_governance_document;')
        op.execute('GRANT SELECT, INSERT ON governance.document_projection_receipts\nTO datariver_governance_document;')
        op.execute("CREATE OR REPLACE FUNCTION governance.reject_document_parent_mutation_v1()\nRETURNS trigger\nLANGUAGE plpgsql\nAS $$\nBEGIN\n    IF NEW.parent_document_id IS DISTINCT FROM OLD.parent_document_id THEN\n        RAISE EXCEPTION\n            'Governance Document version hierarchy is immutable'\n            USING ERRCODE = '55000';\n    END IF;\n    RETURN NEW;\nEND\n$$;")
        op.execute('CREATE TRIGGER reject_document_parent_mutation\nBEFORE UPDATE ON governance.document_versions\nFOR EACH ROW\nEXECUTE FUNCTION governance.reject_document_parent_mutation_v1();')
        op.execute("DO $datariver$\nDECLARE\n    role_name text;\n    role_is_safe boolean;\nBEGIN\n    FOREACH role_name IN ARRAY ARRAY['datariver_app', 'datariver_knowledge_ingestion']\n    LOOP\n        SELECT\n            rolcanlogin\n            AND NOT rolsuper\n            AND NOT rolcreatedb\n            AND NOT rolcreaterole\n            AND NOT rolreplication\n            AND NOT rolbypassrls\n        INTO role_is_safe\n        FROM pg_roles\n        WHERE rolname = role_name;\n        IF NOT COALESCE(role_is_safe, false) THEN\n            RAISE EXCEPTION '% must be a safe NOBYPASSRLS LOGIN role', role_name;\n        END IF;\n    END LOOP;\n    IF EXISTS (\n        SELECT 1\n        FROM pg_roles AS candidate\n        WHERE candidate.rolname <> 'datariver_knowledge_ingestion'\n          AND pg_has_role('datariver_knowledge_ingestion', candidate.oid, 'MEMBER')\n    ) OR EXISTS (\n        SELECT 1\n        FROM pg_roles AS candidate\n        WHERE candidate.rolname <> 'datariver_knowledge_ingestion'\n          AND NOT candidate.rolsuper\n          AND pg_has_role(candidate.oid, 'datariver_knowledge_ingestion', 'MEMBER')\n    ) THEN\n        RAISE EXCEPTION 'datariver_knowledge_ingestion role membership is unsafe';\n    END IF;\nEND\n$datariver$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.enforce_studio_ingestion_changeset_provenance_v1()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = pg_catalog, knowledge\nAS $$\nBEGIN\n    IF TG_OP = 'INSERT'\n       AND NEW.studio_ingestion_job_id IS NOT NULL\n       AND session_user <> 'datariver_knowledge_ingestion' THEN\n        RAISE EXCEPTION 'Studio ingestion Changeset provenance is function-owned'\n            USING ERRCODE = '42501';\n    END IF;\n    IF TG_OP = 'UPDATE' THEN\n        IF NEW.studio_ingestion_job_id\n            IS DISTINCT FROM OLD.studio_ingestion_job_id THEN\n            RAISE EXCEPTION 'Studio ingestion Changeset provenance is immutable'\n                USING ERRCODE = '55000';\n        END IF;\n        IF OLD.studio_ingestion_job_id IS NOT NULL\n           AND ROW(\n               NEW.workspace_id, NEW.graph_id, NEW.base_release_id,\n               NEW.ontology_version_id, NEW.author_id,\n               NEW.source_analysis_job_id, NEW.created_at\n           ) IS DISTINCT FROM ROW(\n               OLD.workspace_id, OLD.graph_id, OLD.base_release_id,\n               OLD.ontology_version_id, OLD.author_id,\n               OLD.source_analysis_job_id, OLD.created_at\n           ) THEN\n            RAISE EXCEPTION 'Studio ingestion Changeset pins are immutable'\n                USING ERRCODE = '55000';\n        END IF;\n    END IF;\n    RETURN NEW;\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.enforce_studio_ingestion_operation_scope_v1()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = pg_catalog, knowledge\nAS $$\nDECLARE\n    target_workspace_id uuid := CASE WHEN TG_OP = 'DELETE'\n        THEN OLD.workspace_id ELSE NEW.workspace_id END;\n    target_changeset_id uuid := CASE WHEN TG_OP = 'DELETE'\n        THEN OLD.changeset_id ELSE NEW.changeset_id END;\n    studio_job_id uuid;\n    previous_studio_job_id uuid;\nBEGIN\n    SELECT studio_ingestion_job_id\n    INTO studio_job_id\n    FROM knowledge.changesets\n    WHERE workspace_id = target_workspace_id\n      AND id = target_changeset_id;\n    IF TG_OP = 'UPDATE' THEN\n        SELECT studio_ingestion_job_id\n        INTO previous_studio_job_id\n        FROM knowledge.changesets\n        WHERE workspace_id = OLD.workspace_id\n          AND id = OLD.changeset_id;\n    END IF;\n    IF COALESCE(studio_job_id, previous_studio_job_id) IS NOT NULL\n       AND session_user <> 'datariver_knowledge_ingestion' THEN\n        RAISE EXCEPTION 'Studio ingestion operations are function-owned'\n            USING ERRCODE = '42501';\n    END IF;\n    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.reject_studio_ingestion_evidence_mutation_v1()\nRETURNS trigger\nLANGUAGE plpgsql\nSET search_path = pg_catalog\nAS $$\nBEGIN\n    IF TG_OP <> 'INSERT' THEN\n        RAISE EXCEPTION 'Studio ingestion evidence is append-only'\n            USING ERRCODE = '55000';\n    END IF;\n    RETURN NEW;\nEND\n$$;")
        op.execute('CREATE TRIGGER enforce_studio_ingestion_changeset_provenance\nBEFORE INSERT OR UPDATE ON knowledge.changesets\nFOR EACH ROW EXECUTE FUNCTION\n    knowledge.enforce_studio_ingestion_changeset_provenance_v1();')
        op.execute('CREATE TRIGGER enforce_studio_ingestion_operation_scope\nBEFORE INSERT OR UPDATE OR DELETE ON knowledge.change_operations\nFOR EACH ROW EXECUTE FUNCTION\n    knowledge.enforce_studio_ingestion_operation_scope_v1();')
        op.execute('CREATE TRIGGER reject_studio_ingestion_binding_pin_mutation\nBEFORE UPDATE OR DELETE ON knowledge.studio_ingestion_binding_pins\nFOR EACH ROW EXECUTE FUNCTION knowledge.reject_studio_ingestion_evidence_mutation_v1();')
        op.execute('CREATE TRIGGER reject_studio_ingestion_attempt_mutation\nBEFORE DELETE ON knowledge.studio_ingestion_attempts\nFOR EACH ROW EXECUTE FUNCTION knowledge.reject_studio_ingestion_evidence_mutation_v1();')
        op.execute('CREATE TRIGGER reject_studio_ingestion_event_mutation\nBEFORE UPDATE OR DELETE ON knowledge.studio_ingestion_events\nFOR EACH ROW EXECUTE FUNCTION knowledge.reject_studio_ingestion_evidence_mutation_v1();')
        op.execute('CREATE TRIGGER reject_studio_ingestion_vector_receipt_mutation\nBEFORE UPDATE OR DELETE ON knowledge.studio_ingestion_vector_receipts\nFOR EACH ROW EXECUTE FUNCTION knowledge.reject_studio_ingestion_evidence_mutation_v1();')
        op.execute('ALTER TABLE knowledge.studio_ingestion_jobs ENABLE ROW LEVEL SECURITY;')
        op.execute('ALTER TABLE knowledge.studio_ingestion_jobs FORCE ROW LEVEL SECURITY;')
        op.execute('ALTER TABLE knowledge.studio_ingestion_binding_pins ENABLE ROW LEVEL SECURITY;')
        op.execute('ALTER TABLE knowledge.studio_ingestion_binding_pins FORCE ROW LEVEL SECURITY;')
        op.execute('ALTER TABLE knowledge.studio_ingestion_attempts ENABLE ROW LEVEL SECURITY;')
        op.execute('ALTER TABLE knowledge.studio_ingestion_attempts FORCE ROW LEVEL SECURITY;')
        op.execute('ALTER TABLE knowledge.studio_ingestion_events ENABLE ROW LEVEL SECURITY;')
        op.execute('ALTER TABLE knowledge.studio_ingestion_events FORCE ROW LEVEL SECURITY;')
        op.execute('ALTER TABLE knowledge.studio_ingestion_vector_receipts ENABLE ROW LEVEL SECURITY;')
        op.execute('ALTER TABLE knowledge.studio_ingestion_vector_receipts FORCE ROW LEVEL SECURITY;')
        op.execute("CREATE POLICY studio_ingestion_jobs_workspace\nON knowledge.studio_ingestion_jobs\nUSING (\n    workspace_id = NULLIF(current_setting('app.workspace_id', true), '')::uuid\n    AND (\n        session_user = 'datariver_knowledge_ingestion'\n        OR requested_by =\n            NULLIF(current_setting('app.subject_id', true), '')::uuid\n    )\n)\nWITH CHECK (\n    workspace_id = NULLIF(current_setting('app.workspace_id', true), '')::uuid\n    AND (\n        session_user = 'datariver_knowledge_ingestion'\n        OR requested_by =\n            NULLIF(current_setting('app.subject_id', true), '')::uuid\n    )\n);")
        op.execute("CREATE POLICY studio_ingestion_binding_pins_workspace\nON knowledge.studio_ingestion_binding_pins\nUSING (\n    workspace_id = NULLIF(current_setting('app.workspace_id', true), '')::uuid\n    AND (\n        session_user = 'datariver_knowledge_ingestion'\n        OR EXISTS (\n            SELECT 1\n            FROM knowledge.studio_ingestion_jobs AS job\n            WHERE job.workspace_id = studio_ingestion_binding_pins.workspace_id\n              AND job.id = studio_ingestion_binding_pins.job_id\n              AND job.requested_by =\n                  NULLIF(current_setting('app.subject_id', true), '')::uuid\n        )\n    )\n)\nWITH CHECK (\n    workspace_id = NULLIF(current_setting('app.workspace_id', true), '')::uuid\n    AND (\n        session_user = 'datariver_knowledge_ingestion'\n        OR EXISTS (\n            SELECT 1\n            FROM knowledge.studio_ingestion_jobs AS job\n            WHERE job.workspace_id = studio_ingestion_binding_pins.workspace_id\n              AND job.id = studio_ingestion_binding_pins.job_id\n              AND job.requested_by =\n                  NULLIF(current_setting('app.subject_id', true), '')::uuid\n        )\n    )\n);")
        op.execute("CREATE POLICY studio_ingestion_attempts_workspace\nON knowledge.studio_ingestion_attempts\nUSING (\n    workspace_id = NULLIF(current_setting('app.workspace_id', true), '')::uuid\n    AND session_user = 'datariver_knowledge_ingestion'\n)\nWITH CHECK (\n    workspace_id = NULLIF(current_setting('app.workspace_id', true), '')::uuid\n    AND session_user = 'datariver_knowledge_ingestion'\n);")
        op.execute("CREATE POLICY studio_ingestion_events_workspace\nON knowledge.studio_ingestion_events\nUSING (\n    workspace_id = NULLIF(current_setting('app.workspace_id', true), '')::uuid\n    AND (\n        session_user = 'datariver_knowledge_ingestion'\n        OR EXISTS (\n            SELECT 1\n            FROM knowledge.studio_ingestion_jobs AS job\n            WHERE job.workspace_id = studio_ingestion_events.workspace_id\n              AND job.id = studio_ingestion_events.job_id\n              AND job.requested_by =\n                  NULLIF(current_setting('app.subject_id', true), '')::uuid\n        )\n    )\n)\nWITH CHECK (\n    workspace_id = NULLIF(current_setting('app.workspace_id', true), '')::uuid\n    AND (\n        session_user = 'datariver_knowledge_ingestion'\n        OR EXISTS (\n            SELECT 1\n            FROM knowledge.studio_ingestion_jobs AS job\n            WHERE job.workspace_id = studio_ingestion_events.workspace_id\n              AND job.id = studio_ingestion_events.job_id\n              AND job.requested_by =\n                  NULLIF(current_setting('app.subject_id', true), '')::uuid\n        )\n    )\n);")
        op.execute("CREATE POLICY studio_ingestion_vector_receipts_workspace\nON knowledge.studio_ingestion_vector_receipts\nUSING (\n    workspace_id = NULLIF(current_setting('app.workspace_id', true), '')::uuid\n    AND session_user = 'datariver_knowledge_ingestion'\n)\nWITH CHECK (\n    workspace_id = NULLIF(current_setting('app.workspace_id', true), '')::uuid\n    AND session_user = 'datariver_knowledge_ingestion'\n);")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.append_studio_ingestion_event_v1(\n    p_workspace_id uuid,\n    p_job_id uuid,\n    p_attempt_id uuid,\n    p_state text,\n    p_reason_code text,\n    p_actor_id uuid,\n    p_actor_kind text,\n    p_details jsonb\n)\nRETURNS void\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, knowledge\nAS $$\nDECLARE\n    next_sequence integer;\n    now_at timestamptz := transaction_timestamp();\n    evidence_hash text;\nBEGIN\n    IF p_state NOT IN (\n        'PENDING','RUNNING','RETRY_WAIT','CANCEL_REQUESTED',\n        'SUCCESS','FAILED','STALE','CANCELLED'\n    )\n       OR p_actor_kind NOT IN ('HUMAN','SERVICE')\n       OR char_length(COALESCE(p_reason_code, '')) NOT BETWEEN 1 AND 100\n       OR jsonb_typeof(p_details) <> 'object'\n       OR octet_length(p_details::text) > 8192 THEN\n        RAISE EXCEPTION 'invalid Studio ingestion transition evidence'\n            USING ERRCODE = '23514';\n    END IF;\n    SELECT COALESCE(max(event.sequence), 0) + 1\n    INTO next_sequence\n    FROM knowledge.studio_ingestion_events AS event\n    WHERE event.workspace_id = p_workspace_id\n      AND event.job_id = p_job_id;\n    evidence_hash := encode(sha256(convert_to(jsonb_build_object(\n        'contract', 'STUDIO_INGESTION_EVENT_V1',\n        'workspace_id', p_workspace_id,\n        'job_id', p_job_id,\n        'attempt_id', p_attempt_id,\n        'sequence', next_sequence,\n        'state', p_state,\n        'reason_code', p_reason_code,\n        'actor_id', p_actor_id,\n        'actor_kind', p_actor_kind,\n        'details', p_details,\n        'occurred_at', now_at\n    )::text, 'UTF8')), 'hex');\n    INSERT INTO knowledge.studio_ingestion_events (\n        id, workspace_id, job_id, sequence, attempt_id, state, reason_code,\n        actor_id, actor_kind, evidence_hash, details_document, occurred_at\n    )\n    VALUES (\n        gen_random_uuid(), p_workspace_id, p_job_id, next_sequence, p_attempt_id,\n        p_state, p_reason_code, p_actor_id, p_actor_kind, evidence_hash,\n        p_details, now_at\n    );\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.emit_studio_ingestion_outbox_v1(\n    p_workspace_id uuid,\n    p_job_id uuid,\n    p_state text,\n    p_version integer\n)\nRETURNS void\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, integration\nAS $$\nBEGIN\n    INSERT INTO integration.outbox_events (\n        id, workspace_id, aggregate_type, aggregate_id, event_type,\n        schema_version, payload, created_at, published_at, dead_lettered_at,\n        lease_until, attempts, last_error_code\n    )\n    VALUES (\n        gen_random_uuid(), p_workspace_id, 'knowledge_studio_ingestion',\n        p_job_id, 'knowledge.studio-ingestion.' || lower(p_state) || '.v1',\n        1, jsonb_build_object(\n            'job_id', p_job_id,\n            'state', p_state,\n            'version', p_version\n        ), transaction_timestamp(), NULL, NULL, NULL, 0, NULL\n    );\nEND\n$$;")
        op.execute('CREATE OR REPLACE FUNCTION knowledge.current_studio_ingestion_service_can_v1(\n    p_workspace_id uuid,\n    p_action text,\n    p_classification integer,\n    p_domain_id uuid\n)\nRETURNS boolean\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = pg_catalog, platform, iam\nAS $$\n    SELECT session_user = \'datariver_knowledge_ingestion\'\n       AND p_workspace_id IS NOT DISTINCT FROM\n           NULLIF(current_setting(\'app.workspace_id\', true), \'\')::uuid\n       AND p_action = \'kg.ingestion.execute\'\n       AND EXISTS (\n           SELECT 1\n           FROM platform.workspaces AS workspace\n           JOIN iam.workspace_memberships AS membership\n             ON membership.workspace_id = workspace.id\n           JOIN iam.subjects AS subject\n             ON subject.id = membership.subject_id\n           WHERE workspace.id = p_workspace_id\n             AND workspace.status = \'ACTIVE\'\n             AND membership.subject_id =\n                 NULLIF(current_setting(\'app.subject_id\', true), \'\')::uuid\n             AND subject.active IS TRUE\n             AND membership.active IS TRUE\n             AND (\n                 membership.access_expires_at IS NULL\n                 OR membership.access_expires_at > transaction_timestamp()\n             )\n             AND membership.job_function = \'SERVICE_ACCOUNT\'\n             AND COALESCE(membership.attributes -> \'groups\', \'[]\'::jsonb)\n                 = \'["service-accounts","knowledge-ingestion-workers"]\'::jsonb\n             AND COALESCE(\n                 membership.attributes -> \'allowed_actions\', \'[]\'::jsonb\n             ) = \'["kg.ingestion.execute"]\'::jsonb\n             AND COALESCE(\n                 membership.attributes -> \'denied_actions\', \'[]\'::jsonb\n             ) = \'[]\'::jsonb\n             AND membership.clearance >= p_classification\n             AND (\n                 p_classification = 0\n                 OR p_domain_id IS NULL\n                 OR COALESCE(\n                     membership.attributes -> \'allowed_domain_ids\', \'[]\'::jsonb\n                 ) ? p_domain_id::text\n             )\n       )\n$$;')
        op.execute("CREATE OR REPLACE FUNCTION knowledge.current_studio_ingestion_human_can_v1(\n    p_workspace_id uuid,\n    p_actor_id uuid,\n    p_classification integer,\n    p_domain_id uuid\n)\nRETURNS boolean\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = pg_catalog, platform, iam\nAS $$\n    SELECT session_user = 'datariver_app'\n       AND p_workspace_id IS NOT DISTINCT FROM\n           NULLIF(current_setting('app.workspace_id', true), '')::uuid\n       AND p_actor_id IS NOT DISTINCT FROM\n           NULLIF(current_setting('app.subject_id', true), '')::uuid\n       AND EXISTS (\n           SELECT 1\n           FROM platform.workspaces AS workspace\n           JOIN iam.workspace_memberships AS membership\n             ON membership.workspace_id = workspace.id\n           JOIN iam.subjects AS subject\n             ON subject.id = membership.subject_id\n           WHERE workspace.id = p_workspace_id\n             AND workspace.status = 'ACTIVE'\n             AND membership.subject_id = p_actor_id\n             AND subject.active IS TRUE\n             AND membership.active IS TRUE\n             AND (\n                 membership.access_expires_at IS NULL\n                 OR membership.access_expires_at > transaction_timestamp()\n             )\n             AND COALESCE(membership.job_function, '') <> 'SERVICE_ACCOUNT'\n             AND membership.clearance >= p_classification\n             AND COALESCE(\n                 membership.attributes -> 'allowed_actions', '[]'::jsonb\n             ) ? 'kg.edit'\n             AND NOT (\n                 COALESCE(\n                     membership.attributes -> 'denied_actions', '[]'::jsonb\n                 ) ? 'kg.edit'\n             )\n             AND (\n                 p_classification = 0\n                 OR p_domain_id IS NULL\n                 OR COALESCE(\n                     membership.attributes -> 'allowed_domain_ids', '[]'::jsonb\n                 ) ? p_domain_id::text\n             )\n       )\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.request_studio_ingestion_v1(\n    p_workspace_id uuid,\n    p_draft_id uuid,\n    p_expected_version integer,\n    p_request_hash text,\n    p_manifest_id text,\n    p_manifest_version integer,\n    p_manifest_hash text,\n    p_source_profile_pins jsonb,\n    p_embedding_binding jsonb,\n    p_maximum_attempts integer\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, platform, iam, catalog, integration, knowledge\nAS $$\nDECLARE\n    actor_id uuid := NULLIF(current_setting('app.subject_id', true), '')::uuid;\n    draft knowledge.studio_drafts%ROWTYPE;\n    studio_release knowledge.studio_releases%ROWTYPE;\n    graph knowledge.graphs%ROWTYPE;\n    ontology knowledge.ontology_versions%ROWTYPE;\n    binding record;\n    profile_pin jsonb;\n    rules jsonb;\n    job_id uuid := gen_random_uuid();\n    global_pin_hash text;\n    binding_pin_hash text;\n    embedding_hash text;\n    vector_target_count integer := 0;\n    binding_count integer;\n    source_count integer;\n    now_at timestamptz := transaction_timestamp();\n    base_hash text;\n    locked_authorization_hash text;\nBEGIN\n    IF session_user <> 'datariver_app'\n       OR p_workspace_id IS DISTINCT FROM\n           NULLIF(current_setting('app.workspace_id', true), '')::uuid\n       OR actor_id IS NULL\n       OR p_expected_version < 1\n       OR p_request_hash !~ '^[0-9a-f]{64}$'\n       OR char_length(COALESCE(p_manifest_id, '')) NOT BETWEEN 1 AND 255\n       OR p_manifest_id IS DISTINCT FROM btrim(p_manifest_id)\n       OR p_manifest_version < 1\n       OR p_manifest_hash !~ '^[0-9a-f]{64}$'\n       OR jsonb_typeof(p_source_profile_pins) <> 'array'\n       OR jsonb_array_length(p_source_profile_pins) NOT BETWEEN 1 AND 500\n       OR p_maximum_attempts NOT BETWEEN 1 AND 20\n       OR (\n           p_embedding_binding IS NOT NULL\n           AND (\n               jsonb_typeof(p_embedding_binding) <> 'object'\n               OR octet_length(p_embedding_binding::text) > 8192\n           )\n       ) THEN\n        RAISE EXCEPTION 'invalid Studio ingestion request'\n            USING ERRCODE = '42501';\n    END IF;\n    SELECT * INTO draft\n    FROM knowledge.studio_drafts\n    WHERE workspace_id = p_workspace_id AND id = p_draft_id\n    FOR UPDATE;\n    IF NOT FOUND\n       OR draft.version <> p_expected_version\n       OR draft.state <> 'PUBLISHED'\n       OR draft.current_step <> 'ABOX'\n       OR draft.materialized_graph_id IS NULL\n       OR draft.materialized_ontology_version_id IS NULL\n       OR draft.published_studio_release_id IS NULL THEN\n        RAISE EXCEPTION 'Studio ingestion requires an exact published Draft'\n            USING ERRCODE = '55000';\n    END IF;\n    SELECT * INTO graph\n    FROM knowledge.graphs\n    WHERE workspace_id = p_workspace_id\n      AND id = draft.materialized_graph_id\n    FOR UPDATE;\n    SELECT * INTO studio_release\n    FROM knowledge.studio_releases\n    WHERE workspace_id = p_workspace_id\n      AND graph_id = graph.id\n      AND id = draft.published_studio_release_id\n    FOR SHARE;\n    SELECT * INTO ontology\n    FROM knowledge.ontology_versions\n    WHERE workspace_id = p_workspace_id\n      AND graph_id = graph.id\n      AND id = draft.materialized_ontology_version_id\n    FOR SHARE;\n    IF graph.id IS NULL\n       OR graph.status <> 'PUBLISHED'\n       OR graph.active_studio_release_id IS DISTINCT FROM studio_release.id\n       OR studio_release.state <> 'ACTIVE'\n       OR studio_release.source_draft_id IS DISTINCT FROM draft.id\n       OR studio_release.source_draft_version <> draft.version - 1\n       OR studio_release.ontology_version_id IS DISTINCT FROM ontology.id\n       OR ontology.status <> 'PUBLISHED' THEN\n        RAISE EXCEPTION 'Studio release pins changed before ingestion'\n            USING ERRCODE = '55000';\n    END IF;\n    IF NOT knowledge.current_studio_ingestion_human_can_v1(\n        p_workspace_id, actor_id, graph.classification, graph.domain_ref_id\n    ) THEN\n        RAISE EXCEPTION 'Studio ingestion requester is not authorized'\n            USING ERRCODE = '42501';\n    END IF;\n    PERFORM 1\n    FROM platform.workspaces AS workspace\n    JOIN iam.workspace_memberships AS membership\n      ON membership.workspace_id = workspace.id\n    JOIN iam.subjects AS subject ON subject.id = membership.subject_id\n    WHERE workspace.id = p_workspace_id\n      AND workspace.status = 'ACTIVE'\n      AND membership.subject_id = actor_id\n      AND subject.active IS TRUE\n      AND membership.active IS TRUE\n      AND (\n          membership.access_expires_at IS NULL\n          OR membership.access_expires_at > now_at\n      )\n      AND COALESCE(membership.job_function, '') <> 'SERVICE_ACCOUNT'\n      AND membership.clearance >= graph.classification\n      AND COALESCE(\n          membership.attributes -> 'allowed_actions', '[]'::jsonb\n      ) ? 'kg.edit'\n      AND NOT (\n          COALESCE(\n              membership.attributes -> 'denied_actions', '[]'::jsonb\n          ) ? 'kg.edit'\n      )\n      AND (\n          graph.classification = 0\n          OR graph.domain_ref_id IS NULL\n          OR COALESCE(\n              membership.attributes -> 'allowed_domain_ids', '[]'::jsonb\n          ) ? graph.domain_ref_id::text\n      )\n    FOR SHARE OF workspace, membership, subject;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'Studio ingestion requester is not authorized'\n            USING ERRCODE = '42501';\n    END IF;\n    SELECT encode(sha256(convert_to(jsonb_build_object(\n        'contract', 'KNOWLEDGE_STUDIO_INGESTION_REQUEST_AUTHORIZATION_DB_V1',\n        'workspace_id', membership.workspace_id,\n        'subject_id', membership.subject_id,\n        'subject_active', subject.active,\n        'membership_active', membership.active,\n        'access_expires_at', membership.access_expires_at,\n        'job_function', membership.job_function,\n        'clearance', membership.clearance,\n        'attributes', membership.attributes\n    )::text, 'UTF8')), 'hex')\n    INTO locked_authorization_hash\n    FROM iam.workspace_memberships AS membership\n    JOIN iam.subjects AS subject ON subject.id = membership.subject_id\n    WHERE membership.workspace_id = p_workspace_id\n      AND membership.subject_id = actor_id;\n    SELECT count(*) INTO source_count\n    FROM jsonb_array_elements(p_source_profile_pins) AS pin\n    WHERE jsonb_typeof(pin) = 'object'\n      AND (\n          pin - ARRAY[\n              'asset_id','source_version','projection_source_version',\n              'connection_profile_id','connection_profile_version',\n              'connection_profile_hash'\n          ]\n      ) = '{}'::jsonb\n      AND (pin ->> 'asset_id') IS NOT NULL\n      AND char_length(COALESCE(pin ->> 'source_version', '')) BETWEEN 1 AND 255\n      AND char_length(COALESCE(pin ->> 'projection_source_version', ''))\n          BETWEEN 1 AND 255\n      AND char_length(COALESCE(pin ->> 'connection_profile_id', ''))\n          BETWEEN 1 AND 255\n      AND (pin ->> 'connection_profile_version') ~ '^[1-9][0-9]*$'\n      AND pin ->> 'connection_profile_hash' ~ '^[0-9a-f]{64}$';\n    IF source_count <> jsonb_array_length(p_source_profile_pins)\n       OR source_count <> (\n           SELECT count(DISTINCT pin ->> 'asset_id')\n           FROM jsonb_array_elements(p_source_profile_pins) AS pin\n       ) THEN\n        RAISE EXCEPTION 'Studio source profile pins are invalid'\n            USING ERRCODE = '23514';\n    END IF;\n    SELECT count(*) INTO binding_count\n    FROM knowledge.abox_binding_versions\n    WHERE workspace_id = p_workspace_id\n      AND studio_release_id = studio_release.id;\n    IF binding_count NOT BETWEEN 1 AND 500 THEN\n        RAISE EXCEPTION 'Studio Release has no bounded A-Box Binding set'\n            USING ERRCODE = '23514';\n    END IF;\n    IF EXISTS (\n        SELECT 1\n        FROM jsonb_array_elements(p_source_profile_pins) AS pin\n        WHERE NOT EXISTS (\n            SELECT 1\n            FROM knowledge.abox_binding_versions AS binding_version\n            JOIN knowledge.source_references AS source\n              ON source.workspace_id = binding_version.workspace_id\n             AND source.id = binding_version.source_reference_id\n            WHERE binding_version.workspace_id = p_workspace_id\n              AND binding_version.studio_release_id = studio_release.id\n              AND source.catalog_asset_id::text = pin ->> 'asset_id'\n        )\n    ) OR EXISTS (\n        SELECT 1\n        FROM knowledge.abox_binding_versions AS binding_version\n        JOIN knowledge.source_references AS source\n          ON source.workspace_id = binding_version.workspace_id\n         AND source.id = binding_version.source_reference_id\n        WHERE binding_version.workspace_id = p_workspace_id\n          AND binding_version.studio_release_id = studio_release.id\n          AND NOT EXISTS (\n              SELECT 1\n              FROM jsonb_array_elements(p_source_profile_pins) AS pin\n              WHERE pin ->> 'asset_id' = source.catalog_asset_id::text\n          )\n    ) THEN\n        RAISE EXCEPTION 'Studio source profile pins do not match released Bindings'\n            USING ERRCODE = '23514';\n    END IF;\n    FOR binding IN\n        SELECT\n            binding_version.*,\n            source.catalog_asset_id,\n            source.source_version,\n            source.projection_source_version,\n            source.classification AS source_classification,\n            source.selection_hash,\n            target.canonical_name AS target_class_canonical_name,\n            target.kind AS target_kind\n        FROM knowledge.abox_binding_versions AS binding_version\n        JOIN knowledge.source_references AS source\n          ON source.workspace_id = binding_version.workspace_id\n         AND source.id = binding_version.source_reference_id\n        JOIN knowledge.ontology_elements AS target\n          ON target.workspace_id = binding_version.workspace_id\n         AND target.ontology_version_id = binding_version.ontology_version_id\n         AND target.id = binding_version.target_ontology_element_id\n        WHERE binding_version.workspace_id = p_workspace_id\n          AND binding_version.studio_release_id = studio_release.id\n        ORDER BY binding_version.ordinal\n    LOOP\n        IF binding.target_kind <> 'CLASS'\n           OR binding.source_classification > graph.classification THEN\n            RAISE EXCEPTION 'Studio DB ingestion v1 supports Class bindings only'\n                USING ERRCODE = '23514';\n        END IF;\n        SELECT pin INTO profile_pin\n        FROM jsonb_array_elements(p_source_profile_pins) AS pin\n        WHERE pin ->> 'asset_id' = binding.catalog_asset_id::text;\n        IF profile_pin IS NULL\n           OR profile_pin ->> 'source_version' IS DISTINCT FROM binding.source_version\n           OR profile_pin ->> 'projection_source_version'\n                IS DISTINCT FROM binding.projection_source_version\n           OR char_length(COALESCE(profile_pin ->> 'connection_profile_id', ''))\n                NOT BETWEEN 1 AND 255\n           OR (profile_pin ->> 'connection_profile_version')::integer < 1\n           OR profile_pin ->> 'connection_profile_hash' !~ '^[0-9a-f]{64}$' THEN\n            RAISE EXCEPTION 'Studio Binding has no exact source profile pin'\n                USING ERRCODE = '55000';\n        END IF;\n        SELECT jsonb_agg(\n            jsonb_build_object(\n                'method', rule.method,\n                'source_field_path', rule.source_field_path,\n                'target_stable_element_id', rule.target_stable_element_id,\n                'target_canonical_name', element.canonical_name,\n                'target_data_type', CASE\n                    WHEN rule.method = 'PROPERTY'\n                    THEN element.element_document ->> 'data_type'\n                    ELSE NULL\n                END,\n                'target_nullable', CASE\n                    WHEN rule.method = 'PROPERTY'\n                    THEN element.element_document -> 'nullable'\n                    ELSE NULL\n                END,\n                'vector_index_enabled', CASE\n                    WHEN rule.method = 'PROPERTY'\n                    THEN COALESCE(\n                        (element.element_document ->> 'vector_index_enabled')::boolean,\n                        false\n                    )\n                    ELSE false\n                END,\n                'transform_id', rule.transform_id,\n                'transform_version', rule.transform_version\n            )\n            ORDER BY rule.ordinal\n        ) INTO rules\n        FROM knowledge.abox_mapping_rule_versions AS rule\n        JOIN knowledge.ontology_elements AS element\n          ON element.workspace_id = rule.workspace_id\n         AND element.ontology_version_id = rule.ontology_version_id\n         AND element.id = rule.target_ontology_element_id\n        WHERE rule.workspace_id = p_workspace_id\n          AND rule.binding_version_id = binding.id\n          AND rule.method IN ('SUBJECT_ID','PROPERTY');\n        IF rules IS NULL\n           OR (\n               SELECT count(*)\n               FROM jsonb_array_elements(rules) AS rule\n               WHERE rule ->> 'method' = 'SUBJECT_ID'\n           ) <> 1\n           OR (\n               SELECT count(*)\n               FROM knowledge.abox_mapping_rule_versions AS rule\n               WHERE rule.workspace_id = p_workspace_id\n                 AND rule.binding_version_id = binding.id\n           ) <> jsonb_array_length(rules) THEN\n            RAISE EXCEPTION 'Studio Binding Mapping is unsupported or incomplete'\n                USING ERRCODE = '23514';\n        END IF;\n        vector_target_count := vector_target_count + (\n            SELECT count(*)\n            FROM jsonb_array_elements(rules) AS rule\n            WHERE (rule ->> 'vector_index_enabled')::boolean IS TRUE\n        );\n    END LOOP;\n    IF vector_target_count > 0 AND p_embedding_binding IS NULL THEN\n        RAISE EXCEPTION 'Vector mappings require an exact embedding binding'\n            USING ERRCODE = '23514';\n    END IF;\n    embedding_hash := CASE\n        WHEN p_embedding_binding IS NULL THEN NULL\n        ELSE encode(sha256(convert_to(p_embedding_binding::text, 'UTF8')), 'hex')\n    END;\n    SELECT content_hash INTO base_hash\n    FROM knowledge.releases\n    WHERE workspace_id = p_workspace_id\n      AND graph_id = graph.id\n      AND id = graph.active_release_id;\n    global_pin_hash := encode(sha256(convert_to(jsonb_build_object(\n        'contract', 'KNOWLEDGE_STUDIO_DB_INGESTION_PIN_V1',\n        'graph_id', graph.id,\n        'graph_version', graph.version,\n        'studio_release_id', studio_release.id,\n        'studio_contract_hash', studio_release.contract_hash,\n        'ontology_version_id', ontology.id,\n        'ontology_checksum', ontology.checksum,\n        'manifest_id', p_manifest_id,\n        'manifest_version', p_manifest_version,\n        'manifest_hash', p_manifest_hash,\n        'source_profile_pins', p_source_profile_pins,\n        'embedding_binding_hash', embedding_hash,\n        'requester_authorization_hash', locked_authorization_hash\n    )::text, 'UTF8')), 'hex');\n    INSERT INTO knowledge.studio_ingestion_jobs (\n        id, workspace_id, graph_id, draft_id, studio_release_id,\n        studio_release_no, studio_contract_hash, ontology_version_id,\n        ontology_checksum, requested_by, graph_version, graph_classification,\n        graph_domain_ref_id, graph_domain_source_version, vector_target_count,\n        state, progress_percent, stage, manifest_id, manifest_version,\n        manifest_hash, pin_hash, request_hash, requester_authorization_hash,\n        embedding_binding_document, embedding_binding_hash,\n        base_release_id, base_release_hash, attempt_count, maximum_attempts,\n        current_attempt_id, next_attempt_at, lease_epoch, lease_token_hash,\n        lease_owner_fingerprint, lease_started_at, lease_expires_at,\n        source_access_started_at, source_access_deadline, result_changeset_id,\n        result_evidence_hash, source_read_receipt_hash, last_failure_code,\n        cancel_requested_by, cancel_requested_at, cancel_reason, completed_at,\n        created_at, updated_at, version\n    )\n    VALUES (\n        job_id, p_workspace_id, graph.id, draft.id, studio_release.id,\n        studio_release.release_no, studio_release.contract_hash, ontology.id,\n        ontology.checksum, actor_id, graph.version, graph.classification,\n        graph.domain_ref_id, graph.domain_source_version, vector_target_count,\n        'PENDING', 0, 'QUEUED', p_manifest_id, p_manifest_version,\n        p_manifest_hash, global_pin_hash, p_request_hash,\n        locked_authorization_hash, p_embedding_binding, embedding_hash,\n        graph.active_release_id, base_hash, 0, p_maximum_attempts,\n        NULL, now_at, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL,\n        NULL, NULL, NULL, NULL, NULL, NULL, NULL, now_at, now_at, 1\n    );\n    FOR binding IN\n        SELECT\n            binding_version.*,\n            source.catalog_asset_id,\n            source.source_version,\n            source.projection_source_version,\n            source.classification AS source_classification,\n            source.selection_hash,\n            target.canonical_name AS target_class_canonical_name\n        FROM knowledge.abox_binding_versions AS binding_version\n        JOIN knowledge.source_references AS source\n          ON source.workspace_id = binding_version.workspace_id\n         AND source.id = binding_version.source_reference_id\n        JOIN knowledge.ontology_elements AS target\n          ON target.workspace_id = binding_version.workspace_id\n         AND target.ontology_version_id = binding_version.ontology_version_id\n         AND target.id = binding_version.target_ontology_element_id\n        WHERE binding_version.workspace_id = p_workspace_id\n          AND binding_version.studio_release_id = studio_release.id\n        ORDER BY binding_version.ordinal\n    LOOP\n        SELECT pin INTO profile_pin\n        FROM jsonb_array_elements(p_source_profile_pins) AS pin\n        WHERE pin ->> 'asset_id' = binding.catalog_asset_id::text;\n        SELECT jsonb_agg(\n            jsonb_build_object(\n                'method', rule.method,\n                'source_field_path', rule.source_field_path,\n                'target_stable_element_id', rule.target_stable_element_id,\n                'target_canonical_name', element.canonical_name,\n                'target_data_type', CASE\n                    WHEN rule.method = 'PROPERTY'\n                    THEN element.element_document ->> 'data_type'\n                    ELSE NULL\n                END,\n                'target_nullable', CASE\n                    WHEN rule.method = 'PROPERTY'\n                    THEN element.element_document -> 'nullable'\n                    ELSE NULL\n                END,\n                'vector_index_enabled', CASE\n                    WHEN rule.method = 'PROPERTY'\n                    THEN COALESCE(\n                        (element.element_document ->> 'vector_index_enabled')::boolean,\n                        false\n                    )\n                    ELSE false\n                END,\n                'transform_id', rule.transform_id,\n                'transform_version', rule.transform_version\n            )\n            ORDER BY rule.ordinal\n        ) INTO rules\n        FROM knowledge.abox_mapping_rule_versions AS rule\n        JOIN knowledge.ontology_elements AS element\n          ON element.workspace_id = rule.workspace_id\n         AND element.ontology_version_id = rule.ontology_version_id\n         AND element.id = rule.target_ontology_element_id\n        WHERE rule.workspace_id = p_workspace_id\n          AND rule.binding_version_id = binding.id;\n        binding_pin_hash := encode(sha256(convert_to(jsonb_build_object(\n            'contract', 'STUDIO_INGESTION_BINDING_PIN_V1',\n            'job_pin_hash', global_pin_hash,\n            'binding_version_id', binding.id,\n            'mapping_hash', binding.mapping_hash,\n            'source_reference_id', binding.source_reference_id,\n            'source_version', binding.source_version,\n            'projection_source_version', binding.projection_source_version,\n            'selection_hash', binding.selection_hash,\n            'profile', profile_pin,\n            'rules', rules\n        )::text, 'UTF8')), 'hex');\n        INSERT INTO knowledge.studio_ingestion_binding_pins (\n            id, workspace_id, job_id, ordinal, studio_release_id,\n            binding_version_id, source_reference_id, source_asset_id,\n            source_version, projection_source_version, source_classification,\n            selection_hash, target_class_stable_id,\n            target_class_canonical_name, mapping_hash, connection_profile_id,\n            connection_profile_version, connection_profile_hash,\n            rules_document, pin_hash, created_at\n        )\n        VALUES (\n            gen_random_uuid(), p_workspace_id, job_id, binding.ordinal,\n            studio_release.id, binding.id, binding.source_reference_id,\n            binding.catalog_asset_id, binding.source_version,\n            binding.projection_source_version, binding.source_classification,\n            binding.selection_hash, binding.target_stable_element_id,\n            binding.target_class_canonical_name, binding.mapping_hash,\n            profile_pin ->> 'connection_profile_id',\n            (profile_pin ->> 'connection_profile_version')::integer,\n            profile_pin ->> 'connection_profile_hash',\n            rules, binding_pin_hash, now_at\n        );\n    END LOOP;\n    PERFORM knowledge.append_studio_ingestion_event_v1(\n        p_workspace_id, job_id, NULL, 'PENDING', 'REQUESTED',\n        actor_id, 'HUMAN', jsonb_build_object('pin_hash', global_pin_hash)\n    );\n    PERFORM knowledge.emit_studio_ingestion_outbox_v1(\n        p_workspace_id, job_id, 'PENDING', 1\n    );\n    RETURN jsonb_build_object('job_id', job_id::text);\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.cancel_studio_ingestion_v1(\n    p_workspace_id uuid,\n    p_job_id uuid,\n    p_expected_version integer,\n    p_reason text\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, platform, iam, knowledge\nAS $$\nDECLARE\n    actor_id uuid := NULLIF(current_setting('app.subject_id', true), '')::uuid;\n    job knowledge.studio_ingestion_jobs%ROWTYPE;\n    now_at timestamptz := transaction_timestamp();\n    target_state text;\nBEGIN\n    IF session_user <> 'datariver_app'\n       OR p_workspace_id IS DISTINCT FROM\n           NULLIF(current_setting('app.workspace_id', true), '')::uuid\n       OR actor_id IS NULL\n       OR char_length(COALESCE(btrim(p_reason), '')) NOT BETWEEN 1 AND 500 THEN\n        RAISE EXCEPTION 'invalid Studio ingestion cancellation'\n            USING ERRCODE = '42501';\n    END IF;\n    SELECT * INTO job\n    FROM knowledge.studio_ingestion_jobs\n    WHERE workspace_id = p_workspace_id AND id = p_job_id\n    FOR UPDATE;\n    IF NOT FOUND\n       OR job.requested_by IS DISTINCT FROM actor_id\n       OR job.version <> p_expected_version\n       OR NOT knowledge.current_studio_ingestion_human_can_v1(\n           p_workspace_id, actor_id,\n           COALESCE(job.graph_classification, 0), job.graph_domain_ref_id\n       )\n       OR job.state NOT IN ('PENDING','RETRY_WAIT','RUNNING') THEN\n        RAISE EXCEPTION 'Studio ingestion cancellation changed concurrently'\n            USING ERRCODE = '55000';\n    END IF;\n    target_state := CASE WHEN job.state = 'RUNNING' THEN 'CANCEL_REQUESTED'\n                         ELSE 'CANCELLED' END;\n    UPDATE knowledge.studio_ingestion_jobs\n    SET state = target_state,\n        stage = CASE WHEN target_state = 'CANCELLED' THEN 'COMPLETED' ELSE stage END,\n        last_failure_code = NULL,\n        cancel_requested_by = actor_id,\n        cancel_requested_at = now_at,\n        cancel_reason = btrim(p_reason),\n        completed_at = CASE WHEN target_state = 'CANCELLED' THEN now_at ELSE NULL END,\n        updated_at = now_at,\n        version = version + 1\n    WHERE workspace_id = p_workspace_id AND id = p_job_id\n    RETURNING * INTO job;\n    PERFORM knowledge.append_studio_ingestion_event_v1(\n        p_workspace_id, p_job_id, job.current_attempt_id, target_state,\n        'CANCEL_REQUESTED', actor_id, 'HUMAN',\n        jsonb_build_object('reason', btrim(p_reason))\n    );\n    PERFORM knowledge.emit_studio_ingestion_outbox_v1(\n        p_workspace_id, p_job_id, target_state, job.version\n    );\n    RETURN jsonb_build_object(\n        'job_id', p_job_id::text, 'state', target_state, 'version', job.version\n    );\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.retry_studio_ingestion_v1(\n    p_workspace_id uuid,\n    p_job_id uuid,\n    p_expected_version integer\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, iam, knowledge\nAS $$\nDECLARE\n    actor_id uuid := NULLIF(current_setting('app.subject_id', true), '')::uuid;\n    job knowledge.studio_ingestion_jobs%ROWTYPE;\n    now_at timestamptz := transaction_timestamp();\nBEGIN\n    IF session_user <> 'datariver_app'\n       OR p_workspace_id IS DISTINCT FROM\n           NULLIF(current_setting('app.workspace_id', true), '')::uuid\n       OR actor_id IS NULL THEN\n        RAISE EXCEPTION 'invalid Studio ingestion retry'\n            USING ERRCODE = '42501';\n    END IF;\n    SELECT * INTO job\n    FROM knowledge.studio_ingestion_jobs\n    WHERE workspace_id = p_workspace_id AND id = p_job_id\n    FOR UPDATE;\n    IF NOT FOUND\n       OR job.requested_by IS DISTINCT FROM actor_id\n       OR job.version <> p_expected_version\n       OR NOT knowledge.current_studio_ingestion_human_can_v1(\n           p_workspace_id, actor_id,\n           COALESCE(job.graph_classification, 0), job.graph_domain_ref_id\n       )\n       OR job.state NOT IN ('FAILED','STALE','CANCELLED')\n       OR job.attempt_count >= 20 THEN\n        RAISE EXCEPTION 'Studio ingestion retry changed concurrently'\n            USING ERRCODE = '55000';\n    END IF;\n    UPDATE knowledge.studio_ingestion_jobs\n    SET state = 'RETRY_WAIT', stage = 'QUEUED', progress_percent = 0,\n        maximum_attempts = greatest(maximum_attempts, attempt_count + 1),\n        next_attempt_at = now_at, last_failure_code = 'MANUAL_RETRY',\n        cancel_requested_by = NULL, cancel_requested_at = NULL, cancel_reason = NULL,\n        completed_at = NULL, updated_at = now_at, version = version + 1\n    WHERE workspace_id = p_workspace_id AND id = p_job_id\n    RETURNING * INTO job;\n    PERFORM knowledge.append_studio_ingestion_event_v1(\n        p_workspace_id, p_job_id, job.current_attempt_id, 'RETRY_WAIT',\n        'MANUAL_RETRY', actor_id, 'HUMAN',\n        jsonb_build_object('attempt_count', job.attempt_count)\n    );\n    PERFORM knowledge.emit_studio_ingestion_outbox_v1(\n        p_workspace_id, p_job_id, 'RETRY_WAIT', job.version\n    );\n    RETURN jsonb_build_object(\n        'job_id', p_job_id::text, 'state', 'RETRY_WAIT', 'version', job.version\n    );\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.claim_studio_ingestion_v1(\n    p_workspace_id uuid,\n    p_worker_fingerprint text,\n    p_lease_token text,\n    p_lease_seconds integer\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, platform, iam, catalog, integration, knowledge\nAS $$\nDECLARE\n    job knowledge.studio_ingestion_jobs%ROWTYPE;\n    previous_attempt knowledge.studio_ingestion_attempts%ROWTYPE;\n    attempt_id uuid := gen_random_uuid();\n    actor_id uuid := NULLIF(current_setting('app.subject_id', true), '')::uuid;\n    now_at timestamptz := transaction_timestamp();\n    token_hash text;\n    new_epoch bigint;\n    new_attempt integer;\n    drift_code text;\n    claim_document jsonb;\n    workspace_available boolean;\n    current_authorization_hash text;\nBEGIN\n    IF char_length(COALESCE(p_worker_fingerprint, '')) NOT BETWEEN 1 AND 255\n       OR p_worker_fingerprint IS DISTINCT FROM btrim(p_worker_fingerprint)\n       OR char_length(COALESCE(p_lease_token, '')) NOT BETWEEN 32 AND 200\n       OR p_lease_seconds NOT BETWEEN 60 AND 3600\n       OR NOT knowledge.current_studio_ingestion_service_can_v1(\n           p_workspace_id, 'kg.ingestion.execute', 0, NULL\n       ) THEN\n        RAISE EXCEPTION 'invalid Studio ingestion claim'\n            USING ERRCODE = '42501';\n    END IF;\n    SELECT * INTO job\n    FROM knowledge.studio_ingestion_jobs AS candidate\n    WHERE candidate.workspace_id = p_workspace_id\n      AND candidate.state IN ('RUNNING','CANCEL_REQUESTED')\n      AND candidate.lease_expires_at <= now_at\n      AND knowledge.current_studio_ingestion_service_can_v1(\n          candidate.workspace_id, 'kg.ingestion.execute',\n          candidate.graph_classification, candidate.graph_domain_ref_id\n      )\n    ORDER BY candidate.lease_expires_at, candidate.id\n    FOR UPDATE SKIP LOCKED\n    LIMIT 1;\n    IF FOUND THEN\n        SELECT * INTO previous_attempt\n        FROM knowledge.studio_ingestion_attempts\n        WHERE workspace_id = p_workspace_id AND id = job.current_attempt_id\n        FOR UPDATE;\n        UPDATE knowledge.studio_ingestion_attempts\n        SET state = 'SUPERSEDED', stage = 'COMPLETED',\n            retryable = (job.state <> 'CANCEL_REQUESTED'),\n            failure_code = 'LEASE_EXPIRED', finished_at = now_at\n        WHERE workspace_id = p_workspace_id\n          AND id = previous_attempt.id\n          AND job_id = job.id\n          AND state = 'RUNNING'\n          AND lease_epoch = job.lease_epoch\n          AND lease_token_hash = job.lease_token_hash;\n        IF NOT FOUND THEN\n            RAISE EXCEPTION 'Studio ingestion expired attempt fence is invalid'\n                USING ERRCODE = '55000';\n        END IF;\n        IF job.state = 'CANCEL_REQUESTED' THEN\n            UPDATE knowledge.studio_ingestion_jobs\n            SET state = 'CANCELLED', stage = 'COMPLETED',\n                lease_token_hash = NULL, lease_owner_fingerprint = NULL,\n                lease_started_at = NULL, lease_expires_at = NULL,\n                completed_at = now_at, updated_at = now_at, version = version + 1\n            WHERE workspace_id = p_workspace_id AND id = job.id\n            RETURNING * INTO job;\n            PERFORM knowledge.append_studio_ingestion_event_v1(\n                p_workspace_id, job.id, previous_attempt.id, 'CANCELLED',\n                'CANCELLED_AFTER_LEASE_EXPIRY', actor_id, 'SERVICE',\n                jsonb_build_object('lease_epoch', job.lease_epoch)\n            );\n            PERFORM knowledge.emit_studio_ingestion_outbox_v1(\n                p_workspace_id, job.id, 'CANCELLED', job.version\n            );\n        ELSIF job.attempt_count >= job.maximum_attempts THEN\n            UPDATE knowledge.studio_ingestion_jobs\n            SET state = 'STALE', stage = 'COMPLETED',\n                last_failure_code = 'LEASE_EXHAUSTED',\n                lease_token_hash = NULL, lease_owner_fingerprint = NULL,\n                lease_started_at = NULL, lease_expires_at = NULL,\n                completed_at = now_at, updated_at = now_at, version = version + 1\n            WHERE workspace_id = p_workspace_id AND id = job.id\n            RETURNING * INTO job;\n            PERFORM knowledge.append_studio_ingestion_event_v1(\n                p_workspace_id, job.id, previous_attempt.id, 'STALE',\n                'LEASE_EXHAUSTED', actor_id, 'SERVICE',\n                jsonb_build_object('lease_epoch', job.lease_epoch)\n            );\n            PERFORM knowledge.emit_studio_ingestion_outbox_v1(\n                p_workspace_id, job.id, 'STALE', job.version\n            );\n        ELSE\n            UPDATE knowledge.studio_ingestion_jobs\n            SET state = 'RETRY_WAIT', stage = 'QUEUED', progress_percent = 0,\n                next_attempt_at = now_at + interval '5 seconds',\n                last_failure_code = 'LEASE_EXPIRED',\n                lease_token_hash = NULL, lease_owner_fingerprint = NULL,\n                lease_started_at = NULL, lease_expires_at = NULL,\n                updated_at = now_at, version = version + 1\n            WHERE workspace_id = p_workspace_id AND id = job.id\n            RETURNING * INTO job;\n            PERFORM knowledge.append_studio_ingestion_event_v1(\n                p_workspace_id, job.id, previous_attempt.id, 'RETRY_WAIT',\n                'LEASE_EXPIRED', actor_id, 'SERVICE',\n                jsonb_build_object('lease_epoch', job.lease_epoch)\n            );\n            PERFORM knowledge.emit_studio_ingestion_outbox_v1(\n                p_workspace_id, job.id, 'RETRY_WAIT', job.version\n            );\n        END IF;\n    END IF;\n    SELECT * INTO job\n    FROM knowledge.studio_ingestion_jobs AS candidate\n    WHERE candidate.workspace_id = p_workspace_id\n      AND candidate.state IN ('PENDING','RETRY_WAIT')\n      AND candidate.next_attempt_at <= now_at\n      AND knowledge.current_studio_ingestion_service_can_v1(\n          candidate.workspace_id, 'kg.ingestion.execute',\n          candidate.graph_classification, candidate.graph_domain_ref_id\n      )\n    ORDER BY candidate.next_attempt_at, candidate.created_at, candidate.id\n    FOR UPDATE SKIP LOCKED\n    LIMIT 1;\n    IF NOT FOUND THEN\n        RETURN NULL;\n    END IF;\n    IF NOT knowledge.current_studio_ingestion_service_can_v1(\n           p_workspace_id, 'kg.ingestion.execute',\n           job.graph_classification, job.graph_domain_ref_id\n       ) THEN\n        RETURN NULL;\n    END IF;\n    SELECT true INTO workspace_available\n    FROM platform.workspaces\n    WHERE id = p_workspace_id AND status = 'ACTIVE'\n    FOR SHARE;\n    PERFORM 1 FROM knowledge.graphs\n    WHERE workspace_id = job.workspace_id AND id = job.graph_id\n    FOR SHARE;\n    PERFORM 1 FROM knowledge.studio_releases\n    WHERE workspace_id = job.workspace_id\n      AND graph_id = job.graph_id\n      AND id = job.studio_release_id\n    FOR SHARE;\n    PERFORM 1 FROM knowledge.ontology_versions\n    WHERE workspace_id = job.workspace_id\n      AND graph_id = job.graph_id\n      AND id = job.ontology_version_id\n    FOR SHARE;\n    IF job.base_release_id IS NOT NULL THEN\n        PERFORM 1 FROM knowledge.releases\n        WHERE workspace_id = job.workspace_id\n          AND graph_id = job.graph_id\n          AND id = job.base_release_id\n        FOR SHARE;\n    END IF;\n    PERFORM 1\n    FROM iam.workspace_memberships AS membership\n    JOIN iam.subjects AS subject ON subject.id = membership.subject_id\n    WHERE membership.workspace_id = job.workspace_id\n      AND membership.subject_id = job.requested_by\n    FOR SHARE OF membership, subject;\n    SELECT encode(sha256(convert_to(jsonb_build_object(\n        'contract', 'KNOWLEDGE_STUDIO_INGESTION_REQUEST_AUTHORIZATION_DB_V1',\n        'workspace_id', membership.workspace_id,\n        'subject_id', membership.subject_id,\n        'subject_active', subject.active,\n        'membership_active', membership.active,\n        'access_expires_at', membership.access_expires_at,\n        'job_function', membership.job_function,\n        'clearance', membership.clearance,\n        'attributes', membership.attributes\n    )::text, 'UTF8')), 'hex')\n    INTO current_authorization_hash\n    FROM iam.workspace_memberships AS membership\n    JOIN iam.subjects AS subject ON subject.id = membership.subject_id\n    WHERE membership.workspace_id = job.workspace_id\n      AND membership.subject_id = job.requested_by;\n    SELECT CASE\n        WHEN NOT COALESCE(workspace_available, false)\n        THEN 'STALE_WORKSPACE'\n        WHEN graph.id IS NULL\n          OR graph.version <> job.graph_version\n          OR graph.status <> 'PUBLISHED'\n          OR graph.classification <> job.graph_classification\n          OR graph.domain_ref_id IS DISTINCT FROM job.graph_domain_ref_id\n          OR graph.domain_source_version IS DISTINCT FROM job.graph_domain_source_version\n          OR graph.active_studio_release_id IS DISTINCT FROM job.studio_release_id\n          OR graph.active_release_id IS DISTINCT FROM job.base_release_id\n        THEN 'STALE_GRAPH'\n        WHEN studio_release.id IS NULL\n          OR studio_release.state <> 'ACTIVE'\n          OR studio_release.contract_hash <> job.studio_contract_hash\n          OR studio_release.ontology_version_id <> job.ontology_version_id\n        THEN 'STALE_STUDIO_RELEASE'\n        WHEN ontology.id IS NULL OR ontology.checksum <> job.ontology_checksum\n        THEN 'STALE_ONTOLOGY'\n        WHEN job.base_release_id IS NOT NULL\n          AND (base_release.id IS NULL OR base_release.content_hash <> job.base_release_hash)\n        THEN 'STALE_BASE_RELEASE'\n        WHEN NOT (\n            COALESCE(subject.active, false)\n            AND COALESCE(membership.active, false)\n            AND (\n                membership.access_expires_at IS NULL\n                OR membership.access_expires_at > now_at\n            )\n            AND COALESCE(membership.job_function, '') <> 'SERVICE_ACCOUNT'\n            AND membership.clearance >= job.graph_classification\n            AND COALESCE(\n                membership.attributes -> 'allowed_actions', '[]'::jsonb\n            ) ? 'kg.edit'\n            AND NOT (\n                COALESCE(\n                    membership.attributes -> 'denied_actions', '[]'::jsonb\n                ) ? 'kg.edit'\n            )\n            AND (\n                job.graph_classification = 0\n                OR job.graph_domain_ref_id IS NULL\n                OR COALESCE(\n                    membership.attributes -> 'allowed_domain_ids', '[]'::jsonb\n                ) ? job.graph_domain_ref_id::text\n            )\n        )\n        THEN 'STALE_REQUESTER_AUTHORIZATION'\n        WHEN current_authorization_hash IS DISTINCT FROM\n             job.requester_authorization_hash\n        THEN 'STALE_REQUESTER_AUTHORIZATION'\n        ELSE NULL\n    END INTO drift_code\n    FROM knowledge.graphs AS graph\n    LEFT JOIN knowledge.studio_releases AS studio_release\n      ON studio_release.workspace_id = graph.workspace_id\n     AND studio_release.graph_id = graph.id\n     AND studio_release.id = job.studio_release_id\n    LEFT JOIN knowledge.ontology_versions AS ontology\n      ON ontology.workspace_id = graph.workspace_id\n     AND ontology.graph_id = graph.id\n     AND ontology.id = job.ontology_version_id\n    LEFT JOIN knowledge.releases AS base_release\n      ON base_release.workspace_id = graph.workspace_id\n     AND base_release.graph_id = graph.id\n     AND base_release.id = job.base_release_id\n    LEFT JOIN iam.workspace_memberships AS membership\n      ON membership.workspace_id = job.workspace_id\n     AND membership.subject_id = job.requested_by\n    LEFT JOIN iam.subjects AS subject ON subject.id = job.requested_by\n    WHERE graph.workspace_id = job.workspace_id AND graph.id = job.graph_id;\n    IF NOT FOUND THEN\n        drift_code := 'STALE_GRAPH';\n    END IF;\n    IF drift_code IS NOT NULL THEN\n        UPDATE knowledge.studio_ingestion_jobs\n        SET state = 'STALE', stage = 'COMPLETED',\n            last_failure_code = drift_code, completed_at = now_at,\n            updated_at = now_at, version = version + 1\n        WHERE workspace_id = p_workspace_id AND id = job.id\n        RETURNING * INTO job;\n        PERFORM knowledge.append_studio_ingestion_event_v1(\n            p_workspace_id, job.id, job.current_attempt_id, 'STALE',\n            drift_code, actor_id, 'SERVICE', '{}'::jsonb\n        );\n        PERFORM knowledge.emit_studio_ingestion_outbox_v1(\n            p_workspace_id, job.id, 'STALE', job.version\n        );\n        RETURN NULL;\n    END IF;\n    token_hash := encode(sha256(convert_to(p_lease_token, 'UTF8')), 'hex');\n    new_epoch := job.lease_epoch + 1;\n    new_attempt := job.attempt_count + 1;\n    INSERT INTO knowledge.studio_ingestion_attempts (\n        id, workspace_id, job_id, attempt_no, lease_epoch, lease_token_hash,\n        worker_fingerprint, state, stage, claimed_at, lease_expires_at,\n        source_access_started_at, source_access_deadline,\n        source_read_receipt_hash, materialization_hash, result_evidence_hash,\n        retryable, failure_code, finished_at\n    )\n    VALUES (\n        attempt_id, p_workspace_id, job.id, new_attempt, new_epoch, token_hash,\n        p_worker_fingerprint, 'RUNNING', 'SOURCE_READ', now_at,\n        now_at + make_interval(secs => p_lease_seconds),\n        NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL\n    );\n    UPDATE knowledge.studio_ingestion_jobs\n    SET state = 'RUNNING', stage = 'SOURCE_READ', progress_percent = 10,\n        attempt_count = new_attempt, current_attempt_id = attempt_id,\n        lease_epoch = new_epoch, lease_token_hash = token_hash,\n        lease_owner_fingerprint = p_worker_fingerprint,\n        lease_started_at = now_at,\n        lease_expires_at = now_at + make_interval(secs => p_lease_seconds),\n        source_access_started_at = NULL, source_access_deadline = NULL,\n        last_failure_code = NULL, updated_at = now_at, version = version + 1\n    WHERE workspace_id = p_workspace_id AND id = job.id\n    RETURNING * INTO job;\n    PERFORM knowledge.append_studio_ingestion_event_v1(\n        p_workspace_id, job.id, attempt_id, 'RUNNING', 'WORKER_CLAIMED',\n        actor_id, 'SERVICE', jsonb_build_object(\n            'attempt_no', new_attempt, 'lease_epoch', new_epoch,\n            'worker_fingerprint', p_worker_fingerprint\n        )\n    );\n    SELECT jsonb_build_object(\n        'workspace_id', job.workspace_id::text,\n        'job_id', job.id::text,\n        'graph_id', job.graph_id::text,\n        'draft_id', job.draft_id::text,\n        'studio_release_id', job.studio_release_id::text,\n        'ontology_version_id', job.ontology_version_id::text,\n        'requested_by', job.requested_by::text,\n        'graph_classification', job.graph_classification,\n        'manifest_id', job.manifest_id,\n        'manifest_version', job.manifest_version,\n        'manifest_hash', job.manifest_hash,\n        'pin_hash', job.pin_hash,\n        'embedding_binding', job.embedding_binding_document,\n        'bindings', (\n            SELECT jsonb_agg(jsonb_build_object(\n                'pin_id', pin.id::text,\n                'binding_version_id', pin.binding_version_id::text,\n                'source_reference_id', pin.source_reference_id::text,\n                'source_asset_id', pin.source_asset_id::text,\n                'source_version', pin.source_version,\n                'projection_source_version', pin.projection_source_version,\n                'source_classification', pin.source_classification,\n                'target_class_stable_id', pin.target_class_stable_id,\n                'target_class_canonical_name', pin.target_class_canonical_name,\n                'mapping_hash', pin.mapping_hash,\n                'connection_profile_id', pin.connection_profile_id,\n                'connection_profile_version', pin.connection_profile_version,\n                'connection_profile_hash', pin.connection_profile_hash,\n                'rules', pin.rules_document\n            ) ORDER BY pin.ordinal)\n            FROM knowledge.studio_ingestion_binding_pins AS pin\n            WHERE pin.workspace_id = job.workspace_id AND pin.job_id = job.id\n        ),\n        'attempt_id', attempt_id::text,\n        'attempt_no', new_attempt,\n        'lease_epoch', new_epoch,\n        'worker_fingerprint', p_worker_fingerprint\n    ) INTO claim_document;\n    RETURN claim_document;\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.current_studio_ingestion_lease_matches_v1(\n    p_workspace_id uuid,\n    p_job_id uuid,\n    p_attempt_id uuid,\n    p_lease_epoch bigint,\n    p_lease_token text,\n    p_worker_fingerprint text\n)\nRETURNS boolean\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = pg_catalog, knowledge\nAS $$\n    SELECT EXISTS (\n        SELECT 1\n        FROM knowledge.studio_ingestion_jobs AS job\n        JOIN knowledge.studio_ingestion_attempts AS attempt\n          ON attempt.workspace_id = job.workspace_id\n         AND attempt.job_id = job.id\n         AND attempt.id = job.current_attempt_id\n        WHERE job.workspace_id = p_workspace_id\n          AND job.id = p_job_id\n          AND attempt.id = p_attempt_id\n          AND job.lease_epoch = p_lease_epoch\n          AND attempt.lease_epoch = p_lease_epoch\n          AND job.lease_token_hash = encode(\n              sha256(convert_to(p_lease_token, 'UTF8')), 'hex'\n          )\n          AND attempt.lease_token_hash = job.lease_token_hash\n          AND attempt.worker_fingerprint = job.lease_owner_fingerprint\n          AND job.lease_owner_fingerprint = p_worker_fingerprint\n          AND attempt.state = 'RUNNING'\n    )\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.freeze_studio_ingestion_source_access_v1(\n    p_workspace_id uuid,\n    p_job_id uuid,\n    p_attempt_id uuid,\n    p_lease_epoch bigint,\n    p_lease_token text,\n    p_worker_fingerprint text,\n    p_hard_timeout_seconds integer,\n    p_completion_margin_seconds integer\n)\nRETURNS timestamptz\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, knowledge\nAS $$\nDECLARE\n    job knowledge.studio_ingestion_jobs%ROWTYPE;\n    token_hash text := encode(sha256(convert_to(p_lease_token, 'UTF8')), 'hex');\n    now_at timestamptz := clock_timestamp();\n    deadline timestamptz;\nBEGIN\n    SELECT * INTO job\n    FROM knowledge.studio_ingestion_jobs\n    WHERE workspace_id = p_workspace_id AND id = p_job_id\n    FOR UPDATE;\n    IF NOT knowledge.current_studio_ingestion_service_can_v1(\n           p_workspace_id, 'kg.ingestion.execute',\n           COALESCE(job.graph_classification, 0), job.graph_domain_ref_id\n       )\n       OR job.state <> 'RUNNING'\n       OR job.current_attempt_id IS DISTINCT FROM p_attempt_id\n       OR job.lease_epoch <> p_lease_epoch\n       OR job.lease_token_hash IS DISTINCT FROM token_hash\n       OR job.lease_owner_fingerprint IS DISTINCT FROM p_worker_fingerprint\n       OR NOT knowledge.current_studio_ingestion_lease_matches_v1(\n           p_workspace_id, p_job_id, p_attempt_id, p_lease_epoch, p_lease_token,\n           p_worker_fingerprint\n       )\n       OR job.lease_expires_at <= now_at\n       OR job.source_access_deadline IS NOT NULL\n       OR p_hard_timeout_seconds NOT BETWEEN 1 AND 3600\n       OR p_completion_margin_seconds NOT BETWEEN 1 AND 600 THEN\n        RAISE EXCEPTION 'invalid Studio source-access freeze'\n            USING ERRCODE = '55000';\n    END IF;\n    deadline := least(\n        now_at + make_interval(secs => p_hard_timeout_seconds),\n        job.lease_expires_at - make_interval(secs => p_completion_margin_seconds)\n    );\n    IF deadline <= now_at THEN\n        RAISE EXCEPTION 'Studio source-access budget is exhausted'\n            USING ERRCODE = '57014';\n    END IF;\n    UPDATE knowledge.studio_ingestion_jobs\n    SET source_access_started_at = now_at, source_access_deadline = deadline,\n        updated_at = transaction_timestamp(), version = version + 1\n    WHERE workspace_id = p_workspace_id AND id = p_job_id;\n    UPDATE knowledge.studio_ingestion_attempts\n    SET source_access_started_at = now_at, source_access_deadline = deadline\n    WHERE workspace_id = p_workspace_id AND id = p_attempt_id\n      AND job_id = p_job_id AND state = 'RUNNING'\n      AND lease_epoch = p_lease_epoch AND lease_token_hash = token_hash;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'Studio source-access attempt is unavailable'\n            USING ERRCODE = '55000';\n    END IF;\n    RETURN deadline;\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.assert_studio_ingestion_source_statement_fence_v1(\n    p_workspace_id uuid,\n    p_job_id uuid,\n    p_attempt_id uuid,\n    p_lease_epoch bigint,\n    p_lease_token text,\n    p_worker_fingerprint text\n)\nRETURNS integer\nLANGUAGE plpgsql\nSTABLE\nSECURITY DEFINER\nSET search_path = pg_catalog, knowledge\nAS $$\nDECLARE\n    job knowledge.studio_ingestion_jobs%ROWTYPE;\n    token_hash text := encode(sha256(convert_to(p_lease_token, 'UTF8')), 'hex');\n    now_at timestamptz := clock_timestamp();\n    remaining integer;\nBEGIN\n    SELECT * INTO job\n    FROM knowledge.studio_ingestion_jobs\n    WHERE workspace_id = p_workspace_id AND id = p_job_id;\n    IF NOT knowledge.current_studio_ingestion_service_can_v1(\n           p_workspace_id, 'kg.ingestion.execute',\n           COALESCE(job.graph_classification, 0), job.graph_domain_ref_id\n       )\n       OR job.state <> 'RUNNING'\n       OR job.current_attempt_id IS DISTINCT FROM p_attempt_id\n       OR job.lease_epoch <> p_lease_epoch\n       OR job.lease_token_hash IS DISTINCT FROM token_hash\n       OR job.lease_owner_fingerprint IS DISTINCT FROM p_worker_fingerprint\n       OR NOT knowledge.current_studio_ingestion_lease_matches_v1(\n           p_workspace_id, p_job_id, p_attempt_id, p_lease_epoch, p_lease_token,\n           p_worker_fingerprint\n       )\n       OR job.lease_expires_at <= now_at\n       OR job.source_access_deadline IS NULL\n       OR job.source_access_deadline <= now_at THEN\n        RAISE EXCEPTION 'Studio source statement is outside its fence'\n            USING ERRCODE = '57014';\n    END IF;\n    remaining := floor(\n        extract(epoch FROM (job.source_access_deadline - now_at)) * 1000\n    )::integer;\n    RETURN greatest(1, remaining);\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.renew_studio_ingestion_v1(\n    p_workspace_id uuid,\n    p_job_id uuid,\n    p_attempt_id uuid,\n    p_lease_epoch bigint,\n    p_lease_token text,\n    p_worker_fingerprint text,\n    p_lease_seconds integer,\n    p_stage text,\n    p_progress_percent integer\n)\nRETURNS timestamptz\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, knowledge\nAS $$\nDECLARE\n    job knowledge.studio_ingestion_jobs%ROWTYPE;\n    token_hash text := encode(sha256(convert_to(p_lease_token, 'UTF8')), 'hex');\n    now_at timestamptz := clock_timestamp();\n    new_expiry timestamptz;\nBEGIN\n    SELECT * INTO job\n    FROM knowledge.studio_ingestion_jobs\n    WHERE workspace_id = p_workspace_id AND id = p_job_id\n    FOR UPDATE;\n    IF NOT knowledge.current_studio_ingestion_service_can_v1(\n           p_workspace_id, 'kg.ingestion.execute',\n           COALESCE(job.graph_classification, 0), job.graph_domain_ref_id\n       )\n       OR job.state <> 'RUNNING'\n       OR job.current_attempt_id IS DISTINCT FROM p_attempt_id\n       OR job.lease_epoch <> p_lease_epoch\n       OR job.lease_token_hash IS DISTINCT FROM token_hash\n       OR job.lease_owner_fingerprint IS DISTINCT FROM p_worker_fingerprint\n       OR NOT knowledge.current_studio_ingestion_lease_matches_v1(\n           p_workspace_id, p_job_id, p_attempt_id, p_lease_epoch, p_lease_token,\n           p_worker_fingerprint\n       )\n       OR job.lease_expires_at <= now_at\n       OR p_lease_seconds NOT BETWEEN 60 AND 3600\n       OR p_stage NOT IN ('MAPPING','EMBEDDING','FINALIZING')\n       OR p_progress_percent NOT BETWEEN 20 AND 99\n       OR p_progress_percent < job.progress_percent\n       OR (\n           CASE p_stage\n               WHEN 'MAPPING' THEN 2\n               WHEN 'EMBEDDING' THEN 3\n               WHEN 'FINALIZING' THEN 4\n               ELSE 0\n           END\n           <\n           CASE job.stage\n               WHEN 'SOURCE_READ' THEN 1\n               WHEN 'MAPPING' THEN 2\n               WHEN 'EMBEDDING' THEN 3\n               WHEN 'FINALIZING' THEN 4\n               ELSE 5\n           END\n       ) THEN\n        RAISE EXCEPTION 'invalid Studio ingestion renewal'\n            USING ERRCODE = '55000';\n    END IF;\n    new_expiry := now_at + make_interval(secs => p_lease_seconds);\n    UPDATE knowledge.studio_ingestion_jobs\n    SET stage = p_stage, progress_percent = p_progress_percent,\n        lease_started_at = now_at, lease_expires_at = new_expiry,\n        updated_at = transaction_timestamp(), version = version + 1\n    WHERE workspace_id = p_workspace_id AND id = p_job_id;\n    UPDATE knowledge.studio_ingestion_attempts\n    SET stage = p_stage, lease_expires_at = new_expiry\n    WHERE workspace_id = p_workspace_id AND id = p_attempt_id\n      AND job_id = p_job_id AND state = 'RUNNING'\n      AND lease_epoch = p_lease_epoch AND lease_token_hash = token_hash;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'Studio ingestion renewal attempt is unavailable'\n            USING ERRCODE = '55000';\n    END IF;\n    RETURN new_expiry;\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.ensure_studio_ingestion_current_v1(\n    p_workspace_id uuid,\n    p_job_id uuid,\n    p_attempt_id uuid,\n    p_lease_epoch bigint,\n    p_lease_token text,\n    p_worker_fingerprint text,\n    p_manifest_id text,\n    p_manifest_version integer,\n    p_manifest_hash text,\n    p_embedding_binding jsonb\n)\nRETURNS text\nLANGUAGE plpgsql\nSTABLE\nSECURITY DEFINER\nSET search_path = pg_catalog, iam, knowledge\nAS $$\nDECLARE\n    job knowledge.studio_ingestion_jobs%ROWTYPE;\n    graph knowledge.graphs%ROWTYPE;\n    studio_release knowledge.studio_releases%ROWTYPE;\n    ontology knowledge.ontology_versions%ROWTYPE;\n    base_release knowledge.releases%ROWTYPE;\n    membership iam.workspace_memberships%ROWTYPE;\n    subject iam.subjects%ROWTYPE;\n    token_hash text := encode(sha256(convert_to(p_lease_token, 'UTF8')), 'hex');\n    current_authorization_hash text;\nBEGIN\n    SELECT * INTO job FROM knowledge.studio_ingestion_jobs\n    WHERE workspace_id = p_workspace_id AND id = p_job_id;\n    IF NOT knowledge.current_studio_ingestion_service_can_v1(\n           p_workspace_id, 'kg.ingestion.execute',\n           COALESCE(job.graph_classification, 0), job.graph_domain_ref_id\n       )\n       OR job.state <> 'RUNNING'\n       OR job.current_attempt_id IS DISTINCT FROM p_attempt_id\n       OR job.lease_epoch <> p_lease_epoch\n       OR job.lease_token_hash IS DISTINCT FROM token_hash\n       OR job.lease_owner_fingerprint IS DISTINCT FROM p_worker_fingerprint\n       OR NOT knowledge.current_studio_ingestion_lease_matches_v1(\n           p_workspace_id, p_job_id, p_attempt_id, p_lease_epoch, p_lease_token,\n           p_worker_fingerprint\n       )\n       OR job.lease_expires_at <= clock_timestamp() THEN\n        RAISE EXCEPTION 'Studio ingestion claim is stale'\n            USING ERRCODE = '55000';\n    END IF;\n    IF job.manifest_id <> p_manifest_id\n       OR job.manifest_version <> p_manifest_version\n       OR job.manifest_hash <> p_manifest_hash THEN\n        RETURN 'STALE_SOURCE_MANIFEST';\n    END IF;\n    IF job.embedding_binding_document IS DISTINCT FROM p_embedding_binding THEN\n        RETURN 'STALE_EMBEDDING_BINDING';\n    END IF;\n    SELECT * INTO graph FROM knowledge.graphs\n    WHERE workspace_id = p_workspace_id AND id = job.graph_id;\n    SELECT * INTO studio_release FROM knowledge.studio_releases\n    WHERE workspace_id = p_workspace_id AND graph_id = job.graph_id\n      AND id = job.studio_release_id;\n    SELECT * INTO ontology FROM knowledge.ontology_versions\n    WHERE workspace_id = p_workspace_id AND graph_id = job.graph_id\n      AND id = job.ontology_version_id;\n    SELECT * INTO base_release FROM knowledge.releases\n    WHERE workspace_id = p_workspace_id AND graph_id = job.graph_id\n      AND id = job.base_release_id;\n    SELECT * INTO membership FROM iam.workspace_memberships\n    WHERE workspace_id = p_workspace_id AND subject_id = job.requested_by;\n    SELECT * INTO subject FROM iam.subjects WHERE id = job.requested_by;\n    IF graph.id IS NULL\n       OR graph.version <> job.graph_version\n       OR graph.status <> 'PUBLISHED'\n       OR graph.classification <> job.graph_classification\n       OR graph.domain_ref_id IS DISTINCT FROM job.graph_domain_ref_id\n       OR graph.domain_source_version IS DISTINCT FROM job.graph_domain_source_version\n       OR graph.active_studio_release_id IS DISTINCT FROM job.studio_release_id\n       OR graph.active_release_id IS DISTINCT FROM job.base_release_id THEN\n        RETURN 'STALE_GRAPH';\n    END IF;\n    IF studio_release.id IS NULL\n       OR studio_release.state <> 'ACTIVE'\n       OR studio_release.contract_hash <> job.studio_contract_hash\n       OR studio_release.ontology_version_id <> job.ontology_version_id THEN\n        RETURN 'STALE_STUDIO_RELEASE';\n    END IF;\n    IF ontology.id IS NULL OR ontology.checksum <> job.ontology_checksum THEN\n        RETURN 'STALE_ONTOLOGY';\n    END IF;\n    IF job.base_release_id IS NOT NULL\n       AND (\n           base_release.id IS NULL\n           OR base_release.content_hash <> job.base_release_hash\n       ) THEN\n        RETURN 'STALE_BASE_RELEASE';\n    END IF;\n    SELECT encode(sha256(convert_to(jsonb_build_object(\n        'contract', 'KNOWLEDGE_STUDIO_INGESTION_REQUEST_AUTHORIZATION_DB_V1',\n        'workspace_id', membership.workspace_id,\n        'subject_id', membership.subject_id,\n        'subject_active', subject.active,\n        'membership_active', membership.active,\n        'access_expires_at', membership.access_expires_at,\n        'job_function', membership.job_function,\n        'clearance', membership.clearance,\n        'attributes', membership.attributes\n    )::text, 'UTF8')), 'hex')\n    INTO current_authorization_hash;\n    IF subject.id IS NULL OR membership.subject_id IS NULL\n       OR NOT subject.active OR NOT membership.active\n       OR (\n           membership.access_expires_at IS NOT NULL\n           AND membership.access_expires_at <= transaction_timestamp()\n       )\n       OR COALESCE(membership.job_function, '') = 'SERVICE_ACCOUNT'\n       OR membership.clearance < job.graph_classification\n       OR NOT (\n           COALESCE(\n               membership.attributes -> 'allowed_actions', '[]'::jsonb\n           ) ? 'kg.edit'\n       )\n       OR (\n           COALESCE(\n               membership.attributes -> 'denied_actions', '[]'::jsonb\n           ) ? 'kg.edit'\n       )\n       OR (\n           job.graph_classification <> 0\n           AND job.graph_domain_ref_id IS NOT NULL\n           AND NOT (\n               COALESCE(\n                   membership.attributes -> 'allowed_domain_ids', '[]'::jsonb\n               ) ? job.graph_domain_ref_id::text\n           )\n       )\n       OR current_authorization_hash <> job.requester_authorization_hash THEN\n        RETURN 'STALE_REQUESTER_AUTHORIZATION';\n    END IF;\n    RETURN NULL;\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.begin_studio_ingestion_completion_v1(\n    p_workspace_id uuid,\n    p_job_id uuid,\n    p_attempt_id uuid,\n    p_lease_epoch bigint,\n    p_lease_token text,\n    p_worker_fingerprint text\n)\nRETURNS uuid\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, knowledge\nAS $$\nDECLARE\n    job knowledge.studio_ingestion_jobs%ROWTYPE;\n    token_hash text := encode(sha256(convert_to(p_lease_token, 'UTF8')), 'hex');\n    changeset_id uuid := gen_random_uuid();\nBEGIN\n    SELECT * INTO job FROM knowledge.studio_ingestion_jobs\n    WHERE workspace_id = p_workspace_id AND id = p_job_id\n    FOR UPDATE;\n    IF NOT knowledge.current_studio_ingestion_service_can_v1(\n           p_workspace_id, 'kg.ingestion.execute',\n           COALESCE(job.graph_classification, 0), job.graph_domain_ref_id\n       )\n       OR job.state <> 'RUNNING'\n       OR job.current_attempt_id IS DISTINCT FROM p_attempt_id\n       OR job.lease_epoch <> p_lease_epoch\n       OR job.lease_token_hash IS DISTINCT FROM token_hash\n       OR job.lease_owner_fingerprint IS DISTINCT FROM p_worker_fingerprint\n       OR job.stage <> 'FINALIZING'\n       OR NOT knowledge.current_studio_ingestion_lease_matches_v1(\n           p_workspace_id, p_job_id, p_attempt_id, p_lease_epoch, p_lease_token,\n           p_worker_fingerprint\n       )\n       OR job.lease_expires_at <= clock_timestamp()\n       OR job.source_access_deadline IS NULL\n       OR EXISTS (\n           SELECT 1 FROM knowledge.changesets\n           WHERE workspace_id = p_workspace_id\n             AND studio_ingestion_job_id = p_job_id\n       ) THEN\n        RAISE EXCEPTION 'invalid Studio ingestion completion start'\n            USING ERRCODE = '55000';\n    END IF;\n    INSERT INTO knowledge.changesets (\n        id, workspace_id, graph_id, base_release_id, ontology_version_id,\n        title, state, author_id, source_analysis_job_id,\n        studio_ingestion_job_id, reviewed_by, reviewed_at, review_reason,\n        published_release_id, created_at, updated_at, version\n    )\n    VALUES (\n        changeset_id, p_workspace_id, job.graph_id, job.base_release_id,\n        job.ontology_version_id,\n        'Studio DB ingestion ' || left(job.id::text, 8),\n        'DRAFT', job.requested_by, NULL, job.id,\n        NULL, NULL, NULL, NULL, transaction_timestamp(), transaction_timestamp(), 1\n    );\n    RETURN changeset_id;\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.append_studio_ingestion_result_batch_v1(\n    p_workspace_id uuid,\n    p_job_id uuid,\n    p_attempt_id uuid,\n    p_lease_epoch bigint,\n    p_lease_token text,\n    p_worker_fingerprint text,\n    p_changeset_id uuid,\n    p_operations jsonb,\n    p_vectors jsonb\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, knowledge\nAS $$\nDECLARE\n    job knowledge.studio_ingestion_jobs%ROWTYPE;\n    operation jsonb;\n    vector_item jsonb;\n    provenance_item jsonb;\n    property_name text;\n    property_value jsonb;\n    property_rule jsonb;\n    vector_property_value jsonb;\n    binding_pin knowledge.studio_ingestion_binding_pins%ROWTYPE;\n    property_element knowledge.ontology_elements%ROWTYPE;\n    token_hash text := encode(sha256(convert_to(p_lease_token, 'UTF8')), 'hex');\n    operation_count integer;\n    vector_count integer;\n    calculated_vector_hash text;\nBEGIN\n    SELECT * INTO job FROM knowledge.studio_ingestion_jobs\n    WHERE workspace_id = p_workspace_id AND id = p_job_id\n    FOR UPDATE;\n    operation_count := CASE WHEN jsonb_typeof(p_operations) = 'array'\n                            THEN jsonb_array_length(p_operations) ELSE -1 END;\n    vector_count := CASE WHEN jsonb_typeof(p_vectors) = 'array'\n                         THEN jsonb_array_length(p_vectors) ELSE -1 END;\n    IF NOT knowledge.current_studio_ingestion_service_can_v1(\n           p_workspace_id, 'kg.ingestion.execute',\n           COALESCE(job.graph_classification, 0), job.graph_domain_ref_id\n       )\n       OR job.state <> 'RUNNING'\n       OR job.current_attempt_id IS DISTINCT FROM p_attempt_id\n       OR job.lease_epoch <> p_lease_epoch\n       OR job.lease_token_hash IS DISTINCT FROM token_hash\n       OR job.lease_owner_fingerprint IS DISTINCT FROM p_worker_fingerprint\n       OR job.stage <> 'FINALIZING'\n       OR NOT knowledge.current_studio_ingestion_lease_matches_v1(\n           p_workspace_id, p_job_id, p_attempt_id, p_lease_epoch, p_lease_token,\n           p_worker_fingerprint\n       )\n       OR job.lease_expires_at <= clock_timestamp()\n       OR operation_count NOT BETWEEN 0 AND 500\n       OR vector_count NOT BETWEEN 0 AND 500\n       OR operation_count + vector_count < 1\n       OR octet_length(p_operations::text) > 4194304\n       OR octet_length(p_vectors::text) > 16777216\n       OR NOT EXISTS (\n           SELECT 1 FROM knowledge.changesets\n           WHERE workspace_id = p_workspace_id\n             AND graph_id = job.graph_id\n             AND id = p_changeset_id\n             AND studio_ingestion_job_id = p_job_id\n             AND ontology_version_id = job.ontology_version_id\n             AND state = 'DRAFT'\n       ) THEN\n        RAISE EXCEPTION 'invalid Studio ingestion result batch'\n            USING ERRCODE = '55000';\n    END IF;\n    FOR operation IN SELECT value FROM jsonb_array_elements(p_operations)\n    LOOP\n        IF jsonb_typeof(operation) <> 'object'\n           OR (operation - ARRAY[\n               'sequence','operation','entity_kind','stable_entity_id',\n               'document','provenance','confidence'\n           ]) <> '{}'::jsonb\n           OR (operation ->> 'sequence') !~ '^[1-9][0-9]*$'\n           OR (operation ->> 'sequence')::integer > 100000\n           OR operation ->> 'operation' <> 'UPSERT'\n           OR operation ->> 'entity_kind' <> 'NODE'\n           OR jsonb_typeof(operation -> 'document') <> 'object'\n           OR jsonb_typeof(operation -> 'provenance') <> 'array'\n           OR jsonb_array_length(operation -> 'provenance') <> 1\n           OR (\n               (operation -> 'document') - ARRAY[\n                   'entity_type','properties','classification'\n               ]\n           ) <> '{}'::jsonb\n           OR jsonb_typeof(operation -> 'document' -> 'properties') <> 'object'\n           OR (operation -> 'document' ->> 'classification') !~ '^[0-3]$'\n           OR (operation -> 'document' ->> 'classification')::integer\n                > job.graph_classification\n           OR (operation ->> 'confidence')::numeric <> 1 THEN\n            RAISE EXCEPTION 'invalid Studio typed operation'\n                USING ERRCODE = '23514';\n        END IF;\n        provenance_item := operation -> 'provenance' -> 0;\n        IF jsonb_typeof(provenance_item) <> 'object'\n           OR (\n               provenance_item - ARRAY[\n                   'source_ref','source_locator','source_version',\n                   'method','confidence'\n               ]\n           ) <> '{}'::jsonb\n           OR provenance_item ->> 'source_ref'\n                !~ '^knowledge-studio-binding:[0-9a-f-]{36}$'\n           OR provenance_item ->> 'method' <> 'DB_MAPPING_IDENTITY_V1'\n           OR (provenance_item ->> 'confidence')::numeric <> 1 THEN\n            RAISE EXCEPTION 'invalid Studio operation provenance'\n                USING ERRCODE = '23514';\n        END IF;\n        SELECT * INTO binding_pin\n        FROM knowledge.studio_ingestion_binding_pins AS candidate\n        WHERE candidate.workspace_id = p_workspace_id\n          AND candidate.job_id = p_job_id\n          AND candidate.binding_version_id::text =\n              substr(\n                  provenance_item ->> 'source_ref',\n                  char_length('knowledge-studio-binding:') + 1\n              )\n          AND candidate.target_class_canonical_name =\n              operation -> 'document' ->> 'entity_type';\n        IF NOT FOUND\n           OR (operation -> 'document' ->> 'classification')::integer\n                <> binding_pin.source_classification\n           OR provenance_item ->> 'source_version' <>\n                binding_pin.source_version || '@' ||\n                binding_pin.projection_source_version\n           OR provenance_item ->> 'source_locator' !~\n                (\n                    '^catalog-asset:' || binding_pin.source_asset_id::text ||\n                    '#identity-sha256=[0-9a-f]{64}$'\n                )\n           OR EXISTS (\n               SELECT 1\n               FROM jsonb_each(\n                   operation -> 'document' -> 'properties'\n               ) AS property(name, value)\n               WHERE NOT EXISTS (\n                   SELECT 1\n                   FROM jsonb_array_elements(binding_pin.rules_document) AS rule\n                   WHERE rule ->> 'method' = 'PROPERTY'\n                     AND rule ->> 'target_canonical_name' = property.name\n               )\n           )\n           OR EXISTS (\n               SELECT 1\n               FROM jsonb_array_elements(binding_pin.rules_document) AS rule\n               WHERE rule ->> 'method' = 'PROPERTY'\n                 AND (rule ->> 'target_nullable')::boolean IS FALSE\n                 AND NOT (\n                     operation -> 'document' -> 'properties'\n                     ? (rule ->> 'target_canonical_name')\n                 )\n           ) THEN\n            RAISE EXCEPTION 'Studio operation is outside its released Binding'\n                USING ERRCODE = '23514';\n        END IF;\n        FOR property_name, property_value IN\n            SELECT key, value\n            FROM jsonb_each(operation -> 'document' -> 'properties')\n        LOOP\n            SELECT rule INTO property_rule\n            FROM jsonb_array_elements(binding_pin.rules_document) AS rule\n            WHERE rule ->> 'method' = 'PROPERTY'\n              AND rule ->> 'target_canonical_name' = property_name;\n            IF property_rule IS NULL\n               OR jsonb_typeof(property_value)\n                    NOT IN ('string','number','boolean') THEN\n                RAISE EXCEPTION 'Studio operation Property is not a typed Mapping'\n                    USING ERRCODE = '23514';\n            END IF;\n        END LOOP;\n        INSERT INTO knowledge.change_operations (\n            id, workspace_id, changeset_id, sequence, operation, entity_kind,\n            stable_entity_id, document, provenance, confidence\n        )\n        VALUES (\n            gen_random_uuid(), p_workspace_id, p_changeset_id,\n            (operation ->> 'sequence')::integer,\n            operation ->> 'operation', operation ->> 'entity_kind',\n            (operation ->> 'stable_entity_id')::uuid,\n            operation -> 'document', operation -> 'provenance',\n            (operation ->> 'confidence')::double precision\n        );\n    END LOOP;\n    FOR vector_item IN SELECT value FROM jsonb_array_elements(p_vectors)\n    LOOP\n        IF job.embedding_binding_hash IS NULL\n           OR jsonb_typeof(vector_item) <> 'object'\n           OR (vector_item - ARRAY[\n               'entity_id','property_stable_id','content_hash',\n               'dimension','vector','vector_hash'\n           ]) <> '{}'::jsonb\n           OR vector_item ->> 'content_hash' !~ '^[0-9a-f]{64}$'\n           OR vector_item ->> 'vector_hash' !~ '^[0-9a-f]{64}$'\n           OR (vector_item ->> 'dimension') !~ '^[1-9][0-9]*$'\n           OR (vector_item ->> 'dimension')::integer NOT BETWEEN 1 AND 16384\n           OR jsonb_typeof(vector_item -> 'vector') <> 'array'\n           OR jsonb_array_length(vector_item -> 'vector')\n                <> (vector_item ->> 'dimension')::integer\n           OR EXISTS (\n               SELECT 1\n               FROM jsonb_array_elements_text(vector_item -> 'vector') AS item(value)\n               WHERE item.value::numeric NOT BETWEEN -1e100::numeric AND 1e100::numeric\n           ) THEN\n            RAISE EXCEPTION 'invalid Studio vector receipt'\n                USING ERRCODE = '23514';\n        END IF;\n        calculated_vector_hash := encode(sha256(convert_to(\n            replace((vector_item -> 'vector')::text, ', ', ','), 'UTF8'\n        )), 'hex');\n        IF calculated_vector_hash <> vector_item ->> 'vector_hash' THEN\n            RAISE EXCEPTION 'Studio vector receipt hash mismatch'\n                USING ERRCODE = '23514';\n        END IF;\n        SELECT * INTO property_element\n        FROM knowledge.ontology_elements\n        WHERE workspace_id = p_workspace_id\n          AND ontology_version_id = job.ontology_version_id\n          AND stable_element_id = vector_item ->> 'property_stable_id'\n          AND kind = 'PROPERTY';\n        IF NOT FOUND THEN\n            RAISE EXCEPTION 'Studio vector Property is outside the ontology'\n                USING ERRCODE = '23514';\n        END IF;\n        SELECT operation.document -> 'properties' ->\n                   (rule ->> 'target_canonical_name')\n        INTO vector_property_value\n        FROM knowledge.studio_ingestion_binding_pins AS pin\n        CROSS JOIN LATERAL jsonb_array_elements(pin.rules_document) AS rule\n        JOIN knowledge.change_operations AS operation\n          ON operation.workspace_id = pin.workspace_id\n         AND operation.changeset_id = p_changeset_id\n         AND operation.stable_entity_id =\n             (vector_item ->> 'entity_id')::uuid\n         AND operation.document ->> 'entity_type' =\n             pin.target_class_canonical_name\n        WHERE pin.workspace_id = p_workspace_id\n          AND pin.job_id = p_job_id\n          AND rule ->> 'method' = 'PROPERTY'\n          AND rule ->> 'target_stable_element_id' =\n              vector_item ->> 'property_stable_id'\n          AND (rule ->> 'vector_index_enabled')::boolean IS TRUE\n        LIMIT 1;\n        IF NOT FOUND\n           OR jsonb_typeof(vector_property_value) <> 'string'\n           OR encode(sha256(convert_to(\n               regexp_replace(\n                   btrim(vector_property_value #>> '{}'),\n                   '[[:space:]]+', ' ', 'g'\n               ),\n               'UTF8'\n           )), 'hex') <> vector_item ->> 'content_hash' THEN\n            RAISE EXCEPTION 'Studio vector is outside its released Mapping'\n                USING ERRCODE = '23514';\n        END IF;\n        INSERT INTO knowledge.studio_ingestion_vector_receipts (\n            id, workspace_id, job_id, attempt_id, changeset_id,\n            ontology_version_id, property_ontology_element_id, entity_id,\n            property_stable_id, content_hash, embedding_binding_hash,\n            dimension, vector_document, vector_hash, created_at\n        )\n        VALUES (\n            gen_random_uuid(), p_workspace_id, p_job_id, p_attempt_id,\n            p_changeset_id, job.ontology_version_id, property_element.id,\n            (vector_item ->> 'entity_id')::uuid,\n            vector_item ->> 'property_stable_id',\n            vector_item ->> 'content_hash', job.embedding_binding_hash,\n            (vector_item ->> 'dimension')::integer,\n            vector_item -> 'vector', vector_item ->> 'vector_hash',\n            transaction_timestamp()\n        );\n    END LOOP;\n    RETURN jsonb_build_object(\n        'operation_count', operation_count,\n        'vector_receipt_count', vector_count\n    );\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.complete_studio_ingestion_v1(\n    p_workspace_id uuid,\n    p_job_id uuid,\n    p_attempt_id uuid,\n    p_lease_epoch bigint,\n    p_lease_token text,\n    p_worker_fingerprint text,\n    p_changeset_id uuid,\n    p_source_read_receipt_hash text,\n    p_result_hash text,\n    p_operation_count integer,\n    p_vector_receipt_count integer,\n    p_call_id text\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, platform, iam, knowledge\nAS $$\nDECLARE\n    job knowledge.studio_ingestion_jobs%ROWTYPE;\n    graph knowledge.graphs%ROWTYPE;\n    studio_release knowledge.studio_releases%ROWTYPE;\n    ontology knowledge.ontology_versions%ROWTYPE;\n    base_release knowledge.releases%ROWTYPE;\n    membership iam.workspace_memberships%ROWTYPE;\n    subject iam.subjects%ROWTYPE;\n    actor_id uuid := NULLIF(current_setting('app.subject_id', true), '')::uuid;\n    token_hash text := encode(sha256(convert_to(p_lease_token, 'UTF8')), 'hex');\n    now_at timestamptz := transaction_timestamp();\n    actual_operations integer;\n    actual_vectors integer;\n    expected_vectors integer;\n    minimum_sequence integer;\n    maximum_sequence integer;\n    current_authorization_hash text;\n    workspace_available boolean;\nBEGIN\n    SELECT * INTO job FROM knowledge.studio_ingestion_jobs\n    WHERE workspace_id = p_workspace_id AND id = p_job_id\n    FOR UPDATE;\n    SELECT * INTO graph FROM knowledge.graphs\n    WHERE workspace_id = p_workspace_id AND id = job.graph_id\n    FOR SHARE;\n    SELECT * INTO studio_release FROM knowledge.studio_releases\n    WHERE workspace_id = p_workspace_id AND graph_id = job.graph_id\n      AND id = job.studio_release_id\n    FOR SHARE;\n    SELECT * INTO ontology FROM knowledge.ontology_versions\n    WHERE workspace_id = p_workspace_id AND graph_id = job.graph_id\n      AND id = job.ontology_version_id\n    FOR SHARE;\n    SELECT * INTO base_release FROM knowledge.releases\n    WHERE workspace_id = p_workspace_id AND graph_id = job.graph_id\n      AND id = job.base_release_id\n    FOR SHARE;\n    SELECT * INTO membership FROM iam.workspace_memberships\n    WHERE workspace_id = p_workspace_id AND subject_id = job.requested_by\n    FOR SHARE;\n    SELECT * INTO subject FROM iam.subjects\n    WHERE id = job.requested_by\n    FOR SHARE;\n    SELECT true INTO workspace_available\n    FROM platform.workspaces\n    WHERE id = p_workspace_id AND status = 'ACTIVE'\n    FOR SHARE;\n    SELECT encode(sha256(convert_to(jsonb_build_object(\n        'contract', 'KNOWLEDGE_STUDIO_INGESTION_REQUEST_AUTHORIZATION_DB_V1',\n        'workspace_id', membership.workspace_id,\n        'subject_id', membership.subject_id,\n        'subject_active', subject.active,\n        'membership_active', membership.active,\n        'access_expires_at', membership.access_expires_at,\n        'job_function', membership.job_function,\n        'clearance', membership.clearance,\n        'attributes', membership.attributes\n    )::text, 'UTF8')), 'hex')\n    INTO current_authorization_hash;\n    SELECT count(*), min(sequence), max(sequence)\n    INTO actual_operations, minimum_sequence, maximum_sequence\n    FROM knowledge.change_operations\n    WHERE workspace_id = p_workspace_id AND changeset_id = p_changeset_id;\n    SELECT count(*) INTO actual_vectors\n    FROM knowledge.studio_ingestion_vector_receipts\n    WHERE workspace_id = p_workspace_id AND job_id = p_job_id\n      AND changeset_id = p_changeset_id;\n    SELECT count(*) INTO expected_vectors\n    FROM knowledge.change_operations AS operation\n    JOIN knowledge.studio_ingestion_binding_pins AS pin\n      ON pin.workspace_id = operation.workspace_id\n     AND pin.job_id = p_job_id\n     AND pin.binding_version_id::text = substr(\n         operation.provenance -> 0 ->> 'source_ref',\n         char_length('knowledge-studio-binding:') + 1\n     )\n     AND pin.target_class_canonical_name =\n         operation.document ->> 'entity_type'\n    CROSS JOIN LATERAL jsonb_array_elements(pin.rules_document) AS rule\n    WHERE operation.workspace_id = p_workspace_id\n      AND operation.changeset_id = p_changeset_id\n      AND rule ->> 'method' = 'PROPERTY'\n      AND (rule ->> 'vector_index_enabled')::boolean IS TRUE\n      AND operation.document -> 'properties'\n          ? (rule ->> 'target_canonical_name');\n    IF NOT knowledge.current_studio_ingestion_service_can_v1(\n           p_workspace_id, 'kg.ingestion.execute',\n           COALESCE(job.graph_classification, 0), job.graph_domain_ref_id\n       )\n       OR job.state <> 'RUNNING'\n       OR job.current_attempt_id IS DISTINCT FROM p_attempt_id\n       OR job.lease_epoch <> p_lease_epoch\n       OR job.lease_token_hash IS DISTINCT FROM token_hash\n       OR job.lease_owner_fingerprint IS DISTINCT FROM p_worker_fingerprint\n       OR NOT knowledge.current_studio_ingestion_lease_matches_v1(\n           p_workspace_id, p_job_id, p_attempt_id, p_lease_epoch, p_lease_token,\n           p_worker_fingerprint\n       )\n       OR job.lease_expires_at <= clock_timestamp()\n       OR job.stage <> 'FINALIZING'\n       OR NOT COALESCE(workspace_available, false)\n       OR graph.id IS NULL\n       OR graph.version <> job.graph_version\n       OR graph.status <> 'PUBLISHED'\n       OR graph.classification <> job.graph_classification\n       OR graph.domain_ref_id IS DISTINCT FROM job.graph_domain_ref_id\n       OR graph.domain_source_version IS DISTINCT FROM job.graph_domain_source_version\n       OR graph.active_studio_release_id IS DISTINCT FROM job.studio_release_id\n       OR graph.active_release_id IS DISTINCT FROM job.base_release_id\n       OR studio_release.id IS NULL\n       OR studio_release.state <> 'ACTIVE'\n       OR studio_release.contract_hash <> job.studio_contract_hash\n       OR studio_release.ontology_version_id <> job.ontology_version_id\n       OR ontology.id IS NULL\n       OR ontology.checksum <> job.ontology_checksum\n       OR (\n           job.base_release_id IS NOT NULL\n           AND (\n               base_release.id IS NULL\n               OR base_release.content_hash <> job.base_release_hash\n           )\n       )\n       OR subject.id IS NULL\n       OR membership.subject_id IS NULL\n       OR NOT subject.active\n       OR NOT membership.active\n       OR (\n           membership.access_expires_at IS NOT NULL\n           AND membership.access_expires_at <= now_at\n       )\n       OR COALESCE(membership.job_function, '') = 'SERVICE_ACCOUNT'\n       OR membership.clearance < job.graph_classification\n       OR NOT (\n           COALESCE(\n               membership.attributes -> 'allowed_actions', '[]'::jsonb\n           ) ? 'kg.edit'\n       )\n       OR (\n           COALESCE(\n               membership.attributes -> 'denied_actions', '[]'::jsonb\n           ) ? 'kg.edit'\n       )\n       OR (\n           job.graph_classification <> 0\n           AND job.graph_domain_ref_id IS NOT NULL\n           AND NOT (\n               COALESCE(\n                   membership.attributes -> 'allowed_domain_ids', '[]'::jsonb\n               ) ? job.graph_domain_ref_id::text\n           )\n       )\n       OR current_authorization_hash <> job.requester_authorization_hash\n       OR p_source_read_receipt_hash !~ '^[0-9a-f]{64}$'\n       OR p_result_hash !~ '^[0-9a-f]{64}$'\n       OR char_length(COALESCE(p_call_id, '')) NOT BETWEEN 1 AND 200\n       OR p_operation_count NOT BETWEEN 1 AND 100000\n       OR p_vector_receipt_count NOT BETWEEN 0 AND 100000\n       OR actual_operations <> p_operation_count\n       OR actual_vectors <> p_vector_receipt_count\n       OR actual_vectors <> expected_vectors\n       OR minimum_sequence <> 1\n       OR maximum_sequence <> actual_operations\n       OR NOT EXISTS (\n           SELECT 1 FROM knowledge.changesets\n           WHERE workspace_id = p_workspace_id\n             AND graph_id = job.graph_id\n             AND id = p_changeset_id\n             AND studio_ingestion_job_id = p_job_id\n             AND ontology_version_id = job.ontology_version_id\n             AND base_release_id IS NOT DISTINCT FROM job.base_release_id\n             AND author_id = job.requested_by\n             AND state = 'DRAFT'\n       ) THEN\n        RAISE EXCEPTION 'invalid Studio ingestion completion'\n            USING ERRCODE = '55000';\n    END IF;\n    UPDATE knowledge.studio_ingestion_attempts\n    SET state = 'SUCCESS', stage = 'COMPLETED',\n        source_read_receipt_hash = p_source_read_receipt_hash,\n        materialization_hash = p_result_hash,\n        result_evidence_hash = p_result_hash,\n        retryable = false, failure_code = NULL, finished_at = now_at\n    WHERE workspace_id = p_workspace_id AND id = p_attempt_id\n      AND job_id = p_job_id AND state = 'RUNNING'\n      AND lease_epoch = p_lease_epoch AND lease_token_hash = token_hash;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'Studio ingestion completion attempt is unavailable'\n            USING ERRCODE = '55000';\n    END IF;\n    UPDATE knowledge.studio_ingestion_jobs\n    SET state = 'SUCCESS', stage = 'COMPLETED', progress_percent = 100,\n        result_changeset_id = p_changeset_id,\n        result_evidence_hash = p_result_hash,\n        source_read_receipt_hash = p_source_read_receipt_hash,\n        lease_token_hash = NULL, lease_owner_fingerprint = NULL,\n        lease_started_at = NULL, lease_expires_at = NULL,\n        completed_at = now_at, updated_at = now_at, version = version + 1\n    WHERE workspace_id = p_workspace_id AND id = p_job_id\n    RETURNING * INTO job;\n    PERFORM knowledge.append_studio_ingestion_event_v1(\n        p_workspace_id, p_job_id, p_attempt_id, 'SUCCESS', 'CHANGESET_CREATED',\n        actor_id, 'SERVICE', jsonb_build_object(\n            'changeset_id', p_changeset_id,\n            'result_evidence_hash', p_result_hash,\n            'operation_count', p_operation_count,\n            'vector_receipt_count', p_vector_receipt_count,\n            'call_id', p_call_id\n        )\n    );\n    PERFORM knowledge.emit_studio_ingestion_outbox_v1(\n        p_workspace_id, p_job_id, 'SUCCESS', job.version\n    );\n    RETURN jsonb_build_object(\n        'job_id', p_job_id::text,\n        'changeset_id', p_changeset_id::text,\n        'state', 'SUCCESS',\n        'version', job.version\n    );\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.fail_studio_ingestion_v1(\n    p_workspace_id uuid,\n    p_job_id uuid,\n    p_attempt_id uuid,\n    p_lease_epoch bigint,\n    p_lease_token text,\n    p_worker_fingerprint text,\n    p_call_id text,\n    p_failure_code text,\n    p_retryable boolean,\n    p_stale boolean\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, knowledge\nAS $$\nDECLARE\n    job knowledge.studio_ingestion_jobs%ROWTYPE;\n    actor_id uuid := NULLIF(current_setting('app.subject_id', true), '')::uuid;\n    token_hash text := encode(sha256(convert_to(p_lease_token, 'UTF8')), 'hex');\n    now_at timestamptz := transaction_timestamp();\n    target_state text;\n    attempt_state text;\nBEGIN\n    SELECT * INTO job FROM knowledge.studio_ingestion_jobs\n    WHERE workspace_id = p_workspace_id AND id = p_job_id\n    FOR UPDATE;\n    IF NOT knowledge.current_studio_ingestion_service_can_v1(\n           p_workspace_id, 'kg.ingestion.execute',\n           COALESCE(job.graph_classification, 0), job.graph_domain_ref_id\n       )\n       OR job.state NOT IN ('RUNNING','CANCEL_REQUESTED')\n       OR job.current_attempt_id IS DISTINCT FROM p_attempt_id\n       OR job.lease_epoch <> p_lease_epoch\n       OR job.lease_token_hash IS DISTINCT FROM token_hash\n       OR job.lease_owner_fingerprint IS DISTINCT FROM p_worker_fingerprint\n       OR NOT knowledge.current_studio_ingestion_lease_matches_v1(\n           p_workspace_id, p_job_id, p_attempt_id, p_lease_epoch, p_lease_token,\n           p_worker_fingerprint\n       )\n       OR job.lease_expires_at <= clock_timestamp()\n       OR char_length(COALESCE(p_call_id, '')) NOT BETWEEN 1 AND 200\n       OR p_failure_code !~ '^[A-Z0-9_]{1,100}$' THEN\n        RAISE EXCEPTION 'invalid Studio ingestion failure'\n            USING ERRCODE = '55000';\n    END IF;\n    target_state := CASE\n        WHEN job.state = 'CANCEL_REQUESTED' THEN 'CANCELLED'\n        WHEN p_stale THEN 'STALE'\n        WHEN p_retryable AND job.attempt_count < job.maximum_attempts THEN 'RETRY_WAIT'\n        ELSE 'FAILED'\n    END;\n    attempt_state := CASE\n        WHEN target_state = 'CANCELLED' THEN 'CANCELLED'\n        WHEN target_state = 'STALE' THEN 'STALE'\n        ELSE 'FAILED'\n    END;\n    UPDATE knowledge.studio_ingestion_attempts\n    SET state = attempt_state, stage = 'COMPLETED',\n        retryable = p_retryable, failure_code = p_failure_code,\n        finished_at = now_at\n    WHERE workspace_id = p_workspace_id AND id = p_attempt_id\n      AND job_id = p_job_id AND state = 'RUNNING'\n      AND lease_epoch = p_lease_epoch AND lease_token_hash = token_hash;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'Studio ingestion failure attempt is unavailable'\n            USING ERRCODE = '55000';\n    END IF;\n    UPDATE knowledge.studio_ingestion_jobs\n    SET state = target_state,\n        stage = CASE WHEN target_state = 'RETRY_WAIT' THEN 'QUEUED' ELSE 'COMPLETED' END,\n        progress_percent = 0,\n        next_attempt_at = CASE\n            WHEN target_state = 'RETRY_WAIT'\n            THEN now_at + make_interval(\n                secs => least(60, 5 * (2 ^ attempt_count))::integer\n            )\n            ELSE next_attempt_at\n        END,\n        last_failure_code = CASE\n            WHEN target_state = 'CANCELLED' THEN NULL ELSE p_failure_code\n        END,\n        lease_token_hash = NULL, lease_owner_fingerprint = NULL,\n        lease_started_at = NULL, lease_expires_at = NULL,\n        completed_at = CASE\n            WHEN target_state = 'RETRY_WAIT' THEN NULL ELSE now_at\n        END,\n        updated_at = now_at, version = version + 1\n    WHERE workspace_id = p_workspace_id AND id = p_job_id\n    RETURNING * INTO job;\n    PERFORM knowledge.append_studio_ingestion_event_v1(\n        p_workspace_id, p_job_id, p_attempt_id, target_state,\n        p_failure_code, actor_id, 'SERVICE',\n        jsonb_build_object('call_id', p_call_id, 'retryable', p_retryable)\n    );\n    PERFORM knowledge.emit_studio_ingestion_outbox_v1(\n        p_workspace_id, p_job_id, target_state, job.version\n    );\n    RETURN jsonb_build_object(\n        'job_id', p_job_id::text,\n        'state', target_state,\n        'version', job.version\n    );\nEND\n$$;")
        op.execute('REVOKE ALL ON FUNCTION knowledge.request_studio_ingestion_v1(uuid,uuid,integer,text,text,integer,text,jsonb,jsonb,integer) FROM PUBLIC')
        op.execute('REVOKE ALL ON FUNCTION knowledge.cancel_studio_ingestion_v1(uuid,uuid,integer,text) FROM PUBLIC')
        op.execute('REVOKE ALL ON FUNCTION knowledge.retry_studio_ingestion_v1(uuid,uuid,integer) FROM PUBLIC')
        op.execute('REVOKE ALL ON FUNCTION knowledge.claim_studio_ingestion_v1(uuid,text,text,integer) FROM PUBLIC')
        op.execute('REVOKE ALL ON FUNCTION knowledge.freeze_studio_ingestion_source_access_v1(uuid,uuid,uuid,bigint,text,text,integer,integer) FROM PUBLIC')
        op.execute('REVOKE ALL ON FUNCTION knowledge.assert_studio_ingestion_source_statement_fence_v1(uuid,uuid,uuid,bigint,text,text) FROM PUBLIC')
        op.execute('REVOKE ALL ON FUNCTION knowledge.renew_studio_ingestion_v1(uuid,uuid,uuid,bigint,text,text,integer,text,integer) FROM PUBLIC')
        op.execute('REVOKE ALL ON FUNCTION knowledge.ensure_studio_ingestion_current_v1(uuid,uuid,uuid,bigint,text,text,text,integer,text,jsonb) FROM PUBLIC')
        op.execute('REVOKE ALL ON FUNCTION knowledge.begin_studio_ingestion_completion_v1(uuid,uuid,uuid,bigint,text,text) FROM PUBLIC')
        op.execute('REVOKE ALL ON FUNCTION knowledge.append_studio_ingestion_result_batch_v1(uuid,uuid,uuid,bigint,text,text,uuid,jsonb,jsonb) FROM PUBLIC')
        op.execute('REVOKE ALL ON FUNCTION knowledge.complete_studio_ingestion_v1(uuid,uuid,uuid,bigint,text,text,uuid,text,text,integer,integer,text) FROM PUBLIC')
        op.execute('REVOKE ALL ON FUNCTION knowledge.fail_studio_ingestion_v1(uuid,uuid,uuid,bigint,text,text,text,text,boolean,boolean) FROM PUBLIC')
        op.execute('REVOKE ALL ON FUNCTION knowledge.append_studio_ingestion_event_v1(uuid,uuid,uuid,text,text,uuid,text,jsonb) FROM PUBLIC')
        op.execute('REVOKE ALL ON FUNCTION knowledge.emit_studio_ingestion_outbox_v1(uuid,uuid,text,integer) FROM PUBLIC')
        op.execute('REVOKE ALL ON FUNCTION knowledge.current_studio_ingestion_service_can_v1(uuid,text,integer,uuid) FROM PUBLIC')
        op.execute('REVOKE ALL ON FUNCTION knowledge.current_studio_ingestion_human_can_v1(uuid,uuid,integer,uuid) FROM PUBLIC')
        op.execute('REVOKE ALL ON FUNCTION knowledge.current_studio_ingestion_lease_matches_v1(uuid,uuid,uuid,bigint,text,text) FROM PUBLIC')
        op.execute('REVOKE ALL ON FUNCTION knowledge.reject_studio_ingestion_evidence_mutation_v1() FROM PUBLIC')
        op.execute('REVOKE ALL ON FUNCTION knowledge.enforce_studio_ingestion_changeset_provenance_v1() FROM PUBLIC')
        op.execute('REVOKE ALL ON FUNCTION knowledge.enforce_studio_ingestion_operation_scope_v1() FROM PUBLIC')
        op.execute('DO $datariver$\nBEGIN\n    REVOKE ALL PRIVILEGES ON knowledge.studio_ingestion_jobs,\n        knowledge.studio_ingestion_binding_pins,\n        knowledge.studio_ingestion_attempts,\n        knowledge.studio_ingestion_events,\n        knowledge.studio_ingestion_vector_receipts\n        FROM datariver_app, datariver_knowledge_ingestion;\n    REVOKE ALL PRIVILEGES ON ALL SEQUENCES IN SCHEMA knowledge\n        FROM datariver_knowledge_ingestion;\n    REVOKE ALL PRIVILEGES ON SCHEMA knowledge\n        FROM datariver_knowledge_ingestion;\n\n    GRANT SELECT ON knowledge.studio_ingestion_jobs,\n        knowledge.studio_ingestion_binding_pins,\n        knowledge.studio_ingestion_events\n        TO datariver_app;\n\n    GRANT USAGE ON SCHEMA knowledge TO datariver_knowledge_ingestion;\n    GRANT EXECUTE ON FUNCTION knowledge.request_studio_ingestion_v1(\n        uuid, uuid, integer, text, text, integer, text, jsonb, jsonb, integer\n    ) TO datariver_app;\n    GRANT EXECUTE ON FUNCTION knowledge.cancel_studio_ingestion_v1(\n        uuid, uuid, integer, text\n    ) TO datariver_app;\n    GRANT EXECUTE ON FUNCTION knowledge.retry_studio_ingestion_v1(\n        uuid, uuid, integer\n    ) TO datariver_app;\n\n    GRANT EXECUTE ON FUNCTION knowledge.claim_studio_ingestion_v1(\n        uuid, text, text, integer\n    ) TO datariver_knowledge_ingestion;\n    GRANT EXECUTE ON FUNCTION knowledge.freeze_studio_ingestion_source_access_v1(\n        uuid, uuid, uuid, bigint, text, text, integer, integer\n    ) TO datariver_knowledge_ingestion;\n    GRANT EXECUTE ON FUNCTION\n        knowledge.assert_studio_ingestion_source_statement_fence_v1(\n            uuid, uuid, uuid, bigint, text, text\n        ) TO datariver_knowledge_ingestion;\n    GRANT EXECUTE ON FUNCTION knowledge.renew_studio_ingestion_v1(\n        uuid, uuid, uuid, bigint, text, text, integer, text, integer\n    ) TO datariver_knowledge_ingestion;\n    GRANT EXECUTE ON FUNCTION knowledge.ensure_studio_ingestion_current_v1(\n        uuid, uuid, uuid, bigint, text, text, text, integer, text, jsonb\n    ) TO datariver_knowledge_ingestion;\n    GRANT EXECUTE ON FUNCTION knowledge.begin_studio_ingestion_completion_v1(\n        uuid, uuid, uuid, bigint, text, text\n    ) TO datariver_knowledge_ingestion;\n    GRANT EXECUTE ON FUNCTION knowledge.append_studio_ingestion_result_batch_v1(\n        uuid, uuid, uuid, bigint, text, text, uuid, jsonb, jsonb\n    ) TO datariver_knowledge_ingestion;\n    GRANT EXECUTE ON FUNCTION knowledge.complete_studio_ingestion_v1(\n        uuid, uuid, uuid, bigint, text, text, uuid, text, text,\n        integer, integer, text\n    ) TO datariver_knowledge_ingestion;\n    GRANT EXECUTE ON FUNCTION knowledge.fail_studio_ingestion_v1(\n        uuid, uuid, uuid, bigint, text, text, text, text, boolean, boolean\n    ) TO datariver_knowledge_ingestion;\nEND\n$datariver$;')
        op.execute("DO $datariver$\nDECLARE\n    role_name text;\n    role_is_safe boolean;\nBEGIN\n    FOREACH role_name IN ARRAY ARRAY['datariver_app', 'datariver_knowledge_proposal']\n    LOOP\n        SELECT\n            rolcanlogin\n            AND NOT rolsuper\n            AND NOT rolcreatedb\n            AND NOT rolcreaterole\n            AND NOT rolreplication\n            AND NOT rolbypassrls\n        INTO role_is_safe\n        FROM pg_roles\n        WHERE rolname = role_name;\n        IF NOT COALESCE(role_is_safe, false) THEN\n            RAISE EXCEPTION '% must be a safe NOBYPASSRLS LOGIN role', role_name;\n        END IF;\n    END LOOP;\n    IF EXISTS (\n        SELECT 1 FROM pg_roles AS candidate\n        WHERE candidate.rolname <> 'datariver_knowledge_proposal'\n          AND pg_has_role('datariver_knowledge_proposal', candidate.oid, 'MEMBER')\n    ) OR EXISTS (\n        SELECT 1 FROM pg_roles AS candidate\n        WHERE candidate.rolname <> 'datariver_knowledge_proposal'\n          AND NOT candidate.rolsuper\n          AND pg_has_role(candidate.oid, 'datariver_knowledge_proposal', 'MEMBER')\n    ) THEN\n        RAISE EXCEPTION 'datariver_knowledge_proposal role membership is unsafe';\n    END IF;\nEND\n$datariver$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.tbox_proposal_canonical_json_v1(p_value jsonb)\nRETURNS text\nLANGUAGE plpgsql\nIMMUTABLE\nSTRICT\nSET search_path = pg_catalog, knowledge\nAS $$\nDECLARE\n    value_kind text := jsonb_typeof(p_value);\n    rendered text;\nBEGIN\n    IF value_kind = 'object' THEN\n        SELECT '{' || COALESCE(string_agg(\n            to_jsonb(entry.key)::text || ':' ||\n                knowledge.tbox_proposal_canonical_json_v1(entry.value),\n            ',' ORDER BY entry.key\n        ), '') || '}'\n        INTO rendered\n        FROM jsonb_each(p_value) AS entry;\n        RETURN rendered;\n    ELSIF value_kind = 'array' THEN\n        SELECT '[' || COALESCE(string_agg(\n            knowledge.tbox_proposal_canonical_json_v1(item.value),\n            ',' ORDER BY item.ordinality\n        ), '') || ']'\n        INTO rendered\n        FROM jsonb_array_elements(p_value) WITH ORDINALITY AS item(value, ordinality);\n        RETURN rendered;\n    END IF;\n    RETURN p_value::text;\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.tbox_proposal_json_hash_v1(p_value jsonb)\nRETURNS text\nLANGUAGE sql\nIMMUTABLE\nSTRICT\nSET search_path = pg_catalog, knowledge\nAS $$\n    SELECT encode(sha256(convert_to(\n        knowledge.tbox_proposal_canonical_json_v1(p_value), 'UTF8'\n    )), 'hex')\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.current_tbox_proposal_authorization_hash_v1(\n    p_workspace_id uuid,\n    p_subject_id uuid\n)\nRETURNS text\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = pg_catalog, platform, iam, knowledge\nAS $$\n    SELECT knowledge.tbox_proposal_json_hash_v1(jsonb_build_object(\n        'contract', 'KNOWLEDGE_STUDIO_PROPOSAL_REQUEST_AUTHORIZATION_V1',\n        'subject_id', membership.subject_id::text,\n        'workspace_id', membership.workspace_id::text,\n        'active', subject.active AND membership.active AND (\n            membership.access_expires_at IS NULL\n            OR membership.access_expires_at > transaction_timestamp()\n        ),\n        'department_id', CASE WHEN membership.department_id IS NULL THEN NULL\n            ELSE to_jsonb(membership.department_id::text) END,\n        'groups', COALESCE((\n            SELECT jsonb_agg(value ORDER BY value)\n            FROM jsonb_array_elements_text(\n                COALESCE(membership.attributes -> 'groups', '[]'::jsonb)\n            ) AS item(value)\n        ), '[]'::jsonb),\n        'job_function', membership.job_function,\n        'clearance', membership.clearance,\n        'allowed_system_ids', CASE\n            WHEN EXISTS (\n                SELECT 1\n                FROM iam.canonical_admin_bindings AS admin_binding\n                WHERE admin_binding.workspace_id = membership.workspace_id\n                  AND admin_binding.subject_id = membership.subject_id\n            ) OR EXISTS (\n                SELECT 1\n                FROM iam.profile_role_assignments AS profile_assignment\n                WHERE profile_assignment.workspace_id = membership.workspace_id\n                  AND profile_assignment.subject_id = membership.subject_id\n            ) THEN COALESCE((\n                SELECT jsonb_agg(active_scope.system_id ORDER BY active_scope.system_id)\n                FROM (\n                    SELECT DISTINCT assignee.system_id::text AS system_id\n                    FROM platform.system_assignees AS assignee\n                    JOIN platform.data_systems AS data_system\n                      ON data_system.workspace_id = assignee.workspace_id\n                     AND data_system.id = assignee.system_id\n                    WHERE assignee.workspace_id = membership.workspace_id\n                      AND assignee.subject_id = membership.subject_id\n                      AND assignee.active IS TRUE\n                      AND data_system.active IS TRUE\n                ) AS active_scope\n            ), '[]'::jsonb)\n            ELSE COALESCE((\n                SELECT jsonb_agg(value ORDER BY value)\n                FROM jsonb_array_elements_text(\n                    COALESCE(membership.attributes -> 'allowed_system_ids', '[]'::jsonb)\n                ) AS item(value)\n            ), '[]'::jsonb)\n        END,\n        'allowed_domain_ids', COALESCE((\n            SELECT jsonb_agg(value ORDER BY value)\n            FROM jsonb_array_elements_text(\n                COALESCE(membership.attributes -> 'allowed_domain_ids', '[]'::jsonb)\n            ) AS item(value)\n        ), '[]'::jsonb),\n        'allowed_actions', COALESCE((\n            SELECT jsonb_agg(value ORDER BY value)\n            FROM jsonb_array_elements_text(\n                COALESCE(membership.attributes -> 'allowed_actions', '[]'::jsonb)\n            ) AS item(value)\n        ), '[]'::jsonb),\n        'denied_actions', COALESCE((\n            SELECT jsonb_agg(value ORDER BY value)\n            FROM jsonb_array_elements_text(\n                COALESCE(membership.attributes -> 'denied_actions', '[]'::jsonb)\n            ) AS item(value)\n        ), '[]'::jsonb),\n        'builtin_policy_version', 'builtin-abac-v3'\n    ))\n    FROM iam.workspace_memberships AS membership\n    JOIN iam.subjects AS subject ON subject.id = membership.subject_id\n    WHERE membership.workspace_id = p_workspace_id\n      AND membership.subject_id = p_subject_id\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.current_tbox_proposal_human_can_v1(\n    p_workspace_id uuid,\n    p_actor_id uuid,\n    p_classification integer,\n    p_domain_id uuid\n)\nRETURNS boolean\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = pg_catalog, platform, iam\nAS $$\n    SELECT session_user = 'datariver_app'\n       AND p_workspace_id IS NOT DISTINCT FROM\n           NULLIF(current_setting('app.workspace_id', true), '')::uuid\n       AND p_actor_id IS NOT DISTINCT FROM\n           NULLIF(current_setting('app.subject_id', true), '')::uuid\n       AND EXISTS (\n           SELECT 1\n           FROM platform.workspaces AS workspace\n           JOIN iam.workspace_memberships AS membership\n             ON membership.workspace_id = workspace.id\n           JOIN iam.subjects AS subject ON subject.id = membership.subject_id\n           WHERE workspace.id = p_workspace_id\n             AND workspace.status = 'ACTIVE'\n             AND membership.subject_id = p_actor_id\n             AND subject.active IS TRUE\n             AND membership.active IS TRUE\n             AND (\n                 membership.access_expires_at IS NULL\n                 OR membership.access_expires_at > transaction_timestamp()\n             )\n             AND COALESCE(membership.job_function, '') <> 'SERVICE_ACCOUNT'\n             AND membership.clearance >= p_classification\n             AND COALESCE(\n                 membership.attributes -> 'allowed_actions', '[]'::jsonb\n             ) ? 'kg.edit'\n             AND NOT (\n                 COALESCE(\n                     membership.attributes -> 'denied_actions', '[]'::jsonb\n                 ) ? 'kg.edit'\n             )\n             AND (\n                 p_classification = 0\n                 OR p_domain_id IS NULL\n                 OR COALESCE(\n                     membership.attributes -> 'allowed_domain_ids', '[]'::jsonb\n                 ) ? p_domain_id::text\n             )\n       )\n$$;")
        op.execute('CREATE OR REPLACE FUNCTION knowledge.current_tbox_proposal_service_can_v1(\n    p_workspace_id uuid,\n    p_classification integer,\n    p_domain_id uuid\n)\nRETURNS boolean\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = pg_catalog, platform, iam\nAS $$\n    SELECT session_user = \'datariver_knowledge_proposal\'\n       AND p_workspace_id IS NOT DISTINCT FROM\n           NULLIF(current_setting(\'app.workspace_id\', true), \'\')::uuid\n       AND EXISTS (\n           SELECT 1\n           FROM platform.workspaces AS workspace\n           JOIN iam.workspace_memberships AS membership\n             ON membership.workspace_id = workspace.id\n           JOIN iam.subjects AS subject ON subject.id = membership.subject_id\n           WHERE workspace.id = p_workspace_id\n             AND workspace.status = \'ACTIVE\'\n             AND membership.subject_id =\n                 NULLIF(current_setting(\'app.subject_id\', true), \'\')::uuid\n             AND subject.active IS TRUE\n             AND membership.active IS TRUE\n             AND membership.access_expires_at IS NULL\n             AND membership.job_function = \'SERVICE_ACCOUNT\'\n             AND membership.clearance >= p_classification\n             AND COALESCE(membership.attributes -> \'groups\', \'[]\'::jsonb)\n                 = \'["service-accounts","knowledge-proposal-workers"]\'::jsonb\n             AND COALESCE(\n                 membership.attributes -> \'allowed_actions\', \'[]\'::jsonb\n             ) = \'["kg.proposal.execute"]\'::jsonb\n             AND COALESCE(\n                 membership.attributes -> \'denied_actions\', \'[]\'::jsonb\n             ) = \'[]\'::jsonb\n             AND COALESCE(\n                 membership.attributes -> \'allowed_system_ids\', \'[]\'::jsonb\n             ) = \'[]\'::jsonb\n       )\n$$;')
        op.execute("CREATE OR REPLACE FUNCTION knowledge.tbox_proposal_job_document_v1(\n    p_workspace_id uuid,\n    p_job_id uuid\n)\nRETURNS jsonb\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = pg_catalog, knowledge\nAS $$\n    SELECT jsonb_build_object(\n        'job_id', job.id::text,\n        'workspace_id', job.workspace_id::text,\n        'draft_id', job.draft_id::text,\n        'requested_by', job.requested_by::text,\n        'input_kind', job.input_kind,\n        'mode', job.mode,\n        'target_block_id', CASE WHEN job.target_block_id IS NULL THEN NULL\n            ELSE to_jsonb(job.target_block_id::text) END,\n        'state', job.state,\n        'stage', job.stage,\n        'progress_percent', job.progress_percent,\n        'attempt_count', job.attempt_count,\n        'maximum_attempts', job.maximum_attempts,\n        'next_attempt_at', job.next_attempt_at,\n        'last_failure_code', job.last_failure_code,\n        'version', job.version,\n        'created_at', job.created_at,\n        'updated_at', job.updated_at,\n        'completed_at', job.completed_at,\n        'result', CASE WHEN job.result_proposal_id IS NULL THEN NULL ELSE\n            jsonb_build_object(\n                'proposal_id', job.result_proposal_id::text,\n                'evidence_hash', job.result_evidence_hash\n            ) END,\n        'supersedes_job_id', CASE WHEN job.supersedes_job_id IS NULL THEN NULL\n            ELSE to_jsonb(job.supersedes_job_id::text) END\n    )\n    FROM knowledge.tbox_proposal_jobs AS job\n    WHERE job.workspace_id = p_workspace_id AND job.id = p_job_id\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.tbox_proposal_job_pins_v1(\n    p_workspace_id uuid,\n    p_job_id uuid\n)\nRETURNS jsonb\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = pg_catalog, knowledge\nAS $$\n    SELECT jsonb_build_object(\n        'contract', 'KNOWLEDGE_STUDIO_TBOX_PROPOSAL_JOB_PINS_V1',\n        'workspace_id', job.workspace_id::text,\n        'draft_id', job.draft_id::text,\n        'requested_by', job.requested_by::text,\n        'input_kind', job.input_kind,\n        'mode', job.mode,\n        'target_block_id', CASE WHEN job.target_block_id IS NULL THEN NULL\n            ELSE to_jsonb(job.target_block_id::text) END,\n        'base_draft_version', job.base_draft_version,\n        'base_tbox_hash', job.base_tbox_hash,\n        'source', CASE WHEN job.input_kind = 'DOCUMENT_SCHEMA' THEN\n            jsonb_build_object(\n                'kind', 'DOCUMENT_SCHEMA',\n                'manifest_id', job.manifest_id::text,\n                'manifest_version', job.manifest_version,\n                'content_sha256', job.source_content_hash,\n                'media_type', job.source_media_type,\n                'size_bytes', job.source_size_bytes,\n                'classification', job.source_classification,\n                'content_profile', job.source_content_profile,\n                'validation_evidence_hash', job.source_validation_evidence_hash,\n                'filename', job.source_filename\n            ) ELSE job.catalog_source_document END,\n        'parser_configuration_hash', job.parser_config_hash,\n        'schema_binding', job.schema_binding_document,\n        'requester_authorization_hash', job.requester_authorization_hash,\n        'prepared_at', job.prepared_at\n    )\n    FROM knowledge.tbox_proposal_jobs AS job\n    WHERE job.workspace_id = p_workspace_id AND job.id = p_job_id\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.tbox_proposal_current_elements_v1(\n    p_workspace_id uuid,\n    p_draft_id uuid\n)\nRETURNS jsonb\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = pg_catalog, knowledge\nAS $$\n    SELECT COALESCE(jsonb_agg(jsonb_build_object(\n        'stable_element_id', element.stable_element_id,\n        'kind', element.kind,\n        'canonical_name', element.canonical_name,\n        'display_name', element.display_name,\n        'parent_stable_element_id', CASE\n            WHEN element.kind = 'CLASS' THEN class_detail.parent_stable_class_id\n            WHEN element.kind = 'PROPERTY' THEN property_detail.owner_stable_class_id\n            ELSE NULL END,\n        'hierarchy_relation', CASE\n            WHEN class_detail.parent_stable_class_id IS NULL THEN NULL\n            ELSE class_detail.hierarchy_relation END,\n        'source_stable_element_id', relationship_detail.source_stable_class_id,\n        'target_stable_element_id', relationship_detail.target_stable_class_id,\n        'data_type', property_detail.data_type,\n        'nullable', property_detail.nullable,\n        'definition', element.definition,\n        'aliases', element.aliases,\n        'unit', property_detail.unit,\n        'vector_index_enabled', COALESCE(property_detail.vector_index_enabled, false),\n        'metadata_reference_id', CASE\n            WHEN element.kind = 'CLASS' THEN class_detail.metadata_reference_id\n            WHEN element.kind = 'PROPERTY' THEN property_detail.metadata_reference_id\n            ELSE relationship_detail.metadata_reference_id END,\n        'metadata_reference_urn', CASE\n            WHEN element.kind = 'CLASS' THEN class_detail.metadata_reference_urn\n            WHEN element.kind = 'PROPERTY' THEN property_detail.metadata_reference_urn\n            ELSE relationship_detail.metadata_reference_urn END,\n        'layout_x', element.layout_x,\n        'layout_y', element.layout_y\n    ) ORDER BY element.ordinal, element.stable_element_id), '[]'::jsonb)\n    FROM knowledge.tbox_draft_elements AS element\n    LEFT JOIN knowledge.tbox_classes AS class_detail\n      ON class_detail.workspace_id = element.workspace_id\n     AND class_detail.draft_id = element.draft_id\n     AND class_detail.stable_class_id = element.stable_element_id\n    LEFT JOIN knowledge.tbox_properties AS property_detail\n      ON property_detail.workspace_id = element.workspace_id\n     AND property_detail.draft_id = element.draft_id\n     AND property_detail.stable_property_id = element.stable_element_id\n    LEFT JOIN knowledge.tbox_relationships AS relationship_detail\n      ON relationship_detail.workspace_id = element.workspace_id\n     AND relationship_detail.draft_id = element.draft_id\n     AND relationship_detail.stable_relationship_id = element.stable_element_id\n    WHERE element.workspace_id = p_workspace_id\n      AND element.draft_id = p_draft_id\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.tbox_proposal_job_drift_v1(\n    p_workspace_id uuid,\n    p_job_id uuid,\n    p_schema_binding jsonb\n)\nRETURNS text\nLANGUAGE plpgsql\nSTABLE\nSECURITY DEFINER\nSET search_path = pg_catalog, platform, iam, catalog, integration, knowledge\nAS $$\nDECLARE\n    job knowledge.tbox_proposal_jobs%ROWTYPE;\n    draft knowledge.studio_drafts%ROWTYPE;\n    manifest integration.object_manifests%ROWTYPE;\n    asset catalog.assets_projection%ROWTYPE;\n    current_authorization_hash text;\n    current_validation_hash text;\nBEGIN\n    SELECT * INTO job\n    FROM knowledge.tbox_proposal_jobs\n    WHERE workspace_id = p_workspace_id AND id = p_job_id;\n    IF job.id IS NULL THEN\n        RETURN 'STALE_JOB';\n    END IF;\n    SELECT * INTO draft\n    FROM knowledge.studio_drafts\n    WHERE workspace_id = job.workspace_id AND id = job.draft_id;\n    IF draft.id IS NULL OR draft.author_id <> job.requested_by\n       OR draft.state <> 'DRAFT' OR draft.current_step <> 'TBOX'\n       OR draft.version <> job.base_draft_version THEN\n        RETURN 'STALE_DRAFT';\n    END IF;\n    IF job.target_block_id IS NOT NULL AND NOT EXISTS (\n        SELECT 1 FROM knowledge.tbox_draft_blocks AS block\n        WHERE block.workspace_id = job.workspace_id\n          AND block.draft_id = job.draft_id\n          AND block.id = job.target_block_id\n    ) THEN\n        RETURN 'STALE_TARGET_BLOCK';\n    END IF;\n    current_authorization_hash :=\n        knowledge.current_tbox_proposal_authorization_hash_v1(\n            job.workspace_id, job.requested_by\n        );\n    IF current_authorization_hash IS DISTINCT FROM job.requester_authorization_hash\n       OR NOT EXISTS (\n           SELECT 1\n           FROM iam.workspace_memberships AS membership\n           JOIN iam.subjects AS subject ON subject.id = membership.subject_id\n           WHERE membership.workspace_id = job.workspace_id\n             AND membership.subject_id = job.requested_by\n             AND subject.active IS TRUE AND membership.active IS TRUE\n             AND (\n                 membership.access_expires_at IS NULL\n                 OR membership.access_expires_at > transaction_timestamp()\n             )\n             AND COALESCE(membership.job_function, '') <> 'SERVICE_ACCOUNT'\n             AND membership.clearance >= draft.classification\n             AND COALESCE(\n                 membership.attributes -> 'allowed_actions', '[]'::jsonb\n             ) ? 'kg.edit'\n             AND NOT (\n                 COALESCE(\n                     membership.attributes -> 'denied_actions', '[]'::jsonb\n                 ) ? 'kg.edit'\n             )\n             AND (\n                 draft.classification = 0 OR draft.domain_ref_id IS NULL\n                 OR COALESCE(\n                     membership.attributes -> 'allowed_domain_ids', '[]'::jsonb\n                 ) ? draft.domain_ref_id::text\n             )\n       ) THEN\n        RETURN 'STALE_AUTHORIZATION';\n    END IF;\n    IF p_schema_binding IS NOT NULL AND (\n        jsonb_typeof(p_schema_binding) <> 'object'\n        OR octet_length(p_schema_binding::text) > 8192\n        OR knowledge.tbox_proposal_json_hash_v1(p_schema_binding)\n            <> job.schema_binding_hash\n        OR p_schema_binding <> job.schema_binding_document\n    ) THEN\n        RETURN 'STALE_MODEL_BINDING';\n    END IF;\n    IF job.input_kind = 'DOCUMENT_SCHEMA' THEN\n        SELECT * INTO manifest\n        FROM integration.object_manifests\n        WHERE workspace_id = job.workspace_id AND id = job.manifest_id;\n        current_validation_hash := knowledge.tbox_proposal_json_hash_v1(\n            jsonb_build_object(\n                'contract', 'KNOWLEDGE_STUDIO_UPLOAD_VALIDATION_EVIDENCE_V1',\n                'manifest_id', manifest.id::text,\n                'manifest_version', manifest.version,\n                'validation_summary', manifest.validation_summary\n            )\n        );\n        IF manifest.id IS NULL OR manifest.state <> 'ACCEPTED'\n           OR manifest.owner_id <> job.requested_by\n           OR manifest.version <> job.manifest_version\n           OR manifest.actual_sha256 IS DISTINCT FROM job.source_content_hash\n           OR manifest.actual_mime IS DISTINCT FROM job.source_media_type\n           OR manifest.actual_size_bytes IS DISTINCT FROM job.source_size_bytes\n           OR manifest.classification IS DISTINCT FROM job.source_classification\n           OR manifest.classification > draft.classification\n           OR manifest.classification > 1\n           OR manifest.content_profile <> 'KNOWLEDGE_STUDIO_DOCUMENT_V1'\n           OR manifest.content_profile IS DISTINCT FROM job.source_content_profile\n           OR manifest.display_name IS DISTINCT FROM job.source_filename\n           OR current_validation_hash IS DISTINCT FROM\n               job.source_validation_evidence_hash\n           OR manifest.validation_summary ->> 'profile_configuration_hash'\n               IS DISTINCT FROM job.parser_config_hash THEN\n            RETURN 'STALE_SOURCE';\n        END IF;\n    ELSE\n        SELECT * INTO asset\n        FROM catalog.assets_projection\n        WHERE workspace_id = job.workspace_id AND id = job.catalog_asset_id;\n        IF asset.id IS NULL OR asset.deleted_at IS NOT NULL\n           OR asset.lifecycle <> 'ACTIVE'\n           OR asset.classification IS DISTINCT FROM job.source_classification\n           OR asset.classification > draft.classification\n           OR asset.classification > 1\n           OR asset.source_version IS DISTINCT FROM\n               job.catalog_source_document ->> 'projection_source_version'\n           OR asset.name IS DISTINCT FROM job.catalog_source_document ->> 'name'\n           OR asset.asset_type IS DISTINCT FROM\n               job.catalog_source_document ->> 'asset_type'\n           OR knowledge.tbox_proposal_json_hash_v1(job.catalog_source_document)\n               <> job.catalog_source_hash THEN\n            RETURN 'STALE_SOURCE';\n        END IF;\n    END IF;\n    IF job.state = 'CANCEL_REQUESTED' THEN\n        RETURN 'STALE_CANCEL_REQUESTED';\n    END IF;\n    RETURN NULL;\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.tbox_proposal_lease_matches_v1(\n    p_workspace_id uuid,\n    p_job_id uuid,\n    p_attempt_id uuid,\n    p_lease_epoch bigint,\n    p_lease_token text,\n    p_worker_fingerprint text\n)\nRETURNS boolean\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = pg_catalog, knowledge\nAS $$\n    SELECT EXISTS (\n        SELECT 1\n        FROM knowledge.tbox_proposal_jobs AS job\n        JOIN knowledge.tbox_proposal_attempts AS attempt\n          ON attempt.workspace_id = job.workspace_id\n         AND attempt.job_id = job.id\n         AND attempt.id = job.current_attempt_id\n        WHERE job.workspace_id = p_workspace_id\n          AND job.id = p_job_id\n          AND job.current_attempt_id = p_attempt_id\n          AND job.lease_epoch = p_lease_epoch\n          AND job.lease_token_hash = encode(\n              sha256(convert_to(p_lease_token, 'UTF8')), 'hex'\n          )\n          AND job.lease_owner_fingerprint = p_worker_fingerprint\n          AND attempt.lease_epoch = p_lease_epoch\n          AND attempt.lease_token_hash = job.lease_token_hash\n          AND attempt.worker_fingerprint = p_worker_fingerprint\n          AND attempt.state = 'RUNNING'\n          AND attempt.finished_at IS NULL\n    )\n$$;")
        op.execute('CREATE OR REPLACE FUNCTION knowledge.append_tbox_proposal_event_v1(\n    p_workspace_id uuid,\n    p_job_id uuid,\n    p_attempt_id uuid,\n    p_state text,\n    p_stage text,\n    p_actor_kind text,\n    p_actor_ref text,\n    p_details jsonb\n)\nRETURNS void\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, knowledge\nAS $$\nDECLARE\n    next_sequence bigint;\n    occurred timestamptz := transaction_timestamp();\n    evidence_hash text;\nBEGIN\n    IF p_state NOT IN (\n        \'QUEUED\',\'RUNNING\',\'RETRY_WAIT\',\'CANCEL_REQUESTED\',\n        \'SUCCEEDED\',\'FAILED\',\'STALE\',\'CANCELLED\'\n    ) OR p_stage NOT IN (\n        \'QUEUED\',\'SOURCE_VALIDATION\',\'PARSING\',\'INFERENCE\',\n        \'VALIDATING\',\'FINALIZING\',\'COMPLETED\'\n    ) OR p_actor_kind NOT IN (\'HUMAN\',\'SERVICE\')\n      OR char_length(COALESCE(p_actor_ref, \'\')) NOT BETWEEN 1 AND 300\n      OR jsonb_typeof(p_details) <> \'object\'\n      OR octet_length(p_details::text) > 8192\n      OR p_details::text ~*\n          \'"(bucket|object_key|excerpt|prompt|provider_body|content)"\\\\s*:\'\n    THEN\n        RAISE EXCEPTION \'invalid T-Box Proposal transition evidence\'\n            USING ERRCODE = \'55000\';\n    END IF;\n    SELECT COALESCE(max(event.sequence), 0) + 1\n    INTO next_sequence\n    FROM knowledge.tbox_proposal_events AS event\n    WHERE event.workspace_id = p_workspace_id AND event.job_id = p_job_id;\n    evidence_hash := knowledge.tbox_proposal_json_hash_v1(jsonb_build_object(\n        \'contract\', \'KNOWLEDGE_STUDIO_TBOX_PROPOSAL_JOB_EVENT_V1\',\n        \'workspace_id\', p_workspace_id::text,\n        \'job_id\', p_job_id::text,\n        \'attempt_id\', CASE WHEN p_attempt_id IS NULL THEN NULL\n            ELSE to_jsonb(p_attempt_id::text) END,\n        \'sequence\', next_sequence,\n        \'state\', p_state,\n        \'stage\', p_stage,\n        \'actor_kind\', p_actor_kind,\n        \'actor_ref\', p_actor_ref,\n        \'details\', p_details,\n        \'occurred_at\', occurred\n    ));\n    INSERT INTO knowledge.tbox_proposal_events (\n        workspace_id, job_id, sequence, attempt_id, state, stage,\n        actor_kind, actor_ref, reason_code, details_document,\n        evidence_hash, occurred_at\n    ) VALUES (\n        p_workspace_id, p_job_id, next_sequence, p_attempt_id, p_state, p_stage,\n        p_actor_kind, p_actor_ref, p_details ->> \'reason_code\', p_details,\n        evidence_hash, occurred\n    );\nEND\n$$;')
        op.execute("CREATE OR REPLACE FUNCTION knowledge.emit_tbox_proposal_outbox_v1(\n    p_workspace_id uuid,\n    p_job_id uuid,\n    p_state text,\n    p_version integer\n)\nRETURNS void\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, integration\nAS $$\nBEGIN\n    INSERT INTO integration.outbox_events (\n        id, workspace_id, aggregate_type, aggregate_id, event_type,\n        schema_version, payload, created_at, published_at, dead_lettered_at,\n        lease_until, attempts, last_error_code\n    ) VALUES (\n        gen_random_uuid(), p_workspace_id, 'knowledge_tbox_proposal_job',\n        p_job_id, 'knowledge.tbox-proposal-job.' || lower(p_state) || '.v1',\n        1, jsonb_build_object(\n            'job_id', p_job_id::text,\n            'state', p_state,\n            'version', p_version\n        ), transaction_timestamp(), NULL, NULL, NULL, 0, NULL\n    );\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.reject_tbox_proposal_evidence_mutation_v1()\nRETURNS trigger\nLANGUAGE plpgsql\nSET search_path = pg_catalog\nAS $$\nBEGIN\n    RAISE EXCEPTION 'T-Box Proposal evidence is append-only'\n        USING ERRCODE = '55000';\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.enforce_tbox_proposal_job_pin_immutability_v1()\nRETURNS trigger\nLANGUAGE plpgsql\nSET search_path = pg_catalog\nAS $$\nBEGIN\n    IF ROW(\n        NEW.id, NEW.workspace_id, NEW.draft_id, NEW.target_block_id,\n        NEW.requested_by, NEW.input_kind, NEW.mode, NEW.base_draft_version,\n        NEW.base_tbox_hash, NEW.request_hash, NEW.requester_authorization_hash,\n        NEW.parser_config_hash, NEW.schema_binding_document,\n        NEW.schema_binding_hash, NEW.source_pin_hash, NEW.pin_hash,\n        NEW.prepared_at, NEW.manifest_id, NEW.manifest_version,\n        NEW.source_content_hash, NEW.source_media_type, NEW.source_size_bytes,\n        NEW.source_classification, NEW.source_content_profile,\n        NEW.source_validation_evidence_hash, NEW.source_filename,\n        NEW.catalog_asset_id, NEW.catalog_source_document,\n        NEW.catalog_source_hash, NEW.maximum_attempts,\n        NEW.supersedes_job_id, NEW.created_at\n    ) IS DISTINCT FROM ROW(\n        OLD.id, OLD.workspace_id, OLD.draft_id, OLD.target_block_id,\n        OLD.requested_by, OLD.input_kind, OLD.mode, OLD.base_draft_version,\n        OLD.base_tbox_hash, OLD.request_hash, OLD.requester_authorization_hash,\n        OLD.parser_config_hash, OLD.schema_binding_document,\n        OLD.schema_binding_hash, OLD.source_pin_hash, OLD.pin_hash,\n        OLD.prepared_at, OLD.manifest_id, OLD.manifest_version,\n        OLD.source_content_hash, OLD.source_media_type, OLD.source_size_bytes,\n        OLD.source_classification, OLD.source_content_profile,\n        OLD.source_validation_evidence_hash, OLD.source_filename,\n        OLD.catalog_asset_id, OLD.catalog_source_document,\n        OLD.catalog_source_hash, OLD.maximum_attempts,\n        OLD.supersedes_job_id, OLD.created_at\n    ) THEN\n        RAISE EXCEPTION 'T-Box Proposal job pins are immutable'\n            USING ERRCODE = '55000';\n    END IF;\n    RETURN NEW;\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.enforce_tbox_proposal_attempt_immutability_v1()\nRETURNS trigger\nLANGUAGE plpgsql\nSET search_path = pg_catalog\nAS $$\nBEGIN\n    IF ROW(\n        NEW.id, NEW.workspace_id, NEW.job_id, NEW.attempt_no,\n        NEW.lease_epoch, NEW.lease_token_hash, NEW.worker_fingerprint,\n        NEW.claimed_at\n    ) IS DISTINCT FROM ROW(\n        OLD.id, OLD.workspace_id, OLD.job_id, OLD.attempt_no,\n        OLD.lease_epoch, OLD.lease_token_hash, OLD.worker_fingerprint,\n        OLD.claimed_at\n    ) THEN\n        RAISE EXCEPTION 'T-Box Proposal attempt pins are immutable'\n            USING ERRCODE = '55000';\n    END IF;\n    RETURN NEW;\nEND\n$$;")
        op.execute('CREATE OR REPLACE FUNCTION knowledge.enforce_tbox_proposal_content_safety_v1()\nRETURNS trigger\nLANGUAGE plpgsql\nSET search_path = pg_catalog\nAS $$\nBEGIN\n    IF char_length(NEW.prompt) > 512\n       OR NEW.prompt ~ \'[\\\\x00-\\\\x1F\\\\x7F]\'\n       OR NOT (\n           NEW.prompt = \'Governed Schema Assistant proposal\'\n           OR NEW.prompt = \'Governed Asset Release proposal\'\n           OR NEW.prompt LIKE \'Document schema proposal: %\'\n           OR NEW.prompt LIKE \'Catalog schema proposal: %\'\n       )\n       OR (\n           NEW.source_reference_document IS NOT NULL\n           AND (\n               jsonb_typeof(NEW.source_reference_document) <> \'object\'\n               OR octet_length(NEW.source_reference_document::text) > 65536\n               OR NEW.source_reference_document::text ~*\n                   \'"(bucket|object_key|excerpt|prompt|provider_body|content)"\\\\s*:\'\n           )\n       )\n    THEN\n        RAISE EXCEPTION \'T-Box Proposal content contains unsafe retained input\'\n            USING ERRCODE = \'55000\';\n    END IF;\n    RETURN NEW;\nEND\n$$;')
        op.execute("CREATE OR REPLACE FUNCTION knowledge.request_tbox_proposal_job_v1(\n    p_workspace_id uuid,\n    p_draft_id uuid,\n    p_requested_by uuid,\n    p_target_block_id uuid,\n    p_input_kind text,\n    p_mode text,\n    p_base_draft_version integer,\n    p_base_tbox_hash text,\n    p_request_hash text,\n    p_requester_authorization_hash text,\n    p_source_pin jsonb,\n    p_source_pin_hash text,\n    p_parser_configuration_hash text,\n    p_schema_binding jsonb,\n    p_schema_binding_hash text,\n    p_pin_hash text,\n    p_maximum_attempts integer,\n    p_idempotency_key text\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, platform, iam, catalog, integration, knowledge\nAS $$\nDECLARE\n    actor_id uuid := NULLIF(current_setting('app.subject_id', true), '')::uuid;\n    draft knowledge.studio_drafts%ROWTYPE;\n    manifest integration.object_manifests%ROWTYPE;\n    asset catalog.assets_projection%ROWTYPE;\n    job_id uuid := gen_random_uuid();\n    now_at timestamptz := transaction_timestamp();\n    idempotency_key_hash text := encode(\n        sha256(convert_to(p_idempotency_key, 'UTF8')), 'hex'\n    );\n    replay integration.idempotency_keys%ROWTYPE;\n    source_manifest_id uuid;\n    source_asset_id uuid;\n    validation_hash text;\n    result jsonb;\nBEGIN\n    IF session_user <> 'datariver_app'\n       OR actor_id IS DISTINCT FROM p_requested_by\n       OR p_workspace_id IS DISTINCT FROM\n           NULLIF(current_setting('app.workspace_id', true), '')::uuid\n       OR p_input_kind NOT IN ('DOCUMENT_SCHEMA','CATALOG_SCHEMA')\n       OR p_mode NOT IN ('MERGE_INTO_CURRENT','APPEND_LAYER')\n       OR (p_mode = 'MERGE_INTO_CURRENT') <> (p_target_block_id IS NOT NULL)\n       OR p_base_draft_version < 1\n       OR p_base_tbox_hash !~ '^[0-9a-f]{64}$'\n       OR p_request_hash !~ '^[0-9a-f]{64}$'\n       OR p_requester_authorization_hash !~ '^[0-9a-f]{64}$'\n       OR p_source_pin_hash !~ '^[0-9a-f]{64}$'\n       OR p_parser_configuration_hash !~ '^[0-9a-f]{64}$'\n       OR p_schema_binding_hash !~ '^[0-9a-f]{64}$'\n       OR p_pin_hash !~ '^[0-9a-f]{64}$'\n       OR p_maximum_attempts NOT BETWEEN 1 AND 20\n       OR char_length(COALESCE(p_idempotency_key, '')) NOT BETWEEN 1 AND 200\n       OR p_idempotency_key <> btrim(p_idempotency_key)\n       OR jsonb_typeof(p_source_pin) <> 'object'\n       OR octet_length(p_source_pin::text) > 65536\n       OR jsonb_typeof(p_schema_binding) <> 'object'\n       OR octet_length(p_schema_binding::text) > 8192\n       OR knowledge.tbox_proposal_json_hash_v1(p_source_pin) <> p_source_pin_hash\n       OR knowledge.tbox_proposal_json_hash_v1(p_schema_binding)\n           <> p_schema_binding_hash\n    THEN\n        RAISE EXCEPTION 'invalid T-Box Proposal job request'\n            USING ERRCODE = '55000';\n    END IF;\n    PERFORM pg_advisory_xact_lock(hashtextextended(\n        p_workspace_id::text || ':' || 'knowledge.tbox-proposal.request.v1' || ':' ||\n            p_idempotency_key, 0\n    ));\n    SELECT stored_replay.* INTO replay\n    FROM integration.idempotency_keys AS stored_replay\n    WHERE stored_replay.workspace_id = p_workspace_id\n      AND stored_replay.operation = 'knowledge.tbox-proposal.request.v1'\n      AND stored_replay.key_hash = idempotency_key_hash;\n    IF replay.workspace_id IS NOT NULL THEN\n        IF replay.request_hash <> p_request_hash THEN\n            RAISE EXCEPTION 'T-Box Proposal idempotency key was reused'\n                USING ERRCODE = '55000';\n        END IF;\n        RETURN knowledge.tbox_proposal_job_document_v1(\n            p_workspace_id, (replay.result ->> 'job_id')::uuid\n        );\n    END IF;\n    SELECT * INTO draft\n    FROM knowledge.studio_drafts\n    WHERE workspace_id = p_workspace_id AND id = p_draft_id\n    FOR UPDATE;\n    IF draft.id IS NULL OR draft.author_id <> actor_id\n       OR draft.state <> 'DRAFT' OR draft.current_step <> 'TBOX'\n       OR draft.version <> p_base_draft_version\n       OR NOT knowledge.current_tbox_proposal_human_can_v1(\n           p_workspace_id, actor_id, draft.classification, draft.domain_ref_id\n       ) OR knowledge.current_tbox_proposal_authorization_hash_v1(\n           p_workspace_id, actor_id\n       ) IS DISTINCT FROM p_requester_authorization_hash\n    THEN\n        RAISE EXCEPTION 'T-Box Proposal requester or Draft pin is stale'\n            USING ERRCODE = '42501';\n    END IF;\n    IF p_target_block_id IS NOT NULL AND NOT EXISTS (\n        SELECT 1 FROM knowledge.tbox_draft_blocks AS block\n        WHERE block.workspace_id = p_workspace_id\n          AND block.draft_id = p_draft_id\n          AND block.id = p_target_block_id\n    ) THEN\n        RAISE EXCEPTION 'T-Box Proposal target block is unavailable'\n            USING ERRCODE = '55000';\n    END IF;\n    IF p_input_kind = 'DOCUMENT_SCHEMA' THEN\n        IF (p_source_pin - ARRAY[\n            'kind','manifest_id','manifest_version','content_sha256','media_type',\n            'size_bytes','classification','content_profile',\n            'validation_evidence_hash','filename'\n        ]) <> '{}'::jsonb OR p_source_pin ->> 'kind' <> 'DOCUMENT_SCHEMA'\n           OR COALESCE(p_source_pin ->> 'manifest_id', '') !~\n               '^[0-9a-fA-F-]{36}$'\n           OR COALESCE(p_source_pin ->> 'manifest_version', '') !~ '^[1-9][0-9]*$'\n           OR p_source_pin ->> 'content_sha256' !~ '^[0-9a-f]{64}$'\n           OR COALESCE(p_source_pin ->> 'size_bytes', '') !~ '^[1-9][0-9]*$'\n           OR (p_source_pin ->> 'size_bytes')::bigint > 10485760\n           OR COALESCE(p_source_pin ->> 'classification', '') NOT IN ('0','1')\n           OR p_source_pin ->> 'content_profile'\n               <> 'KNOWLEDGE_STUDIO_DOCUMENT_V1'\n           OR p_source_pin ->> 'validation_evidence_hash' !~ '^[0-9a-f]{64}$'\n           OR char_length(COALESCE(p_source_pin ->> 'filename', ''))\n               NOT BETWEEN 1 AND 255\n           OR p_source_pin ->> 'filename' ~ '[/\\\\]'\n        THEN\n            RAISE EXCEPTION 'invalid accepted-upload Proposal pin'\n                USING ERRCODE = '55000';\n        END IF;\n        source_manifest_id := (p_source_pin ->> 'manifest_id')::uuid;\n        SELECT * INTO manifest\n        FROM integration.object_manifests\n        WHERE workspace_id = p_workspace_id AND id = source_manifest_id\n        FOR SHARE;\n        validation_hash := knowledge.tbox_proposal_json_hash_v1(\n            jsonb_build_object(\n                'contract', 'KNOWLEDGE_STUDIO_UPLOAD_VALIDATION_EVIDENCE_V1',\n                'manifest_id', manifest.id::text,\n                'manifest_version', manifest.version,\n                'validation_summary', manifest.validation_summary\n            )\n        );\n        IF manifest.id IS NULL OR manifest.owner_id <> actor_id\n           OR manifest.state <> 'ACCEPTED'\n           OR manifest.version <> (p_source_pin ->> 'manifest_version')::integer\n           OR manifest.actual_sha256 IS DISTINCT FROM\n               p_source_pin ->> 'content_sha256'\n           OR manifest.actual_mime IS DISTINCT FROM p_source_pin ->> 'media_type'\n           OR manifest.actual_size_bytes IS DISTINCT FROM\n               (p_source_pin ->> 'size_bytes')::bigint\n           OR manifest.classification IS DISTINCT FROM\n               (p_source_pin ->> 'classification')::integer\n           OR manifest.classification > draft.classification\n           OR manifest.classification > 1\n           OR manifest.content_profile <> 'KNOWLEDGE_STUDIO_DOCUMENT_V1'\n           OR manifest.display_name IS DISTINCT FROM p_source_pin ->> 'filename'\n           OR validation_hash IS DISTINCT FROM\n               p_source_pin ->> 'validation_evidence_hash'\n           OR manifest.validation_summary ->> 'profile_configuration_hash'\n               IS DISTINCT FROM p_parser_configuration_hash\n        THEN\n            RAISE EXCEPTION 'accepted-upload Proposal pin is stale'\n                USING ERRCODE = '55000';\n        END IF;\n    ELSE\n        IF (p_source_pin - ARRAY[\n            'kind','asset_id','name','asset_type','classification','source_version',\n            'projection_source_version','selected_field_paths','platform',\n            'database_name','schema_name','domain','tags','glossary_terms'\n        ]) <> '{}'::jsonb OR p_source_pin ->> 'kind' <> 'CATALOG_SCHEMA'\n           OR COALESCE(p_source_pin ->> 'asset_id', '') !~\n               '^[0-9a-fA-F-]{36}$'\n           OR COALESCE(p_source_pin ->> 'classification', '') NOT IN ('0','1')\n           OR jsonb_typeof(p_source_pin -> 'selected_field_paths') <> 'array'\n           OR jsonb_array_length(p_source_pin -> 'selected_field_paths')\n               NOT BETWEEN 1 AND 100\n           OR octet_length(p_source_pin::text) > 65536\n        THEN\n            RAISE EXCEPTION 'invalid Catalog Proposal pin'\n                USING ERRCODE = '55000';\n        END IF;\n        source_asset_id := (p_source_pin ->> 'asset_id')::uuid;\n        SELECT * INTO asset\n        FROM catalog.assets_projection\n        WHERE workspace_id = p_workspace_id AND id = source_asset_id\n        FOR SHARE;\n        IF asset.id IS NULL OR asset.deleted_at IS NOT NULL\n           OR asset.lifecycle <> 'ACTIVE'\n           OR asset.classification <> (p_source_pin ->> 'classification')::integer\n           OR asset.classification > draft.classification OR asset.classification > 1\n           OR asset.source_version IS DISTINCT FROM\n               p_source_pin ->> 'projection_source_version'\n           OR asset.name IS DISTINCT FROM p_source_pin ->> 'name'\n           OR asset.asset_type IS DISTINCT FROM p_source_pin ->> 'asset_type'\n           OR EXISTS (\n               SELECT 1\n               FROM jsonb_array_elements_text(\n                   p_source_pin -> 'selected_field_paths'\n               ) AS selected(value)\n               WHERE char_length(selected.value) NOT BETWEEN 1 AND 2000\n                  OR NOT asset.column_names ? selected.value\n           )\n           OR (\n               SELECT count(*) <> count(DISTINCT selected.value)\n               FROM jsonb_array_elements_text(\n                   p_source_pin -> 'selected_field_paths'\n               ) AS selected(value)\n           )\n        THEN\n            RAISE EXCEPTION 'Catalog Proposal pin is stale'\n                USING ERRCODE = '55000';\n        END IF;\n    END IF;\n    INSERT INTO knowledge.tbox_proposal_jobs (\n        id, workspace_id, draft_id, target_block_id, requested_by,\n        input_kind, mode, base_draft_version, base_tbox_hash, request_hash,\n        requester_authorization_hash, parser_config_hash,\n        schema_binding_document, schema_binding_hash, source_pin_hash, pin_hash,\n        prepared_at, manifest_id, manifest_version, source_content_hash,\n        source_media_type, source_size_bytes, source_classification,\n        source_content_profile, source_validation_evidence_hash, source_filename,\n        catalog_asset_id, catalog_source_document, catalog_source_hash,\n        state, stage, progress_percent, attempt_count, maximum_attempts,\n        next_attempt_at, current_attempt_id, lease_epoch, lease_token_hash,\n        lease_owner_fingerprint, lease_started_at, lease_expires_at,\n        cancel_requested_by, cancel_requested_at, cancel_reason,\n        result_proposal_id, result_evidence_hash, last_failure_code,\n        completed_at, supersedes_job_id, created_at, updated_at, version\n    ) VALUES (\n        job_id, p_workspace_id, p_draft_id, p_target_block_id, actor_id,\n        p_input_kind, p_mode, p_base_draft_version, p_base_tbox_hash,\n        p_request_hash, p_requester_authorization_hash,\n        p_parser_configuration_hash, p_schema_binding, p_schema_binding_hash,\n        p_source_pin_hash, p_pin_hash, now_at,\n        source_manifest_id,\n        CASE WHEN p_input_kind = 'DOCUMENT_SCHEMA'\n            THEN (p_source_pin ->> 'manifest_version')::integer ELSE NULL END,\n        CASE WHEN p_input_kind = 'DOCUMENT_SCHEMA'\n            THEN p_source_pin ->> 'content_sha256' ELSE NULL END,\n        CASE WHEN p_input_kind = 'DOCUMENT_SCHEMA'\n            THEN p_source_pin ->> 'media_type' ELSE NULL END,\n        CASE WHEN p_input_kind = 'DOCUMENT_SCHEMA'\n            THEN (p_source_pin ->> 'size_bytes')::integer ELSE NULL END,\n        (p_source_pin ->> 'classification')::integer,\n        CASE WHEN p_input_kind = 'DOCUMENT_SCHEMA'\n            THEN p_source_pin ->> 'content_profile' ELSE NULL END,\n        CASE WHEN p_input_kind = 'DOCUMENT_SCHEMA'\n            THEN p_source_pin ->> 'validation_evidence_hash' ELSE NULL END,\n        CASE WHEN p_input_kind = 'DOCUMENT_SCHEMA'\n            THEN p_source_pin ->> 'filename' ELSE NULL END,\n        source_asset_id,\n        CASE WHEN p_input_kind = 'CATALOG_SCHEMA' THEN p_source_pin ELSE NULL END,\n        CASE WHEN p_input_kind = 'CATALOG_SCHEMA' THEN p_source_pin_hash ELSE NULL END,\n        'QUEUED', 'QUEUED', 0, 0, p_maximum_attempts,\n        now_at, NULL, 0, NULL, NULL, NULL, NULL,\n        NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,\n        now_at, now_at, 1\n    );\n    PERFORM knowledge.append_tbox_proposal_event_v1(\n        p_workspace_id, job_id, NULL, 'QUEUED', 'QUEUED',\n        'HUMAN', actor_id::text,\n        jsonb_build_object('reason_code', 'REQUESTED')\n    );\n    PERFORM knowledge.emit_tbox_proposal_outbox_v1(\n        p_workspace_id, job_id, 'QUEUED', 1\n    );\n    result := knowledge.tbox_proposal_job_document_v1(p_workspace_id, job_id);\n    INSERT INTO integration.idempotency_keys (\n        workspace_id, operation, key_hash, request_hash, result,\n        created_at, expires_at\n    ) VALUES (\n        p_workspace_id, 'knowledge.tbox-proposal.request.v1', idempotency_key_hash,\n        p_request_hash, jsonb_build_object('job_id', job_id::text),\n        now_at, now_at + interval '24 hours'\n    );\n    RETURN result;\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.get_owned_tbox_proposal_job_v1(\n    p_workspace_id uuid,\n    p_draft_id uuid,\n    p_job_id uuid,\n    p_actor_id uuid\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nSTABLE\nSECURITY DEFINER\nSET search_path = pg_catalog, knowledge\nAS $$\nDECLARE\n    job knowledge.tbox_proposal_jobs%ROWTYPE;\n    draft knowledge.studio_drafts%ROWTYPE;\nBEGIN\n    IF session_user <> 'datariver_app'\n       OR p_workspace_id IS DISTINCT FROM\n           NULLIF(current_setting('app.workspace_id', true), '')::uuid\n       OR p_actor_id IS DISTINCT FROM\n           NULLIF(current_setting('app.subject_id', true), '')::uuid\n    THEN\n        RAISE EXCEPTION 'T-Box Proposal job read is not permitted'\n            USING ERRCODE = '42501';\n    END IF;\n    SELECT * INTO job FROM knowledge.tbox_proposal_jobs\n    WHERE workspace_id = p_workspace_id AND draft_id = p_draft_id\n      AND id = p_job_id AND requested_by = p_actor_id;\n    IF job.id IS NULL THEN\n        RETURN NULL;\n    END IF;\n    SELECT * INTO draft FROM knowledge.studio_drafts\n    WHERE workspace_id = job.workspace_id AND id = job.draft_id;\n    IF draft.id IS NULL OR draft.author_id <> p_actor_id\n       OR NOT knowledge.current_tbox_proposal_human_can_v1(\n           p_workspace_id, p_actor_id, draft.classification, draft.domain_ref_id\n       ) THEN\n        RAISE EXCEPTION 'T-Box Proposal job read is not permitted'\n            USING ERRCODE = '42501';\n    END IF;\n    RETURN knowledge.tbox_proposal_job_document_v1(p_workspace_id, p_job_id);\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.list_owned_tbox_proposal_jobs_v1(\n    p_workspace_id uuid,\n    p_draft_id uuid,\n    p_actor_id uuid,\n    p_limit integer,\n    p_cursor text\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nSTABLE\nSECURITY DEFINER\nSET search_path = pg_catalog, knowledge\nAS $$\nDECLARE\n    draft knowledge.studio_drafts%ROWTYPE;\n    cursor_id uuid;\n    cursor_created_at timestamptz;\n    items jsonb;\n    next_cursor text;\nBEGIN\n    IF session_user <> 'datariver_app'\n       OR p_workspace_id IS DISTINCT FROM\n           NULLIF(current_setting('app.workspace_id', true), '')::uuid\n       OR p_actor_id IS DISTINCT FROM\n           NULLIF(current_setting('app.subject_id', true), '')::uuid\n       OR p_limit NOT BETWEEN 1 AND 100\n       OR (p_cursor IS NOT NULL AND p_cursor !~ '^[0-9a-fA-F-]{36}$')\n    THEN\n        RAISE EXCEPTION 'T-Box Proposal job list is not permitted'\n            USING ERRCODE = '42501';\n    END IF;\n    SELECT * INTO draft FROM knowledge.studio_drafts\n    WHERE workspace_id = p_workspace_id AND id = p_draft_id;\n    IF draft.id IS NULL OR draft.author_id <> p_actor_id\n       OR NOT knowledge.current_tbox_proposal_human_can_v1(\n           p_workspace_id, p_actor_id, draft.classification, draft.domain_ref_id\n       ) THEN\n        RAISE EXCEPTION 'T-Box Proposal job list is not permitted'\n            USING ERRCODE = '42501';\n    END IF;\n    IF p_cursor IS NOT NULL THEN\n        cursor_id := p_cursor::uuid;\n        SELECT created_at INTO cursor_created_at\n        FROM knowledge.tbox_proposal_jobs\n        WHERE workspace_id = p_workspace_id AND draft_id = p_draft_id\n          AND requested_by = p_actor_id AND id = cursor_id;\n        IF cursor_created_at IS NULL THEN\n            RAISE EXCEPTION 'invalid T-Box Proposal job cursor'\n                USING ERRCODE = '55000';\n        END IF;\n    END IF;\n    WITH page AS (\n        SELECT job.id, job.created_at,\n               row_number() OVER (ORDER BY job.created_at DESC, job.id DESC) AS position\n        FROM knowledge.tbox_proposal_jobs AS job\n        WHERE job.workspace_id = p_workspace_id\n          AND job.draft_id = p_draft_id\n          AND job.requested_by = p_actor_id\n          AND (\n              cursor_created_at IS NULL\n              OR (job.created_at, job.id) < (cursor_created_at, cursor_id)\n          )\n        ORDER BY job.created_at DESC, job.id DESC\n        LIMIT p_limit + 1\n    )\n    SELECT COALESCE(jsonb_agg(\n               knowledge.tbox_proposal_job_document_v1(p_workspace_id, page.id)\n               ORDER BY page.position\n           ) FILTER (WHERE page.position <= p_limit), '[]'::jsonb),\n           max(CASE WHEN page.position = p_limit + 1 THEN (\n               SELECT prior.id::text FROM page AS prior\n               WHERE prior.position = p_limit\n           ) END)\n    INTO items, next_cursor\n    FROM page;\n    RETURN jsonb_build_object('items', items, 'next_cursor', next_cursor);\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.cancel_tbox_proposal_job_v1(\n    p_workspace_id uuid,\n    p_draft_id uuid,\n    p_job_id uuid,\n    p_actor_id uuid,\n    p_expected_version integer,\n    p_reason text,\n    p_request_hash text,\n    p_idempotency_key text\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, integration, knowledge\nAS $$\nDECLARE\n    job knowledge.tbox_proposal_jobs%ROWTYPE;\n    draft knowledge.studio_drafts%ROWTYPE;\n    now_at timestamptz := transaction_timestamp();\n    operation_name text := 'knowledge.tbox-proposal.cancel:' || p_job_id::text;\n    idempotency_key_hash text := encode(\n        sha256(convert_to(p_idempotency_key, 'UTF8')), 'hex'\n    );\n    replay integration.idempotency_keys%ROWTYPE;\n    target_state text;\nBEGIN\n    IF session_user <> 'datariver_app'\n       OR p_workspace_id IS DISTINCT FROM\n           NULLIF(current_setting('app.workspace_id', true), '')::uuid\n       OR p_actor_id IS DISTINCT FROM\n           NULLIF(current_setting('app.subject_id', true), '')::uuid\n       OR p_expected_version < 1\n       OR p_request_hash !~ '^[0-9a-f]{64}$'\n       OR char_length(COALESCE(p_idempotency_key, '')) NOT BETWEEN 1 AND 200\n       OR p_idempotency_key <> btrim(p_idempotency_key)\n       OR char_length(COALESCE(p_reason, '')) NOT BETWEEN 1 AND 1000\n       OR p_reason <> btrim(p_reason) OR p_reason ~ '[\\\\x00-\\\\x1F\\\\x7F]'\n    THEN\n        RAISE EXCEPTION 'invalid T-Box Proposal cancellation'\n            USING ERRCODE = '55000';\n    END IF;\n    PERFORM pg_advisory_xact_lock(hashtextextended(\n        p_workspace_id::text || ':' || operation_name || ':' || p_idempotency_key, 0\n    ));\n    SELECT stored_replay.* INTO replay\n    FROM integration.idempotency_keys AS stored_replay\n    WHERE stored_replay.workspace_id = p_workspace_id\n      AND stored_replay.operation = operation_name\n      AND stored_replay.key_hash = idempotency_key_hash;\n    IF replay.workspace_id IS NOT NULL THEN\n        IF replay.request_hash <> p_request_hash THEN\n            RAISE EXCEPTION 'T-Box Proposal cancellation key was reused'\n                USING ERRCODE = '55000';\n        END IF;\n        RETURN knowledge.tbox_proposal_job_document_v1(p_workspace_id, p_job_id);\n    END IF;\n    SELECT * INTO job FROM knowledge.tbox_proposal_jobs\n    WHERE workspace_id = p_workspace_id AND draft_id = p_draft_id\n      AND id = p_job_id AND requested_by = p_actor_id\n    FOR UPDATE;\n    SELECT * INTO draft FROM knowledge.studio_drafts\n    WHERE workspace_id = p_workspace_id AND id = p_draft_id;\n    IF job.id IS NULL OR draft.id IS NULL OR draft.author_id <> p_actor_id\n       OR job.version <> p_expected_version\n       OR NOT knowledge.current_tbox_proposal_human_can_v1(\n           p_workspace_id, p_actor_id, draft.classification, draft.domain_ref_id\n       ) OR job.state NOT IN ('QUEUED','RETRY_WAIT','RUNNING')\n    THEN\n        RAISE EXCEPTION 'T-Box Proposal cancellation changed concurrently'\n            USING ERRCODE = '55000';\n    END IF;\n    target_state := CASE WHEN job.state = 'RUNNING'\n        THEN 'CANCEL_REQUESTED' ELSE 'CANCELLED' END;\n    UPDATE knowledge.tbox_proposal_jobs\n    SET state = target_state,\n        stage = CASE WHEN target_state = 'CANCELLED' THEN 'COMPLETED' ELSE stage END,\n        cancel_requested_by = p_actor_id,\n        cancel_requested_at = now_at,\n        cancel_reason = p_reason,\n        completed_at = CASE WHEN target_state = 'CANCELLED' THEN now_at ELSE NULL END,\n        updated_at = now_at,\n        version = version + 1\n    WHERE workspace_id = p_workspace_id AND id = p_job_id\n    RETURNING * INTO job;\n    PERFORM knowledge.append_tbox_proposal_event_v1(\n        p_workspace_id, p_job_id, job.current_attempt_id,\n        target_state, job.stage, 'HUMAN', p_actor_id::text,\n        jsonb_build_object(\n            'reason_code', 'CANCEL_REQUESTED',\n            'reason_hash', encode(sha256(convert_to(p_reason, 'UTF8')), 'hex')\n        )\n    );\n    PERFORM knowledge.emit_tbox_proposal_outbox_v1(\n        p_workspace_id, p_job_id, target_state, job.version\n    );\n    INSERT INTO integration.idempotency_keys (\n        workspace_id, operation, key_hash, request_hash, result,\n        created_at, expires_at\n    ) VALUES (\n        p_workspace_id, operation_name, idempotency_key_hash, p_request_hash,\n        jsonb_build_object('job_id', p_job_id::text),\n        now_at, now_at + interval '24 hours'\n    );\n    RETURN knowledge.tbox_proposal_job_document_v1(p_workspace_id, p_job_id);\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.retry_tbox_proposal_job_v1(\n    p_workspace_id uuid,\n    p_draft_id uuid,\n    p_job_id uuid,\n    p_actor_id uuid,\n    p_expected_version integer,\n    p_request_hash text,\n    p_idempotency_key text\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, integration, knowledge\nAS $$\nDECLARE\n    prior_job knowledge.tbox_proposal_jobs%ROWTYPE;\n    draft knowledge.studio_drafts%ROWTYPE;\n    successor_id uuid := gen_random_uuid();\n    now_at timestamptz := transaction_timestamp();\n    operation_name text := 'knowledge.tbox-proposal.retry:' || p_job_id::text;\n    idempotency_key_hash text := encode(\n        sha256(convert_to(p_idempotency_key, 'UTF8')), 'hex'\n    );\n    replay integration.idempotency_keys%ROWTYPE;\n    drift_code text;\nBEGIN\n    IF session_user <> 'datariver_app'\n       OR p_workspace_id IS DISTINCT FROM\n           NULLIF(current_setting('app.workspace_id', true), '')::uuid\n       OR p_actor_id IS DISTINCT FROM\n           NULLIF(current_setting('app.subject_id', true), '')::uuid\n       OR p_expected_version < 1 OR p_request_hash !~ '^[0-9a-f]{64}$'\n       OR char_length(COALESCE(p_idempotency_key, '')) NOT BETWEEN 1 AND 200\n       OR p_idempotency_key <> btrim(p_idempotency_key)\n    THEN\n        RAISE EXCEPTION 'invalid T-Box Proposal retry'\n            USING ERRCODE = '55000';\n    END IF;\n    PERFORM pg_advisory_xact_lock(hashtextextended(\n        p_workspace_id::text || ':' || operation_name || ':' || p_idempotency_key, 0\n    ));\n    SELECT stored_replay.* INTO replay\n    FROM integration.idempotency_keys AS stored_replay\n    WHERE stored_replay.workspace_id = p_workspace_id\n      AND stored_replay.operation = operation_name\n      AND stored_replay.key_hash = idempotency_key_hash;\n    IF replay.workspace_id IS NOT NULL THEN\n        IF replay.request_hash <> p_request_hash THEN\n            RAISE EXCEPTION 'T-Box Proposal retry key was reused'\n                USING ERRCODE = '55000';\n        END IF;\n        RETURN knowledge.tbox_proposal_job_document_v1(\n            p_workspace_id, (replay.result ->> 'job_id')::uuid\n        );\n    END IF;\n    SELECT * INTO prior_job FROM knowledge.tbox_proposal_jobs\n    WHERE workspace_id = p_workspace_id AND draft_id = p_draft_id\n      AND id = p_job_id AND requested_by = p_actor_id\n    FOR UPDATE;\n    SELECT * INTO draft FROM knowledge.studio_drafts\n    WHERE workspace_id = p_workspace_id AND id = p_draft_id;\n    IF prior_job.id IS NULL OR draft.id IS NULL OR draft.author_id <> p_actor_id\n       OR prior_job.version <> p_expected_version\n       OR prior_job.state NOT IN ('FAILED','STALE','CANCELLED')\n       OR NOT knowledge.current_tbox_proposal_human_can_v1(\n           p_workspace_id, p_actor_id, draft.classification, draft.domain_ref_id\n       ) OR EXISTS (\n           SELECT 1 FROM knowledge.tbox_proposal_jobs AS successor\n           WHERE successor.workspace_id = p_workspace_id\n             AND successor.supersedes_job_id = p_job_id\n       )\n    THEN\n        RAISE EXCEPTION 'T-Box Proposal retry changed concurrently'\n            USING ERRCODE = '55000';\n    END IF;\n    drift_code := knowledge.tbox_proposal_job_drift_v1(\n        p_workspace_id, p_job_id, prior_job.schema_binding_document\n    );\n    IF drift_code IS NOT NULL AND drift_code <> 'STALE_CANCEL_REQUESTED' THEN\n        RAISE EXCEPTION 'T-Box Proposal retry pins are stale: %', drift_code\n            USING ERRCODE = '55000';\n    END IF;\n    INSERT INTO knowledge.tbox_proposal_jobs (\n        id, workspace_id, draft_id, target_block_id, requested_by,\n        input_kind, mode, base_draft_version, base_tbox_hash, request_hash,\n        requester_authorization_hash, parser_config_hash,\n        schema_binding_document, schema_binding_hash, source_pin_hash, pin_hash,\n        prepared_at, manifest_id, manifest_version, source_content_hash,\n        source_media_type, source_size_bytes, source_classification,\n        source_content_profile, source_validation_evidence_hash, source_filename,\n        catalog_asset_id, catalog_source_document, catalog_source_hash,\n        state, stage, progress_percent, attempt_count, maximum_attempts,\n        next_attempt_at, current_attempt_id, lease_epoch, lease_token_hash,\n        lease_owner_fingerprint, lease_started_at, lease_expires_at,\n        cancel_requested_by, cancel_requested_at, cancel_reason,\n        result_proposal_id, result_evidence_hash, last_failure_code,\n        completed_at, supersedes_job_id, created_at, updated_at, version\n    ) SELECT\n        successor_id, workspace_id, draft_id, target_block_id, requested_by,\n        input_kind, mode, base_draft_version, base_tbox_hash, p_request_hash,\n        requester_authorization_hash, parser_config_hash,\n        schema_binding_document, schema_binding_hash, source_pin_hash, pin_hash,\n        prepared_at, manifest_id, manifest_version, source_content_hash,\n        source_media_type, source_size_bytes, source_classification,\n        source_content_profile, source_validation_evidence_hash, source_filename,\n        catalog_asset_id, catalog_source_document, catalog_source_hash,\n        'QUEUED', 'QUEUED', 0, 0, maximum_attempts,\n        now_at, NULL, 0, NULL, NULL, NULL, NULL,\n        NULL, NULL, NULL, NULL, NULL, NULL, NULL,\n        p_job_id, now_at, now_at, 1\n    FROM knowledge.tbox_proposal_jobs\n    WHERE workspace_id = p_workspace_id AND id = p_job_id;\n    PERFORM knowledge.append_tbox_proposal_event_v1(\n        p_workspace_id, successor_id, NULL, 'QUEUED', 'QUEUED',\n        'HUMAN', p_actor_id::text,\n        jsonb_build_object(\n            'reason_code', 'MANUAL_RETRY',\n            'supersedes_job_id', p_job_id::text\n        )\n    );\n    PERFORM knowledge.emit_tbox_proposal_outbox_v1(\n        p_workspace_id, successor_id, 'QUEUED', 1\n    );\n    INSERT INTO integration.idempotency_keys (\n        workspace_id, operation, key_hash, request_hash, result,\n        created_at, expires_at\n    ) VALUES (\n        p_workspace_id, operation_name, idempotency_key_hash, p_request_hash,\n        jsonb_build_object('job_id', successor_id::text),\n        now_at, now_at + interval '24 hours'\n    );\n    RETURN knowledge.tbox_proposal_job_document_v1(p_workspace_id, successor_id);\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.claim_tbox_proposal_job_v1(\n    p_workspace_id uuid,\n    p_worker_fingerprint text,\n    p_lease_token text,\n    p_lease_seconds integer\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, integration, knowledge\nAS $$\nDECLARE\n    job knowledge.tbox_proposal_jobs%ROWTYPE;\n    draft knowledge.studio_drafts%ROWTYPE;\n    expired_job knowledge.tbox_proposal_jobs%ROWTYPE;\n    attempt_id uuid;\n    token_hash text := encode(sha256(convert_to(p_lease_token, 'UTF8')), 'hex');\n    worker_subject_id uuid := NULLIF(current_setting('app.subject_id', true), '')::uuid;\n    now_at timestamptz := transaction_timestamp();\n    lease_until timestamptz;\n    drift_code text;\n    target_state text;\n    attempt_no integer;\n    expired_attempt_id uuid;\nBEGIN\n    IF p_workspace_id IS DISTINCT FROM\n           NULLIF(current_setting('app.workspace_id', true), '')::uuid\n       OR char_length(COALESCE(p_worker_fingerprint, '')) NOT BETWEEN 1 AND 255\n       OR p_worker_fingerprint <> btrim(p_worker_fingerprint)\n       OR char_length(COALESCE(p_lease_token, '')) NOT BETWEEN 32 AND 512\n       OR p_lease_seconds NOT BETWEEN 5 AND 3600\n       OR NOT knowledge.current_tbox_proposal_service_can_v1(\n           p_workspace_id, 0, NULL\n       )\n    THEN\n        RAISE EXCEPTION 'T-Box Proposal claim is not permitted'\n            USING ERRCODE = '42501';\n    END IF;\n    FOR expired_job IN\n        SELECT queued.*\n        FROM knowledge.tbox_proposal_jobs AS queued\n        JOIN knowledge.studio_drafts AS source_draft\n          ON source_draft.workspace_id = queued.workspace_id\n         AND source_draft.id = queued.draft_id\n        WHERE queued.workspace_id = p_workspace_id\n          AND queued.state IN ('RUNNING','CANCEL_REQUESTED')\n          AND queued.lease_expires_at <= clock_timestamp()\n        ORDER BY queued.lease_expires_at, queued.id\n        FOR UPDATE OF queued SKIP LOCKED\n    LOOP\n        SELECT * INTO draft FROM knowledge.studio_drafts\n        WHERE workspace_id = expired_job.workspace_id\n          AND id = expired_job.draft_id;\n        IF NOT knowledge.current_tbox_proposal_service_can_v1(\n            p_workspace_id, COALESCE(draft.classification, 0), draft.domain_ref_id\n        ) THEN\n            CONTINUE;\n        END IF;\n        expired_attempt_id := expired_job.current_attempt_id;\n        target_state := CASE\n            WHEN expired_job.state = 'CANCEL_REQUESTED' THEN 'CANCELLED'\n            WHEN expired_job.attempt_count < expired_job.maximum_attempts\n                THEN 'RETRY_WAIT'\n            ELSE 'FAILED'\n        END;\n        UPDATE knowledge.tbox_proposal_attempts\n        SET state = CASE WHEN target_state = 'CANCELLED'\n                THEN 'CANCELLED' ELSE 'SUPERSEDED' END,\n            stage = 'COMPLETED', retryable = (target_state = 'RETRY_WAIT'),\n            failure_code = 'LEASE_EXPIRED', finished_at = now_at\n        WHERE workspace_id = p_workspace_id\n          AND id = expired_job.current_attempt_id\n          AND job_id = expired_job.id AND state = 'RUNNING';\n        UPDATE knowledge.tbox_proposal_jobs\n        SET state = target_state,\n            stage = CASE WHEN target_state = 'RETRY_WAIT'\n                THEN 'QUEUED' ELSE 'COMPLETED' END,\n            progress_percent = 0,\n            current_attempt_id = NULL,\n            lease_token_hash = NULL,\n            lease_owner_fingerprint = NULL,\n            lease_started_at = NULL,\n            lease_expires_at = NULL,\n            next_attempt_at = CASE WHEN target_state = 'RETRY_WAIT'\n                THEN now_at ELSE next_attempt_at END,\n            last_failure_code = CASE WHEN target_state = 'CANCELLED'\n                THEN NULL ELSE 'LEASE_EXPIRED' END,\n            completed_at = CASE WHEN target_state = 'RETRY_WAIT'\n                THEN NULL ELSE now_at END,\n            updated_at = now_at,\n            version = version + 1\n        WHERE workspace_id = p_workspace_id AND id = expired_job.id\n        RETURNING * INTO expired_job;\n        PERFORM knowledge.append_tbox_proposal_event_v1(\n            p_workspace_id, expired_job.id, expired_attempt_id,\n            target_state, expired_job.stage, 'SERVICE', worker_subject_id::text,\n            jsonb_build_object('reason_code', 'LEASE_EXPIRED')\n        );\n        PERFORM knowledge.emit_tbox_proposal_outbox_v1(\n            p_workspace_id, expired_job.id, target_state, expired_job.version\n        );\n    END LOOP;\n    LOOP\n        SELECT queued.* INTO job\n        FROM knowledge.tbox_proposal_jobs AS queued\n        WHERE queued.workspace_id = p_workspace_id\n          AND queued.state IN ('QUEUED','RETRY_WAIT')\n          AND queued.next_attempt_at <= now_at\n        ORDER BY queued.next_attempt_at, queued.created_at, queued.id\n        LIMIT 1\n        FOR UPDATE SKIP LOCKED;\n        IF job.id IS NULL THEN\n            RETURN NULL;\n        END IF;\n        SELECT * INTO draft FROM knowledge.studio_drafts\n        WHERE workspace_id = job.workspace_id AND id = job.draft_id;\n        IF NOT knowledge.current_tbox_proposal_service_can_v1(\n            p_workspace_id, COALESCE(draft.classification, 0), draft.domain_ref_id\n        ) THEN\n            RAISE EXCEPTION 'T-Box Proposal worker scope is not permitted'\n                USING ERRCODE = '42501';\n        END IF;\n        drift_code := knowledge.tbox_proposal_job_drift_v1(\n            p_workspace_id, job.id, NULL\n        );\n        IF drift_code IS NOT NULL THEN\n            UPDATE knowledge.tbox_proposal_jobs\n            SET state = 'STALE', stage = 'COMPLETED', progress_percent = 0,\n                last_failure_code = drift_code, completed_at = now_at,\n                current_attempt_id = NULL, lease_token_hash = NULL,\n                lease_owner_fingerprint = NULL, lease_started_at = NULL,\n                lease_expires_at = NULL, updated_at = now_at, version = version + 1\n            WHERE workspace_id = p_workspace_id AND id = job.id\n            RETURNING * INTO job;\n            PERFORM knowledge.append_tbox_proposal_event_v1(\n                p_workspace_id, job.id, NULL, 'STALE', 'COMPLETED',\n                'SERVICE', worker_subject_id::text,\n                jsonb_build_object('reason_code', drift_code)\n            );\n            PERFORM knowledge.emit_tbox_proposal_outbox_v1(\n                p_workspace_id, job.id, 'STALE', job.version\n            );\n            job.id := NULL;\n            CONTINUE;\n        END IF;\n        attempt_id := gen_random_uuid();\n        attempt_no := job.attempt_count + 1;\n        lease_until := clock_timestamp() + make_interval(secs => p_lease_seconds);\n        INSERT INTO knowledge.tbox_proposal_attempts (\n            id, workspace_id, job_id, attempt_no, lease_epoch,\n            lease_token_hash, worker_fingerprint, state, stage,\n            claimed_at, lease_expires_at, retryable, output_hash,\n            failure_code, finished_at\n        ) VALUES (\n            attempt_id, p_workspace_id, job.id, attempt_no,\n            job.lease_epoch + 1, token_hash, p_worker_fingerprint,\n            'RUNNING', 'SOURCE_VALIDATION', now_at, lease_until,\n            NULL, NULL, NULL, NULL\n        );\n        UPDATE knowledge.tbox_proposal_jobs\n        SET state = 'RUNNING', stage = 'SOURCE_VALIDATION',\n            progress_percent = 10, attempt_count = attempt_no,\n            current_attempt_id = attempt_id, lease_epoch = lease_epoch + 1,\n            lease_token_hash = token_hash,\n            lease_owner_fingerprint = p_worker_fingerprint,\n            lease_started_at = now_at, lease_expires_at = lease_until,\n            last_failure_code = NULL, updated_at = now_at, version = version + 1\n        WHERE workspace_id = p_workspace_id AND id = job.id\n        RETURNING * INTO job;\n        PERFORM knowledge.append_tbox_proposal_event_v1(\n            p_workspace_id, job.id, attempt_id, 'RUNNING',\n            'SOURCE_VALIDATION', 'SERVICE', worker_subject_id::text,\n            jsonb_build_object(\n                'reason_code', 'CLAIMED',\n                'attempt_no', attempt_no,\n                'lease_epoch', job.lease_epoch,\n                'worker_fingerprint_hash', encode(sha256(\n                    convert_to(p_worker_fingerprint, 'UTF8')\n                ), 'hex')\n            )\n        );\n        PERFORM knowledge.emit_tbox_proposal_outbox_v1(\n            p_workspace_id, job.id, 'RUNNING', job.version\n        );\n        RETURN jsonb_build_object(\n            'job', knowledge.tbox_proposal_job_document_v1(p_workspace_id, job.id),\n            'pins', knowledge.tbox_proposal_job_pins_v1(p_workspace_id, job.id),\n            'current_elements', knowledge.tbox_proposal_current_elements_v1(\n                p_workspace_id, job.draft_id\n            ),\n            'attempt_id', attempt_id::text,\n            'attempt_no', attempt_no,\n            'lease_epoch', job.lease_epoch,\n            'worker_fingerprint', p_worker_fingerprint,\n            'source_locator', CASE WHEN job.input_kind = 'DOCUMENT_SCHEMA' THEN (\n                SELECT jsonb_build_object(\n                    'bucket', manifest.bucket,\n                    'object_key', manifest.object_key\n                )\n                FROM integration.object_manifests AS manifest\n                WHERE manifest.workspace_id = p_workspace_id\n                  AND manifest.id = job.manifest_id\n            ) ELSE NULL END\n        );\n    END LOOP;\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.renew_tbox_proposal_job_v1(\n    p_workspace_id uuid,\n    p_job_id uuid,\n    p_attempt_id uuid,\n    p_lease_epoch bigint,\n    p_lease_token text,\n    p_worker_fingerprint text,\n    p_lease_seconds integer,\n    p_stage text,\n    p_progress_percent integer\n)\nRETURNS timestamptz\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, knowledge\nAS $$\nDECLARE\n    job knowledge.tbox_proposal_jobs%ROWTYPE;\n    draft knowledge.studio_drafts%ROWTYPE;\n    token_hash text := encode(sha256(convert_to(p_lease_token, 'UTF8')), 'hex');\n    lease_until timestamptz;\nBEGIN\n    SELECT * INTO job FROM knowledge.tbox_proposal_jobs\n    WHERE workspace_id = p_workspace_id AND id = p_job_id\n    FOR UPDATE;\n    SELECT * INTO draft FROM knowledge.studio_drafts\n    WHERE workspace_id = p_workspace_id AND id = job.draft_id;\n    IF job.id IS NULL\n       OR NOT knowledge.current_tbox_proposal_service_can_v1(\n           p_workspace_id, COALESCE(draft.classification, 0), draft.domain_ref_id\n       ) OR job.state <> 'RUNNING'\n       OR job.current_attempt_id IS DISTINCT FROM p_attempt_id\n       OR job.lease_epoch <> p_lease_epoch\n       OR job.lease_token_hash IS DISTINCT FROM token_hash\n       OR job.lease_owner_fingerprint IS DISTINCT FROM p_worker_fingerprint\n       OR job.lease_expires_at <= clock_timestamp()\n       OR p_lease_seconds NOT BETWEEN 5 AND 3600\n       OR p_stage NOT IN ('PARSING','INFERENCE','VALIDATING','FINALIZING')\n       OR p_progress_percent NOT BETWEEN 11 AND 99\n       OR p_progress_percent < job.progress_percent\n       OR NOT knowledge.tbox_proposal_lease_matches_v1(\n           p_workspace_id, p_job_id, p_attempt_id, p_lease_epoch,\n           p_lease_token, p_worker_fingerprint\n       )\n    THEN\n        RAISE EXCEPTION 'T-Box Proposal lease was superseded'\n            USING ERRCODE = '55000';\n    END IF;\n    lease_until := clock_timestamp() + make_interval(secs => p_lease_seconds);\n    UPDATE knowledge.tbox_proposal_attempts\n    SET stage = p_stage, lease_expires_at = lease_until\n    WHERE workspace_id = p_workspace_id AND id = p_attempt_id\n      AND job_id = p_job_id AND state = 'RUNNING'\n      AND lease_epoch = p_lease_epoch AND lease_token_hash = token_hash;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'T-Box Proposal attempt was superseded'\n            USING ERRCODE = '55000';\n    END IF;\n    UPDATE knowledge.tbox_proposal_jobs\n    SET stage = p_stage, progress_percent = p_progress_percent,\n        lease_expires_at = lease_until, updated_at = transaction_timestamp(),\n        version = version + 1\n    WHERE workspace_id = p_workspace_id AND id = p_job_id;\n    RETURN lease_until;\nEND\n$$;")
        op.execute("CREATE OR REPLACE FUNCTION knowledge.ensure_tbox_proposal_job_current_v1(\n    p_workspace_id uuid,\n    p_job_id uuid,\n    p_attempt_id uuid,\n    p_lease_epoch bigint,\n    p_lease_token text,\n    p_worker_fingerprint text,\n    p_schema_binding jsonb\n)\nRETURNS text\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, knowledge\nAS $$\nDECLARE\n    job knowledge.tbox_proposal_jobs%ROWTYPE;\n    draft knowledge.studio_drafts%ROWTYPE;\nBEGIN\n    SELECT * INTO job FROM knowledge.tbox_proposal_jobs\n    WHERE workspace_id = p_workspace_id AND id = p_job_id\n    FOR UPDATE;\n    SELECT * INTO draft FROM knowledge.studio_drafts\n    WHERE workspace_id = p_workspace_id AND id = job.draft_id;\n    IF job.id IS NULL\n       OR NOT knowledge.current_tbox_proposal_service_can_v1(\n           p_workspace_id, COALESCE(draft.classification, 0), draft.domain_ref_id\n       ) OR job.state NOT IN ('RUNNING','CANCEL_REQUESTED')\n       OR job.lease_expires_at <= clock_timestamp()\n       OR NOT knowledge.tbox_proposal_lease_matches_v1(\n           p_workspace_id, p_job_id, p_attempt_id, p_lease_epoch,\n           p_lease_token, p_worker_fingerprint\n       )\n    THEN\n        RAISE EXCEPTION 'T-Box Proposal lease was superseded'\n            USING ERRCODE = '55000';\n    END IF;\n    IF job.state = 'CANCEL_REQUESTED' THEN\n        UPDATE knowledge.tbox_proposal_attempts\n        SET state = 'CANCELLED', stage = 'COMPLETED', retryable = false,\n            failure_code = NULL, finished_at = transaction_timestamp()\n        WHERE workspace_id = p_workspace_id AND id = p_attempt_id\n          AND job_id = p_job_id AND state = 'RUNNING'\n          AND lease_epoch = p_lease_epoch\n          AND lease_token_hash = encode(\n              sha256(convert_to(p_lease_token, 'UTF8')), 'hex'\n          );\n        IF NOT FOUND THEN\n            RAISE EXCEPTION 'T-Box Proposal cancellation attempt was superseded'\n                USING ERRCODE = '55000';\n        END IF;\n        UPDATE knowledge.tbox_proposal_jobs\n        SET state = 'CANCELLED', stage = 'COMPLETED',\n            current_attempt_id = NULL, lease_token_hash = NULL,\n            lease_owner_fingerprint = NULL, lease_started_at = NULL,\n            lease_expires_at = NULL, last_failure_code = NULL,\n            completed_at = transaction_timestamp(),\n            updated_at = transaction_timestamp(), version = version + 1\n        WHERE workspace_id = p_workspace_id AND id = p_job_id\n        RETURNING * INTO job;\n        PERFORM knowledge.append_tbox_proposal_event_v1(\n            p_workspace_id, p_job_id, p_attempt_id,\n            'CANCELLED', 'COMPLETED', 'SERVICE',\n            NULLIF(current_setting('app.subject_id', true), ''),\n            jsonb_build_object('reason_code', 'CANCELLED_BEFORE_PROVIDER')\n        );\n        PERFORM knowledge.emit_tbox_proposal_outbox_v1(\n            p_workspace_id, p_job_id, 'CANCELLED', job.version\n        );\n        RETURN 'CANCELLED';\n    END IF;\n    RETURN knowledge.tbox_proposal_job_drift_v1(\n        p_workspace_id, p_job_id, p_schema_binding\n    );\nEND\n$$;")
        op.execute('CREATE OR REPLACE FUNCTION knowledge.complete_tbox_proposal_job_v1(\n    p_workspace_id uuid,\n    p_job_id uuid,\n    p_attempt_id uuid,\n    p_lease_epoch bigint,\n    p_lease_token text,\n    p_worker_fingerprint text,\n    p_call_id text,\n    p_elements jsonb,\n    p_conflicts jsonb,\n    p_prompt_label text,\n    p_model_binding jsonb,\n    p_source_reference jsonb,\n    p_result_hash text\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, integration, knowledge\nAS $$\nDECLARE\n    job knowledge.tbox_proposal_jobs%ROWTYPE;\n    draft knowledge.studio_drafts%ROWTYPE;\n    now_at timestamptz := transaction_timestamp();\n    token_hash text := encode(sha256(convert_to(p_lease_token, \'UTF8\')), \'hex\');\n    proposal_id uuid := gen_random_uuid();\n    operation_name text := \'knowledge.tbox-proposal.complete:\' || p_job_id::text;\n    idempotency_key_hash text := encode(\n        sha256(convert_to(p_call_id, \'UTF8\')), \'hex\'\n    );\n    replay integration.idempotency_keys%ROWTYPE;\n    drift_code text;\n    element jsonb;\nBEGIN\n    IF char_length(COALESCE(p_call_id, \'\')) NOT BETWEEN 1 AND 200\n       OR p_result_hash !~ \'^[0-9a-f]{64}$\'\n       OR jsonb_typeof(p_elements) <> \'array\'\n       OR jsonb_array_length(p_elements) NOT BETWEEN 1 AND 500\n       OR octet_length(p_elements::text) > 2097152\n       OR jsonb_typeof(p_conflicts) <> \'array\'\n       OR jsonb_array_length(p_conflicts) > 500\n       OR octet_length(p_conflicts::text) > 1048576\n       OR jsonb_typeof(p_model_binding) <> \'object\'\n       OR octet_length(p_model_binding::text) > 8192\n       OR jsonb_typeof(p_source_reference) <> \'object\'\n       OR octet_length(p_source_reference::text) > 65536\n       OR p_source_reference::text ~*\n           \'"(bucket|object_key|excerpt|prompt|provider_body|content)"\\\\s*:\'\n       OR char_length(COALESCE(p_prompt_label, \'\')) NOT BETWEEN 1 AND 512\n       OR p_prompt_label <> btrim(p_prompt_label)\n       OR p_prompt_label ~ \'[\\\\x00-\\\\x1F\\\\x7F]\'\n       OR NOT (\n           p_prompt_label = \'Governed Schema Assistant proposal\'\n           OR p_prompt_label LIKE \'Document schema proposal: %\'\n           OR p_prompt_label LIKE \'Catalog schema proposal: %\'\n       )\n    THEN\n        RAISE EXCEPTION \'invalid T-Box Proposal completion payload\'\n            USING ERRCODE = \'55000\';\n    END IF;\n    FOR element IN SELECT value FROM jsonb_array_elements(p_elements)\n    LOOP\n        IF jsonb_typeof(element) <> \'object\'\n           OR (element - ARRAY[\n               \'stable_element_id\',\'kind\',\'canonical_name\',\'display_name\',\n               \'parent_stable_element_id\',\'hierarchy_relation\',\n               \'source_stable_element_id\',\'target_stable_element_id\',\'data_type\',\n               \'nullable\',\'definition\',\'aliases\',\'unit\',\'vector_index_enabled\',\n               \'metadata_reference_id\',\'metadata_reference_urn\',\'layout_x\',\'layout_y\'\n           ]) <> \'{}\'::jsonb\n           OR element ->> \'kind\' NOT IN (\'CLASS\',\'PROPERTY\',\'RELATION\')\n           OR char_length(COALESCE(element ->> \'stable_element_id\', \'\'))\n               NOT BETWEEN 1 AND 128\n           OR char_length(COALESCE(element ->> \'canonical_name\', \'\'))\n               NOT BETWEEN 1 AND 255\n           OR char_length(COALESCE(element ->> \'display_name\', \'\'))\n               NOT BETWEEN 1 AND 255\n           OR jsonb_typeof(element -> \'aliases\') <> \'array\'\n           OR jsonb_array_length(element -> \'aliases\') > 50\n        THEN\n            RAISE EXCEPTION \'invalid typed T-Box Proposal element\'\n                USING ERRCODE = \'55000\';\n        END IF;\n    END LOOP;\n    PERFORM pg_advisory_xact_lock(hashtextextended(\n        p_workspace_id::text || \':\' || operation_name || \':\' || p_call_id, 0\n    ));\n    SELECT stored_replay.* INTO replay\n    FROM integration.idempotency_keys AS stored_replay\n    WHERE stored_replay.workspace_id = p_workspace_id\n      AND stored_replay.operation = operation_name\n      AND stored_replay.key_hash = idempotency_key_hash;\n    IF replay.workspace_id IS NOT NULL THEN\n        IF replay.request_hash <> p_result_hash THEN\n            RAISE EXCEPTION \'T-Box Proposal completion call was reused\'\n                USING ERRCODE = \'55000\';\n        END IF;\n        RETURN knowledge.tbox_proposal_job_document_v1(p_workspace_id, p_job_id);\n    END IF;\n    SELECT * INTO job FROM knowledge.tbox_proposal_jobs\n    WHERE workspace_id = p_workspace_id AND id = p_job_id\n    FOR UPDATE;\n    SELECT * INTO draft FROM knowledge.studio_drafts\n    WHERE workspace_id = p_workspace_id AND id = job.draft_id;\n    IF job.id IS NULL\n       OR NOT knowledge.current_tbox_proposal_service_can_v1(\n           p_workspace_id, COALESCE(draft.classification, 0), draft.domain_ref_id\n       ) OR job.state <> \'RUNNING\'\n       OR job.current_attempt_id IS DISTINCT FROM p_attempt_id\n       OR job.lease_epoch <> p_lease_epoch\n       OR job.lease_token_hash IS DISTINCT FROM token_hash\n       OR job.lease_owner_fingerprint IS DISTINCT FROM p_worker_fingerprint\n       OR job.lease_expires_at <= clock_timestamp()\n       OR NOT knowledge.tbox_proposal_lease_matches_v1(\n           p_workspace_id, p_job_id, p_attempt_id, p_lease_epoch,\n           p_lease_token, p_worker_fingerprint\n       ) OR knowledge.tbox_proposal_json_hash_v1(p_model_binding)\n           <> job.schema_binding_hash\n       OR p_model_binding <> job.schema_binding_document\n    THEN\n        RAISE EXCEPTION \'T-Box Proposal completion lease was superseded\'\n            USING ERRCODE = \'55000\';\n    END IF;\n    drift_code := knowledge.tbox_proposal_job_drift_v1(\n        p_workspace_id, p_job_id, p_model_binding\n    );\n    IF drift_code IS NOT NULL THEN\n        RAISE EXCEPTION \'T-Box Proposal completion pins are stale: %\', drift_code\n            USING ERRCODE = \'55000\';\n    END IF;\n    INSERT INTO knowledge.tbox_proposals (\n        id, workspace_id, draft_id, target_block_id, created_by,\n        state, mode, merge_strategy, base_draft_version, prompt,\n        proposal_document, conflicts_document, model_binding_document,\n        source_reference_document, error_code, applied_at, rejected_at,\n        created_at, updated_at, version\n    ) VALUES (\n        proposal_id, p_workspace_id, job.draft_id, job.target_block_id,\n        job.requested_by, \'READY\', job.mode, \'KEEP_ORIGINAL\',\n        job.base_draft_version, p_prompt_label,\n        jsonb_build_object(\n            \'contract_version\', \'KNOWLEDGE_STUDIO_TBOX_PROPOSAL_V1\',\n            \'elements\', p_elements\n        ), p_conflicts, p_model_binding, p_source_reference,\n        NULL, NULL, NULL, now_at, now_at, 1\n    );\n    UPDATE knowledge.tbox_proposal_attempts\n    SET state = \'SUCCEEDED\', stage = \'COMPLETED\', retryable = false,\n        output_hash = p_result_hash, failure_code = NULL, finished_at = now_at\n    WHERE workspace_id = p_workspace_id AND id = p_attempt_id\n      AND job_id = p_job_id AND state = \'RUNNING\'\n      AND lease_epoch = p_lease_epoch AND lease_token_hash = token_hash;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION \'T-Box Proposal completion attempt was superseded\'\n            USING ERRCODE = \'55000\';\n    END IF;\n    UPDATE knowledge.tbox_proposal_jobs\n    SET state = \'SUCCEEDED\', stage = \'COMPLETED\', progress_percent = 100,\n        current_attempt_id = NULL, lease_token_hash = NULL,\n        lease_owner_fingerprint = NULL, lease_started_at = NULL,\n        lease_expires_at = NULL, result_proposal_id = proposal_id,\n        result_evidence_hash = p_result_hash, last_failure_code = NULL,\n        completed_at = now_at, updated_at = now_at, version = version + 1\n    WHERE workspace_id = p_workspace_id AND id = p_job_id\n    RETURNING * INTO job;\n    PERFORM knowledge.append_tbox_proposal_event_v1(\n        p_workspace_id, p_job_id, p_attempt_id, \'SUCCEEDED\', \'COMPLETED\',\n        \'SERVICE\', NULLIF(current_setting(\'app.subject_id\', true), \'\'),\n        jsonb_build_object(\n            \'reason_code\', \'PROPOSAL_READY\',\n            \'proposal_id\', proposal_id::text,\n            \'result_hash\', p_result_hash,\n            \'call_id_hash\', idempotency_key_hash\n        )\n    );\n    PERFORM knowledge.emit_tbox_proposal_outbox_v1(\n        p_workspace_id, p_job_id, \'SUCCEEDED\', job.version\n    );\n    INSERT INTO integration.idempotency_keys (\n        workspace_id, operation, key_hash, request_hash, result,\n        created_at, expires_at\n    ) VALUES (\n        p_workspace_id, operation_name, idempotency_key_hash, p_result_hash,\n        jsonb_build_object(\n            \'job_id\', p_job_id::text,\n            \'proposal_id\', proposal_id::text\n        ), now_at, now_at + interval \'24 hours\'\n    );\n    RETURN knowledge.tbox_proposal_job_document_v1(p_workspace_id, p_job_id);\nEND\n$$;')
        op.execute("CREATE OR REPLACE FUNCTION knowledge.fail_tbox_proposal_job_v1(\n    p_workspace_id uuid,\n    p_job_id uuid,\n    p_attempt_id uuid,\n    p_lease_epoch bigint,\n    p_lease_token text,\n    p_worker_fingerprint text,\n    p_call_id text,\n    p_failure_code text,\n    p_retryable boolean,\n    p_stale boolean\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nVOLATILE\nSECURITY DEFINER\nSET search_path = pg_catalog, integration, knowledge\nAS $$\nDECLARE\n    job knowledge.tbox_proposal_jobs%ROWTYPE;\n    draft knowledge.studio_drafts%ROWTYPE;\n    now_at timestamptz := transaction_timestamp();\n    token_hash text := encode(sha256(convert_to(p_lease_token, 'UTF8')), 'hex');\n    operation_name text := 'knowledge.tbox-proposal.fail:' || p_job_id::text;\n    idempotency_key_hash text := encode(\n        sha256(convert_to(p_call_id, 'UTF8')), 'hex'\n    );\n    request_hash text;\n    replay integration.idempotency_keys%ROWTYPE;\n    target_state text;\n    attempt_state text;\nBEGIN\n    request_hash := knowledge.tbox_proposal_json_hash_v1(jsonb_build_object(\n        'failure_code', p_failure_code,\n        'retryable', p_retryable,\n        'stale', p_stale\n    ));\n    IF char_length(COALESCE(p_call_id, '')) NOT BETWEEN 1 AND 200\n       OR p_failure_code !~ '^[A-Z0-9_]{1,100}$'\n    THEN\n        RAISE EXCEPTION 'invalid T-Box Proposal failure payload'\n            USING ERRCODE = '55000';\n    END IF;\n    PERFORM pg_advisory_xact_lock(hashtextextended(\n        p_workspace_id::text || ':' || operation_name || ':' || p_call_id, 0\n    ));\n    SELECT stored_replay.* INTO replay\n    FROM integration.idempotency_keys AS stored_replay\n    WHERE stored_replay.workspace_id = p_workspace_id\n      AND stored_replay.operation = operation_name\n      AND stored_replay.key_hash = idempotency_key_hash;\n    IF replay.workspace_id IS NOT NULL THEN\n        IF replay.request_hash <> request_hash THEN\n            RAISE EXCEPTION 'T-Box Proposal failure call was reused'\n                USING ERRCODE = '55000';\n        END IF;\n        RETURN knowledge.tbox_proposal_job_document_v1(p_workspace_id, p_job_id);\n    END IF;\n    SELECT * INTO job FROM knowledge.tbox_proposal_jobs\n    WHERE workspace_id = p_workspace_id AND id = p_job_id\n    FOR UPDATE;\n    SELECT * INTO draft FROM knowledge.studio_drafts\n    WHERE workspace_id = p_workspace_id AND id = job.draft_id;\n    IF job.id IS NULL\n       OR NOT knowledge.current_tbox_proposal_service_can_v1(\n           p_workspace_id, COALESCE(draft.classification, 0), draft.domain_ref_id\n       ) OR job.state NOT IN ('RUNNING','CANCEL_REQUESTED')\n       OR job.current_attempt_id IS DISTINCT FROM p_attempt_id\n       OR job.lease_epoch <> p_lease_epoch\n       OR job.lease_token_hash IS DISTINCT FROM token_hash\n       OR job.lease_owner_fingerprint IS DISTINCT FROM p_worker_fingerprint\n       OR job.lease_expires_at <= clock_timestamp()\n       OR NOT knowledge.tbox_proposal_lease_matches_v1(\n           p_workspace_id, p_job_id, p_attempt_id, p_lease_epoch,\n           p_lease_token, p_worker_fingerprint\n       )\n    THEN\n        RAISE EXCEPTION 'T-Box Proposal failure lease was superseded'\n            USING ERRCODE = '55000';\n    END IF;\n    target_state := CASE\n        WHEN job.state = 'CANCEL_REQUESTED' THEN 'CANCELLED'\n        WHEN p_stale THEN 'STALE'\n        WHEN p_retryable AND job.attempt_count < job.maximum_attempts\n            THEN 'RETRY_WAIT'\n        ELSE 'FAILED'\n    END;\n    attempt_state := CASE\n        WHEN target_state = 'CANCELLED' THEN 'CANCELLED'\n        WHEN target_state = 'STALE' THEN 'STALE'\n        ELSE 'FAILED'\n    END;\n    UPDATE knowledge.tbox_proposal_attempts\n    SET state = attempt_state, stage = 'COMPLETED', retryable = p_retryable,\n        failure_code = p_failure_code, finished_at = now_at\n    WHERE workspace_id = p_workspace_id AND id = p_attempt_id\n      AND job_id = p_job_id AND state = 'RUNNING'\n      AND lease_epoch = p_lease_epoch AND lease_token_hash = token_hash;\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'T-Box Proposal failure attempt was superseded'\n            USING ERRCODE = '55000';\n    END IF;\n    UPDATE knowledge.tbox_proposal_jobs\n    SET state = target_state,\n        stage = CASE WHEN target_state = 'RETRY_WAIT'\n            THEN 'QUEUED' ELSE 'COMPLETED' END,\n        progress_percent = 0,\n        current_attempt_id = NULL, lease_token_hash = NULL,\n        lease_owner_fingerprint = NULL, lease_started_at = NULL,\n        lease_expires_at = NULL,\n        next_attempt_at = CASE WHEN target_state = 'RETRY_WAIT'\n            THEN now_at + make_interval(\n                secs => least(60, 5 * (2 ^ attempt_count))::integer\n            ) ELSE next_attempt_at END,\n        last_failure_code = CASE WHEN target_state = 'CANCELLED'\n            THEN NULL ELSE p_failure_code END,\n        completed_at = CASE WHEN target_state = 'RETRY_WAIT'\n            THEN NULL ELSE now_at END,\n        updated_at = now_at, version = version + 1\n    WHERE workspace_id = p_workspace_id AND id = p_job_id\n    RETURNING * INTO job;\n    PERFORM knowledge.append_tbox_proposal_event_v1(\n        p_workspace_id, p_job_id, p_attempt_id, target_state, job.stage,\n        'SERVICE', NULLIF(current_setting('app.subject_id', true), ''),\n        jsonb_build_object(\n            'reason_code', p_failure_code,\n            'retryable', p_retryable,\n            'call_id_hash', idempotency_key_hash\n        )\n    );\n    PERFORM knowledge.emit_tbox_proposal_outbox_v1(\n        p_workspace_id, p_job_id, target_state, job.version\n    );\n    INSERT INTO integration.idempotency_keys (\n        workspace_id, operation, key_hash, request_hash, result,\n        created_at, expires_at\n    ) VALUES (\n        p_workspace_id, operation_name, idempotency_key_hash, request_hash,\n        jsonb_build_object('job_id', p_job_id::text),\n        now_at, now_at + interval '24 hours'\n    );\n    RETURN knowledge.tbox_proposal_job_document_v1(p_workspace_id, p_job_id);\nEND\n$$;")
        op.execute('CREATE TRIGGER enforce_tbox_proposal_job_pin_immutability\nBEFORE UPDATE ON knowledge.tbox_proposal_jobs\nFOR EACH ROW EXECUTE FUNCTION\n    knowledge.enforce_tbox_proposal_job_pin_immutability_v1();')
        op.execute('CREATE TRIGGER reject_tbox_proposal_job_delete\nBEFORE DELETE ON knowledge.tbox_proposal_jobs\nFOR EACH ROW EXECUTE FUNCTION\n    knowledge.reject_tbox_proposal_evidence_mutation_v1();')
